talas::project::ProjectDocument makePulseGeneratorDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters = pulseGeneratorParameters(),
    bool connectModulator = false,
    bool connectEnvelope = false,
    bool connectReset = false,
    bool connectFrequency = false)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("pulse", "talas.pulseGenerator", std::move(parameters)));
    if (connectFrequency)
    {
        document.graph.nodes.push_back(node("freq", "talas.constant", {{"value", "2.0"}}));
        document.graph.connections.push_back(connection("freq", "value", "pulse", "frequency"));
    }
    if (connectModulator)
    {
        document.graph.nodes.push_back(node("mod", "talas.oscillator", {{"frequency", "1 hz"}, {"amplitude", "1.0"}}));
        document.graph.connections.push_back(connection("mod", "audioOut", "pulse", "modulator"));
    }
    if (connectEnvelope)
    {
        document.graph.nodes.push_back(node("env", "talas.constant", {{"value", "0.25"}}));
        document.graph.connections.push_back(connection("env", "value", "pulse", "envelope"));
    }
    if (connectReset)
    {
        document.graph.nodes.push_back(node("reset", "talas.constant", {{"value", "1.0"}}));
        document.graph.connections.push_back(connection("reset", "value", "pulse", "reset"));
    }
    document.graph.connections.push_back(connection("pulse", "audioOut", "out", "audioIn"));
    return document;
}

