talas::project::ProjectDocument makePointwiseExtremumDocument(
    std::string_view typeId)
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("extremum", std::string{typeId}));
    constexpr std::array ids{
        "input0Left", "input0Right", "input1Left", "input1Right",
        "input2Left", "input2Right"};
    for (std::size_t index = 0; index < ids.size(); ++index)
    {
        std::vector<talas::project::ProjectParameterExpression> parameters{
            booleanParameter("channel1", index == 0)};
        if (index != 0)
        {
            parameters.push_back(booleanParameter(
                "channel" + std::to_string(index + 1), true));
        }
        document.graph.nodes.push_back(node(
            ids[index], "talas.audioInput", std::move(parameters)));
        document.graph.connections.push_back(connection(
            ids[index], "audioOut", "extremum", ids[index]));
    }
    document.graph.connections.push_back(connection(
        "extremum", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "extremum", "rightOut", "out", "rightIn"));
    return document;
}

