// These fixtures give the FreqTracker in hz, move the formants with the
// pitch and shift by a phase vocoder, as projects before formats 47, 52 and
// 83 did.
std::vector<talas::project::ProjectParameterExpression> withHertzTracker(
    std::vector<talas::project::ProjectParameterExpression> parameters)
{
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "scaling";
        }))
        parameters.push_back(choiceParameter("scaling", "legacyVocoder"));
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "trackerUnits";
        }))
        parameters.push_back(choiceParameter("trackerUnits", "legacyHertz"));
    if (std::ranges::none_of(parameters, [](const auto& parameter) {
            return parameter.parameterId == "formants";
        }))
        parameters.push_back(choiceParameter("formants", "legacyMove"));
    return parameters;
}

