talas::project::ProjectDocument makeParallelLiveSpectralAnalysisInspectionDocument()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "inputA", "talas.audioInput",
        {booleanParameter("channel1", true),
         booleanParameter("channel2", false)}));
    document.graph.nodes.push_back(node(
        "inputB", "talas.audioInput",
        {booleanParameter("channel1", false),
         booleanParameter("channel2", true)}));
    document.graph.nodes.push_back(node(
        "spectrumA", "talas.liveSpectralAnalysis",
        liveSpectralAnalysisParameters({{"initFreq", "8 hz"}})));
    document.graph.nodes.push_back(node(
        "spectrumB", "talas.liveSpectralAnalysis",
        liveSpectralAnalysisParameters({{"initFreq", "12 hz"}})));
    document.graph.nodes.push_back(node(
        "bridgeA", "talas.partialSpectrumLegacyHoldV1"));
    document.graph.nodes.push_back(node(
        "bridgeB", "talas.partialSpectrumLegacyHoldV1"));
    document.graph.nodes.push_back(node(
        "selectorA", "talas.spectrumTrackSelector",
        spectrumTrackSelectorParameters({{"track", "1"}})));
    document.graph.nodes.push_back(node(
        "selectorB", "talas.spectrumTrackSelector",
        spectrumTrackSelectorParameters({{"track", "1"}})));
    document.graph.connections.push_back(connection(
        "inputA", "audioOut", "spectrumA", "audioIn"));
    document.graph.connections.push_back(connection(
        "inputB", "audioOut", "spectrumB", "audioIn"));
    document.graph.connections.push_back(connection(
        "spectrumA", "spectrumOut", "bridgeA", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "spectrumB", "spectrumOut", "bridgeB", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "bridgeA", "spectrumOut", "selectorA", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "bridgeB", "spectrumOut", "selectorB", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "selectorA", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "selectorB", "leftOut", "out", "rightIn"));
    return document;
}

