double toneCorrelationMagnitude(
    const std::vector<double>& samples,
    double sampleRate,
    double frequency,
    std::size_t firstFrame)
{
    constexpr double pi = 3.1415926535897932384626433832795;
    require(firstFrame < samples.size(), "correlation first frame should be inside rendered samples");

    double sineProjection = 0.0;
    double cosineProjection = 0.0;
    double sampleEnergy = 0.0;
    double basisEnergy = 0.0;
    for (std::size_t frame = firstFrame; frame < samples.size(); ++frame)
    {
        const auto angle = 2.0 * pi * frequency * static_cast<double>(frame) / sampleRate;
        const auto sine = std::sin(angle);
        const auto cosine = std::cos(angle);
        sineProjection += samples[frame] * sine;
        cosineProjection += samples[frame] * cosine;
        sampleEnergy += samples[frame] * samples[frame];
        basisEnergy += sine * sine;
    }

    require(sampleEnergy > 0.0, "correlation sample energy should be non-zero");
    require(basisEnergy > 0.0, "correlation basis energy should be non-zero");
    return std::sqrt(sineProjection * sineProjection + cosineProjection * cosineProjection)
        / std::sqrt(sampleEnergy * basisEnergy);
}

