void requireCompileParameterError(
    const talas::project::ProjectDocument& document,
    std::string_view nodeId,
    std::string_view parameterId,
    const std::string& message)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);

    require(!compile.ok(), message);
    require(
        hasDiagnostic(compile, DiagnosticCode::ParameterEvaluationError, nodeId, {}, parameterId),
        message + " should identify " + std::string(parameterId));
}

void requireHandBuiltTrackingRenderParameterError(
    std::string trackerType,
    std::vector<talas::runtime::ParameterValue> trackerParameters,
    std::string_view parameterId,
    const std::string& message)
{
    const auto result = renderHandBuiltTrackingVcaPlan(std::move(trackerType), std::move(trackerParameters));

    require(!result.ok(), message);
    require(result.mono.empty(), "failed render should not return audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "detector", {}, parameterId),
        message + " should identify " + std::string(parameterId));
}

