void testPulseGeneratorRejectsForgedInterpolationAtRender()
{
    auto compiled = talas::runtime::compileProject(
        makePulseGeneratorDocument(),
        makeRegistry(),
        talas::runtime::RenderSettings{8.0, 8});
    require(compiled.ok(),
        "C94 forged interpolation fixture should compile before mutation");
    auto& plan = const_cast<talas::runtime::RuntimePlan&>(
        compiled.graph->plan());
    const auto pulse = std::ranges::find(
        plan.steps, std::string_view{"talas.pulseGenerator"},
        &talas::runtime::CompileStep::typeId);
    require(pulse != plan.steps.end(),
        "C94 forged interpolation fixture should expose Pulse Generator");
    const auto interpolation = std::ranges::find(
        pulse->parameters, std::string_view{"interpolation"},
        &talas::runtime::ParameterValue::id);
    require(interpolation != pulse->parameters.end(),
        "C94 forged interpolation fixture should expose interpolation");
    interpolation->choice = "cubic";

    const auto result = talas::runtime::renderOffline(*compiled.graph, 8);
    require(!result.ok() && result.mono.empty(),
        "C94 offline renderer should reject a forged interpolation choice atomically");
    require(hasDiagnostic(
                result,
                DiagnosticCode::GraphValidationFailed,
                "pulse",
                {},
                "interpolation"),
        "C94 forged interpolation rejection should identify the exact parameter");
}

