void testMultislopeDownstreamFailureRollsBackOfflineState()
{
    auto document = makeMultislopeFunctionGeneratorVcaDocument();
    document.graph.nodes.push_back(node(
        "z_failureLeft", "talas.constant",
        {{"value", "!C116OfflineRetryGain"}}));
    document.graph.nodes.push_back(node(
        "z_failureRight", "talas.constant", {{"value", "1e200"}}));
    document.graph.nodes.push_back(node(
        "z_failureProduct", "talas.product"));
    document.graph.nodes.push_back(node(
        "z_failureCheck", "talas.scaleAndOffset",
        {{"scale", "1"}, {"offset", "0"}}));
    document.graph.nodes.push_back(node(
        "z_failureOsc", "talas.oscillator",
        {{"frequency", "0.5 hz"}, {"amplitude", "0.25"}}));
    document.graph.nodes.push_back(node("z_failureVca", "talas.vca"));
    document.graph.nodes.push_back(node(
        "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "vca" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "z_failureLeft", "value", "z_failureProduct", "left"));
    document.graph.connections.push_back(connection(
        "z_failureRight", "value", "z_failureProduct", "right"));
    document.graph.connections.push_back(connection(
        "z_failureProduct", "value", "z_failureCheck", "value"));
    document.graph.connections.push_back(connection(
        "z_failureOsc", "audioOut", "z_failureVca", "audioIn"));
    document.graph.connections.push_back(connection(
        "z_failureCheck", "value", "z_failureVca", "gain"));
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "zz_mix", "in1"));
    document.graph.connections.push_back(connection(
        "z_failureVca", "audioOut", "zz_mix", "in2"));
    document.graph.connections.push_back(connection(
        "zz_mix", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.eventValues = {
        {"C116OfflineRetryGain", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C116OfflineRetryGain",
            std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compile = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compile.ok(),
        "C116 downstream offline rollback fixture should compile");
    talas::runtime::OfflineRenderSession session{*compile.graph};
    require(session.render(2).ok(),
        "C116 downstream offline fixture should establish Multislope state");
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeMultislope =
        talas::runtime::OfflineRenderSessionTestAccess::
            multislopeState(session, "multi");
    const auto rejected = session.render(2);
    require(!rejected.ok(),
        "C116 downstream offline hazard should reject the transaction");
    require(rejected.mono.empty(),
        "C116 rejected downstream offline transaction should publish no audio");
    require(talas::runtime::OfflineRenderSessionTestAccess::state(session)
                == before,
        "C116 downstream offline failure should preserve public transaction state");
    require(talas::runtime::OfflineRenderSessionTestAccess::
                    multislopeState(session, "multi")
                == beforeMultislope,
        "C116 downstream offline failure should preserve Multislope state");
}

