void testMultisegmentEnvelopeSessionDoesNotRestartOneShot()
{
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    const auto document = makeMultisegmentEnvelopeVcaDocument();
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "multisegment session document should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(3);
    const auto second = session.render(4);

    require(first.ok(), "first multisegment session render should not emit diagnostics");
    require(second.ok(), "second multisegment session render should not emit diagnostics");
    require(first.mono.size() == 3, "first multisegment session render should return requested frames");
    require(second.mono.size() == 4, "second multisegment session render should return requested frames");
    requireNear(first.mono[0], 0.0, 1.0e-12, "multisegment session first frame 0");
    requireNear(first.mono[1], sinPiOver8 * 0.25, 1.0e-12, "multisegment session first frame 1");
    requireNear(first.mono[2], sinPiOver4 * 0.5, 1.0e-12, "multisegment session first frame 2");
    requireNear(second.mono[0], sin3PiOver8 * 0.75, 1.0e-12, "multisegment session second frame 0");
    requireNear(second.mono[1], 1.0, 1.0e-12, "multisegment session second frame 1");
    requireNear(second.mono[2], sin3PiOver8 * 0.875, 1.0e-12, "multisegment session second frame 2");
    requireNear(second.mono[3], sinPiOver4 * 0.75, 1.0e-12, "multisegment session second frame 3");
}

void requireMultisegmentEnvelopeRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::string_view parameterId)
{
    const auto result = renderDocument(makeMultisegmentEnvelopeVcaDocument(std::move(parameters)), 4.0, 5);

    require(!result.ok(), "invalid multisegment envelope should fail render");
    require(result.mono.empty(), "failed multisegment envelope render should not return audio");
    if (!hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "env", {}, parameterId))
    {
        std::string details;
        for (const auto& diagnostic : result.diagnostics)
        {
            details += diagnostic.nodeId + "." + diagnostic.portId + "." + diagnostic.parameterId + ": " + diagnostic.message + "\n";
        }
        throw std::runtime_error("render should identify malformed multisegment envelope parameter "
            + std::string(parameterId)
            + ", got:\n"
            + details);
    }
}

