void testGraphicalEnvelopeExtremeFiniteInterpolationRemainsFinite()
{
    const auto result = renderDocument(
        makeGraphicalEnvelopeVcaDocument(graphicalEnvelopeParameters({
            textParameter(
                "envelope",
                "{0 s} {-1e308} {1 s} {1e308}"),
        })),
        2.0,
        3);

    require(result.ok(),
        "C158 extreme finite Graphical Envelope interpolation should render offline");
    require(result.mono.size() == 3
            && std::ranges::all_of(result.mono, [](double sample) {
                return std::isfinite(sample);
            }),
        "C158 extreme finite Graphical Envelope interpolation should publish only finite offline samples");
    requireNear(result.mono[1], 0.0, 1.0e-12,
        "C158 opposite-sign extreme midpoint should interpolate without overflow");
}

