void testGraphicalEnvelopeDownstreamFailureRollsBackOfflineStateWithoutOscillator()
{
    auto document = makeGraphicalEnvelopeVcaDocument();
    auto source = std::ranges::find(
        document.graph.nodes,
        "osc",
        &talas::project::ProjectNode::instanceId);
    require(source != document.graph.nodes.end(),
        "C158 offline rollback fixture should expose its source");
    source->typeId = "talas.audioInput";
    source->parameters = {
        booleanParameter("channel1", true),
        booleanParameter("channel2", false),
    };
    document.graph.nodes.push_back(node(
        "z_failureLeft", "talas.constant",
        {{"value", "!C158OfflineRetryGain"}}));
    document.graph.nodes.push_back(node(
        "z_failureRight", "talas.constant", {{"value", "1e200"}}));
    document.graph.nodes.push_back(node(
        "z_failureProduct", "talas.product"));
    document.graph.nodes.push_back(node(
        "z_failureVca", "talas.vca"));
    document.graph.nodes.push_back(node(
        "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "vca" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "z_failureLeft", "value", "z_failureProduct", "left"));
    document.graph.connections.push_back(connection(
        "z_failureRight", "value", "z_failureProduct", "right"));
    document.graph.connections.push_back(connection(
        "osc", "audioOut", "z_failureVca", "audioIn"));
    document.graph.connections.push_back(connection(
        "z_failureProduct", "value", "z_failureVca", "gain"));
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "zz_mix", "in1"));
    document.graph.connections.push_back(connection(
        "z_failureVca", "audioOut", "zz_mix", "in2"));
    document.graph.connections.push_back(connection(
        "zz_mix", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.audioInputChannels = {{1, {1.0, 1.0, 1.0, 1.0}}};
    settings.eventValues = {
        {"C158OfflineRetryGain", 1.0,
            talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C158OfflineRetryGain",
            std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C158 downstream offline rollback fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    require(session.render(2).ok(),
        "C158 downstream offline fixture should establish Graphical Envelope state");
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeGraphical =
        talas::runtime::OfflineRenderSessionTestAccess::
            graphicalEnvelopeState(session, "env");
    const auto rejected = session.render(2);
    require(!rejected.ok() && rejected.mono.empty(),
        "C158 downstream offline hazard should reject without audio publication");
    require(talas::runtime::OfflineRenderSessionTestAccess::state(session)
                == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    graphicalEnvelopeState(session, "env")
                == beforeGraphical,
        "C158 downstream offline failure should preserve Graphical Envelope and public transaction state without oscillator ancestry");
}

