void testArPromotedAndCompilerDemotedInstancesRenderTogether()
{
    auto document = makeArVcaDocument();
    document.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    document.variableLibrary.variables.push_back({
        "gain",
        "Gain",
        talas::expr::ValueDomain::Scalar,
        0.5,
    });
    document.graph.nodes.push_back(node(
        "contextEnv", "talas.ar",
        arParameters({{"scale", "@gain"}})));
    document.graph.nodes.push_back(node("envelopeSum", "talas.add"));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "env" && edge.toNode == "vca";
    });
    document.graph.connections.push_back(connection(
        "env", "value", "envelopeSum", "left"));
    document.graph.connections.push_back(connection(
        "contextEnv", "value", "envelopeSum", "right"));
    document.graph.connections.push_back(connection(
        "envelopeSum", "value", "vca", "gain"));

    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), talas::runtime::RenderSettings{4.0, 5});
    require(compiled.ok(),
        "C163 mixed promoted and contextual AR fixture should compile");
    const auto promotedCount = std::ranges::count_if(
        compiled.graph->plan().steps, [](const auto& step) {
            return step.typeId == "talas.ar"
                && step.offlineSupport
                    == talas::core::ExecutionSupport::Supported;
        });
    const auto subsetCount = std::ranges::count_if(
        compiled.graph->plan().steps, [](const auto& step) {
            return step.typeId == "talas.ar"
                && step.offlineSupport
                    == talas::core::ExecutionSupport::Subset;
        });
    require(promotedCount == 1 && subsetCount == 1,
        "C163 compiler should promote only the exact AR instance");

    const auto rendered = talas::runtime::renderOffline(*compiled.graph, 5);
    require(rendered.ok() && rendered.mono.size() == 5,
        "C163 promoted and compiler-demoted AR instances should render together");
}

void testArScheduledControlsAreOfflinePartitionResetAndFailureAtomic()
{
    auto document = makeArVcaDocument(arParameters({
        {"attackTime", "!Attack"},
        {"releaseTime", "!Release"},
        {"scale", "!Scale"},
        {"gate", "!KeyDown"},
    }));
    auto carrier = std::ranges::find(
        document.graph.nodes, std::string_view{"osc"},
        &talas::project::ProjectNode::instanceId);
    require(carrier != document.graph.nodes.end(),
        "C163 offline schedule fixture should expose its carrier");
    carrier->parameters[1].expression = "0.5";

    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.eventValues = {
        {"Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {"Release", 0.5, talas::expr::ValueDomain::Seconds},
        {"Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "Attack", 0.25, talas::expr::ValueDomain::Seconds},
        {2, "Scale", -0.5, talas::expr::ValueDomain::Scalar},
        {3, "KeyDown", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "Release", 0.25, talas::expr::ValueDomain::Seconds},
        {5, "Attack", 0.5, talas::expr::ValueDomain::Seconds},
        {5, "Scale", 0.75, talas::expr::ValueDomain::Scalar},
        {5, "KeyDown", 1.0, talas::expr::ValueDomain::Scalar},
        {7, "Release", 0.25, talas::expr::ValueDomain::Seconds},
        {7, "KeyDown", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C163 offline four-control schedule fixture should compile");
    talas::runtime::OfflineRenderSession oneShot{*compiled.graph};
    talas::runtime::OfflineRenderSession partitioned{*compiled.graph};
    const auto expected = oneShot.render(8);
    const auto first = partitioned.render(3);
    const auto second = partitioned.render(2);
    const auto third = partitioned.render(3);
    require(expected.ok() && first.ok() && second.ok() && third.ok(),
        "C163 offline four-control schedule should render across partitions");
    auto actual = first.mono;
    actual.insert(actual.end(), second.mono.begin(), second.mono.end());
    actual.insert(actual.end(), third.mono.begin(), third.mono.end());
    require(actual == expected.mono,
        "C163 offline four-control schedule should be partition invariant");
    partitioned.reset();
    const auto replay = partitioned.render(8);
    require(replay.ok() && replay.mono == expected.mono,
        "C163 offline reset should replay the four-control schedule exactly");

    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C163OfflineDownstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "outputScale", "talas.level", {
            {"left", "100"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "vca" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "outputScale", "audioIn"));
    document.graph.connections.push_back(connection(
        "outputScale", "leftOut", "out", "audioIn"));
    settings.eventValues.push_back({
        "C163OfflineDownstream", 1.0,
        talas::expr::ValueDomain::Scalar,
    });
    settings.eventValueChanges.push_back({
        6, "C163OfflineDownstream",
        std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar,
    });
    std::ranges::sort(
        settings.eventValueChanges, {},
        &talas::runtime::EventValueChange::frame);
    const auto failingCompiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(failingCompiled.ok(),
        "C163 offline scheduled rollback fixture should compile"
            + (failingCompiled.diagnostics.empty()
                    ? std::string{}
                    : ": " + failingCompiled.diagnostics.front().message));
    talas::runtime::OfflineRenderSession candidate{*failingCompiled.graph};
    require(candidate.render(3).ok(),
        "C163 offline rollback fixture should establish scheduled AR state");
    const auto rejected = candidate.render(4);
    const auto retry = candidate.render(3);
    const auto repeatedFailure = candidate.render(1);

    std::erase_if(settings.eventValueChanges, [](const auto& change) {
        return change.name == "C163OfflineDownstream";
    });
    const auto referenceCompiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(referenceCompiled.ok(),
        "C163 offline scheduled rollback reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(3).ok(),
        "C163 offline rollback reference should establish scheduled AR state");
    const auto referenceRetry = reference.render(3);
    require(!rejected.ok() && rejected.mono.empty(),
        "C163 late downstream failure should reject its whole offline transaction");
    require(retry.ok() && referenceRetry.ok(),
        "C163 offline scheduled AR should remain renderable after rollback");
    require(retry.mono == referenceRetry.mono,
        "C163 failed offline transaction should restore four-control AR schedule and envelope state before retry");
    require(!repeatedFailure.ok() && repeatedFailure.mono.empty(),
        "C163 offline rollback should restore the failing event cursor for a deterministic repeated rejection");
}

void testArConnectedGateReleasesLinearly()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 6;
    settings.tableResources.push_back({"Tables/Gate", {1.0, 1.0, 1.0, 0.0, 0.0, 0.0}});

    auto document = makeVcaDocument(
        {
            node("gate", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Gate")})),
            node("env", "talas.ar", arParameters({{"gate", "0.0"}, {"attackTime", "0.5 s"}, {"releaseTime", "0.5 s"}})),
        },
        {
            connection("gate", "value", "env", "gate"),
            connection("env", "value", "vca", "gain"),
        },
        {},
        {{"frequency", "0.25 hz"}, {"amplitude", "1.0"}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-gate ar document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 6);
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);

    require(result.ok(), "connected-gate ar render should not emit diagnostics");
    require(result.mono.size() == 6, "connected-gate ar render should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "connected-gate ar frame 0");
    requireNear(result.mono[1], sinPiOver8 * 0.5, 1.0e-12, "connected-gate ar frame 1 should attack");
    requireNear(result.mono[2], sinPiOver4, 1.0e-12, "connected-gate ar frame 2 should reach scale");
    requireNear(result.mono[3], sin3PiOver8, 1.0e-12, "connected-gate ar frame 3 should start release from current value");
    requireNear(result.mono[4], 0.5, 1.0e-12, "connected-gate ar frame 4 should release halfway");
    requireNear(result.mono[5], 0.0, 1.0e-12, "connected-gate ar frame 5 should finish release");
}

