void testOscillatorAuthorityRejectsInvalidConnectedArFallback()
{
    auto document = makeArVcaDocument(arParameters({{"gate", "0"}}));
    document.graph.nodes.push_back(node(
        "gateControl", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "gateControl", "value", "env", "gate"));
    const auto settings = talas::runtime::RenderSettings{4.0, 4};
    auto candidateGraph = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    const auto referenceGraph = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(candidateGraph.ok() && referenceGraph.ok(),
        "C91 connected fallback fixtures should compile");
    auto& plan = const_cast<talas::runtime::RuntimePlan&>(
        candidateGraph.graph->plan());
    const auto ar = std::ranges::find(
        plan.steps, std::string_view{"talas.ar"},
        &talas::runtime::CompileStep::typeId);
    require(ar != plan.steps.end(), "C91 fixture should expose AR");
    const auto gate = std::ranges::find(
        ar->parameters, std::string_view{"gate"},
        &talas::runtime::ParameterValue::id);
    require(gate != ar->parameters.end(),
        "C91 fixture should expose inert gate");
    gate->value = std::numeric_limits<double>::infinity();
    talas::runtime::OfflineRenderSession candidate{*candidateGraph.graph};
    talas::runtime::OfflineRenderSession reference{*referenceGraph.graph};
    const auto actual = candidate.render(4);
    const auto expected = reference.render(4);
    require(!actual.ok() && expected.ok(),
        "C160 Oscillator authority should reject an invalid connected AR "
        "fallback without rejecting its compiler-owned reference");
}

