void testArFailureRollsBackOfflineStateBeforeRetry()
{
    auto document = makeArVcaDocument(arParameters({
        {"attackTime", "0.5 s"},
        {"releaseTime", "1 s"},
        {"scale", "1"},
        {"gate", "!C91Gate"},
    }));
    document.graph.nodes.push_back(node(
        "gateControl", "talas.constant", {{"value", "!C91Gate"}}));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C91OfflineDownstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "outputScale", "talas.level", {
            {"left", "3"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "vca" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "gateControl", "value", "env", "gate"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "outputScale", "audioIn"));
    document.graph.connections.push_back(connection(
        "outputScale", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"C91Gate", 1.0, talas::expr::ValueDomain::Scalar},
        {"C91OfflineDownstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C91Gate", 0.0, talas::expr::ValueDomain::Scalar},
        {3, "C91OfflineDownstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C91 offline rollback fixture should compile");
    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    require(candidate.render(2).ok(), "C91 should establish attack state");
    const auto rejected = candidate.render(2);
    const auto retry = candidate.render(1);

    auto referenceSettings = settings;
    referenceSettings.eventValueChanges.erase(
        referenceSettings.eventValueChanges.begin() + 1);
    const auto referenceCompiled = talas::runtime::compileProject(
        document, makeRegistry(), referenceSettings);
    require(referenceCompiled.ok(), "C91 reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(2).ok(), "C91 reference should establish state");
    const auto referenceRetry = reference.render(1);
    require(!rejected.ok() && rejected.mono.empty(),
        "C91 later offline failure should reject the whole transaction");
    require(retry.ok() && referenceRetry.ok()
            && retry.mono == referenceRetry.mono,
        "C91 failed offline transaction should restore AR before retry");
}

