void testAdsrConnectedGateReleasesFromCurrentValue()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 7;
    settings.tableResources.push_back({"Tables/Gate", {1.0, 1.0, 1.0, 1.0, 0.0, 0.0, 0.0}});

    auto document = makeVcaDocument(
        {
            node("gate", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Gate")})),
            node(
                "env",
                "talas.adsr",
                adsrParameters({{"gate", "0.0"}, {"attackTime", "0.5 s"}, {"decayTime", "0.5 s"}, {"releaseTime", "0.5 s"}})),
        },
        {
            connection("gate", "value", "env", "gate"),
            connection("env", "value", "vca", "gain"),
        },
        {},
        {{"frequency", "0.25 hz"}, {"amplitude", "1.0"}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-gate adsr document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 7);
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);

    require(result.ok(), "connected-gate adsr render should not emit diagnostics");
    require(result.mono.size() == 7, "connected-gate adsr render should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "connected-gate adsr frame 0");
    requireNear(result.mono[1], sinPiOver8 * 0.5, 1.0e-12, "connected-gate adsr frame 1 should attack");
    requireNear(result.mono[2], sinPiOver4, 1.0e-12, "connected-gate adsr frame 2 should reach attack peak");
    requireNear(result.mono[3], sin3PiOver8 * 0.625, 1.0e-12, "connected-gate adsr frame 3 should decay");
    requireNear(result.mono[4], 0.625, 1.0e-12, "connected-gate adsr frame 4 should start release from current value");
    requireNear(result.mono[5], sin3PiOver8 * 0.3125, 1.0e-12, "connected-gate adsr frame 5 should release halfway");
    requireNear(result.mono[6], 0.0, 1.0e-12, "connected-gate adsr frame 6 should finish release");
}

void testAdsrPositiveLegatoReattacksFromCurrentValue()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.audioInputChannels.push_back({1, std::vector<double>(5, 1.0)});
    settings.tableResources.push_back({"Tables/Gate", {1.0, 1.0, 0.0, 1.0, 1.0}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("vca", "talas.vca"));
    document.graph.nodes.push_back(node("input", "talas.audioInput"));
    document.graph.nodes.push_back(node(
        "env",
        "talas.adsr",
        adsrParameters({
            {"gate", "0.0"},
            {"attackTime", "1 s"},
            {"decayTime", "1 s"},
            {"sustainLevel", "0.5"},
            {"releaseTime", "1 s"},
            {"legato", "1.0"},
        })));
    document.graph.nodes.push_back(node("gate", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Gate")})));
    document.graph.connections.push_back(connection("input", "audioOut", "vca", "audioIn"));
    document.graph.connections.push_back(connection("env", "value", "vca", "gain"));
    document.graph.connections.push_back(connection("gate", "value", "env", "gate"));
    document.graph.connections.push_back(connection("vca", "audioOut", "out", "audioIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "positive-legato adsr document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "positive-legato adsr render should not emit diagnostics");
    require(result.mono.size() == 5, "positive-legato adsr should return requested frames");
    const std::vector<double> expected{0.0, 0.25, 0.25, 0.25, 0.5};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "positive-legato adsr frame " + std::to_string(frame));
}

