void testAdsrConnectedGateIgnoresInvalidInertFallback()
{
    auto document = makeAdsrVcaDocument(adsrParameters({
        {"gate", "1e200 * 1e200"}}));
    document.graph.nodes.push_back(node(
        "gateControl", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "gateControl", "value", "env", "gate"));
    const auto settings = talas::runtime::RenderSettings{4.0, 4};
    const auto candidateGraph = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    auto referenceDocument = makeAdsrVcaDocument(
        adsrParameters({{"gate", "0"}}));
    referenceDocument.graph.nodes.push_back(node(
        "gateControl", "talas.constant", {{"value", "1"}}));
    referenceDocument.graph.connections.push_back(connection(
        "gateControl", "value", "env", "gate"));
    const auto referenceGraph = talas::runtime::compileProject(
        referenceDocument, makeRegistry(), settings);
    require(candidateGraph.ok() && referenceGraph.ok(),
        "C92 connected fallback fixtures should compile");
    talas::runtime::OfflineRenderSession candidate{*candidateGraph.graph};
    talas::runtime::OfflineRenderSession reference{*referenceGraph.graph};
    const auto actual = candidate.render(4);
    const auto expected = reference.render(4);
    require(actual.ok() && expected.ok() && actual.mono == expected.mono,
        "C92 connected finite gate should own invalid inert offline fallback");
}

