void testAdsrRejectsUnsupportedConfigurationsAtRender()
{
    // Only linear segments take a negative Scale.
    requireAdsrRenderFailure(
        adsrParameters({choiceParameter("type", "exponential"), {"scale", "-1"}}),
        "scale");
    requireAdsrRenderFailure(
        adsrParameters({{"attackTime", "0 s"}}),
        "attackTime");
    requireAdsrRenderFailure(
        adsrParameters({{"decayTime", "0 s"}}),
        "decayTime");
    requireAdsrRenderFailure(
        adsrParameters({{"releaseTime", "0 s"}}),
        "releaseTime");
    requireAdsrRenderFailure(
        adsrParameters({{"sustainLevel", "-0.1"}}),
        "sustainLevel");
    requireAdsrRenderFailure(
        adsrParameters({{"sustainLevel", "1.1"}}),
        "sustainLevel");

    const auto result = renderHandBuiltTrackingVcaPlan(
        "talas.adsr",
        {
            {"attackTime", talas::expr::ValueDomain::Seconds, 0.5},
            {"decayTime", talas::expr::ValueDomain::Seconds, 0.5},
            {"sustainLevel", talas::expr::ValueDomain::Scalar, 0.25},
            {"releaseTime", talas::expr::ValueDomain::Seconds, 0.25},
            choiceRuntimeParameter("type", "linear"),
            {"scale", talas::expr::ValueDomain::Scalar, std::numeric_limits<double>::infinity()},
            {"gate", talas::expr::ValueDomain::Scalar, 1.0},
            {"legato", talas::expr::ValueDomain::Scalar, 0.0},
        });
    require(!result.ok(), "hand-built adsr envelope with non-finite scale should fail render");
    require(result.mono.empty(), "failed hand-built adsr envelope render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "detector", {}, "scale"), "hand-built render should identify adsr scale");
}

talas::runtime::OfflineRenderResult renderFunctionGeneratorDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<double> samples,
    std::size_t frameCount)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = frameCount;
    settings.tableResources.push_back({"Tables/Envelope", std::move(samples)});

    const auto document = makeFunctionGeneratorVcaDocument(std::move(parameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "function generator document should compile before render");
    return talas::runtime::renderOffline(*compile.graph, frameCount);
}

