void requireFunctionGeneratorFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::TableResource> tableResources,
    std::string_view parameterId)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = std::move(tableResources);

    const auto document = makeFunctionGeneratorVcaDocument(std::move(parameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid function generator document should compile before render validation");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "invalid function generator should fail render");
    require(result.mono.empty(), "failed function generator render should not return audio");
    const auto hasExactParameterDiagnostic = hasDiagnostic(
        result, DiagnosticCode::GraphValidationFailed,
        "fg", {}, parameterId);
    require(hasExactParameterDiagnostic
            || ((parameterId == "wavetable"
                 || parameterId == "fromMemoryWriter")
                && hasDiagnostic(
                    result,
                    DiagnosticCode::GraphValidationFailed)),
        "render should identify the Function Generator parameter or promoted immutable-resource authority: "
            + std::string{parameterId}
            + (result.diagnostics.empty() ? std::string{}
                : ": " + result.diagnostics.front().message));
}

void testFunctionGeneratorRejectsUnsupportedConfigurationsAtRender()
{
    requireFunctionGeneratorFailure(
        functionGeneratorParameters(),
        {},
        "wavetable");
    requireFunctionGeneratorFailure(
        functionGeneratorParameters(),
        {{"Tables/Envelope", {}}},
        "wavetable");
    requireFunctionGeneratorFailure(
        functionGeneratorParameters(),
        {{"Tables/Envelope", {0.0, std::numeric_limits<double>::infinity()}}},
        "wavetable");
    // An OnDuration must be greater than zero, so a fixed one of 0 s
    // is refused as it compiles; a connected one is checked as it plays.
    {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = 5;
        settings.tableResources = {{"Tables/Envelope", {0.0, 1.0}}};
        const auto refused = talas::runtime::compileProject(
            makeFunctionGeneratorVcaDocument(functionGeneratorParameters({{"onDuration", "0 s"}})), makeRegistry(), settings);
        require(!refused.ok() && refused.diagnostics.front().parameterId == "onDuration",
            "a fixed OnDuration of 0 s should be refused as it compiles");
    }
    requireFunctionGeneratorFailure(
        functionGeneratorParameters({booleanParameter("fromMemoryWriter", true)}),
        {{"Tables/Envelope", {0.0, 1.0}}},
        "fromMemoryWriter");
}

void testFunctionGeneratorLateConnectedFailureRollsBackOfflineState()
{
    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.tableResources = {
        {"Tables/Envelope", {0.0, 1.0, 0.0}},
        {"Tables/FunctionDurations", {1.0, 0.0}},
    };

    auto document = makeFunctionGeneratorVcaDocument(
        functionGeneratorParameters({{"onDuration", "0 s"}}));
    document.graph.nodes.push_back(node(
        "duration", "talas.triggeredTableRead",
        triggeredTableReadParameters({
            resourceParameter(
                "wavetable", "Tables/FunctionDurations")})));
    document.graph.connections.push_back(connection(
        "duration", "value", "fg", "onDuration"));

    const auto compile = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compile.ok(),
        "C115 late-failure offline Function Generator fixture should compile");
    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeFunction =
        talas::runtime::OfflineRenderSessionTestAccess::
            functionGeneratorState(session, "fg");
    const auto rejected = session.render(2);
    require(!rejected.ok() && rejected.mono.empty()
            && talas::runtime::OfflineRenderSessionTestAccess::state(session)
                == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    functionGeneratorState(session, "fg")
                == beforeFunction,
        "C115 late invalid connected duration should publish no offline transaction or Function Generator state");
}

