        require(compile.ok(), "invalid connected grainDuration chopper document should compile");
        const auto result = talas::runtime::renderOffline(*compile.graph, 5);
        require(!result.ok(), "chopper should reject non-positive connected grainDuration");
        require(result.mono.empty(), "failed connected chopper grainDuration render should not return audio");
