void testTriggeredTableReadStreamsPlainTableWhileTriggered()
{
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);

    const auto result = renderTriggeredTableReadDocument(
        triggeredTableReadParameters(),
        {0.25, 0.5, 0.75, 1.0},
        6);

    require(result.ok(), "triggered table read render should not emit diagnostics");
    require(result.mono.size() == 6, "triggered table read render should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "triggered table read frame 0");
    requireNear(result.mono[1], sinPiOver8 * 0.5, 1.0e-12, "triggered table read frame 1");
    requireNear(result.mono[2], sinPiOver4 * 0.75, 1.0e-12, "triggered table read frame 2");
    requireNear(result.mono[3], sin3PiOver8, 1.0e-12, "triggered table read frame 3");
    requireNear(result.mono[4], 1.0, 1.0e-12, "triggered table read frame 4 should hold final table sample");
    requireNear(result.mono[5], sin3PiOver8, 1.0e-12, "triggered table read frame 5 should hold final table sample");
}

// Projects before format 71 loop a whole plain table unless loops are
// ignored.
void testTriggeredTableReadLegacyLoopsWholePlainTable()
{
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);

    const auto result = renderTriggeredTableReadDocument(
        triggeredTableReadParameters({booleanParameter("ignoreLoops", false),
            choiceParameter("headerLoop", "legacyWholeTable")}),
        {0.25, 0.5},
        6);

    require(result.ok(), "looped triggered table read render should not emit diagnostics");
    require(result.mono.size() == 6, "looped triggered table read render should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "looped triggered table read frame 0");
    requireNear(result.mono[1], sinPiOver8 * 0.5, 1.0e-12, "looped triggered table read frame 1");
    requireNear(result.mono[2], sinPiOver4 * 0.25, 1.0e-12, "looped triggered table read frame 2 should wrap to table start");
    requireNear(result.mono[3], sin3PiOver8 * 0.5, 1.0e-12, "looped triggered table read frame 3");
    requireNear(result.mono[4], 0.25, 1.0e-12, "looped triggered table read frame 4 should wrap again");
    requireNear(result.mono[5], sin3PiOver8 * 0.5, 1.0e-12, "looped triggered table read frame 5");
}

