void testTriggeredTableReadSessionContinuesTablePosition()
{
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.tableResources.push_back({"Tables/Steps", {1.0, 2.0, 3.0, 4.0}});

    const auto document = makeTriggeredTableReadVcaDocument();
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "triggered table read session document should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(3);
    const auto second = session.render(3);

    require(first.ok(), "first triggered table read session render should not emit diagnostics");
    require(second.ok(), "second triggered table read session render should not emit diagnostics");
    require(first.mono.size() == 3, "first triggered table read session render should return requested frames");
    require(second.mono.size() == 3, "second triggered table read session render should return requested frames");
    requireNear(first.mono[0], 0.0, 1.0e-12, "triggered table read session first frame 0");
    requireNear(first.mono[1], sinPiOver8 * 2.0, 1.0e-12, "triggered table read session first frame 1");
    requireNear(first.mono[2], sinPiOver4 * 3.0, 1.0e-12, "triggered table read session first frame 2");
    requireNear(second.mono[0], sin3PiOver8 * 4.0, 1.0e-12, "triggered table read session second frame 0");
    requireNear(second.mono[1], 4.0, 1.0e-12, "triggered table read session second frame 1");
    requireNear(second.mono[2], sin3PiOver8 * 4.0, 1.0e-12, "triggered table read session second frame 2");
}

void testTriggeredTableReadDirectControlsFailureRollbackAndReset()
{
    auto directSettings = talas::runtime::RenderSettings{4.0, 6};
    directSettings.eventValues = {
        {"TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
    };
    directSettings.eventValueChanges = {
        {2, "TableTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {3, "TableGate", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "TableGate", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    directSettings.tableResources.push_back(
        {"Tables/Steps", {1.0, 2.0, 3.0, 4.0}});
    const auto direct = talas::runtime::compileProject(
        makeTriggeredTableReadVcaDocument({
            {"trigger", "!TableTrigger"},
            resourceParameter("wavetable", "Tables/Steps"),
            {"gate", "!TableGate"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }),
        makeRegistry(), directSettings);
    require(direct.ok(),
        "C71 direct Event Value Triggered Table Read fixture should compile");
    const auto directResult = talas::runtime::renderOffline(*direct.graph, 6);
    const std::vector<double> directExpected{
        0.0,
        0.7653668647301796,
        1.4142135623730951,
        0.0,
        1.0,
        1.8477590650225735,
    };
    require(
        directResult.ok()
            && directResult.mono.size() == directExpected.size(),
        "C71 offline direct controls should render the complete trigger and gate sequence");
    for (std::size_t frame = 0; frame < directExpected.size(); ++frame)
        requireNear(
            directResult.mono[frame], directExpected[frame], 1.0e-12,
            "C71 offline direct trigger and gate sequence frame "
                + std::to_string(frame));

    auto failureDocument = makeTriggeredTableReadVcaDocument({
        {"trigger", "!TableTrigger"},
        resourceParameter("wavetable", "Tables/Steps"),
        {"gate", "!TableGate"},
        booleanParameter("ignoreLoops", true),
        booleanParameter("fromMemoryWriter", false),
    });
    failureDocument.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C71Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        failureDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    failureDocument.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    failureDocument.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto failureSettings = talas::runtime::RenderSettings{4.0, 6};
    failureSettings.eventValues = {
        {"TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"TableGate", 0.0, talas::expr::ValueDomain::Scalar},
        {"C71Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    failureSettings.eventValueChanges = {
        {2, "TableTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {3, "TableGate", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "TableGate", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "TableTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {5, "C71Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    failureSettings.tableResources.push_back(
        {"Tables/Steps", {1.0, 2.0, 3.0, 4.0}});
    const auto compiled = talas::runtime::compileProject(
        failureDocument, makeRegistry(), failureSettings);
    require(compiled.ok(), "C71 offline rollback fixture should compile");

    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    talas::runtime::OfflineRenderSession reference{*compiled.graph};
    const auto candidateFirst = candidate.render(2);
    const auto referenceFirst = reference.render(2);
    require(
        candidateFirst.ok() && referenceFirst.ok()
            && candidateFirst.mono == referenceFirst.mono,
        "C71 rollback fixture should establish matching table cursor state");
    const auto rejected = candidate.render(4);
    const auto retry = candidate.render(3);
    const auto referenceNext = reference.render(3);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && referenceNext.ok()
            && retry.mono == referenceNext.mono,
        "C71 failed offline transaction should restore cursor, held sample, gate polarity, and scheduled controls");

    candidate.reset();
    talas::runtime::OfflineRenderSession pristine{*compiled.graph};
    const auto reset = candidate.render(2);
    const auto expectedReset = pristine.render(2);
    require(
        reset.ok() && expectedReset.ok()
            && reset.mono == expectedReset.mono,
        "C71 offline reset should restore pristine Triggered Table Read state");
}

void requireTriggeredTableReadConnectedControlFailure(std::string targetPort)
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/Steps", {0.25, 0.5, 0.75}});

    auto document = makeTriggeredTableReadVcaDocument();
    document.graph.nodes.push_back(node("left", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("right", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("badControl", "talas.add"));
    document.graph.connections.push_back(connection("left", "value", "badControl", "left"));
    document.graph.connections.push_back(connection("right", "value", "badControl", "right"));
    document.graph.connections.push_back(connection("badControl", "value", "table", targetPort));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid connected-control triggered table read document should compile before render validation");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "triggered table read should reject non-finite connected " + targetPort);
    require(result.mono.empty(), "failed triggered table read connected " + targetPort + " render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "table", targetPort, {}), "render should identify triggered table read connected " + targetPort + " input");
}

