void requireStereoInOutputRender(std::string outputTypeId)
{
    const auto pairPorts = stereoInOutputPairPorts(outputTypeId);
    const auto result = renderDocument(makeStereoInOutputDocument(std::move(outputTypeId)), 4.0, 5);

    require(result.ok(), "stereo-in output render should not emit diagnostics");
    require(result.channels.size() == pairPorts.size() * 2, "stereo-in output should expose every rendered pair channel");
    for (std::size_t pairIndex = 0; pairIndex < pairPorts.size(); ++pairIndex)
    {
        const auto amplitude = static_cast<double>(pairIndex + 1);
        requireChannelSamples(result.channels[pairIndex * 2], amplitude, "stereo-in pair left channel " + std::to_string(pairIndex + 1));
        requireChannelSamples(result.channels[(pairIndex * 2) + 1], amplitude, "stereo-in pair right channel " + std::to_string(pairIndex + 1));
    }
    requireChannelSamples(result.mono, 1.0, "stereo-in legacy mono mirror");
    requireChannelSamples(result.right, 1.0, "stereo-in legacy right mirror");
}

