talas::project::ProjectDocument makeDiscretePanDocument(
    std::string panExpression,
    std::string scaleExpression)
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.output4"),
        node("pan", "talas.pan", {
            {"pan", std::move(panExpression)},
            {"scale", std::move(scaleExpression)},
            choiceParameter("type", "power"),
            choiceParameter("layout", "discrete4"),
        }),
        node("input", "talas.audioInput", {
            booleanParameter("channel1", true),
            booleanParameter("channel2", false),
        }),
    };
    document.graph.connections.push_back(connection(
        "input", "audioOut", "pan", "audioIn"));
    for (std::size_t channel = 0; channel < 4; ++channel)
    {
        const auto port = "out" + std::to_string(channel + 1);
        document.graph.connections.push_back(connection(
            "pan", port, "out", port));
    }
    return document;
}

void testPanDiscreteSpeakerBoundariesPreserveCanonicalSilence()
{
    for (const auto position : {0.0, 0.25, 1.0})
    {
        auto settings = talas::runtime::RenderSettings{8.0, 1};
        settings.audioInputChannels.push_back({1, {-2.0}});
        const auto compiled = talas::runtime::compileProject(
            makeDiscretePanDocument(
                std::to_string(position), "1"),
            makeRegistry(),
            settings);
        require(
            compiled.ok(),
            "C134 offline discrete Pan boundary fixture should compile");
        const auto result = talas::runtime::renderOffline(*compiled.graph, 1);
        require(
            result.ok() && result.channels.size() == 4,
            "C134 offline discrete Pan boundary should render four channels");
        for (const auto& channel : result.channels)
        {
            require(
                channel.size() == 1
                    && (channel[0] != 0.0
                        || std::bit_cast<std::uint64_t>(channel[0])
                            == std::uint64_t{0}),
                "C134 offline negative discrete Pan speaker boundaries and wrap should preserve canonical positive-zero silence");
        }
    }
}

void testPanDiscreteLateFailurePublishesNothingAndRetryIsExact()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.audioInputChannels.push_back(
        {1, {-2.0, -2.0, -2.0, -2.0, -2.0}});
    settings.eventValues = {{
        "C134OfflineScale", 1.0,
        talas::expr::ValueDomain::Scalar}};
    settings.eventValueChanges = {{
        3,
        "C134OfflineScale",
        std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar}};
    const auto document = makeDiscretePanDocument(
        "0.25", "!C134OfflineScale");
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "C134 offline discrete Pan late-failure fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto rejected = session.render(5);
    const auto afterRejected =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto retry = session.render(2);

    auto pristineSettings = settings;
    const auto pristineCompiled = talas::runtime::compileProject(
        document, makeRegistry(), pristineSettings);
    require(
        pristineCompiled.ok(),
        "C134 pristine offline discrete Pan retry fixture should compile");
    talas::runtime::OfflineRenderSession pristine{*pristineCompiled.graph};
    const auto expected = pristine.render(2);

    require(
        !rejected.ok()
            && rejected.mono.empty()
            && rejected.right.empty()
            && rejected.channels.empty()
            && afterRejected == before,
        "C134 late offline discrete Pan failure should publish no active channel or session state");
    require(
        retry.ok(),
        "C134 offline discrete Pan retry should succeed after rejected publication");
    require(
        expected.ok(),
        "C134 pristine offline discrete Pan retry oracle should render");
    require(
        retry.channels.size() == expected.channels.size(),
        "C134 offline discrete Pan retry should preserve the pristine channel count");
    for (std::size_t channel = 0;
         channel < retry.channels.size();
         ++channel)
    {
        require(
            retry.channels[channel].size()
                == expected.channels[channel].size(),
            "C134 offline discrete Pan retry should preserve each pristine channel length");
        for (std::size_t frame = 0;
             frame < retry.channels[channel].size();
             ++frame)
        {
            require(
                std::bit_cast<std::uint64_t>(
                    retry.channels[channel][frame])
                    == std::bit_cast<std::uint64_t>(
                        expected.channels[channel][frame]),
                "C134 offline discrete Pan retry should exactly match a pristine session after rejected publication at channel "
                    + std::to_string(channel)
                    + " frame " + std::to_string(frame)
                    + ": retry bits "
                    + std::to_string(std::bit_cast<std::uint64_t>(
                        retry.channels[channel][frame]))
                    + ", expected bits "
                    + std::to_string(std::bit_cast<std::uint64_t>(
                        expected.channels[channel][frame])));
        }
    }
}

