void testOverlappingMixerConnectedOutputLevelsUpdatePerFrame()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/Left", {0.0, 0.25, 0.5, 1.0, -0.5}});
    settings.tableResources.push_back({"Tables/Right", {1.0, 0.5, -0.5, 0.25, 0.0}});

    auto document = makeOverlappingMixerDocument(overlappingMixerParameters({
        {"left", "1.0"},
        {"right", "1.0"},
    }));
    document.graph.nodes.push_back(node("left", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Left")})));
    document.graph.nodes.push_back(node("right", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Right")})));
    document.graph.connections.push_back(connection("left", "value", "mix", "left"));
    document.graph.connections.push_back(connection("right", "value", "mix", "right"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-output overlapping mixer document should compile before render");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-output overlapping mixer render should not emit diagnostics");
    require(result.mono.size() == 5, "dynamic-output overlapping mixer left should return requested frames");
    require(result.right.size() == 5, "dynamic-output overlapping mixer right should return requested frames");
    const std::vector<double> expectedLeft{0.0, 0.75, 0.0, -3.0, -0.0};
    const std::vector<double> expectedRight{0.0, 1.5, -0.0, -0.75, 0.0};
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(result.mono[frame], expectedLeft[frame], 1.0e-12, "dynamic-output overlapping mixer left frame " + std::to_string(frame));
        requireNear(result.right[frame], expectedRight[frame], 1.0e-12, "dynamic-output overlapping mixer right frame " + std::to_string(frame));
    }
}

