void testHandBuiltOverlappingMixerRejectsNonzeroOverlapTimeAtRender()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "osc",
            "talas.oscillator",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                {"amplitude", talas::expr::ValueDomain::Scalar, 1.0},
            },
        },
        {
            "mix",
            "talas.overlappingMixer",
            {binding("in1", "osc", "audioOut", 0)},
            {
                textRuntimeParameter("legacyInputs", "in1"),
                {"overlapTime", talas::expr::ValueDomain::Seconds, 0.001},
                {"left", talas::expr::ValueDomain::Scalar, 1.0},
                {"right", talas::expr::ValueDomain::Scalar, 1.0},
            },
        },
        {
            "out",
            "talas.audioOutput",
            {
                binding("audioIn", "mix", "leftOut", 1),
                binding("rightIn", "mix", "rightOut", 2),
            },
            {},
        },
    };
    plan.buffers = {
        {"osc", "audioOut", talas::core::PortType::Audio, 5},
        {"mix", "leftOut", talas::core::PortType::Audio, 5},
        {"mix", "rightOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;
    plan.rightOutputBufferIndex = 2;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan)), 5);

    require(!result.ok(), "nonzero overlapping mixer overlap time should fail render");
    require(result.mono.empty(), "failed overlapping mixer render should not return left audio");
    require(result.right.empty(), "failed overlapping mixer render should not return right audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "mix", {}, "overlapTime"),
        "render should identify unsupported overlapping mixer overlap time");
}

