void requireAnalogSequencerRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::string_view parameterId)
{
    const auto result = renderDocument(makeAnalogSequencerDocument(std::move(parameters)), 4.0, 5);

    require(!result.ok(), "invalid analog sequencer should fail render");
    require(result.mono.empty(), "failed analog sequencer render should not return left audio");
    require(result.right.empty(), "failed analog sequencer render should not return right audio");
    if (!hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "seq", {}, parameterId))
    {
        std::string details;
        for (const auto& diagnostic : result.diagnostics)
        {
            details += diagnostic.nodeId + "." + diagnostic.portId + "." + diagnostic.parameterId + ": " + diagnostic.message + "\n";
        }
        throw std::runtime_error("render should identify malformed analog sequencer parameter "
            + std::string(parameterId)
            + ", got:\n"
            + details);
    }
}

