void testCrossfadeLateFailurePublishesNothingAndRetryIsExact()
{
    auto settings = talas::runtime::RenderSettings{8.0, 5};
    settings.eventValues = {{
        "C135OfflineScale", 1.0,
        talas::expr::ValueDomain::Scalar}};
    settings.eventValueChanges = {{
        3,
        "C135OfflineScale",
        std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar}};
    auto document = makeCrossfadeDocument(
        {{"pan", "0.5"},
         {"scale", "1"},
         {"fade", "0.5"},
         choiceParameter("type", "linear")},
        false,
        true,
        false);
    const auto scale = std::ranges::find_if(
        document.graph.nodes,
        [](const auto& graphNode) {
            return graphNode.instanceId == "scale";
        });
    require(scale != document.graph.nodes.end(),
        "C135 offline Crossfade scale fixture should exist");
    scale->parameters = {{"value", "!C135OfflineScale"}};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "C135 offline Crossfade late-failure fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto rejected = session.render(5);
    const auto afterRejected =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto retry = session.render(2);

    const auto pristineCompiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        pristineCompiled.ok(),
        "C135 pristine offline Crossfade retry fixture should compile");
    talas::runtime::OfflineRenderSession pristine{*pristineCompiled.graph};
    const auto expected = pristine.render(2);

    require(
        !rejected.ok()
            && rejected.mono.empty()
            && rejected.right.empty()
            && rejected.channels.empty()
            && afterRejected == before,
        "C135 late offline Crossfade failure should publish no output or session state");
    require(
        retry.ok() && expected.ok()
            && retry.mono.size() == expected.mono.size()
            && retry.right.size() == expected.right.size(),
        "C135 offline Crossfade retry should match a pristine session shape");
    for (std::size_t frame = 0; frame < retry.mono.size(); ++frame)
    {
        require(
            std::bit_cast<std::uint64_t>(retry.mono[frame])
                    == std::bit_cast<std::uint64_t>(expected.mono[frame])
                && std::bit_cast<std::uint64_t>(retry.right[frame])
                    == std::bit_cast<std::uint64_t>(expected.right[frame]),
            "C135 offline Crossfade retry should exactly match pristine stereo output at frame "
                + std::to_string(frame));
    }
}

