void testDynamicRangeCompressorConnectedReleaseTimeOverridesParameter()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("drc", "talas.dynamicRangeController", dynamicRangeControllerParameters({{"releaseTime", "0.001 ms"}})));
    document.graph.nodes.push_back(node("side", "talas.audioInput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput", {booleanParameter("channel1", false), booleanParameter("channel2", true)}));
    document.graph.nodes.push_back(node("releaseTime", "talas.constant", {{"value", "1.0"}}));
    document.graph.connections.push_back(connection("side", "audioOut", "drc", "sideChain"));
    document.graph.connections.push_back(connection("input", "audioOut", "drc", "audioIn"));
    document.graph.connections.push_back(connection("releaseTime", "value", "drc", "releaseTime"));
    document.graph.connections.push_back(connection("drc", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.audioInputChannels.push_back({1, {1.0, 0.0, 0.0, 0.0}});
    settings.audioInputChannels.push_back({2, {1.0, 1.0, 1.0, 1.0}});
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-releaseTime dynamic range compressor document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);

    const auto releaseAlpha = std::pow(0.4, 1.0 / 4.0);
    const auto compressorGain = [](double envelope) {
        constexpr auto threshold = 0.5;
        constexpr auto ratio = 2.0;
        if (envelope <= threshold || envelope <= 0.0)
            return 1.0;
        const auto controlledLevel = threshold + ((envelope - threshold) / ratio);
        return controlledLevel / envelope;
    };

    require(result.ok(), "connected-releaseTime dynamic range compressor render should not emit diagnostics");
    require(result.mono.size() == 4, "connected-releaseTime dynamic range compressor render should return requested frames");
    requireNear(result.mono[0], 0.75, 1.0e-12, "connected-releaseTime dynamic range compressor frame 0");
    requireNear(result.mono[1], compressorGain(releaseAlpha), 1.0e-9, "connected-releaseTime dynamic range compressor frame 1 should follow slow release");
    requireNear(result.mono[2], compressorGain(releaseAlpha * releaseAlpha), 1.0e-9, "connected-releaseTime dynamic range compressor frame 2 should keep releasing");
    requireNear(result.mono[3], compressorGain(releaseAlpha * releaseAlpha * releaseAlpha), 1.0e-9, "connected-releaseTime dynamic range compressor frame 3 should nearly recover");
}

