void testDynamicRangeCompressorSessionKeepsEnvelopeAndDelayState()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    const auto document = makeDynamicRangeControllerDocument(dynamicRangeControllerParameters({{"ratio", "1.0"}, {"delay", "0.25 s"}}));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic range compressor session document should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(3);
    const auto oneShot = renderDocument(document, 4.0, 5);

    require(first.ok(), "first dynamic range compressor session render should not emit diagnostics");
    require(second.ok(), "second dynamic range compressor session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot dynamic range compressor render should not emit diagnostics");
    require(first.mono.size() == 2, "first dynamic range compressor session render should return requested frames");
    require(second.mono.size() == 3, "second dynamic range compressor session render should return requested frames");
    require(oneShot.mono.size() == 5, "one-shot dynamic range compressor render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "dynamic range session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "dynamic range session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "dynamic range session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "dynamic range session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "dynamic range session second frame 2");
}

