void requireDynamicRangeControllerRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> controllerParameters,
    std::string_view parameterId)
{
    const auto document = makeDynamicRangeControllerDocument(std::move(controllerParameters));
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic range controller document should compile before render validation");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "dynamic range controller invalid ratio should fail render");
    require(result.mono.empty(), "failed dynamic range controller render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "drc", {}, parameterId), "render should identify dynamic range parameter");
}

