void testChannelCrosserRejectsNonFiniteConnectedMatrixCoefficient()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    auto document = makeChannelCrosserDocument();
    document.graph.nodes.push_back(node("coefficientLeft", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("coefficientRight", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("coefficient", "talas.add"));
    document.graph.connections.push_back(connection("coefficientLeft", "value", "coefficient", "left"));
    document.graph.connections.push_back(connection("coefficientRight", "value", "coefficient", "right"));
    document.graph.connections.push_back(connection("coefficient", "value", "crosser", "leftInLeft"));

    const auto result = renderDocument(document, 4.0, 5);

    require(!result.ok(), "channel crosser should reject non-finite connected matrix coefficient");
    require(result.mono.empty(), "failed connected-matrix channel crosser render should not return left audio");
    require(result.right.empty(), "failed connected-matrix channel crosser render should not return right audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "crosser", "leftInLeft"),
        "render should identify connected channel crosser matrix coefficient");
}

