void testPointwiseMinimumAndMaximumSelectEverySampleAndChannel()
{
    for (const auto [typeId, expectedLeft, expectedRight] : {
             std::tuple{
                 "talas.minimum", std::array{1.0, -4.0},
                 std::array{-1.0, -2.0}},
             std::tuple{
                 "talas.maximum", std::array{3.0, 5.0},
                 std::array{9.0, 4.0}},
         })
    {
        talas::runtime::RenderSettings settings{48000.0, 2};
        settings.audioInputChannels = {
            {1, {2.0, -4.0}}, {2, {8.0, 1.0}},
            {3, {1.0, 5.0}}, {4, {9.0, -2.0}},
            {5, {3.0, 0.0}}, {6, {-1.0, 4.0}},
        };
        const auto compiled = talas::runtime::compileProject(
            makePointwiseExtremumDocument(typeId), makeRegistry(), settings);
        require(compiled.ok(),
            std::string{typeId} + " should compile six ordered audio lanes");
        const auto result = talas::runtime::renderOffline(*compiled.graph, 2);
        require(result.ok(),
            std::string{typeId} + " should render finite offline input");
        require(result.mono == std::vector<double>{
                    expectedLeft.begin(), expectedLeft.end()}
                && result.right == std::vector<double>{
                    expectedRight.begin(), expectedRight.end()},
            std::string{typeId}
                + " should select the published per-sample per-channel extremum");
    }
}

