// A Chopper or Function Generator without a Wavetable is a missing
// setting, not forged authority, and says so.
void testMissingWavetablesAreNamed()
{
    const auto names = [](const talas::runtime::OfflineRenderResult& result,
                           std::string_view text) {
        return !result.ok()
            && std::ranges::any_of(result.diagnostics, [&](const auto& diagnostic) {
                   return diagnostic.message.find(text) != std::string::npos;
               });
    };
    require(names(renderDocument(makeChopperDocument(chopperParameters({
                        resourceParameter("wavetable", "")})),
                      48000.0, 64),
                "Chopper needs a Wavetable"),
        "a Chopper without a Wavetable should say so");

    talas::project::ProjectDocument function;
    function.graph.nodes.push_back(node("out", "talas.audioOutput"));
    function.graph.nodes.push_back(node("function", "talas.functionGenerator",
        {resourceParameter("wavetable", "")}));
    function.graph.connections.push_back(connection("function", "value", "out", "audioIn"));
    require(names(renderDocument(function, 48000.0, 64),
                "Function Generator needs a Wavetable"),
        "a Function Generator without a Wavetable should say so");
}

