void testChannellerRoutesIndependentLiveSelectorsAtExactFrames()
{
    auto document = makeChannellerDocument({
        booleanParameter("leftChannel", false),
        booleanParameter("rightChannel", true),
    });
    document.graph.nodes.push_back(node(
        "leftSelector", "talas.constant", {{"value", "!C49Left"}}));
    document.graph.nodes.push_back(node(
        "rightSelector", "talas.constant", {{"value", "!C49Right"}}));
    document.graph.connections.push_back(connection(
        "leftSelector", "value", "channeller", "leftChannel"));
    document.graph.connections.push_back(connection(
        "rightSelector", "value", "channeller", "rightChannel"));
    document.graph.nodes.push_back(node(
        "rightOsc", "talas.oscillator",
        {{"frequency", "1 hz"}, {"amplitude", "0.5"}}));
    document.graph.connections.push_back(connection(
        "rightOsc", "audioOut", "channeller", "rightIn"));

    talas::runtime::RenderSettings settings{8.0, 3};
    settings.eventValues = {
        {"C49Left", -1.0, talas::expr::ValueDomain::Scalar},
        {"C49Right", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C49Left", 1.0, talas::expr::ValueDomain::Scalar},
        {4, "C49Right", 0.0, talas::expr::ValueDomain::Scalar},
        {5, "C49Left", -0.5, talas::expr::ValueDomain::Scalar},
        {5, "C49Right", 0.25, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "live-selector Channeller should compile");

    const auto result = talas::runtime::renderOffline(*compiled.graph, 7);

    require(result.ok(), "live-selector Channeller should render offline");
    // Only the right channel is checked, then both, then only the left
    // (at a zero crossing), then only the right again.
    const auto half = 0.5 * std::sqrt(0.5);
    const std::array expectedLeft{
        0.0, half, 1.0, std::sqrt(0.5), 0.0, -half, -0.5};
    const std::array expectedRight{
        0.0, half, 0.5, half, 0.0, -half, -0.5};
    require(
        result.mono.size() == expectedLeft.size()
            && result.right.size() == expectedRight.size(),
        "live-selector Channeller should return exact stereo frame counts");
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(
            result.mono[frame], expectedLeft[frame], 1.0e-12,
            "live-selector Channeller left frame");
        requireNear(
            result.right[frame], expectedRight[frame], 1.0e-12,
            "live-selector Channeller right frame");
    }
}

void testChannellerRejectsForgedOfflineLiveSelectorBindings()
{
    auto document = makeChannellerDocument({
        booleanParameter("leftChannel", false),
        booleanParameter("rightChannel", true),
    });
    document.graph.nodes.push_back(node(
        "leftSelector", "talas.constant", {{"value", "1"}}));
    document.graph.connections.push_back(connection(
        "leftSelector", "value", "channeller", "leftChannel"));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), {8.0, 1});
    require(
        compiled.ok(),
        "C49 forged offline selector-binding fixture should compile");

    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        for (auto& step : plan.steps)
        {
            if (step.typeId != "talas.oscillator")
                continue;
            step.offlineSupport = talas::core::ExecutionSupport::Subset;
            step.preparedRealtimeSupport =
                talas::core::ExecutionSupport::Subset;
        }
        const auto result = talas::runtime::renderOffline(
            handBuiltGraph(
                std::move(plan), compiled.graph->renderSettings()),
            1);
        require(
            !result.ok() && result.mono.empty() && result.right.empty(),
            std::string{context}
                + " should reject forged offline C49 bindings");
        require(
            hasDiagnostic(
                result,
                DiagnosticCode::GraphValidationFailed,
                "channeller"),
            std::string{context}
                + " should identify forged offline Channeller authority");
    };
    const auto findChanneller = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.channeller"},
            &talas::runtime::CompileStep::typeId);
    };

    {
        auto plan = compiled.graph->plan();
        const auto channeller = findChanneller(plan);
        require(
            channeller != plan.steps.end(),
            "C49 duplicate-selector offline fixture should expose Channeller");
        const auto selector = std::ranges::find(
            channeller->inputs,
            std::string_view{"leftChannel"},
            &talas::runtime::InputBinding::inputPortId);
        require(
            selector != channeller->inputs.end(),
            "C49 duplicate-selector offline fixture should expose leftChannel");
        channeller->inputs.push_back(*selector);
        requireRejected(std::move(plan), "duplicate left selector binding");
    }
    {
        auto plan = compiled.graph->plan();
        const auto channeller = findChanneller(plan);
        require(
            channeller != plan.steps.end(),
            "C49 duplicate-audio offline fixture should expose Channeller");
        const auto audio = std::ranges::find(
            channeller->inputs,
            std::string_view{"audioIn"},
            &talas::runtime::InputBinding::inputPortId);
        require(
            audio != channeller->inputs.end(),
            "C49 duplicate-audio offline fixture should expose audioIn");
        channeller->inputs.push_back(*audio);
        requireRejected(std::move(plan), "duplicate Channeller audio binding");
    }
    {
        auto plan = compiled.graph->plan();
        const auto channeller = findChanneller(plan);
        require(
            channeller != plan.steps.end(),
            "C49 unrelated-binding offline fixture should expose Channeller");
        const auto selector = std::ranges::find(
            channeller->inputs,
            std::string_view{"leftChannel"},
            &talas::runtime::InputBinding::inputPortId);
        require(
            selector != channeller->inputs.end(),
            "C49 unrelated-binding offline fixture should expose leftChannel");
        auto unrelated = *selector;
        unrelated.inputPortId = "forgedSelector";
        channeller->inputs.push_back(std::move(unrelated));
        requireRejected(std::move(plan), "unrelated Channeller selector binding");
    }
}

