void testDifferenceRejectsNonFiniteOperandsAndResultAtItsOwnBoundary()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    const auto requireRejected = [](std::string_view rejectedPort) {
        const auto rejectResult = rejectedPort == "value";
        auto nodes = std::vector<talas::project::ProjectNode>{
            node("finite", "talas.constant", {{"value", "1"}}),
            node("difference", "talas.difference"),
        };
        auto edges = std::vector<talas::core::Connection>{};
        if (rejectResult)
        {
            nodes.push_back(node(
                "positive", "talas.constant", {{"value", "1e308"}}));
            nodes.push_back(node(
                "negative", "talas.constant", {{"value", "-1e308"}}));
            edges.push_back(connection(
                "positive", "value", "difference", "left"));
            edges.push_back(connection(
                "negative", "value", "difference", "right"));
        }
        else
        {
            nodes.push_back(node(
                "largeA", "talas.constant", {{"value", "1e308"}}));
            nodes.push_back(node(
                "largeB", "talas.constant", {{"value", "1e308"}}));
            nodes.push_back(node("overflow", "talas.add"));
            edges.push_back(connection(
                "largeA", "value", "overflow", "left"));
            edges.push_back(connection(
                "largeB", "value", "overflow", "right"));
            edges.push_back(connection(
                "overflow", "value", "difference",
                std::string{rejectedPort}));
            edges.push_back(connection(
                "finite", "value", "difference",
                rejectedPort == "left" ? "right" : "left"));
        }
        edges.push_back(connection(
            "difference", "value", "vca", "gain"));

        const auto result = renderDocument(
            makeVcaDocument(std::move(nodes), std::move(edges)), 4.0, 5);
        require(!result.ok() && result.mono.empty(),
            "C124 offline Difference should reject its "
                + std::string{rejectedPort}
                + " failure without publishing output");
        require(hasDiagnostic(
                    result, DiagnosticCode::GraphValidationFailed,
                    "difference", rejectedPort),
            "C124 offline Difference should report its rejected "
                + std::string{rejectedPort} + " boundary");
    };

    requireRejected("left");
    requireRejected("right");
    requireRejected("value");
}

