void testEqualityRejectsNonFiniteEitherLaneWithoutPublishingOutput()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    const auto requireRejectedLane = [](std::string_view rejectedPort) {
        auto document = makeVcaDocument(
            {
                node("largeA", "talas.constant", {{"value", "1e308"}}),
                node("largeB", "talas.constant", {{"value", "1e308"}}),
                node("finite", "talas.constant", {{"value", "1"}}),
                node("overflow", "talas.add"),
                node("equal", "talas.equality"),
            },
            {
                connection("largeA", "value", "overflow", "left"),
                connection("largeB", "value", "overflow", "right"),
                connection(
                    "overflow", "value", "equal",
                    std::string{rejectedPort}),
                connection(
                    "finite", "value", "equal",
                    rejectedPort == "left" ? "right" : "left"),
                connection("equal", "value", "vca", "gain"),
            });

        const auto result = renderDocument(document, 4.0, 5);
        require(!result.ok() && result.mono.empty(),
            "C121 offline Equality should reject a non-finite "
                + std::string{rejectedPort}
                + " predecessor without publishing output");
        require(hasDiagnostic(
                    result, DiagnosticCode::GraphValidationFailed,
                    "equal", rejectedPort),
            "C121 offline Equality should report its rejected "
                + std::string{rejectedPort} + " input");
    };

    requireRejectedLane("left");
    requireRejectedLane("right");
}

