void testOscillatorRendersLinearWavetableCycle()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "osc",
        "talas.oscillator",
        {
            {"frequency", "1 hz"},
            {"amplitude", "1.0"},
            resourceParameter("wavetable", "Tables/Osc"),
            choiceParameter("interpolation", "linear"),
        }));
    document.graph.connections.push_back(connection("osc", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = {{"Tables/Osc", {1.0, 2.0, 4.0, 8.0}}};

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "wavetable oscillator document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "wavetable oscillator render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.mono.size() == 5, "wavetable oscillator render should return requested frames");
    const std::vector<double> expected = {1.0, 2.0, 4.0, 8.0, 1.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "wavetable oscillator frame " + std::to_string(frame));
}

