void testOscillatorConnectedControlsIgnoreForgedNonFiniteFallbacks()
{
    const auto makeDocument = [] {
        auto document = makeOscillatorToOutputDocument("1 hz", "0.5");
        document.graph.nodes[1].parameters.push_back({"pitchBend", "0"});
        document.graph.nodes[1].parameters.push_back({"reset", "0"});
        for (const auto [id, value] : {
                 std::pair{"frequency", "1"},
                 std::pair{"amplitude", "0.5"},
                 std::pair{"pitchBend", "0"},
                 std::pair{"reset", "0"},
             })
        {
            const auto source = std::string{id} + "Control";
            document.graph.nodes.push_back(node(
                source, "talas.constant", {{"value", value}}));
            document.graph.connections.push_back(connection(
                source, "value", "osc", id));
        }
        return document;
    };

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    const auto candidateCompile = talas::runtime::compileProject(
        makeDocument(), makeRegistry(), settings);
    const auto referenceCompile = talas::runtime::compileProject(
        makeDocument(), makeRegistry(), settings);
    require(candidateCompile.ok() && referenceCompile.ok(),
        "C95 connected-control fallback fixtures should compile");
    auto& plan = const_cast<talas::runtime::RuntimePlan&>(
        candidateCompile.graph->plan());
    const auto oscillator = std::ranges::find(
        plan.steps, std::string_view{"talas.oscillator"},
        &talas::runtime::CompileStep::typeId);
    require(oscillator != plan.steps.end(),
        "C95 connected-control fallback fixture should expose Oscillator");
    for (const auto parameterId : {
             std::string_view{"frequency"},
             std::string_view{"amplitude"},
             std::string_view{"pitchBend"},
             std::string_view{"reset"},
         })
    {
        const auto parameter = std::ranges::find(
            oscillator->parameters, parameterId,
            &talas::runtime::ParameterValue::id);
        require(parameter != oscillator->parameters.end(),
            "C95 forged fallback fixture should expose "
                + std::string{parameterId});
        parameter->value = std::numeric_limits<double>::infinity();
    }

    const auto actual = talas::runtime::renderOffline(
        *candidateCompile.graph, 4);
    const auto expected = talas::runtime::renderOffline(
        *referenceCompile.graph, 4);
    require(actual.ok() && expected.ok() && actual.mono == expected.mono,
        "C95 connected controls should own forged non-finite offline fallbacks");
}

void testOscillatorRejectsForgedOfflineKernelAuthority()
{
    const auto renderForged = [](bool removeKernelKind) {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = 4;
        auto compiled = talas::runtime::compileProject(
            makeOscillatorToOutputDocument("1 hz", "1.0"),
            makeRegistry(), settings);
        require(compiled.ok(),
            "C95 forged offline Oscillator fixture should compile before mutation");
        auto& plan = const_cast<talas::runtime::RuntimePlan&>(
            compiled.graph->plan());
        const auto oscillator = std::ranges::find(
            plan.steps, std::string_view{"talas.oscillator"},
            &talas::runtime::CompileStep::typeId);
        require(oscillator != plan.steps.end(),
            "C95 forged offline fixture should expose Oscillator");
        if (removeKernelKind)
            oscillator->kernelKind.reset();
        else
            oscillator->offlineBinding =
                talas::core::ExecutionBinding::LegacyAdapter;
        return talas::runtime::renderOffline(*compiled.graph, 4);
    };

    const auto missingKind = renderForged(true);
    const auto legacyBinding = renderForged(false);
    require(!missingKind.ok() && missingKind.mono.empty(),
        "C95 offline Oscillator should reject a missing kernel kind atomically");
    require(!legacyBinding.ok() && legacyBinding.mono.empty(),
        "C95 offline Oscillator should reject a forged legacy binding atomically");

    auto neutralSettings = talas::runtime::RenderSettings{4.0, 4};
    const auto neutralCompile = talas::runtime::compileProject(
        makeOscillatorToOutputDocument("1 hz", "1.0"),
        makeRegistry(), neutralSettings);
    require(neutralCompile.ok(),
        "C95 neutral coherent-forge fixture should compile before mutation");
    auto& neutralPlan = const_cast<talas::runtime::RuntimePlan&>(
        neutralCompile.graph->plan());
    const auto neutralOscillator = std::ranges::find(
        neutralPlan.steps, std::string_view{"talas.oscillator"},
        &talas::runtime::CompileStep::typeId);
    require(neutralOscillator != neutralPlan.steps.end(),
        "C95 neutral coherent-forge fixture should expose Oscillator");
    neutralOscillator->kernelKind.reset();
    neutralOscillator->offlineBinding =
        talas::core::ExecutionBinding::LegacyAdapter;
    const auto mismatchedNeutralLegacy = talas::runtime::renderOffline(
        *neutralCompile.graph, 4);
    require(!mismatchedNeutralLegacy.ok()
            && mismatchedNeutralLegacy.mono.empty(),
        "C95 offline Oscillator should reject legacy authority while prepared binding remains Kernel");

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    auto nonNeutralDocument = makeOscillatorToOutputDocument(
        "1 hz", "1.0");
    nonNeutralDocument.graph.nodes[1].parameters.push_back(
        {"envelope", "0.5"});
    const auto coherentCompile = talas::runtime::compileProject(
        nonNeutralDocument, makeRegistry(), settings);
    require(coherentCompile.ok(),
        "C95 coherent forged legacy fixture should compile before mutation");
    auto& coherentPlan = const_cast<talas::runtime::RuntimePlan&>(
        coherentCompile.graph->plan());
    const auto coherentOscillator = std::ranges::find(
        coherentPlan.steps, std::string_view{"talas.oscillator"},
        &talas::runtime::CompileStep::typeId);
    require(coherentOscillator != coherentPlan.steps.end(),
        "C95 coherent forged legacy fixture should expose Oscillator");
    coherentOscillator->kernelKind.reset();
    coherentOscillator->offlineBinding =
        talas::core::ExecutionBinding::LegacyAdapter;
    coherentOscillator->preparedRealtimeBinding =
        talas::core::ExecutionBinding::LegacyAdapter;
    const auto coherentLegacy = talas::runtime::renderOffline(
        *coherentCompile.graph, 4);
    require(!coherentLegacy.ok() && coherentLegacy.mono.empty(),
        "C95 offline Oscillator should reject coherent legacy authority for a non-neutral profile");
}

void testOscillatorFailureRollsBackOfflinePhaseBeforeRetry()
{
    const auto makeDocument = [] {
        auto document = makeOscillatorToOutputDocument("1 hz", "1.0");
        document.graph.nodes.push_back(node(
            "z_failureLeft", "talas.constant", {
                {"value", "!C95OfflineDownstream"},
            }));
        document.graph.nodes.push_back(node(
            "z_failureRight", "talas.constant", {
                {"value", "!C95OfflineDownstream"},
            }));
        document.graph.nodes.push_back(node(
            "z_failureProduct", "talas.product"));
        document.graph.nodes.push_back(node(
            "z_failureCheck", "talas.scaleAndOffset",
            {{"scale", "1"}, {"offset", "0"}}));
        document.graph.nodes.push_back(node(
            "z_failureCarrier", "talas.oscillator", {
                {"frequency", "0.25 hz"}, {"amplitude", "1"},
            }));
        document.graph.nodes.push_back(node("z_failure", "talas.vca"));
        document.graph.nodes.push_back(node(
            "zz_mix", "talas.mixer", {{"gain1", "1"}, {"gain2", "1"}}));
        std::erase_if(document.graph.connections, [](const auto& edge) {
            return edge.fromNode == "osc" && edge.toNode == "out";
        });
        document.graph.connections.push_back(connection(
            "z_failureLeft", "value", "z_failureProduct", "left"));
        document.graph.connections.push_back(connection(
            "z_failureRight", "value", "z_failureProduct", "right"));
        document.graph.connections.push_back(connection(
            "z_failureProduct", "value", "z_failureCheck", "value"));
        document.graph.connections.push_back(connection(
            "z_failureCarrier", "audioOut", "z_failure", "audioIn"));
        document.graph.connections.push_back(connection(
            "z_failureCheck", "value", "z_failure", "gain"));
        document.graph.connections.push_back(connection(
            "osc", "audioOut", "zz_mix", "in1"));
        document.graph.connections.push_back(connection(
            "z_failure", "audioOut", "zz_mix", "in2"));
        document.graph.connections.push_back(connection(
            "zz_mix", "audioOut", "out", "audioIn"));
        return document;
    };

    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.eventValues = {
        {"C95OfflineDownstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C95OfflineDownstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        makeDocument(), makeRegistry(), settings);
    require(compiled.ok(), "C95 offline rollback fixture should compile");
    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    require(candidate.render(2).ok(),
        "C95 should establish Oscillator phase state");
    const auto rejected = candidate.render(2);
    const auto retry = candidate.render(1);

    auto referenceSettings = settings;
    referenceSettings.eventValueChanges.clear();
    const auto referenceCompiled = talas::runtime::compileProject(
        makeDocument(), makeRegistry(), referenceSettings);
    require(referenceCompiled.ok(), "C95 offline reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(2).ok(),
        "C95 offline reference should establish phase state");
    const auto referenceRetry = reference.render(1);
    require(!rejected.ok() && rejected.mono.empty(),
        "C95 later offline failure should reject the whole transaction without audio");
    require(retry.ok() && referenceRetry.ok()
            && retry.mono == referenceRetry.mono,
        "C95 failed offline transaction should restore Oscillator phase and scheduled controls before retry");
}

