void testVcaRejectsNonFiniteStaticGainAndProductAtItsOwnBoundary()
{
    {
        talas::runtime::RuntimePlan plan;
        plan.steps = {
            {
                "osc", "talas.oscillator", {},
                {
                    {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                    {"amplitude", talas::expr::ValueDomain::Scalar, 1.0},
                },
            },
            {
                "vca", "talas.vca",
                {binding("audioIn", "osc", "audioOut", 0)},
                {{
                    "gain", talas::expr::ValueDomain::Scalar,
                    std::numeric_limits<double>::infinity(),
                }},
            },
            {
                "out", "talas.audioOutput",
                {binding("audioIn", "vca", "audioOut", 1)},
                {},
            },
        };
        plan.buffers = {
            {"osc", "audioOut", talas::core::PortType::Audio, 4},
            {"vca", "audioOut", talas::core::PortType::Audio, 4},
        };
        plan.outputBufferIndex = 1;
        const auto result = talas::runtime::renderOffline(
            handBuiltGraph(std::move(plan)), 4);
        require(!result.ok() && result.mono.empty(),
            "C126 offline VCA should reject a non-finite static gain without publishing output");
        require(hasDiagnostic(
                    result, DiagnosticCode::GraphValidationFailed,
                    "vca", {}, "gain"),
            "C126 offline VCA should identify its rejected static gain");
    }

    const auto overflow = renderDocument(
        makeVcaDocument(
            {}, {}, {{"gain", "1e308"}},
            {{"frequency", "1 hz"}, {"amplitude", "2"}}),
        4.0,
        4);
    require(!overflow.ok() && overflow.mono.empty(),
        "C126 offline VCA should reject a finite overflowing product without publishing output");
    require(hasDiagnostic(
                overflow, DiagnosticCode::GraphValidationFailed,
                "vca", "audioOut"),
        "C126 offline VCA should identify its non-finite product boundary");
}

