void testColoredNoiseChoicesRenderFiniteBoundedSamples()
{
    for (const auto* type : {"white", "pink", "hotPink"})
    {
        const auto samples = renderNoiseSamples(
            {
                {"initialState", "0.125"},
                choiceParameter("type", type),
                {"frequency", "100 hz"},
                {"centerValue", "0.0"},
                {"scale", "1.0"},
            },
            32);

        bool hasMovement = false;
        for (std::size_t index = 0; index < samples.size(); ++index)
        {
            require(std::isfinite(samples[index]), std::string(type) + " noise sample should be finite");
            require(samples[index] >= -1.0 && samples[index] <= 1.0, std::string(type) + " noise sample should stay in raw range");
            if (index > 0 && samples[index] != samples[index - 1])
                hasMovement = true;
        }
        require(hasMovement, std::string(type) + " noise should change after initial state");
    }
}

