void testNoiseOfflineLateFailureAndZeroFrameAreAtomic()
{
    auto document = makeNoiseDocument({
        {"initialState", "1"},
        choiceParameter("type", "white"),
        {"frequency", "0 hz"},
        {"centerValue",
            std::to_string(std::numeric_limits<double>::max())},
        {"scale", "1"},
    });
    document.graph.nodes.push_back(node(
        "scaleControl", "talas.triggeredTableRead", {
            {"trigger", "1"},
            resourceParameter("wavetable", "Tables/C118LateScale"),
            {"gate", "1"},
            booleanParameter("ignoreLoops", true),
            booleanParameter("fromMemoryWriter", false),
        }));
    document.graph.connections.push_back(connection(
        "scaleControl", "value", "noise", "scale"));
    auto settings = talas::runtime::RenderSettings{8.0, 2};
    settings.tableResources = {
        {"Tables/C118LateScale",
            {1.0, std::numeric_limits<double>::max()}},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C118 late-failure offline Noise fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeNoise =
        talas::runtime::OfflineRenderSessionTestAccess::
            noiseState(session, "noise");

    const auto empty = session.render(0);
    require(empty.ok() && empty.mono.empty()
            && talas::runtime::OfflineRenderSessionTestAccess::state(session)
                == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    noiseState(session, "noise")
                == beforeNoise,
        "C118 zero-frame offline Noise render should be a strict state/history no-op");

    const auto rejected = session.render(2);
    require(!rejected.ok() && rejected.mono.empty()
            && talas::runtime::OfflineRenderSessionTestAccess::state(session)
                == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    noiseState(session, "noise")
                == beforeNoise,
        "C118 late offline Noise overflow should publish no output, generator, producer, frame, or history state");
}

