void testWaveshaperWavetablePreservesExtremeFiniteEndpointsAndMidpoint()
{
    const auto maximum = std::numeric_limits<double>::max();
    const auto result = renderWaveshaperDocument(
        wavetableWaveshaperParameters(),
        {-maximum, maximum},
        4);

    require(result.ok(), "extreme finite wavetable Waveshaper should render");
    require(result.mono.size() == 4,
        "extreme finite wavetable Waveshaper should publish every frame");
    require(
        std::ranges::all_of(result.mono, [](double sample) {
            return std::isfinite(sample);
        }),
        "extreme finite wavetable Waveshaper should publish only finite samples");
    require(result.mono[0] == 0.0,
        "extreme finite wavetable Waveshaper should preserve the exact midpoint");
    require(result.mono[1] == maximum,
        "extreme finite wavetable Waveshaper should preserve the exact right endpoint");
    require(result.mono[3] == -maximum,
        "extreme finite wavetable Waveshaper should preserve the exact left endpoint");
}

