void testWaveshaperPolynomialRejectsUnsupportedCoefficientText()
{
    requireWaveshaperRenderFailure(
        {choiceParameter("shapeFrom", "polynomial"), textParameter("coefficients", "")},
        "coefficients");
    // A coefficient may follow an Event Value; one that names no
    // Event Value fails to compile.
    const auto undeclared = talas::runtime::compileProject(
        makeWaveshaperDocument({choiceParameter("shapeFrom", "polynomial"),
            textParameter("coefficients", "{!Gain}")}),
        makeRegistry(),
        {4.0, 5});
    require(!undeclared.ok()
            && std::ranges::any_of(undeclared.diagnostics, [](const auto& diagnostic) {
                   return diagnostic.nodeId == "shape" && diagnostic.parameterId == "coefficients";
               }),
        "a Waveshaper coefficient naming no Event Value should fail to compile");
    requireWaveshaperRenderFailure(
        {choiceParameter("shapeFrom", "polynomial"), textParameter("coefficients", "{0 1")},
        "coefficients");
    requireWaveshaperRenderFailure(
        {choiceParameter("shapeFrom", "polynomial"), textParameter("coefficients", "0, 1")},
        "coefficients");
    requireWaveshaperRenderFailure(
        {choiceParameter("shapeFrom", "polynomial"), textParameter("coefficients", "0 1e309")},
        "coefficients");
}

