void testFirFilterSessionKeepsInputHistoryAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    const auto document = makeFirFilterDocument({textParameter("coefficients", "1 2")});
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "fir filter session document should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(3);
    const auto second = session.render(2);

    require(first.ok(), "first fir filter session render should not emit diagnostics");
    require(second.ok(), "second fir filter session render should not emit diagnostics");
    require(first.mono.size() == 3, "first fir filter session render should return requested frames");
    require(second.mono.size() == 2, "second fir filter session render should return requested frames");
    requireNear(first.mono[0], 0.0, 1.0e-12, "fir filter session first frame 0");
    requireNear(first.mono[1], 1.0, 1.0e-12, "fir filter session first frame 1");
    requireNear(first.mono[2], 2.0, 1.0e-12, "fir filter session first frame 2");
    requireNear(second.mono[0], -1.0, 1.0e-12, "fir filter session second frame 0");
    requireNear(second.mono[1], -2.0, 1.0e-12, "fir filter session second frame 1");
}

