void testShelvingFilterRejectsNonFiniteConnectedScale()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    auto document = makeShelvingFilterDocument(
        "talas.highShelvingFilter",
        {{"cutoffFreq", "500 hz"}, {"boostOrCut", "0"}, {"scale", "1.0"}},
        {{"frequency", "1000 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("a", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("b", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("scale", "talas.add"));
    document.graph.connections.push_back(connection("a", "value", "scale", "left"));
    document.graph.connections.push_back(connection("b", "value", "scale", "right"));
    document.graph.connections.push_back(connection("scale", "value", "shelf", "scale"));

    const auto result = renderDocument(document, 8000.0, 64);

    require(!result.ok(), "shelving filter should reject non-finite connected scale");
    require(result.mono.empty(), "failed connected-scale shelving render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "shelf", "scale", {}), "render should identify connected shelving scale input");
}

