void testTwoFormantElementConnectedScaleUpdatesPerFrame()
{
    const auto firstFormant = renderDocument(
        makeTwoFormantElementDocument(
            {
                {"formant1", "500 hz"},
                {"bandwidth1", "100 hz"},
                {"scale1", "1.0"},
                {"formant2", "1500 hz"},
                {"bandwidth2", "200 hz"},
                {"scale2", "0.0"},
            },
            {{"frequency", "500 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        6);
    const auto secondFormant = renderDocument(
        makeTwoFormantElementDocument(
            {
                {"formant1", "500 hz"},
                {"bandwidth1", "100 hz"},
                {"scale1", "0.0"},
                {"formant2", "1500 hz"},
                {"bandwidth2", "200 hz"},
                {"scale2", "1.0"},
            },
            {{"frequency", "500 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        6);

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 6;
    settings.tableResources.push_back({"Tables/Scale1", {1.0, 0.5, 0.0, 1.5, 1.0, 0.25}});
    settings.tableResources.push_back({"Tables/Scale2", {0.0, 1.0, 0.5, 1.0, 0.0, 1.5}});

    auto document = makeTwoFormantElementDocument(
        {
            {"formant1", "500 hz"},
            {"bandwidth1", "100 hz"},
            {"scale1", "0.0"},
            {"formant2", "1500 hz"},
            {"bandwidth2", "200 hz"},
            {"scale2", "0.0"},
        },
        {{"frequency", "500 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("scale1Control", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Scale1")})));
    document.graph.nodes.push_back(node("scale2Control", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Scale2")})));
    document.graph.connections.push_back(connection("scale1Control", "value", "formants", "scale1"));
    document.graph.connections.push_back(connection("scale2Control", "value", "formants", "scale2"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-scale two formant element document should compile before render");
    const auto dynamic = talas::runtime::renderOffline(*compile.graph, 6);

    require(firstFormant.ok(), "first-formant comparison render should not emit diagnostics");
    require(secondFormant.ok(), "second-formant comparison render should not emit diagnostics");
    require(dynamic.ok(), "dynamic-scale two formant element render should not emit diagnostics");
    require(dynamic.mono.size() == 6, "dynamic-scale two formant element should return requested frames");
    const std::vector<double> scale1{1.0, 0.5, 0.0, 1.5, 1.0, 0.25};
    const std::vector<double> scale2{0.0, 1.0, 0.5, 1.0, 0.0, 1.5};
    for (std::size_t frame = 0; frame < dynamic.mono.size(); ++frame)
    {
        const auto expected = firstFormant.mono[frame] * scale1[frame] + secondFormant.mono[frame] * scale2[frame];
        requireNear(dynamic.mono[frame], expected, 1.0e-12, "dynamic-scale two formant element frame " + std::to_string(frame));
    }
}

