void testTwoFormantElementConnectedFormantBandwidthUpdatesPerFrame()
{
    constexpr std::size_t frameCount = 512;
    const auto staticFirstFormant = renderDocument(
        makeTwoFormantElementDocument(
            {{"formant1", "500 hz"},
             {"bandwidth1", "100 hz"},
             {"scale1", "1.0"},
             {"formant2", "1500 hz"},
             {"bandwidth2", "200 hz"},
             {"scale2", "0.0"}},
            {{"frequency", "500 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        frameCount);

    std::vector<double> formant1(frameCount, 500.0);
    std::vector<double> bandwidth1(frameCount, 100.0);
    for (std::size_t frame = frameCount / 2; frame < frameCount; ++frame)
    {
        formant1[frame] = 1500.0;
        bandwidth1[frame] = 300.0;
    }

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = frameCount;
    settings.tableResources.push_back({"Tables/Formant1", std::move(formant1)});
    settings.tableResources.push_back({"Tables/Bandwidth1", std::move(bandwidth1)});

    auto document = makeTwoFormantElementDocument(
        {{"formant1", "500 hz"},
         {"bandwidth1", "100 hz"},
         {"scale1", "1.0"},
         {"formant2", "1500 hz"},
         {"bandwidth2", "200 hz"},
         {"scale2", "0.0"}},
        {{"frequency", "500 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("formant1Control", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Formant1")})));
    document.graph.nodes.push_back(node("bandwidth1Control", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Bandwidth1")})));
    document.graph.connections.push_back(connection("formant1Control", "value", "formants", "formant1"));
    document.graph.connections.push_back(connection("bandwidth1Control", "value", "formants", "bandwidth1"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-formant two formant element document should compile before render");
    const auto dynamic = talas::runtime::renderOffline(*compile.graph, frameCount);

    require(staticFirstFormant.ok(), "static first-formant comparison render should not emit diagnostics");
    require(dynamic.ok(), "dynamic-formant two formant element render should not emit diagnostics");
    require(dynamic.mono.size() == frameCount, "dynamic-formant two formant element should return requested frames");
    for (std::size_t frame = 0; frame < 128; ++frame)
        requireNear(dynamic.mono[frame], staticFirstFormant.mono[frame], 1.0e-12, "dynamic-formant two formant element first-half frame " + std::to_string(frame));

    double maxDelta = 0.0;
    for (std::size_t frame = 320; frame < frameCount; ++frame)
        maxDelta = std::max(maxDelta, std::abs(dynamic.mono[frame] - staticFirstFormant.mono[frame]));
    require(maxDelta > 1.0e-5, "dynamic formant/bandwidth controls should diverge from frame-0 static formant after table changes");
}

