talas::project::ProjectSoundDefinition makeC74SelectorTone(
    std::string definitionId,
    std::string frequency,
    std::string amplitude)
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = std::move(definitionId);
    definition.displayName = definition.definitionId;
    definition.graph.nodes = {node(
        "osc",
        "talas.oscillator",
        {{"frequency", std::move(frequency)},
         {"amplitude", std::move(amplitude)}})};
    definition.outputs = {
        {"audioOut", talas::core::PortType::Audio, "osc", "audioOut"},
    };
    return definition;
}

talas::project::ProjectDocument makeC74SoundVariableDocument(
    std::string typeId,
    talas::project::ProjectSoundVariableKind kind,
    std::uint16_t initialSelectedOrdinal = 0)
{
    talas::project::ProjectDocument document;
    document.soundDefinitions = {
        makeC74SelectorTone("toneA", "1.25 hz", "2"),
        makeC74SelectorTone("toneB", "2.5 hz", "4"),
    };
    talas::project::ProjectSoundVariableDeclaration declaration;
    declaration.variableId = "selected";
    declaration.displayName = "Selected Sound";
    declaration.kind = kind;
    declaration.candidateDefinitionIds = {"toneA", "toneB"};
    declaration.initialSelectedOrdinal = initialSelectedOrdinal;
    document.soundVariableLibrary.variables = {std::move(declaration)};
    document.graph.nodes = {
        node(
            "selector",
            typeId,
            {textParameter("variableId", "selected")}),
        node(
            "downstream",
            "talas.level",
            {{"left", "!C74Downstream"},
             {"right", "0"},
             booleanParameter("noGain", false)}),
        node("out", "talas.audioOutput"),
    };
    // The one-of-N selector of projects before format 90.
    if (typeId == "talas.soundCollectionVariable")
        document.graph.nodes.front().parameters.push_back(choiceParameter("members", "legacySelected"));
    document.graph.connections = {
        connection("selector", "audioOut", "downstream", "audioIn"),
        connection("downstream", "leftOut", "out", "audioIn"),
    };
    return document;
}

void testC74SoundVariableSelectorsRejectDownstreamFailureAtomically()
{
    const auto run = [](
                         std::string typeId,
                         talas::project::ProjectSoundVariableKind kind,
                         std::string_view context) {
        auto settings = talas::runtime::RenderSettings{128.0, 256};
        settings.eventValues = {
            {"C74Downstream", 1.0, talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {192, "C74Downstream", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar},
        };
        const auto compiled = talas::runtime::compileProject(
            makeC74SoundVariableDocument(typeId, kind),
            makeRegistry(),
            settings);
        require(
            compiled.ok()
                && compiled.graph->preparedSoundVariables().cells.size() == 1,
            std::string{context}
                + " downstream rollback fixture should compile one exact cell");
        const auto& cell =
            compiled.graph->preparedSoundVariables().cells.front();
        const std::array assignments{
            talas::runtime::OfflineSoundVariableAssignment{
                80, 1, 1, cell.identity, "toneB"},
        };

        talas::runtime::OfflineRenderSession candidate{*compiled.graph};
        talas::runtime::OfflineRenderSession reference{*compiled.graph};
        require(
            candidate.scheduleSoundVariableAssignments(assignments)
                && reference.scheduleSoundVariableAssignments(assignments),
            std::string{context}
                + " rollback fixtures should bind the same exact selection");
        const auto candidateSeed = candidate.render(64);
        const auto referenceSeed = reference.render(64);
        require(
            candidateSeed.ok() && referenceSeed.ok()
                && candidateSeed.mono == referenceSeed.mono,
            std::string{context}
                + " rollback fixtures should establish matching live state");

        const auto rejected = candidate.render(256);
        const auto retry = candidate.render(64);
        const auto expected = reference.render(64);
        require(
            !rejected.ok() && rejected.mono.empty(),
            std::string{context}
                + " late downstream overflow should publish no audio");
        require(
            retry.ok() && expected.ok() && retry.mono == expected.mono,
            std::string{context}
                + " rejected public render must restore candidate phases, the selected cell, and all four selector fields");
    };

    run(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        "C74 Variable");
    run(
        "talas.soundCollectionVariable",
        talas::project::ProjectSoundVariableKind::SoundCollection,
        "C74 Sound Collection Variable");
}

void testC74SoundVariableSelectorResetPreservesSelectionWithoutCrossfadeTail()
{
    const auto run = [](
                         std::string typeId,
                         talas::project::ProjectSoundVariableKind kind,
                         std::string_view context) {
        auto settings = talas::runtime::RenderSettings{128.0, 64};
        settings.eventValues = {
            {"C74Downstream", 1.0, talas::expr::ValueDomain::Scalar},
        };
        const auto selected = talas::runtime::compileProject(
            makeC74SoundVariableDocument(typeId, kind),
            makeRegistry(),
            settings);
        const auto selectedAtConstruction = talas::runtime::compileProject(
            makeC74SoundVariableDocument(typeId, kind, 1),
            makeRegistry(),
            settings);
        require(
            selected.ok() && selectedAtConstruction.ok()
                && selected.graph->preparedSoundVariables().cells.size() == 1,
            std::string{context}
                + " reset fixtures should compile exact initial selections");
        const auto& cell =
            selected.graph->preparedSoundVariables().cells.front();
        const std::array assignments{
            talas::runtime::OfflineSoundVariableAssignment{
                32, 1, 1, cell.identity, "toneB"},
        };

        talas::runtime::OfflineRenderSession session{*selected.graph};
        require(
            session.scheduleSoundVariableAssignments(assignments)
                && session.render(32).ok()
                && session.render(32).ok(),
            std::string{context}
                + " reset fixture should enter the selected branch crossfade");
        const auto beforeReset = session.soundVariableValues();
        require(
            beforeReset.size() == 1
                && beforeReset.front().selectedDefinitionId == "toneB",
            std::string{context}
                + " reset fixture should publish the live selected Sound");

        session.reset();
        const auto afterReset = session.soundVariableValues();
        talas::runtime::OfflineRenderSession reference{
            *selectedAtConstruction.graph};
        const auto actual = session.render(32);
        const auto expected = reference.render(32);
        require(
            afterReset.size() == 1
                && afterReset.front().selectedDefinitionId == "toneB",
            std::string{context}
                + " transport reset must preserve the live selected Sound cell");
        require(
            actual.ok() && expected.ok() && actual.mono == expected.mono,
            std::string{context}
                + " transport reset must clear stale crossfade history and start directly on the selected branch");
        const auto actualSecond = session.render(32);
        const auto expectedSecond = reference.render(32);
        const auto afterSecondBlock = session.soundVariableValues();
        require(
            actualSecond.ok() && expectedSecond.ok()
                && actualSecond.mono == expectedSecond.mono
                && afterSecondBlock.size() == 1
                && afterSecondBlock.front().selectedDefinitionId == "toneB",
            std::string{context}
                + " reset-preserved selection must remain the reconstruction baseline after multiple public blocks");
    };

    run(
        "talas.variable",
        talas::project::ProjectSoundVariableKind::Sound,
        "C74 Variable");
    run(
        "talas.soundCollectionVariable",
        talas::project::ProjectSoundVariableKind::SoundCollection,
        "C74 Sound Collection Variable");
}

void testTwoFormantPairOfflineDownstreamFailureIsAtomic()
{
    const auto run = [](
                         talas::project::ProjectDocument document,
                         std::string sourceNodeId,
                         std::string_view context) {
        document.graph.nodes.push_back(node(
            "downstream", "talas.level", {
                {"left", "!C73Downstream"}, {"right", "0"},
                booleanParameter("noGain", false),
            }));
        std::erase_if(
            document.graph.connections,
            [&](const talas::core::Connection& edge) {
                return edge.fromNode == sourceNodeId
                    && edge.toNode == "out";
            });
        document.graph.connections.push_back(connection(
            sourceNodeId, "audioOut", "downstream", "audioIn"));
        document.graph.connections.push_back(connection(
            "downstream", "leftOut", "out", "audioIn"));

        auto settings = talas::runtime::RenderSettings{8000.0, 256};
        settings.eventValues = {
            {"C73Downstream", 1.0, talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {192, "C73Downstream", std::numeric_limits<double>::max(),
                talas::expr::ValueDomain::Scalar},
        };
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(
            compiled.ok(),
            std::string{context} + " rollback fixture should compile");

        talas::runtime::OfflineRenderSession candidate{*compiled.graph};
        talas::runtime::OfflineRenderSession reference{*compiled.graph};
        const auto candidateSeed = candidate.render(64);
        const auto referenceSeed = reference.render(64);
        require(
            candidateSeed.ok() && referenceSeed.ok()
                && candidateSeed.mono == referenceSeed.mono,
            std::string{context}
                + " rollback fixture should establish matching live state");

        const auto rejected = candidate.render(256);
        const auto retry = candidate.render(64);
        const auto expected = reference.render(64);
        require(
            !rejected.ok() && rejected.mono.empty(),
            std::string{context}
                + " late downstream overflow should publish no offline audio");
        require(
            retry.ok() && expected.ok() && retry.mono == expected.mono,
            std::string{context}
                + " rejected public render must restore every entry-live state value");

        candidate.reset();
        talas::runtime::OfflineRenderSession pristine{*compiled.graph};
        const auto reset = candidate.render(64);
        const auto fresh = pristine.render(64);
        require(
            reset.ok() && fresh.ok() && reset.mono == fresh.mono,
            std::string{context}
                + " reset should reproduce the pristine state trajectory");
    };

    run(
        makeTwoFormantElementDocument(
            {{"formant1", "200 hz"},
             {"bandwidth1", "80 hz"},
             {"scale1", "16"},
             {"formant2", "600 hz"},
             {"bandwidth2", "120 hz"},
             {"scale2", "-8"}},
            {{"frequency", "200 hz"}, {"amplitude", "1"}}),
        "formants",
        "C73 Two Formant Element");
    run(
        makeTwoFormantVoiceElementDocument(
            {{"frequency", "200 hz"},
             {"formant1", "200 hz"},
             {"bandwidth1", "80 hz"},
             {"scale1", "16"},
             {"formant2", "600 hz"},
             {"bandwidth2", "120 hz"},
             {"scale2", "-8"},
             {"seed", "123"}}),
        "voice",
        "C73 Two Formant Voice Element");
}

