void testHandBuiltTwoFormantVoiceElementRejectsNyquistFrequencyAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 5;

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "voice",
            "talas.twoFormantVoiceElement",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 4000.0},
                {"formant1", talas::expr::ValueDomain::Hertz, 500.0},
                {"bandwidth1", talas::expr::ValueDomain::Hertz, 100.0},
                {"scale1", talas::expr::ValueDomain::Scalar, 1.0},
                {"formant2", talas::expr::ValueDomain::Hertz, 1500.0},
                {"bandwidth2", talas::expr::ValueDomain::Hertz, 200.0},
                {"scale2", talas::expr::ValueDomain::Scalar, 0.5},
                {"seed", talas::expr::ValueDomain::Scalar, 123.0},
            },
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "voice", "audioOut", 0)},
            {},
        },
    };
    plan.buffers = {{"voice", "audioOut", talas::core::PortType::Audio, 5}};
    plan.outputBufferIndex = 0;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 5);

    require(!result.ok(), "two formant voice with Nyquist frequency should fail render");
    require(result.mono.empty(), "failed two formant voice render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "voice", {}, "frequency"), "render should identify two formant voice frequency");
}

