void testDualParallelTwoPoleFilterSessionKeepsPoleHistoriesAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    const auto document = makeDualParallelTwoPoleFilterDocument({
        textParameter("pole1", "0.25 % 0"),
        {"scale1", "1.0"},
        textParameter("pole2", "0 % 0"),
        {"scale2", "0.5"},
    });
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dual parallel two pole document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(3);
    const auto oneShot = renderDocument(document, 4.0, 5);

    require(first.ok(), "first dual parallel two pole session render should not emit diagnostics");
    require(second.ok(), "second dual parallel two pole session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot dual parallel two pole render should not emit diagnostics");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "dual parallel two pole session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "dual parallel two pole session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "dual parallel two pole session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "dual parallel two pole session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "dual parallel two pole session second frame 2");
}

