void testHarmonicResonatorFreezesCapacityGrowthAcrossSessionCalls()
{
    auto document = makeHarmonicResonatorDocument({
        {"decayTime", "0.25 s"},
        {"brightness", "1.0"},
        {"frequency", "4 hz"},
        resourceParameter("wavetable", "Private"),
        booleanParameter("prezero", true),
        {"scale", "1.0"},
    });
    document.graph.nodes.push_back(node(
        "frequency", "talas.linearRamp", {
            {"duration", "1 s"}, {"start", "4.0"}, {"end", "2.0"},
        }));
    document.graph.connections.push_back(connection(
        "frequency", "value", "resonator", "frequency"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 6;
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "capacity-growth Harmonic Resonator fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(2);
    const auto second = session.render(4);
    require(
        first.ok() && second.ok(),
        "capacity-growth Harmonic Resonator session should render");
    constexpr std::array expectedFirst{0.0, 0.0};
    constexpr std::array expectedSecond{
        1.0, 1.0, 0.0001, -0.9999841510680754};
    for (std::size_t frame = 0; frame < expectedFirst.size(); ++frame)
    {
        requireNear(
            first.mono[frame], expectedFirst[frame], 1.0e-12,
            "capacity-growth Harmonic Resonator first call frame");
    }
    for (std::size_t frame = 0; frame < expectedSecond.size(); ++frame)
    {
        requireNear(
            second.mono[frame], expectedSecond[frame], 1.0e-12,
            "capacity-growth Harmonic Resonator second call frame");
    }
}

