// ADR-0025 (2026-10-10): a HarmonicResonator naming a Wavetable shares
// its line with the Sounds naming it; alone on its line it plays as with
// Private memory.
void testHarmonicResonatorRejectsUnsupportedMemoryModesAtRender()
{
    const auto resonator = [](std::string wavetable) {
        return renderDocument(makeHarmonicResonatorDocument({
                                  {"decayTime", "0.25 s"},
                                  {"brightness", "1.0"},
                                  {"frequency", "1 hz"},
                                  resourceParameter("wavetable", std::move(wavetable)),
                                  booleanParameter("prezero", true),
                                  {"scale", "1.0"},
                              }),
            4.0, 12);
    };
    const auto shared = resonator("SharedDelay");
    const auto alone = resonator("Private");
    require(shared.ok() && alone.ok() && shared.mono.size() == alone.mono.size(),
        "a HarmonicResonator naming a Wavetable should render");
    for (std::size_t frame = 0; frame < alone.mono.size(); ++frame)
        requireNear(shared.mono[frame], alone.mono[frame], 1.0e-12, "a lone shared HarmonicResonator frame " + std::to_string(frame));
    require(std::ranges::any_of(alone.mono, [](double sample) { return sample != 0.0; }),
        "the lone HarmonicResonator fixture should be heard");
}

talas::runtime::OfflineRenderResult renderReResonatorDocument(
    std::vector<talas::project::ProjectParameterExpression> resonatorParameters,
    std::vector<double> coefficients,
    std::size_t frameCount)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = frameCount;
    settings.tableResources.push_back({"Tables/RE", std::move(coefficients)});

    const auto document = makeReResonatorDocument(std::move(resonatorParameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "RE resonator document should compile before render");
    return talas::runtime::renderOffline(*compile.graph, frameCount);
}

