void requireReResonatorRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> resonatorParameters,
    std::vector<talas::runtime::TableResource> tableResources,
    std::string_view parameterId)
{
    const auto result = renderInvalidReResonatorDocument(std::move(resonatorParameters), std::move(tableResources));
    require(!result.ok(), "unsupported RE resonator configuration should fail render");
    require(result.mono.empty(), "failed RE resonator render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "resonator", {}, parameterId), "render should identify RE resonator parameter");
}

void testReResonatorRejectsInvalidResourcesAtRender()
{
    requireReResonatorRenderFailure(
        {resourceParameter("wavetable", "Tables/Missing"), {"timeIndex", "0.0"}},
        {{"Tables/RE", {1.0}}},
        "wavetable");
    requireReResonatorRenderFailure(
        {resourceParameter("wavetable", "Tables/RE"), {"timeIndex", "0.0"}},
        {{"Tables/RE", {}}},
        "wavetable");
    requireReResonatorRenderFailure(
        {resourceParameter("wavetable", "Tables/RE"), {"timeIndex", "0.0"}},
        {{"Tables/RE", {1.0, std::numeric_limits<double>::infinity()}}},
        "wavetable");
}

void testReResonatorRejectsOrderedOverflowBeforeLaterCancellation()
{
    const auto result = renderReResonatorDocument(
        {resourceParameter("wavetable", "Tables/RE"),
         {"timeIndex", "0.0"}},
        {1.1e308, 1.1e308, -1.1e308},
        5);

    require(
        !result.ok(),
        "RE Resonator should reject an overflowing ordered sum before a later cancelling tap");
    require(
        result.mono.empty(),
        "failed RE Resonator arithmetic should publish no offline audio");
    require(
        hasDiagnostic(
            result,
            DiagnosticCode::GraphValidationFailed,
            "resonator",
            "audioIn",
            {}),
        "RE Resonator overflow should identify checked audio arithmetic");
}

void testHandBuiltReResonatorRejectsInvalidTimeIndexAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/RE", {1.0}});

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "osc",
            "talas.oscillator",
            {},
            {{"frequency", talas::expr::ValueDomain::Hertz, 1.0}, {"amplitude", talas::expr::ValueDomain::Scalar, 1.0}},
        },
        {
            "resonator",
            "talas.reResonator",
            {binding("audioIn", "osc", "audioOut", 0)},
            {resourceRuntimeParameter("wavetable", "Tables/RE"), {"timeIndex", talas::expr::ValueDomain::Scalar, 2.0},
                choiceRuntimeParameter("filterForm", "legacyFir")},
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "resonator", "audioOut", 1)},
            {},
        },
    };
    plan.buffers = {
        {"osc", "audioOut", talas::core::PortType::Audio, 5},
        {"resonator", "audioOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 5);

    require(!result.ok(), "stale invalid timeIndex RE resonator render should fail");
    require(result.mono.empty(), "failed stale RE resonator render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "resonator", {}, "timeIndex"), "render should identify stale RE resonator timeIndex");
}

