void testGraphicEqConnectedBandLevelUpdatesPerFrame()
{
    const auto unity = renderDocument(
        makeGraphicEqDocument(
            {{"cf250Hz", "1.0"},
             {"cf500Hz", "1.0"},
             {"cf1000Hz", "1.0"},
             {"cf2000Hz", "1.0"},
             {"cf4000Hz", "1.0"},
             {"cf8000Hz", "1.0"},
             {"cf16000Hz", "1.0"}},
            {{"frequency", "500 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        4096);
    const auto boost = renderDocument(
        makeGraphicEqDocument(
            {{"cf250Hz", "1.0"},
             {"cf500Hz", "2.0"},
             {"cf1000Hz", "1.0"},
             {"cf2000Hz", "1.0"},
             {"cf4000Hz", "1.0"},
             {"cf8000Hz", "1.0"},
             {"cf16000Hz", "1.0"}},
            {{"frequency", "500 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        4096);

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 256;
    settings.tableResources.push_back({"Tables/Levels", {1.0, 2.0, 1.5, 1.0, 0.5, 2.0}});

    auto document = makeGraphicEqDocument(
        {{"cf250Hz", "1.0"},
         {"cf500Hz", "1.0"},
         {"cf1000Hz", "1.0"},
         {"cf2000Hz", "1.0"},
         {"cf4000Hz", "1.0"},
         {"cf8000Hz", "1.0"},
         {"cf16000Hz", "1.0"}},
        {{"frequency", "500 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("level", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Levels")})));
    document.graph.connections.push_back(connection("level", "value", "eq", "cf500Hz"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-level graphic eq document should compile before render");
    const auto dynamic = talas::runtime::renderOffline(*compile.graph, 6);

    require(unity.ok(), "unity graphic eq comparison render should not emit diagnostics");
    require(boost.ok(), "boosted graphic eq comparison render should not emit diagnostics");
    require(dynamic.ok(), "dynamic-level graphic eq render should not emit diagnostics");
    require(dynamic.mono.size() == 6, "dynamic-level graphic eq should return requested frames");
    const std::vector<double> levels{1.0, 2.0, 1.5, 1.0, 0.5, 2.0};
    for (std::size_t frame = 0; frame < levels.size(); ++frame)
    {
        const auto bandContribution = boost.mono[frame] - unity.mono[frame];
        const auto expected = unity.mono[frame] + bandContribution * (levels[frame] - 1.0);
        requireNear(dynamic.mono[frame], expected, 1.0e-12, "dynamic-level graphic eq frame " + std::to_string(frame));
    }
}

