void testSingleSideBandRmUnityScaleUsesLowerPhasePairBranch()
{
    const auto samples = renderSingleSideBandRmSamples(
        "1 hz", "1.0", "1 hz", 4.0, 128);
    for (std::size_t frame = 64; frame < samples.size(); ++frame)
    {
        // sin(pi*frame/2 - pi/4), without large-angle argument rounding.
        const auto expected = (frame % 4 == 0 || frame % 4 == 3 ? -1.0 : 1.0)
            / std::sqrt(2.0);
        require(
            std::abs(samples[frame] - expected) <= 1.0e-14,
            "unity-scale SSB should follow its -45-degree target-frequency phase pair at frame "
                + std::to_string(frame));
    }
}

void testSingleSideBandRmShiftsTargetFrequencyUp()
{
    const auto samples = renderSingleSideBandRmSamples("100 hz", "2.0", "100 hz", 8000.0, 4096);

    const auto target = toneCorrelationMagnitude(samples, 8000.0, 200.0, 1024);
    const auto source = toneCorrelationMagnitude(samples, 8000.0, 100.0, 1024);

    require(target > 0.65, "single side band rm should preserve strong shifted-up target energy");
    require(target > source * 4.0, "single side band rm should favor shifted-up energy over source energy");
}

void testSingleSideBandRmShiftsTargetFrequencyDown()
{
    const auto samples = renderSingleSideBandRmSamples("200 hz", "0.5", "200 hz", 8000.0, 4096);

    const auto target = toneCorrelationMagnitude(samples, 8000.0, 100.0, 1024);
    const auto source = toneCorrelationMagnitude(samples, 8000.0, 200.0, 1024);

    require(target > 0.65, "single side band rm should preserve strong shifted-down target energy");
    require(target > source * 4.0, "single side band rm should favor shifted-down energy over source energy");
}

