void testSingleSideBandRmConnectedFrequencyUpdatesPerFrame()
{
    constexpr std::size_t frameCount = 1024;
    const auto staticFrequency = renderDocument(
        makeSingleSideBandRmDocument(
            {{"frequency", "100 hz"}, {"freqScale", "2.0"}},
            {{"frequency", "100 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        frameCount);

    std::vector<double> frequency(frameCount, 100.0);
    for (std::size_t frame = frameCount / 2; frame < frameCount; ++frame)
        frequency[frame] = 200.0;

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = frameCount;
    settings.tableResources.push_back({"Tables/Frequency", std::move(frequency)});

    auto document = makeSingleSideBandRmDocument(
        {{"frequency", "100 hz"}, {"freqScale", "2.0"}},
        {{"frequency", "100 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("frequencyControl", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Frequency")})));
    document.graph.connections.push_back(connection("frequencyControl", "value", "ssb", "frequency"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-frequency single side band rm document should compile before render");
    const auto dynamic = talas::runtime::renderOffline(*compile.graph, frameCount);

    require(staticFrequency.ok(), "static-frequency single side band rm comparison should render");
    require(dynamic.ok(), "dynamic-frequency single side band rm render should not emit diagnostics");
    require(dynamic.mono.size() == frameCount, "dynamic-frequency single side band rm should return requested frames");
    for (std::size_t frame = 0; frame < 128; ++frame)
        requireNear(dynamic.mono[frame], staticFrequency.mono[frame], 1.0e-12, "dynamic-frequency single side band rm first-half frame " + std::to_string(frame));

    double maxDelta = 0.0;
    for (std::size_t frame = 640; frame < frameCount; ++frame)
        maxDelta = std::max(maxDelta, std::abs(dynamic.mono[frame] - staticFrequency.mono[frame]));
    require(maxDelta > 1.0e-5, "dynamic single side band rm frequency should diverge from frame-0 static frequency after table changes");
}

