void testPhaseShiftBy90ConnectedFrequencyUpdatesPerFrame()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput", audioInputParameters()));
    document.graph.nodes.push_back(node("frequency", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Frequency")})));
    document.graph.nodes.push_back(node("phase", "talas.phaseShiftBy90", {{"frequency", "1 hz"}, choiceParameter("overflow", "unclipped")}));
    document.graph.connections.push_back(connection("input", "audioOut", "phase", "audioIn"));
    document.graph.connections.push_back(connection("frequency", "value", "phase", "frequency"));
    document.graph.connections.push_back(connection("phase", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.audioInputChannels.push_back({1, {1.0, 0.0, 0.0, 0.0}});
    settings.tableResources = {{"Tables/Frequency", {1.0, 1.0, 0.5, 1.0}}};

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-frequency phase shift by 90 document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);
    const auto rootTwo = std::sqrt(2.0);
    const auto r = rootTwo - 1.0;
    const std::vector<double> expected = {
        r, -2.0 * r, rootTwo - 2.0, 4.0 - 3.0 * rootTwo};

    require(result.ok(), "dynamic-frequency phase shift by 90 render should not emit diagnostics");
    require(result.mono.size() == expected.size(), "dynamic-frequency phase shift by 90 render should return requested frames");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic-frequency phase shift by 90 frame " + std::to_string(frame));
}

