void testPhaseShiftBy90DirectScheduleIsPartitionResetAndFailureAtomic()
{
    const auto directDocument = makePhaseShiftBy90Document(
        {{"frequency", "!C165Frequency"}},
        {{"frequency", "0.5 hz"}, {"amplitude", "0.75"}});
    auto connectedDocument = makePhaseShiftBy90Document(
        {{"frequency", "1e200 * 1e200"}},
        {{"frequency", "0.5 hz"}, {"amplitude", "0.75"}});
    connectedDocument.graph.nodes.push_back(node(
        "frequencyControl", "talas.constant", {
            {"value", "!C165ConnectedFrequency"},
        }));
    connectedDocument.graph.connections.push_back(connection(
        "frequencyControl", "value", "phase", "frequency"));

    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.eventValues = {
        {"C165Frequency", 0.5, talas::expr::ValueDomain::Hertz},
        {"C165ConnectedFrequency", 0.5,
            talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C165Frequency", 1.0, talas::expr::ValueDomain::Hertz},
        {2, "C165ConnectedFrequency", 1.0,
            talas::expr::ValueDomain::Scalar},
        {5, "C165Frequency", 1.5, talas::expr::ValueDomain::Hertz},
        {5, "C165ConnectedFrequency", 1.5,
            talas::expr::ValueDomain::Scalar},
    };
    const auto directCompiled = talas::runtime::compileProject(
        directDocument, makeRegistry(), settings);
    const auto connectedCompiled = talas::runtime::compileProject(
        connectedDocument, makeRegistry(), settings);
    require(directCompiled.ok() && connectedCompiled.ok(),
        "C165 direct and connected scheduled-frequency fixtures should compile");
    const auto phase = std::ranges::find(
        directCompiled.graph->plan().steps,
        std::string_view{"talas.phaseShiftBy90"},
        &talas::runtime::CompileStep::typeId);
    require(phase != directCompiled.graph->plan().steps.end()
            && phase->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && phase->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported,
        "C165 direct scheduled frequency should retain promoted authority");

    const auto connected = talas::runtime::renderOffline(
        *connectedCompiled.graph, 8);
    talas::runtime::OfflineRenderSession oneShot{*directCompiled.graph};
    talas::runtime::OfflineRenderSession partitioned{*directCompiled.graph};
    const auto expected = oneShot.render(8);
    const auto empty = partitioned.render(0);
    const auto first = partitioned.render(3);
    const auto second = partitioned.render(2);
    const auto third = partitioned.render(3);
    require(connected.ok() && expected.ok() && empty.ok()
            && empty.mono.empty() && first.ok() && second.ok()
            && third.ok(),
        "C165 scheduled allpass should render through zero and irregular offline partitions");
    auto actual = first.mono;
    actual.insert(actual.end(), second.mono.begin(), second.mono.end());
    actual.insert(actual.end(), third.mono.begin(), third.mono.end());
    require(expected.mono == connected.mono && actual == expected.mono,
        "C165 direct fallback, connected precedence, and partitioned schedules should be bit-exact");

    partitioned.reset();
    const auto reset = partitioned.render(8);
    require(reset.ok() && reset.mono == expected.mono,
        "C165 offline reset should reproduce a fresh direct schedule exactly");

    // A late frequency at Nyquist saturates below it (owner, 2026-10-12)
    // and renders alike in one block and across partitions.
    auto saturatingSettings = settings;
    saturatingSettings.eventValueChanges = {
        {5, "C165Frequency", 4.0, talas::expr::ValueDomain::Hertz},
    };
    const auto saturatingCompiled = talas::runtime::compileProject(
        directDocument, makeRegistry(), saturatingSettings);
    require(saturatingCompiled.ok(),
        "C165 late Nyquist scheduled-frequency fixture should compile");
    talas::runtime::OfflineRenderSession whole{*saturatingCompiled.graph};
    talas::runtime::OfflineRenderSession split{*saturatingCompiled.graph};
    const auto saturated = whole.render(8);
    const auto head = split.render(5);
    const auto tail = split.render(3);
    auto joined = head.mono;
    joined.insert(joined.end(), tail.mono.begin(), tail.mono.end());
    require(saturated.ok() && head.ok() && tail.ok() && joined == saturated.mono,
        "C165 a late Nyquist frequency should saturate and render alike across partitions");
}

void testSingleSideBandRmDirectSchedulesArePartitionResetAndFailureAtomic()
{
    const auto directDocument = makeSingleSideBandRmDocument(
        {
            {"frequency", "!C166Frequency"},
            {"freqScale", "!C166FreqScale"},
        },
        {{"frequency", "0.5 hz"}, {"amplitude", "0.75"}});
    auto connectedDocument = makeSingleSideBandRmDocument(
        {
            {"frequency", "1e200 * 1e200"},
            {"freqScale", "1e200 * 1e200"},
        },
        {{"frequency", "0.5 hz"}, {"amplitude", "0.75"}});
    connectedDocument.graph.nodes.push_back(node(
        "frequencyControl", "talas.constant", {
            {"value", "!C166ConnectedFrequency"},
        }));
    connectedDocument.graph.nodes.push_back(node(
        "scaleControl", "talas.constant", {
            {"value", "!C166ConnectedFreqScale"},
        }));
    connectedDocument.graph.connections.push_back(connection(
        "frequencyControl", "value", "ssb", "frequency"));
    connectedDocument.graph.connections.push_back(connection(
        "scaleControl", "value", "ssb", "freqScale"));

    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.eventValues = {
        {"C166Frequency", 0.5, talas::expr::ValueDomain::Hertz},
        {"C166FreqScale", 0.5, talas::expr::ValueDomain::Scalar},
        {"C166ConnectedFrequency", 0.5,
            talas::expr::ValueDomain::Scalar},
        {"C166ConnectedFreqScale", 0.5,
            talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C166Frequency", 1.0, talas::expr::ValueDomain::Hertz},
        {2, "C166FreqScale", 1.0, talas::expr::ValueDomain::Scalar},
        {2, "C166ConnectedFrequency", 1.0,
            talas::expr::ValueDomain::Scalar},
        {2, "C166ConnectedFreqScale", 1.0,
            talas::expr::ValueDomain::Scalar},
        {5, "C166Frequency", 1.5, talas::expr::ValueDomain::Hertz},
        {5, "C166FreqScale", 2.0, talas::expr::ValueDomain::Scalar},
        {5, "C166ConnectedFrequency", 1.5,
            talas::expr::ValueDomain::Scalar},
        {5, "C166ConnectedFreqScale", 2.0,
            talas::expr::ValueDomain::Scalar},
    };
    const auto directCompiled = talas::runtime::compileProject(
        directDocument, makeRegistry(), settings);
    const auto connectedCompiled = talas::runtime::compileProject(
        connectedDocument, makeRegistry(), settings);
    require(directCompiled.ok() && connectedCompiled.ok(),
        "C166 direct and connected dual-schedule fixtures should compile");
    const auto ssb = std::ranges::find(
        directCompiled.graph->plan().steps,
        std::string_view{"talas.singleSideBandRm"},
        &talas::runtime::CompileStep::typeId);
    require(ssb != directCompiled.graph->plan().steps.end()
            && ssb->offlineSupport
                == talas::core::ExecutionSupport::Supported
            && ssb->preparedRealtimeSupport
                == talas::core::ExecutionSupport::Supported,
        "C166 direct dual schedules should retain promoted authority");

    const auto connected = talas::runtime::renderOffline(
        *connectedCompiled.graph, 8);
    talas::runtime::OfflineRenderSession oneShot{*directCompiled.graph};
    talas::runtime::OfflineRenderSession partitioned{*directCompiled.graph};
    const auto expected = oneShot.render(8);
    const auto empty = partitioned.render(0);
    const auto first = partitioned.render(3);
    const auto second = partitioned.render(2);
    const auto third = partitioned.render(3);
    require(connected.ok() && expected.ok() && empty.ok()
            && empty.mono.empty() && first.ok() && second.ok()
            && third.ok(),
        "C166 scheduled shifter should render through zero and irregular offline partitions");
    auto actual = first.mono;
    actual.insert(actual.end(), second.mono.begin(), second.mono.end());
    actual.insert(actual.end(), third.mono.begin(), third.mono.end());
    require(expected.mono == connected.mono && actual == expected.mono,
        "C166 direct fallbacks, connected precedence, and partitioned dual schedules should be bit-exact");

    partitioned.reset();
    const auto reset = partitioned.render(8);
    require(reset.ok() && reset.mono == expected.mono,
        "C166 offline reset should reproduce fresh allpass, phase, and dual schedules exactly");

    // A late zero scale saturates one step above zero (owner, 2026-10-12)
    // and renders alike in one block and across partitions.
    auto saturatingSettings = settings;
    saturatingSettings.eventValueChanges = {
        {5, "C166FreqScale", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto saturatingCompiled = talas::runtime::compileProject(
        directDocument, makeRegistry(), saturatingSettings);
    require(saturatingCompiled.ok(),
        "C166 late zero scheduled-scale fixture should compile");
    talas::runtime::OfflineRenderSession whole{*saturatingCompiled.graph};
    talas::runtime::OfflineRenderSession split{*saturatingCompiled.graph};
    const auto saturated = whole.render(8);
    const auto head = split.render(5);
    const auto tail = split.render(3);
    auto joined = head.mono;
    joined.insert(joined.end(), tail.mono.begin(), tail.mono.end());
    require(saturated.ok() && head.ok() && tail.ok() && joined == saturated.mono,
        "C166 a late zero scale should saturate and render alike across partitions");
}

