double expectedOscillatorBankSineSample(
    std::size_t frame,
    double sampleRate,
    const std::vector<double>& amplitudes,
    const std::vector<double>& frequencies)
{
    constexpr double pi = 3.1415926535897932384626433832795;
    const auto time = static_cast<double>(frame) / sampleRate;
    double sample = 0.0;
    for (std::size_t partial = 0; partial < amplitudes.size(); ++partial)
        sample += amplitudes[partial] * std::sin(2.0 * pi * frequencies[partial] * time);
    return sample;
}

