void testSosOscillatorsSessionMatchesWavetableAcrossPartitionsAndReset()
{
    auto settings = talas::runtime::RenderSettings{16.0, 11};
    settings.audioInputChannels.push_back(
        {1, std::vector<double>(11, 0.25)});
    settings.tableResources = {
        {"Tables/C102Wave", {0.0, 1.0, 0.0, -1.0}},
    };
    const auto document = makeSosOscillatorsDocument(
        sosOscillatorsParameters({
            {"nbrOscillators", "2"},
            {"firstOscillator", "1"},
            resourceParameter("wavetable", "Tables/C102Wave"),
        }),
        syntheticSpectrumFromArrayParameters({
            textParameter("amplitudes", "1.0 0.5"),
            textParameter("frequencies", "1 2"),
        }));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C102 wavetable partition fixture should compile");

    const auto oneShot = talas::runtime::renderOffline(*compiled.graph, 11);
    require(oneShot.ok(),
        "C102 one-shot wavetable reference should render");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(2);
    const auto second = session.render(5);
    const auto third = session.render(4);
    require(first.ok() && second.ok() && third.ok(),
        "C102 partitioned offline wavetable session should render");
    std::vector<double> partitioned;
    partitioned.insert(
        partitioned.end(), first.mono.begin(), first.mono.end());
    partitioned.insert(
        partitioned.end(), second.mono.begin(), second.mono.end());
    partitioned.insert(
        partitioned.end(), third.mono.begin(), third.mono.end());
    require(partitioned == oneShot.mono,
        "C102 offline partitions should preserve exact retained phase and wavetable order");

    session.reset();
    const auto reset = session.render(5);
    require(reset.ok()
            && std::ranges::equal(
                reset.mono,
                std::span<const double>{oneShot.mono}.first(5)),
        "C102 offline reset should replay the exact fresh wavetable prefix");
}

