void testCheckedSosOscillatorsSelectionUsesExactIntegralBoundary()
{
    using talas::runtime::checked_sos_oscillators::decodePositiveIntegralSelection;
    std::size_t decoded = 99;
    require(decodePositiveIntegralSelection(1.0, 4096, decoded)
            && decoded == 1,
        "C102 exact integral decoder should admit the first selection");
    require(decodePositiveIntegralSelection(4096.0, 4096, decoded)
            && decoded == 4096,
        "C102 exact integral decoder should admit the maximum selection");
    for (const auto rejected : {
             0.0,
             1.0000000005,
             4096.0000000005,
             4097.0,
             std::numeric_limits<double>::infinity(),
         })
    {
        decoded = 99;
        require(!decodePositiveIntegralSelection(
                    rejected, 4096, decoded)
                && decoded == 99,
            "C102 exact integral decoder should reject every non-integral or out-of-range boundary without publishing a value");
    }
}

std::vector<double> expectedBandPassResponse(
    double sampleRate,
    double centerFrequency,
    double bandwidth,
    double amplitude,
    const std::vector<double>& input)
{
    constexpr double pi = 3.1415926535897932384626433832795;
    const auto q = centerFrequency / bandwidth;
    const auto omega = 2.0 * pi * centerFrequency / sampleRate;
    const auto alpha = std::sin(omega) / (2.0 * q);
    const auto cosOmega = std::cos(omega);
    const auto a0 = 1.0 + alpha;
    const auto b0 = alpha / a0;
    const auto b1 = 0.0;
    const auto b2 = -alpha / a0;
    const auto a1 = -2.0 * cosOmega / a0;
    const auto a2 = (1.0 - alpha) / a0;

    std::vector<double> response(input.size(), 0.0);
    double x1 = 0.0;
    double x2 = 0.0;
    double y1 = 0.0;
    double y2 = 0.0;
    for (std::size_t frame = 0; frame < input.size(); ++frame)
    {
        const auto x = input[frame];
        const auto y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;
        response[frame] = y * amplitude;
        x2 = x1;
        x1 = x;
        y2 = y1;
        y1 = y;
    }
    return response;
}

std::vector<double> expectedBandPassResponse(
    double sampleRate,
    double centerFrequency,
    const std::vector<double>& bandwidths,
    double amplitude,
    const std::vector<double>& input)
{
    constexpr double pi = 3.1415926535897932384626433832795;
    const auto omega = 2.0 * pi * centerFrequency / sampleRate;
    const auto cosOmega = std::cos(omega);
    std::vector<double> response(input.size(), 0.0);
    double x1 = 0.0;
    double x2 = 0.0;
    double y1 = 0.0;
    double y2 = 0.0;
    for (std::size_t frame = 0; frame < input.size(); ++frame)
    {
        const auto q = centerFrequency / bandwidths[frame];
        const auto alpha = std::sin(omega) / (2.0 * q);
        const auto a0 = 1.0 + alpha;
        const auto b0 = alpha / a0;
        const auto b1 = 0.0;
        const auto b2 = -alpha / a0;
        const auto a1 = -2.0 * cosOmega / a0;
        const auto a2 = (1.0 - alpha) / a0;
        const auto x = input[frame];
        const auto y = b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2;
        response[frame] = y * amplitude;
        x2 = x1;
        x1 = x;
        y2 = y1;
        y1 = y;
    }
    return response;
}

