    auto document = makeFilterBankDocument(
        filterBankParameters({{"nbrFilters", "1"}, {"bankSize", "1"}, {"bandwidth", "1"}}),
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1.0"},
            textParameter("amplitudes", "1.0"),
            textParameter("frequencies", "2"),
        }));
    document.graph.nodes.push_back(node("bandwidth", "talas.constant", {{"value", "2.0"}}));
    document.graph.connections.push_back(connection("bandwidth", "value", "bank", "bandwidth"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-bandwidth filter bank document should compile");
