talas::runtime::OfflineRenderResult renderFilterBankElementDocument(
    std::vector<talas::project::ProjectParameterExpression> elementParameters,
    std::vector<talas::project::ProjectParameterExpression> spectrumParameters,
    double sampleRate,
    std::size_t frameCount,
    std::vector<double> inputSamples,
    std::vector<double> cascadeSamples)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = sampleRate;
    settings.maxBlockFrames = frameCount;
    settings.audioInputChannels.push_back({1, std::move(inputSamples)});
    settings.audioInputChannels.push_back({2, std::move(cascadeSamples)});

    const auto document = makeFilterBankElementDocument(std::move(elementParameters), std::move(spectrumParameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "filter bank element document should compile before offline render");
    return talas::runtime::renderOffline(*compile.graph, frameCount);
}

