void testFormantBankConnectedFrequencyAccumulatesPhaseAcrossBlocks()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 16.0;
    settings.maxBlockFrames = 3;
    settings.tableResources = {
        {"Tables/RampWindow", {1.0, 0.5, 0.25, 0.0}},
    };

    auto document = makeFormantBankDocument(
        formantBankParameters({
            {"frequency", "4 hz"},
            {"nbrFormants", "1"},
            {"bankSize", "1"},
            resourceParameter("impulseResponse", "Tables/RampWindow"),
        }),
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1.0"},
            textParameter("amplitudes", "1.0"),
            textParameter("frequencies", "4"),
            textParameter("bandwidths", "0"),
        }));
    document.graph.nodes.push_back(node("frequency", "talas.linearRamp", {{"duration", "1 s"}, {"start", "4"}, {"end", "8"}}));
    document.graph.connections.push_back(connection("frequency", "value", "bank", "frequency"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "ramp-frequency formant bank document should compile");
    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(5);
    const auto second = session.render(11);
    const std::vector<double> expected = {
        1.0, 0.0, -0.25, 0.0, 1.0, 0.0, -0.25, 1.0,
        0.0, -0.25, 1.0, 0.0, 1.0, 0.0, -0.25, 1.0,
    };

    require(first.ok(), "first connected-frequency formant bank session render should succeed");
    require(second.ok(), "second connected-frequency formant bank session render should succeed");
    require(first.mono.size() + second.mono.size() == expected.size(),
        "connected-frequency formant bank session should return every expected frame");
    for (std::size_t frame = 0; frame < first.mono.size(); ++frame)
        requireNear(first.mono[frame], expected[frame], 1.0e-12, "connected-frequency formant bank first partition frame " + std::to_string(frame));
    for (std::size_t frame = 0; frame < second.mono.size(); ++frame)
        requireNear(second.mono[frame], expected[first.mono.size() + frame], 1.0e-12, "connected-frequency formant bank second partition frame " + std::to_string(frame));
}

void testFormantBankRejectsInvalidConnectedFrequencyAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 16.0;
    settings.maxBlockFrames = 4;

    auto document = makeFormantBankDocument(
        formantBankParameters({{"frequency", "1 hz"}, {"nbrFormants", "1"}, {"bankSize", "1"}}),
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1.0"},
            textParameter("amplitudes", "1.0"),
            textParameter("frequencies", "1"),
            textParameter("bandwidths", "0"),
        }));
    // A Sound's frequency at or below 0 hz saturates at the lowest, as a
    // pasted SpectrumFundamental's does before its first frame; one at
    // Nyquist is still refused.
    auto saturated = document;
    saturated.graph.nodes.push_back(node("frequency", "talas.constant", {{"value", "-1.0"}}));
    saturated.graph.connections.push_back(connection("frequency", "value", "bank", "frequency"));
    const auto lowest = talas::runtime::compileProject(saturated, makeRegistry(), settings);
    require(lowest.ok() && talas::runtime::renderOffline(*lowest.graph, 4).ok(),
        "formant bank should saturate a connected frequency below zero");
    document.graph.nodes.push_back(node("frequency", "talas.constant", {{"value", "8.0"}}));
    document.graph.connections.push_back(connection("frequency", "value", "bank", "frequency"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid connected-frequency formant bank document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);

    require(!result.ok(), "formant bank should reject invalid connected frequency");
    require(result.mono.empty(), "failed connected-frequency formant bank render should not return audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "bank", "frequency"),
        "render should identify connected formant bank frequency input\n" + diagnosticDetails(result));
}

