void testFormantBankOscillatorConnectedFrequencyAccumulatesPhaseAcrossBlocks()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 16.0;
    settings.maxBlockFrames = 3;
    settings.audioInputChannels.push_back({1, std::vector<double>(16, 0.25)});
    settings.tableResources = {
        {"Tables/RampWindow", {1.0, 0.5, 0.25, 0.0}},
    };

    auto document = makeFormantBankOscillatorDocument(
        formantBankOscillatorParameters({
            {"firstFormant", "1"},
            {"nbrFormants", "1"},
            {"frequency", "4 hz"},
            resourceParameter("formantImpulse", "Tables/RampWindow"),
        }),
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1.0"},
            textParameter("amplitudes", "1.0"),
            textParameter("frequencies", "4"),
            textParameter("bandwidths", "0"),
        }));
    document.graph.nodes.push_back(node("frequency", "talas.linearRamp", {{"duration", "1 s"}, {"start", "4"}, {"end", "8"}}));
    document.graph.connections.push_back(connection("frequency", "value", "formant", "frequency"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "ramp-frequency formant bank oscillator document should compile");
    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(5);
    const auto second = session.render(11);
    const std::vector<double> expected = {
        1.25, 0.25, 0.0, 0.25, 1.25, 0.25, 0.0, 1.25,
        0.25, 0.0, 1.25, 0.25, 1.25, 0.25, 0.0, 1.25,
    };

    require(first.ok(), "first connected-frequency formant bank oscillator session render should succeed");
    require(second.ok(), "second connected-frequency formant bank oscillator session render should succeed");
    require(first.mono.size() + second.mono.size() == expected.size(),
        "connected-frequency formant bank oscillator session should return every expected frame");
    for (std::size_t frame = 0; frame < first.mono.size(); ++frame)
        requireNear(first.mono[frame], expected[frame], 1.0e-12, "connected-frequency formant bank oscillator first partition frame " + std::to_string(frame));
    for (std::size_t frame = 0; frame < second.mono.size(); ++frame)
        requireNear(second.mono[frame], expected[first.mono.size() + frame], 1.0e-12, "connected-frequency formant bank oscillator second partition frame " + std::to_string(frame));
}

