// Each level scales what reaches the filters and Gain the output, so the
// output scales by their product.
void testVocoderLevelsScaleTheFilteredInput()
{
    const auto render = [](std::string typeId,
                            std::vector<talas::project::ProjectParameterExpression> parameters) {
        return renderDocument(
            makeVocoderDocument(std::move(typeId), std::move(parameters),
                {{"frequency", "880 hz"}, {"amplitude", "1"}},
                {{"frequency", "880 hz"}, {"amplitude", "1"}}),
            48000.0,
            2048);
    };
    const auto requireScaled = [](const talas::runtime::OfflineRenderResult& unit,
                                   const talas::runtime::OfflineRenderResult& scaled,
                                   double factor,
                                   std::string_view label) {
        require(unit.ok() && scaled.ok(), std::string{label} + " should render");
        require(std::ranges::any_of(unit.mono, [](double value) { return value != 0.0; }),
            std::string{label} + " should be heard");
        for (std::size_t frame = 0; frame < unit.mono.size(); ++frame)
        {
            require(scaled.mono[frame] == unit.mono[frame] * factor,
                std::string{label} + " should scale by its levels at frame " + std::to_string(frame));
        }
    };
    const auto scale = [](std::vector<talas::project::ProjectParameterExpression> levels) {
        levels.push_back(textParameter("intervals", "0 12"));
        levels.push_back({"tonic", "69 nn"});
        return scaleVocoderParameters(std::move(levels));
    };
    requireScaled(
        render("talas.scaleVocoder", scale({{"sideLevel", "1"}, {"inputLevel", "1"}, {"gain", "1"}})),
        render("talas.scaleVocoder", scale({{"sideLevel", "0.25"}, {"inputLevel", "0.5"}, {"gain", "0.5"}})),
        0.0625, "ScaleVocoder");
    requireScaled(
        render("talas.tunableVocoder", tunableVocoderParameters({{"analysisLevel", "1"},
            {"synthesisLevel", "1"}, {"gain", "1"}, {"analysisFreq", "440 hz"},
            {"synthesisFreq", "440 hz"}})),
        render("talas.tunableVocoder", tunableVocoderParameters({{"analysisLevel", "0.25"},
            {"synthesisLevel", "0.5"}, {"gain", "0.5"}, {"analysisFreq", "440 hz"},
            {"synthesisFreq", "440 hz"}})),
        0.0625, "TunableVocoder");
    requireScaled(
        render("talas.vocoder", vocoderParameters({{"sideLevel", "1"}, {"inputLevel", "1"}})),
        render("talas.vocoder", vocoderParameters({{"sideLevel", "0.25"}, {"inputLevel", "0.5"}})),
        0.125, "Vocoder");
}

void testScaleVocoderTransfersExplicitIntervalBand()
{
    const auto parameters = scaleVocoderParameters({
        {"timeConstant", "5 ms"},
        {"nbrBands", "3"},
        {"bankSize", "3"},
        {"tonic", "69 nn"},
        textParameter("intervals", "-12 0 12"),
        {"sideLevel", "1"},
        {"inputLevel", "1"},
        {"inBandwidth", "0.25"},
        {"sideBandwidth", "0.25"},
        {"gain", "1"},
    });
    const auto matching = renderDocument(
        makeVocoderDocument(
            "talas.scaleVocoder", parameters,
            {{"frequency", "880 hz"}, {"amplitude", "1"}},
            {{"frequency", "880 hz"}, {"amplitude", "1"}}),
        48000.0,
        16384);
    const auto remote = renderDocument(
        makeVocoderDocument(
            "talas.scaleVocoder", parameters,
            {{"frequency", "880 hz"}, {"amplitude", "1"}},
            {{"frequency", "4000 hz"}, {"amplitude", "1"}}),
        48000.0,
        16384);
    require(matching.ok(), "matching ScaleVocoder should render\n" + diagnosticDetails(matching));
    require(remote.ok(), "remote ScaleVocoder should render\n" + diagnosticDetails(remote));
    const auto tailRms = [](const std::vector<double>& samples) {
        double sum = 0.0;
        for (std::size_t frame = samples.size() / 2; frame < samples.size(); ++frame)
            sum += samples[frame] * samples[frame];
        return std::sqrt(sum / static_cast<double>(samples.size() / 2));
    };
    require(tailRms(matching.mono) > tailRms(remote.mono) * 4.0,
        "explicit matching ScaleVocoder interval should dominate remote analysis");
}

void testScaleVocoderOfflineSessionIsPartitionInvariantAndResettable()
{
    constexpr std::size_t frameCount = 2048;
    const auto document = makeVocoderDocument(
        "talas.scaleVocoder",
        scaleVocoderParameters({
            {"timeConstant", "5 ms"},
            {"nbrBands", "4"},
            {"bankSize", "4"},
            {"tonic", "69 nn"},
            textParameter("intervals", "-12 0 7.5 12"),
            {"inputLevel", "0.25"},
            {"sideLevel", "0.75"},
            {"inBandwidth", "0.4"},
            {"sideBandwidth", "0.6"},
            {"gain", "0.8"},
        }),
        {{"frequency", "880 hz"}, {"amplitude", "1"}},
        {{"frequency", "880 hz"}, {"amplitude", "0.75"}});
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 48000.0;
    settings.maxBlockFrames = frameCount;
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "partitioned ScaleVocoder fixture should compile");
    talas::runtime::OfflineRenderSession whole{*compiled.graph};
    talas::runtime::OfflineRenderSession partitioned{*compiled.graph};
    const auto expected = whole.render(frameCount);
    require(expected.ok(), "whole ScaleVocoder session should render");
    std::vector<double> actual;
    actual.reserve(frameCount);
    constexpr std::array<std::size_t, 6> partitions{
        1, 31, 256, 7, 509, 43};
    std::size_t remaining = frameCount;
    std::size_t partition = 0;
    while (remaining != 0)
    {
        const auto count = std::min(
            partitions[partition++ % partitions.size()], remaining);
        const auto block = partitioned.render(count);
        require(block.ok(), "partitioned ScaleVocoder should render");
        actual.insert(actual.end(), block.mono.begin(), block.mono.end());
        remaining -= count;
    }
    require(expected.mono == actual,
        "ScaleVocoder partitions should be bit-identical");
    partitioned.reset();
    const auto reset = partitioned.render(frameCount);
    require(reset.ok(), "reset ScaleVocoder should render");
    require(expected.mono == reset.mono,
        "reset ScaleVocoder should reproduce first-run output");
}

void testTunableVocoderTransfersLinearAndLogarithmicBands()
{
    const auto makeParameters = [](bool logarithmic) {
        return tunableVocoderParameters({
            {"timeConstant", "5 ms"},
            {"nbrBands", "3"},
            {"bankSize", "3"},
            booleanParameter("logSpacing", logarithmic),
            {"analysisFreq", "500 hz"},
            {"synthesisFreq", "500 hz"},
            {"analysisLevel", "1"},
            {"synthesisLevel", "1"},
            {"analysisSpacing", "1"},
            {"synthesisSpacing", "1"},
            {"analysisBW", "0.2"},
            {"synthesisBW", "0.2"},
            {"gain", "1"},
        });
    };
    const auto carrier = std::vector<talas::project::ProjectParameterExpression>{
        {"frequency", "2000 hz"}, {"amplitude", "1"}};
    const auto analysis = std::vector<talas::project::ProjectParameterExpression>{
        {"frequency", "2000 hz"}, {"amplitude", "0.75"}};
    const auto linear = renderDocument(
        makeVocoderDocument(
            "talas.tunableVocoder", makeParameters(false), carrier, analysis),
        48000.0,
        16384);
    const auto logarithmic = renderDocument(
        makeVocoderDocument(
            "talas.tunableVocoder", makeParameters(true), carrier, analysis),
        48000.0,
        16384);
    require(linear.ok(), "active linear TunableVocoder should render\n" + diagnosticDetails(linear));
    require(logarithmic.ok(), "active logarithmic TunableVocoder should render\n" + diagnosticDetails(logarithmic));
    const auto tailRms = [](const std::vector<double>& samples) {
        double sum = 0.0;
        for (std::size_t frame = samples.size() / 2; frame < samples.size(); ++frame)
            sum += samples[frame] * samples[frame];
        return std::sqrt(sum / static_cast<double>(samples.size() / 2));
    };
    require(
        tailRms(logarithmic.mono) > tailRms(linear.mono) * 4.0,
        "logarithmic 2000 Hz band should dominate the remote linear layout");
}

