void testVocoderFamilySpectralShapingRedistributesWetEnergy()
{
    constexpr std::size_t frames = 16384;
    const auto oscillator = [](double frequency) {
        return std::vector<talas::project::ProjectParameterExpression>{
            {"frequency", std::to_string(frequency) + " hz"},
            {"amplitude", "1"}};
    };
    const auto tailRms = [](std::span<const double> samples) {
        double energy = 0.0;
        const auto first = samples.size() / 2;
        for (std::size_t frame = first; frame < samples.size(); ++frame)
            energy += samples[frame] * samples[frame];
        return std::sqrt(energy / static_cast<double>(samples.size() - first));
    };
    const auto render = [&](std::string typeId, auto parameters, double frequency) {
        return renderDocument(
            makeVocoderDocument(
                std::move(typeId), std::move(parameters),
                oscillator(frequency), oscillator(frequency)),
            48000.0, frames);
    };

    const auto brightScale = render(
        "talas.scaleVocoder",
        scaleVocoderParameters({
            textParameter("intervals", "-12 0 7.5 12"),
            {"nbrBands", "4"}, {"bankSize", "4"},
            {"inputLevel", "1"}, {"sideLevel", "1"}, {"gain", "1"},
            {"tone", "1"}, {"rolloff", "1"}}),
        523.2511306011972);
    const auto darkScale = render(
        "talas.scaleVocoder",
        scaleVocoderParameters({
            textParameter("intervals", "-12 0 7.5 12"),
            {"nbrBands", "4"}, {"bankSize", "4"},
            {"inputLevel", "1"}, {"sideLevel", "1"}, {"gain", "1"},
            {"tone", "-1"}, {"rolloff", "1"}}),
        523.2511306011972);
    require(brightScale.ok() && darkScale.ok(),
        "ScaleVocoder shaping fixtures should render");
    // The highest interval, C5 above the C4 tonic, is the band at 523 hz;
    // Rolloff sets how far Tone reaches (format 94).
    require(tailRms(brightScale.mono) > tailRms(darkScale.mono) * 2.0,
        "positive ScaleVocoder tone should emphasize the highest interval");

    // Rolloff sets how far a TunableVocoder's Tone tilts it.
    const auto brightTunable = render(
        "talas.tunableVocoder",
        tunableVocoderParameters({
            booleanParameter("logSpacing", true),
            {"synthesisLevel", "1"}, {"analysisLevel", "1"},
            {"gain", "1"}, {"tone", "1"}, {"rolloff", "2"}}),
        200.0);
    const auto darkTunable = render(
        "talas.tunableVocoder",
        tunableVocoderParameters({
            booleanParameter("logSpacing", true),
            {"synthesisLevel", "1"}, {"analysisLevel", "1"},
            {"gain", "1"}, {"tone", "-1"}, {"rolloff", "2"}}),
        200.0);
    require(brightTunable.ok() && darkTunable.ok(),
        "TunableVocoder shaping fixtures should render");
    // An octave above the 100 hz base, 200 hz is the highest band.
    require(tailRms(brightTunable.mono) > tailRms(darkTunable.mono) * 2.0,
        "positive TunableVocoder tone should emphasize the highest band");

    // Projects before format 79 tilt a Vocoder by Rolloff.
    const auto neutralVocoder = render(
        "talas.vocoder",
        vocoderParameters({
            {"inputLevel", "1"}, {"sideLevel", "1"}, {"rolloff", "0"},
            choiceParameter("inputShaping", "legacyTilt")}),
        1000.0);
    const auto rolledVocoder = render(
        "talas.vocoder",
        vocoderParameters({
            {"inputLevel", "1"}, {"sideLevel", "1"}, {"rolloff", "4"},
            choiceParameter("inputShaping", "legacyTilt")}),
        1000.0);
    require(neutralVocoder.ok() && rolledVocoder.ok(),
        "Vocoder rolloff fixtures should render");
    require(tailRms(neutralVocoder.mono) > tailRms(rolledVocoder.mono) * 2.0,
        "positive Vocoder rolloff should attenuate upper wet bands");
}

void testTunableVocoderOfflineSessionIsPartitionInvariantAndResettable()
{
    constexpr std::size_t frameCount = 2048;
    for (const bool logarithmic : {false, true})
    {
        const auto document = makeVocoderDocument(
            "talas.tunableVocoder",
            tunableVocoderParameters({
                {"timeConstant", "5 ms"},
                {"nbrBands", "4"},
                {"bankSize", "4"},
                booleanParameter("logSpacing", logarithmic),
                {"analysisFreq", "250 hz"},
                {"synthesisFreq", "250 hz"},
                {"analysisLevel", "0.75"},
                {"synthesisLevel", "0.25"},
                {"analysisSpacing", "1"},
                {"synthesisSpacing", "1"},
                {"analysisBW", "0.4"},
                {"synthesisBW", "0.6"},
                {"gain", "0.8"},
            }),
            {{"frequency", "1000 hz"}, {"amplitude", "1"}},
            {{"frequency", "1000 hz"}, {"amplitude", "0.75"}});
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 48000.0;
        settings.maxBlockFrames = frameCount;
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(compiled.ok(), "partitioned TunableVocoder fixture should compile");
        talas::runtime::OfflineRenderSession whole{*compiled.graph};
        talas::runtime::OfflineRenderSession partitioned{*compiled.graph};
        const auto expected = whole.render(frameCount);
        require(expected.ok(), "whole TunableVocoder session should render");
        std::vector<double> actual;
        actual.reserve(frameCount);
        constexpr std::array<std::size_t, 6> partitions{
            1, 31, 256, 7, 509, 43};
        std::size_t remaining = frameCount;
        std::size_t partition = 0;
        while (remaining != 0)
        {
            const auto count = std::min(
                partitions[partition++ % partitions.size()], remaining);
            const auto block = partitioned.render(count);
            require(block.ok(), "partitioned TunableVocoder should render");
            actual.insert(actual.end(), block.mono.begin(), block.mono.end());
            remaining -= count;
        }
        require(expected.mono == actual,
            "TunableVocoder partitions should be bit-identical");
        partitioned.reset();
        const auto reset = partitioned.render(frameCount);
        require(reset.ok(), "reset TunableVocoder should render");
        require(expected.mono == reset.mono,
            "reset TunableVocoder should reproduce first-run output");
    }
}

