void testVocoderChannelBankMapsSpectrumBandsAndCascade()
{
    constexpr std::size_t frames = 16384;
    const auto spectrum = [](std::string frequency) {
        return syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            textParameter("amplitudes", "1"),
            textParameter("frequencies", std::move(frequency)),
            textParameter("bandwidths", "300"),
        });
    };
    const auto oscillator = [](std::string frequency, std::string amplitude) {
        return std::vector<talas::project::ProjectParameterExpression>{
            {"frequency", std::move(frequency)}, {"amplitude", std::move(amplitude)}};
    };
    const auto render = [&](std::string analysisFrequency, double cascadeAmplitude) {
        return renderDocument(
            makeVocoderChannelBankDocument(
                vocoderChannelBankParameters({{"count", "1"}}),
                spectrum("1000"),
                spectrum(std::move(analysisFrequency)),
                oscillator("1000 hz", "1"),
                oscillator("1000 hz", "1"),
                oscillator("37 hz", std::to_string(cascadeAmplitude))),
            48000.0,
            frames);
    };
    const auto matching = render("1000", 0.0);
    const auto remote = render("4000", 0.0);
    const auto withCascade = render("1000", 0.25);
    const auto twoBandSpectrum = syntheticSpectrumFromArrayParameters({
        {"nbrPartials", "2"},
        textParameter("amplitudes", "0 1"),
        textParameter("frequencies", "1000 4000"),
        textParameter("bandwidths", "300 600"),
    });
    const auto selectedSecond = renderDocument(
        makeVocoderChannelBankDocument(
            vocoderChannelBankParameters({{"first", "2"}, {"count", "1"}}),
            twoBandSpectrum,
            twoBandSpectrum,
            oscillator("4000 hz", "1"),
            oscillator("4000 hz", "1"),
            oscillator("37 hz", "0")),
        48000.0,
        frames);
    require(matching.ok() && remote.ok() && withCascade.ok()
            && selectedSecond.ok(),
        "mapped vocoder channel bank fixtures should render");
    const auto tailRms = [](std::span<const double> samples) {
        double energy = 0.0;
        const auto first = samples.size() / 2;
        for (std::size_t frame = first; frame < samples.size(); ++frame)
            energy += samples[frame] * samples[frame];
        return std::sqrt(energy / static_cast<double>(samples.size() - first));
    };
    require(tailRms(matching.mono) > tailRms(remote.mono) * 4.0,
        "selected matching Spectrum band should dominate a remote analysis band");
    require(tailRms(selectedSecond.mono) > tailRms(remote.mono) * 4.0,
        "first/count should select the requested Spectrum channel");
    for (std::size_t frame = 0; frame < frames; ++frame)
    {
        const auto cascade = 0.25 * std::sin(
            2.0 * std::numbers::pi * 37.0 * static_cast<double>(frame) / 48000.0);
        requireNear(
            withCascade.mono[frame], matching.mono[frame] + cascade, 1.0e-12,
            "vocoder channel bank should add cascade exactly once");
    }
}

