void testC63SumOfSinesUsesExactNonBinaryEndpointAndRejectsRateOverflow()
{
    auto result = renderSumOfSinesDocument(
        sumOfSinesParameters({
            {"onDuration", "1 s"},
            {"frequency0", "0.25 hz"},
            {"frequency1", "0.25 hz"},
            {"nbrPartials", "1"},
            {"bankSize", "1"},
            {"envelope", "1"},
        }),
        {1.0},
        10.0,
        12);
    require(result.ok() && result.mono.size() == 12,
        "C63 non-binary endpoint fixture should render");
    requireNear(result.mono[10], 0.0, 1.0e-12,
        "C63 one-second traversal at 10 Hz should stop before sample 10");
    requireNear(result.mono[11], 0.0, 1.0e-12,
        "C63 held-high Gate should remain stopped after exact endpoint");

    result = renderSumOfSinesDocument(
        sumOfSinesParameters({
            {"onDuration", "1 s"},
            {"frequency0", "0.25 hz"},
            {"frequency1", "0.25 hz"},
            {"nbrPartials", "1"},
            {"bankSize", "1"},
            {"envelope", "1"},
        }),
        {1.0},
        99.0,
        101);
    require(result.ok() && result.mono.size() == 101,
        "C63 accumulated non-binary endpoint fixture should render");
    requireNear(result.mono[99], 0.0, 1.0e-12,
        "C63 one-second traversal at 99 Hz should stop before sample 99");
    requireNear(result.mono[100], 0.0, 1.0e-12,
        "C63 99 Hz held-high Gate should remain stopped after completion");

    result = renderSumOfSinesDocument(
        sumOfSinesParameters({
            {"onDuration", "1e308 s"},
            {"frequency0", "0.25 hz"},
            {"frequency1", "0.25 hz"},
            {"nbrPartials", "1"},
            {"bankSize", "1"},
            {"envelope", "1"},
        }),
        {1.0},
        10.0,
        1);
    require(!result.ok() && result.mono.empty(),
        "C63 overflowing OnDuration/sampleRate product should fail closed");
    require(hasDiagnostic(
                result, DiagnosticCode::GraphValidationFailed,
                "sum", {}, "onDuration"),
        "C63 overflowing traversal rate should identify OnDuration");
}

void testC63OfflineSumOfSinesRejectsForgedActiveLoopValueAuthority()
{
    talas::runtime::RenderSettings settings{10.0, 4};
    settings.tableResources = {
        {"Tables/Partials", {1.0, 0.5, 0.25}},
    };
    const auto compiled = talas::runtime::compileProject(
        makeSumOfSinesDocument(sumOfSinesParameters({
            {"frequency0", "0.25 hz"},
            {"frequency1", "0.25 hz"},
            {"analysisFrames0", "3"},
            {"nbrPartials", "1"},
            {"bankSize", "1"},
            booleanParameter("loop", true),
            {"loopStart", "0.25"},
            {"loopEnd", "0.75"},
        })),
        makeRegistry(),
        settings);
    require(compiled.ok(),
        "C63 forged offline loop authority fixture should compile");

    auto plan = compiled.graph->plan();
    const auto sum = std::ranges::find(
        plan.steps, std::string_view{"sum"},
        &talas::runtime::CompileStep::nodeId);
    require(sum != plan.steps.end(),
        "C63 forged offline fixture should expose SumOfSines");
    const auto loopStart = std::ranges::find(
        sum->parameters, std::string_view{"loopStart"},
        &talas::runtime::ParameterValue::id);
    require(loopStart != sum->parameters.end(),
        "C63 forged offline fixture should expose loopStart");
    loopStart->value = 0.5;

    const auto result = talas::runtime::renderOffline(
        handBuiltGraph(std::move(plan), settings), 4);
    require(!result.ok() && result.mono.empty(),
        "C63 offline render should reject forged in-range loopStart value");
    require(hasDiagnostic(
                result, DiagnosticCode::GraphValidationFailed,
                "sum", {}, "loopStart"),
        "C63 offline forged loop value should identify loopStart authority");
}

