void testC61SumOfSinesDefaultFrequencyLifecycleAndFailureRollback()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 16.0;
    settings.maxBlockFrames = 3;
    settings.tableResources = {{"Tables/Partials", {1.0}}};
    const auto document = makeSumOfSinesDocument(sumOfSinesParameters({
        {"frequency0", "0 hz"},
        {"frequency1", "0 hz"},
        {"analysisFrequency0", "2 hz"},
        {"analysisFrequency1", "2 hz"},
        {"nbrPartials", "1"},
        {"bankSize", "1"},
        {"envelope", "1.0"},
    }));
    const auto compile = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compile.ok(), "C61 default-frequency lifecycle should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(3);
    const auto second = session.render(3);
    const auto oneShot = talas::runtime::renderOffline(*compile.graph, 6);
    require(
        first.ok() && second.ok() && oneShot.ok(),
        "C61 default-frequency lifecycle renders should succeed");
    for (std::size_t frame = 0; frame < 3; ++frame)
    {
        requireNear(
            first.mono[frame], oneShot.mono[frame], 1.0e-12,
            "C61 first default-frequency transaction frame "
                + std::to_string(frame));
        requireNear(
            second.mono[frame], oneShot.mono[frame + 3], 1.0e-12,
            "C61 second default-frequency transaction frame "
                + std::to_string(frame));
    }
    session.reset();
    const auto reset = session.render(3);
    require(reset.ok(), "C61 reset default-frequency render should succeed");
    for (std::size_t frame = 0; frame < 3; ++frame)
    {
        requireNear(
            reset.mono[frame], first.mono[frame], 1.0e-12,
            "C61 reset should restore default-frequency phase frame "
                + std::to_string(frame));
    }

    auto failingSettings = settings;
    failingSettings.maxBlockFrames = 5;
    failingSettings.tableResources = {{"Tables/Partials", {2.0}}};
    failingSettings.eventValues = {{
        "C61Downstream", 1.0, talas::expr::ValueDomain::Scalar}};
    failingSettings.eventValueChanges = {{
        2,
        "C61Downstream",
        std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar,
    }};
    auto failingDocument = makeSumOfSinesDocument(sumOfSinesParameters({
        {"frequency0", "0 hz"},
        {"frequency1", "0 hz"},
        {"analysisFrequency0", "2 hz"},
        {"analysisFrequency1", "2 hz"},
        {"nbrPartials", "1"},
        {"bankSize", "1"},
        {"envelope", "1.0"},
    }));
    failingDocument.graph.nodes.push_back(node(
        "downstream",
        "talas.level",
        {{"left", "1"}, {"right", "0"},
         booleanParameter("noGain", false)}));
    failingDocument.graph.nodes.push_back(node(
        "downstreamControl",
        "talas.constant",
        {{"value", "!C61Downstream"}}));
    std::erase_if(
        failingDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "sum" && edge.toNode == "out";
        });
    failingDocument.graph.connections.push_back(connection(
        "sum", "audioOut", "downstream", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "downstreamControl", "value", "downstream", "left"));
    failingDocument.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));
    const auto failingCompile = talas::runtime::compileProject(
        failingDocument, makeRegistry(), failingSettings);
    require(
        failingCompile.ok(),
        "C61 downstream rollback fixture should compile");
    talas::runtime::OfflineRenderSession failing{*failingCompile.graph};
    const auto rejected = failing.render(5);
    const auto retry = failing.render(2);
    require(
        !rejected.ok() && rejected.mono.empty() && retry.ok(),
        "C61 downstream failure should publish nothing and permit retry");
    requireNear(retry.mono[0], 0.0, 1.0e-12,
                "C61 retry should restart at zero phase");
    requireNear(
        retry.mono[1],
        expectedSumOfSinesSample(1, 16.0, 2.0, 1.0, {2.0}),
        1.0e-12,
        "C61 retry should preserve the first phase transition");
}

