void testSumOfSinesRejectsUnsupportedResourceConfigurations()
{
    requireSumOfSinesRenderFailure(sumOfSinesParameters(), {}, "analysis0");
    requireSumOfSinesRenderFailure(sumOfSinesParameters(), {{"Tables/Partials", {}}}, "analysis0");
    requireSumOfSinesRenderFailure(sumOfSinesParameters(), {{"Tables/Partials", {1.0, std::numeric_limits<double>::infinity()}}}, "analysis0");
    requireSumOfSinesRenderFailure(sumOfSinesParameters({{"nbrPartials", "3"}, {"bankSize", "3"}}), {{"Tables/Partials", {1.0, 0.5}}}, "nbrPartials");
    requireSumOfSinesRenderFailure(
        sumOfSinesParameters({{"dbMorph", "0.25"}}),
        {{"Tables/Partials", {1.0, 0.5}}},
        "analysis1");
    requireSumOfSinesRenderFailure(
        sumOfSinesParameters({resourceParameter("analysis1", "Tables/Alt"), {"dbMorph", "0.25"}}),
        {{"Tables/Partials", {1.0, 0.5}}, {"Tables/Alt", {0.25, std::numeric_limits<double>::infinity()}}},
        "analysis1");
    requireSumOfSinesRenderFailure(
        sumOfSinesParameters({resourceParameter("analysis1", "Tables/Alt"), {"dbMorph", "0.25"}, {"nbrPartials", "3"}, {"bankSize", "3"}}),
        {{"Tables/Partials", {1.0, 0.5, 0.25}}, {"Tables/Alt", {0.25, 0.125}}},
        "analysis1");
    requireSumOfSinesRenderFailure(
        sumOfSinesParameters({{"nbrPartials", "1"}, {"bankSize", "1"}}),
        {{"Tables/Partials", std::vector<double>(
            (1U << 20U) + 1U,
            0.0)}},
        "analysis0");

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 16.0;
    settings.maxBlockFrames = 8;
    settings.tableResources.push_back({"Tables/Partials", {1.0, 0.5}});

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "sum",
            "talas.sumOfSines",
            {},
            {
                {"onDuration", talas::expr::ValueDomain::Seconds, 1.0},
                {"frequency0", talas::expr::ValueDomain::Hertz, 1.0},
                {"frequency1", talas::expr::ValueDomain::Hertz, 1.0},
                resourceRuntimeParameter("analysis0", "Tables/Partials"),
                {"analysisFrequency0", talas::expr::ValueDomain::Hertz, 1.0},
                {"analysisFrames0", talas::expr::ValueDomain::Scalar, 1.0},
                resourceRuntimeParameter("analysis1", ""),
                {"analysisFrequency1", talas::expr::ValueDomain::Hertz, 1.0},
                {"analysisFrames1", talas::expr::ValueDomain::Scalar, 1.0},
                {"dbMorph", talas::expr::ValueDomain::Scalar, 0.0},
                {"pchMorph", talas::expr::ValueDomain::Scalar, 0.0},
                {"nbrPartials", talas::expr::ValueDomain::Scalar, 2.0},
                {"bankSize", talas::expr::ValueDomain::Scalar, 2.0},
                {"timeIndex", talas::expr::ValueDomain::Scalar, 0.0},
                {"gate", talas::expr::ValueDomain::Scalar, 1.0},
                booleanRuntimeParameter("loop", true),
                {"loopStart", talas::expr::ValueDomain::Scalar, 0.0},
                {"loopEnd", talas::expr::ValueDomain::Scalar, 0.0},
                booleanRuntimeParameter("ctrlTime", false),
                {"envelope", talas::expr::ValueDomain::Scalar, 0.25},
            },
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "sum", "audioOut", 0)},
            {},
        },
    };
    plan.buffers = {{"sum", "audioOut", talas::core::PortType::Audio, 8}};
    plan.outputBufferIndex = 0;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 8);

    require(!result.ok(), "stale looped sum of sines render should fail");
    require(result.mono.empty(), "failed stale looped sum of sines render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "sum", {}, "loopStart"), "render should identify missing exact loopStart authority");
}

