void testGaOscillatorsSessionKeepsAbsolutePhase()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 256;
    settings.tableResources.push_back({"Tables/GA", {1.0, 0.5, 0.25}});
    const auto document = makeGaOscillatorsDocument(gaOscillatorsParameters({{"frequency", "110 hz"}}));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "ga oscillators document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(256);
    const auto second = session.render(256);
    const auto oneShot = talas::runtime::renderOffline(*compile.graph, 512);

    require(first.ok(), "first ga oscillators session render should not emit diagnostics");
    require(second.ok(), "second ga oscillators session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot ga oscillators render should not emit diagnostics");
    require(first.mono.size() == 256, "first ga oscillators session render should return requested frames");
    require(second.mono.size() == 256, "second ga oscillators session render should return requested frames");
    require(oneShot.mono.size() == 512, "one-shot ga oscillators render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "ga oscillators session first frame 0");
    requireNear(first.mono[128], oneShot.mono[128], 1.0e-12, "ga oscillators session first frame 128");
    requireNear(first.mono[255], oneShot.mono[255], 1.0e-12, "ga oscillators session first frame 255");
    requireNear(second.mono[0], oneShot.mono[256], 1.0e-12, "ga oscillators session second frame 0");
    requireNear(second.mono[128], oneShot.mono[384], 1.0e-12, "ga oscillators session second frame 128");
    requireNear(second.mono[255], oneShot.mono[511], 1.0e-12, "ga oscillators session second frame 255");
}

