void testMalformedPackedFftPlanFailsOfflinePreparationClosed()
{
    constexpr std::size_t size = 16;
    talas::runtime::RenderSettings settings;
    settings.maxBlockFrames = 7;
    settings.audioInputChannels.push_back({
        1,
        std::vector<double>(3 * size - 2, 0.0),
    });
    const auto compiled = talas::runtime::compileProject(
        makePackedFftAudioInputDocument(size, 1),
        makeRegistry(),
        settings);
    require(compiled.ok(),
            "packed malformed-plan oracle should compile");
    auto plan = compiled.graph->plan();
    auto forward = std::ranges::find_if(
        plan.steps,
        [](const talas::runtime::CompileStep& step) {
            return step.nodeId == "forward0";
        });
    require(forward != plan.steps.end()
                && !forward->inputLatencyFrames.empty(),
            "packed malformed-plan oracle should expose forward authority");
    forward->inputLatencyFrames.front() = 1;
    forward->cumulativeInputLatencyFrames = 1;
    forward->cumulativeOutputLatencyFrames = size;
    const talas::runtime::PreparedRuntimeGraph malformed{
        std::move(plan), settings};
    const auto rendered = talas::runtime::renderOffline(
        malformed, 3 * size - 2);
    require(!rendered.ok()
                && rendered.mono.empty()
                && hasDiagnostic(
                    rendered,
                    DiagnosticCode::GraphValidationFailed),
            "source-incoherent packed FFT phase authority should fail offline preparation closed");
}

void testPackedFftRejectsForgedSourceAuthorityAndDuplicateInputOffline()
{
    constexpr std::size_t size = 16;
    talas::runtime::RenderSettings settings;
    settings.maxBlockFrames = 7;
    settings.audioInputChannels.push_back({
        1,
        std::vector<double>(3 * size - 2, 0.0),
    });
    const auto compiled = talas::runtime::compileProject(
        makePackedFftAudioInputDocument(size, 1),
        makeRegistry(),
        settings);
    require(compiled.ok(),
            "packed source-authority oracle should compile");
    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        const talas::runtime::PreparedRuntimeGraph malformed{
            std::move(plan), settings};
        const auto rendered = talas::runtime::renderOffline(
            malformed, 3 * size - 2);
        require(!rendered.ok()
                    && rendered.mono.empty()
                    && hasDiagnostic(
                        rendered,
                        DiagnosticCode::GraphValidationFailed,
                        "forward0"),
                std::string(context)
                    + " should fail packed FFT offline preparation closed\n"
                    + diagnosticDetails(rendered));
    };

    {
        auto plan = compiled.graph->plan();
        auto forward = std::ranges::find(
            plan.steps,
            std::string_view{"forward0"},
            &talas::runtime::CompileStep::nodeId);
        require(forward != plan.steps.end()
                    && forward->inputs.size() == 1
                    && forward->inputs.front().bufferIndex
                        < plan.buffers.size(),
                "forged packed source-port fixture should expose one valid binding");
        auto forgedBuffer = plan.buffers[
            forward->inputs.front().bufferIndex];
        forgedBuffer.portId = "forgedAudioOut";
        forward->inputs.front().sourcePortId = forgedBuffer.portId;
        forward->inputs.front().bufferIndex = plan.buffers.size();
        plan.buffers.push_back(std::move(forgedBuffer));
        requireRejected(
            std::move(plan),
            "self-consistent nonexistent packed FFT source port");
    }

    {
        auto plan = compiled.graph->plan();
        auto forward = std::ranges::find(
            plan.steps,
            std::string_view{"forward0"},
            &talas::runtime::CompileStep::nodeId);
        require(forward != plan.steps.end()
                    && forward->inputs.size() == 1
                    && forward->inputLatencyFrames.size() == 1,
                "duplicate packed input fixture should expose one compiled binding");
        forward->inputs.push_back(forward->inputs.front());
        forward->inputLatencyFrames.push_back(
            forward->inputLatencyFrames.front());
        requireRejected(
            std::move(plan),
            "duplicate packed FFT audioIn binding");
    }
}

void testNativeComplexStftRoundTripIsOfflinePartitionInvariant()
{
    constexpr std::size_t frameSize = 64;
    constexpr std::size_t latency = frameSize - 1;
    constexpr std::size_t frameCount = 321;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    const auto directCompiled = talas::runtime::compileProject(
        makeOscillatorToOutputDocument("1 hz", "1.0"),
        makeRegistry(),
        settings);
    require(directCompiled.ok(), "direct native STFT oracle should compile");
    const auto direct = talas::runtime::renderOffline(
        *directCompiled.graph,
        frameCount - latency);
    require(direct.ok(), "direct native STFT oracle should render");

    for (const auto& [window, hop] :
         std::vector<std::pair<std::string, std::string>>{
             {"rectangular", "64"},
             {"hann", "32"},
             {"hann", "16"},
         })
    {
        const auto compiled = talas::runtime::compileProject(
            makeNativeStftDocument("64", hop, window),
            makeRegistry(),
            settings);
        require(compiled.ok(), "native offline STFT tuple should compile");
        const auto contiguous = talas::runtime::renderOffline(
            *compiled.graph,
            frameCount);
        require(contiguous.ok(), "native offline STFT tuple should render");
        require(contiguous.mono.size() == frameCount,
                "native offline STFT should retain caller-requested length");

        talas::runtime::OfflineRenderSession session{*compiled.graph};
        std::vector<double> partitioned;
        const std::vector<std::size_t> partitions{1, 17, 3, 29, 5, 11};
        std::size_t remaining = frameCount;
        std::size_t partitionIndex = 0;
        while (remaining != 0)
        {
            const auto count = std::min(
                remaining,
                partitions[partitionIndex % partitions.size()]);
            const auto block = session.render(count);
            require(block.ok(), "partitioned native offline STFT call should render");
            partitioned.insert(
                partitioned.end(), block.mono.begin(), block.mono.end());
            remaining -= count;
            ++partitionIndex;
        }
        require(partitioned.size() == contiguous.mono.size(),
                "partitioned native STFT should retain output length");
        for (std::size_t frame = 0; frame < frameCount; ++frame)
        {
            requireNear(
                partitioned[frame],
                contiguous.mono[frame],
                1.0e-12,
                "offline native STFT should be render-call partition invariant");
            const auto expected = frame < latency
                ? 0.0
                : direct.mono[frame - latency];
            requireNear(
                contiguous.mono[frame],
                expected,
                1.0e-9,
                "offline native STFT should reconstruct at exact N-1 latency");
        }
    }
}

void testNativeForwardStftInspectionExposesTypedFramesWithoutAudioPacking()
{
    constexpr std::size_t frameCount = 129;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    const auto compiled = talas::runtime::compileProject(
        makeNativeStftForwardInspectionDocument(),
        makeRegistry(),
        settings);
    require(compiled.ok(),
            "forward-only native STFT inspection fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto inspected = session.inspectComplexSpectrum(
        "forward", "spectrumOut", frameCount);
    std::string inspectionDiagnostics;
    for (const auto& diagnostic : inspected.diagnostics)
    {
        inspectionDiagnostics += " [" + diagnostic.nodeId + "."
            + diagnostic.portId + ": " + diagnostic.message + "]";
    }
    require(inspected.ok(),
            "forward-only native STFT inspection should render"
                + inspectionDiagnostics);

    const auto directCompiled = talas::runtime::compileProject(
        makeOscillatorToOutputDocument("1 hz", "1.0"),
        makeRegistry(),
        settings);
    require(directCompiled.ok(),
            "native STFT inspection oracle should compile");
    const auto direct = talas::runtime::renderOffline(
        *directCompiled.graph,
        frameCount);
    require(direct.ok(),
            "native STFT inspection oracle should render");
    const talas::dsp::NativeStftConfiguration configuration{
        64,
        32,
        talas::dsp::SpectralWindowKind::Hann,
    };
    talas::dsp::PreparedForwardStft oracle{configuration};
    const auto capacity = talas::dsp::preparedSpectralFrameCapacity(
        frameCount, configuration.hopSize, 1, 0);
    require(capacity.has_value(),
            "native STFT inspection oracle capacity should be representable");
    talas::dsp::PreparedComplexSpectrumSequence oracleFrames(
        *capacity,
        configuration.frameSize / 2 + 1);
    require(oracle.process(
                direct.mono,
                {1, 0, 0},
                oracleFrames)
                == talas::dsp::NativeStftStatus::Ok,
            "native STFT inspection oracle should process the source samples");
    require(inspected.frames.size() == oracleFrames.frames().size(),
            "forward-only inspection should expose every emitted complex frame");
    for (std::size_t frameIndex = 0;
         frameIndex < inspected.frames.size();
         ++frameIndex)
    {
        const auto& actual = inspected.frames[frameIndex];
        const auto& expected = oracleFrames.frames()[frameIndex];
        require(actual.formatVersion == expected.formatVersion
                    && actual.analysisTimestamp
                        == expected.analysisTimestamp
                    && actual.sourceSequence == expected.sourceSequence
                    && actual.frameSize == expected.frameSize
                    && actual.hopSize == expected.hopSize
                    && actual.window == expected.window
                    && actual.channelIndex == expected.channelIndex
                    && actual.bins.size() == expected.bins.size(),
                "forward-only inspection should retain exact ComplexSpectrumV1 metadata");
        for (std::size_t bin = 0; bin < actual.bins.size(); ++bin)
        {
            requireNear(
                actual.bins[bin].real(),
                expected.bins[bin].real(),
                1.0e-12,
                "forward-only inspection should expose the native real bin");
            requireNear(
                actual.bins[bin].imag(),
                expected.bins[bin].imag(),
                1.0e-12,
                "forward-only inspection should expose the native imaginary bin");
        }
    }

    talas::runtime::OfflineRenderSession invalidTarget{*compiled.graph};
    const auto rejected = invalidTarget.inspectComplexSpectrum(
        "forward", "audioOut", 1);
    require(!rejected.ok() && rejected.frames.empty(),
            "ComplexSpectrum inspection should reject a non-complex target before rendering");
}

void testOfflineNativeStftRejectsMalformedPreparedShapeBeforeProcessing()
{
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    const auto compiled = talas::runtime::compileProject(
        makeNativeStftDocument("64", "32", "hann"),
        makeRegistry(),
        settings);
    require(compiled.ok(),
            "offline malformed native STFT base fixture should compile");

    const auto requireRejected = [&](
        talas::runtime::RuntimePlan plan,
        std::string_view context) {
        talas::runtime::PreparedRuntimeGraph graph{
            std::move(plan), settings};
        talas::runtime::OfflineRenderSession session{graph};
        const auto result = session.render(17);
        require(!result.ok() && result.mono.empty(),
                std::string(context)
                    + " should fail before native STFT processing");
    };
    {
        auto plan = compiled.graph->plan();
        auto spectrum = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "forward"
                    && buffer.portId == "spectrumOut";
            });
        require(spectrum != plan.buffers.end(),
                "offline malformed native STFT fixture should contain its complex buffer");
        spectrum->complexFrameCapacity = 0;
        requireRejected(std::move(plan),
                        "missing offline ComplexSpectrum shape");
    }
    {
        auto plan = compiled.graph->plan();
        auto spectrum = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.nodeId == "forward"
                    && buffer.portId == "spectrumOut";
            });
        spectrum->complexMaximumBinsPerFrame = 34;
        requireRejected(std::move(plan),
                        "mismatched offline ComplexSpectrum bins");
    }
    {
        auto plan = compiled.graph->plan();
        auto audio = std::ranges::find_if(
            plan.buffers,
            [](const talas::runtime::BufferSpec& buffer) {
                return buffer.type == talas::core::PortType::Audio;
            });
        require(audio != plan.buffers.end(),
                "offline malformed native STFT fixture should contain an audio buffer");
        audio->complexChannelCount = 1;
        requireRejected(std::move(plan),
                        "offline complex metadata on a scalar buffer");
    }
    {
        auto plan = compiled.graph->plan();
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(inverse != plan.steps.end(),
                "offline malformed native STFT fixture should contain its inverse");
        auto hop = std::ranges::find(
            inverse->parameters,
            std::string_view{"hopSize"},
            &talas::runtime::ParameterValue::id);
        auto window = std::ranges::find(
            inverse->parameters,
            std::string_view{"window"},
            &talas::runtime::ParameterValue::id);
        require(hop != inverse->parameters.end()
                    && window != inverse->parameters.end(),
                "offline malformed native STFT fixture should retain inverse configuration");
        hop->value = 64.0;
        window->choice = "rectangular";
        requireRejected(std::move(plan),
                        "offline inverse/producer configuration mismatch");
    }
    {
        auto plan = compiled.graph->plan();
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(inverse != plan.steps.end()
                    && !inverse->inputLatencyFrames.empty()
                    && inverse->inputLatencyFrames.front().has_value()
                    && *inverse->inputLatencyFrames.front() > 0,
                "offline malformed native STFT fixture should retain exact inverse latency");
        --*inverse->inputLatencyFrames.front();
        requireRejected(std::move(plan),
                        "mismatched offline inverse input latency");
    }
    {
        auto plan = compiled.graph->plan();
        auto forward = std::ranges::find(
            plan.steps,
            std::string_view{"forward"},
            &talas::runtime::CompileStep::nodeId);
        auto inverse = std::ranges::find(
            plan.steps,
            std::string_view{"inverse"},
            &talas::runtime::CompileStep::nodeId);
        require(forward != plan.steps.end()
                    && inverse != plan.steps.end()
                    && !inverse->inputLatencyFrames.empty(),
                "offline phase-tamper fixture should retain both native steps");
        constexpr std::size_t falseInputLatency = 5;
        constexpr std::size_t falseOutputLatency =
            falseInputLatency + 64 - 1;
        forward->cumulativeInputLatencyFrames = falseInputLatency;
        forward->cumulativeOutputLatencyFrames = falseOutputLatency;
        inverse->inputLatencyFrames.front() = falseOutputLatency;
        inverse->cumulativeInputLatencyFrames = falseOutputLatency;
        inverse->cumulativeOutputLatencyFrames = falseOutputLatency;
        requireRejected(std::move(plan),
                        "forward cumulative phase detached from its offline audio source");
    }
}

void testNativeForwardFramesAreSampleRateIndependentForIdenticalSamples()
{
    constexpr std::size_t frameCount = 129;
    std::vector<double> input(frameCount);
    for (std::size_t frame = 0; frame < input.size(); ++frame)
    {
        input[frame] = 0.3 * std::sin(0.17 * static_cast<double>(frame))
            + 0.2 * std::cos(0.043 * static_cast<double>(frame));
    }
    const auto inspectAtRate = [&](double sampleRate) {
        talas::runtime::RenderSettings settings;
        settings.sampleRate = sampleRate;
        settings.maxBlockFrames = 17;
        settings.audioInputChannels.push_back({1, input});
        auto compiled = talas::runtime::compileProject(
            makeNativeStftInputInspectionDocument(),
            makeRegistry(),
            settings);
        require(compiled.ok(),
                "sample-rate-independent native STFT fixture should compile");
        talas::runtime::OfflineRenderSession session{*compiled.graph};
        auto result = session.inspectComplexSpectrum(
            "forward", "spectrumOut", frameCount);
        require(result.ok(),
                "sample-rate-independent native STFT fixture should render");
        return result;
    };

    const auto first = inspectAtRate(44100.0);
    const auto second = inspectAtRate(96000.0);
    require(first.frames.size() == second.frames.size(),
            "sample rate should not change sample-domain native frame count");
    for (std::size_t index = 0; index < first.frames.size(); ++index)
    {
        const auto& left = first.frames[index];
        const auto& right = second.frames[index];
        require(left.analysisTimestamp == right.analysisTimestamp
                    && left.sourceSequence == right.sourceSequence
                    && left.frameSize == right.frameSize
                    && left.hopSize == right.hopSize
                    && left.window == right.window
                    && left.channelIndex == right.channelIndex
                    && left.bins == right.bins,
                "identical samples should produce identical native metadata and bins at any sample rate");
    }
}

void testSerialNativeStftRoundTripsHonorKnownUpstreamLatencyOffline()
{
    constexpr std::size_t frameCount = 96;
    constexpr std::size_t impulseFrame = 4;
    constexpr std::size_t expectedLatency = 2 * (16 - 1);
    std::vector<double> input(frameCount, 0.0);
    input[impulseFrame] = 1.0;
    talas::runtime::RenderSettings settings;
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 17;
    settings.audioInputChannels.push_back({1, input});
    const auto compiled = talas::runtime::compileProject(
        makeSerialNativeStftAudioInputDocument(),
        makeRegistry(),
        settings);
    require(compiled.ok(),
            "serial offline native STFT fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto rendered = session.render(frameCount);
    require(rendered.ok(),
            "serial native STFT round trips should render with known upstream latency");
    for (std::size_t frame = 0; frame < frameCount; ++frame)
    {
        requireNear(
            rendered.mono[frame],
            frame == impulseFrame + expectedLatency ? 1.0 : 0.0,
            1.0e-9,
            "serial native STFT round trips should retain exact cumulative phase");
    }
}

void testHandBuiltFftRejectsUnsupportedLengthAtRender()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {"osc", "talas.oscillator", {}, {{"frequency", talas::expr::ValueDomain::Hertz, 1.0}, {"amplitude", talas::expr::ValueDomain::Scalar, 1.0}}},
        {
            "fft",
            "talas.fft",
            {binding("audioIn", "osc", "audioOut", 0)},
            {{"length", talas::expr::ValueDomain::Scalar, 2.0}, booleanRuntimeParameter("inverse", false)},
        },
        {"out", "talas.audioOutput", {binding("audioIn", "fft", "audioOut", 1)}, {}},
    };
    plan.buffers = {
        {"osc", "audioOut", talas::core::PortType::Audio, 5},
        {"fft", "audioOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;
    plan.outputBufferIndices = {1};

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan)), 5);

    require(!result.ok(), "hand-built unsupported fft length should fail render");
    require(result.mono.empty(), "failed fft render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "fft", {}, "length"), "render should identify fft length parameter");
}

void requireConstantSamples(const std::vector<double>& samples, double expected, const std::string& label)
{
    require(samples.size() == 5, label + " should return requested frames");
    for (std::size_t frame = 0; frame < samples.size(); ++frame)
        requireNear(samples[frame], expected, 1.0e-12, label + " frame " + std::to_string(frame));
}

