void testSyntheticSpectrumUsesShortestApplicableArrayPrefix()
{
    const auto renderPrefix = [](
                                  std::vector<talas::project::ProjectParameterExpression> parameters,
                                  std::string_view label) {
        const auto result = renderDocument(
            makeSyntheticSpectrumTrackSelectorDocument(
                std::move(parameters),
                spectrumTrackSelectorParameters({{"track", "1"}})),
            4.0,
            5);
        require(result.ok(), std::string(label) + " common-prefix render should succeed");
        requireConstantSamples(result.mono, 0.5, std::string(label) + " selected amplitude");
        requireConstantSamples(result.right, 100.0, std::string(label) + " selected frequency");
    };

    renderPrefix(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "3"},
            {"envelope", "1"},
            textParameter("amplitudes", "0.5"),
            textParameter("frequencies", "100 -200"),
            textParameter("bandwidths", "10 -20 -30"),
        }),
        "amplitude-shortest");
    renderPrefix(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "3"},
            {"envelope", "1"},
            textParameter("amplitudes", "0.5 0.25"),
            textParameter("frequencies", "100"),
            textParameter("bandwidths", "10 20 30"),
        }),
        "frequency-shortest");
    renderPrefix(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "3"},
            {"envelope", "1"},
            textParameter("amplitudes", "0.5 0.25"),
            textParameter("frequencies", "100 200"),
            textParameter("bandwidths", "10"),
        }),
        "bandwidth-shortest");

    const auto disabledBandwidth = renderDocument(
        makeSyntheticSpectrumTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "4096"},
                booleanParameter("sendBandwidths", false),
                {"envelope", "1"},
                textParameter("amplitudes", "0.5 0.25"),
                textParameter("frequencies", "100 200"),
                textParameter("bandwidths", ""),
            }),
            spectrumTrackSelectorParameters({{"track", "2"}})),
        4.0,
        5);
    require(disabledBandwidth.ok(), "disabled bandwidth array should not truncate the common prefix");
    requireConstantSamples(disabledBandwidth.mono, 0.25, "disabled-bandwidth second amplitude");
    requireConstantSamples(disabledBandwidth.right, 200.0, "disabled-bandwidth second frequency");

    const auto discardedTrack = renderDocument(
        makeSyntheticSpectrumTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "3"},
                {"envelope", "1"},
                textParameter("amplitudes", "0.5"),
                textParameter("frequencies", "100 -200"),
                textParameter("bandwidths", "10 -20 -30"),
            }),
            spectrumTrackSelectorParameters({{"track", "2"}})),
        4.0,
        5);
    require(!discardedTrack.ok(), "selector should reject a track discarded by the common prefix");
    require(discardedTrack.mono.empty(), "discarded-track failure should publish no audio");
    require(
        hasDiagnostic(discardedTrack, DiagnosticCode::GraphValidationFailed, "selector", {}, "track"),
        "discarded-track failure should identify the downstream selector");
}

