void testSyntheticSpectrumBraceExpressionsFailClosedAndIgnoreDisabledBandwidth()
{
    for (const auto& source : {
             std::string{"0.5 {1 + }"},
             std::string{"0.5 {TrackNumber}"},
             std::string{"0.5 {previous(1, 0)}"},
             std::string{"0.5 {1 / 0}"},
         })
    {
        requireSyntheticSpectrumRenderFailure(
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "1"},
                textParameter("amplitudes", source),
                textParameter("frequencies", "100"),
            }),
            "amplitudes");
    }
    // An element that follows an Event Value or a variable is a compiled
    // field of its own; one nothing declares fails to compile.
    for (const auto& source : {std::string{"0.5 {!Gain}"}, std::string{"0.5 {@gain}"}})
    {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = 5;
        require(!talas::runtime::compileProject(
                    makeSyntheticSpectrumTrackSelectorDocument(
                        syntheticSpectrumFromArrayParameters({
                            {"nbrPartials", "1"},
                            textParameter("amplitudes", source),
                            textParameter("frequencies", "100"),
                        }),
                        spectrumTrackSelectorParameters()),
                    makeRegistry(), settings)
                     .ok(),
            "an undeclared live synthetic spectrum element should fail to compile: " + source);
    }

    requireSyntheticSpectrumRenderFailure(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            textParameter("amplitudes", "0.5"),
            textParameter("frequencies", "100 {1 s}"),
        }),
        "frequencies");

    const auto disabledBandwidth = renderDocument(
        makeSyntheticSpectrumTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "1"},
                booleanParameter("sendBandwidths", false),
                {"envelope", "1"},
                textParameter("amplitudes", "{0.5}"),
                textParameter("frequencies", "{100 hz}"),
                textParameter("bandwidths", "{{malformed"),
            }),
            spectrumTrackSelectorParameters({{"track", "1"}})),
        4.0,
        5);
    require(
        disabledBandwidth.ok(),
        "C65 disabled bandwidth expression text should remain inert");
    requireConstantSamples(
        disabledBandwidth.mono,
        0.5,
        "C65 disabled-bandwidth brace amplitude");
    requireConstantSamples(
        disabledBandwidth.right,
        100.0,
        "C65 disabled-bandwidth brace frequency");
}

