void testSyntheticSpectrumFromArraySerializesPairsAcrossOfflineBlocks()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.syntheticSpectrumFromArray",
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "3"},
                booleanParameter("sendBandwidths", false),
                {"envelope", "0.5"},
                textParameter("amplitudes", "1 0.5 0.25"),
                textParameter("frequencies", "1 2 3"),
            })),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "out", "audioIn"),
        connection("source", "frequencyOut", "out", "rightIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 2};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok() && compiled.graph.has_value(),
        "serialized SyntheticSpectrumFromArray graph should compile");
    const auto rendered = talas::runtime::renderOffline(*compiled.graph, 8);
    require(rendered.ok()
            && rendered.mono == std::vector<double>{
                0.5, 0.25, 0.125, 0.5, 0.25, 0.125, 0.5, 0.25}
            && rendered.right == std::vector<double>{
                1, 2, 3, 1, 2, 3, 1, 2},
        "SyntheticSpectrumFromArray partial phase should persist across offline blocks");

    auto bankDocument = document;
    bankDocument.graph.nodes.push_back(node("bank", "talas.oscillatorBank",
        oscillatorBankParameters({resourceParameter("wavetable", "Quarter")})));
    bankDocument.graph.connections = {
        connection("source", "amplitudeOut", "bank", "amplitudeIn"),
        connection("source", "frequencyOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "out", "audioIn"),
    };
    settings.tableResources = {{"Quarter", {0.0, 1.0, 0.0, -1.0}}};
    const auto bank = talas::runtime::compileProject(
        bankDocument, makeRegistry(), settings);
    require(bank.ok() && bank.graph.has_value(),
        "serialized SyntheticSpectrumFromArray should feed OscillatorBank");
    const auto bankRendered = talas::runtime::renderOffline(*bank.graph, 8);
    require(bankRendered.ok() && bankRendered.mono.size() == 8
            && std::ranges::any_of(bankRendered.mono,
                [](double sample) { return sample != 0.0; }),
        "OscillatorBank should synthesize the serialized source pairs");
}

void testSyntheticSpectrumFromSoundsStreamsPairsIntoOscillatorBank()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("amps", "talas.audioInput"),
        node("freqs", "talas.audioInput", {
            booleanParameter("channel1", false),
            booleanParameter("channel2", true)}),
        node("source", "talas.syntheticSpectrumFromSounds",
            syntheticSpectrumFromSoundsParameters()),
        node("bank", "talas.oscillatorBank",
            oscillatorBankParameters({
                resourceParameter("wavetable", "Quarter")})),
    };
    document.graph.connections = {
        connection("amps", "audioOut", "source", "amplitudes"),
        connection("freqs", "audioOut", "source", "frequenciesAndBandwidths"),
        connection("source", "amplitudeOut", "bank", "amplitudeIn"),
        connection("source", "frequencyOut", "bank", "frequencyIn"),
        connection("bank", "audioOut", "out", "audioIn"),
    };
    talas::runtime::RenderSettings settings{8.0, 1};
    settings.tableResources = {
        {"Quarter", {0.0, 1.0, 0.0, -1.0}}};
    settings.audioInputChannels = {
        {1, {0.5, 0.25, 1.0, 0.75, 1.0, 1.0}},
        {2, {1, 2, 2, 1, 1, 2}},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "serialized SyntheticSpectrumFromSounds graph should compile");
    const auto rendered = talas::runtime::renderOffline(*compiled.graph, 6);
    require(rendered.ok() && rendered.mono.size() == 6,
        "serialized SyntheticSpectrumFromSounds should render with one-frame blocks");
    // Each oscillator advances its own phase by its partial's frequency.
    constexpr std::array<double, 6> expected{
        0.0, 0.25, 1.25, 0.0, -1.375, -1.5};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(rendered.mono[frame], expected[frame], 1.0e-12,
            "serialized SyntheticSpectrumFromSounds pair sample");
}

