void testSyntheticSpectrumFromSoundsRejectsDynamicConnectedNbrPartials()
{
    auto document = makeSyntheticSpectrumFromSoundsTrackSelectorDocument(
        syntheticSpectrumFromSoundsParameters({{"nbrPartials", "1"}}),
        spectrumTrackSelectorParameters({{"track", "1"}}));
    document.graph.nodes.push_back(node("nbrPartialsRaw", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/NbrPartials")})));
    document.graph.nodes.push_back(node("nbrPartials", "talas.scaleAndOffset", {{"scale", "1.0"}, {"offset", "1.0"}}));
    document.graph.connections.push_back(connection("nbrPartialsRaw", "value", "nbrPartials", "value"));
    document.graph.connections.push_back(connection("nbrPartials", "value", "spectrum", "nbrPartials"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.audioInputChannels = {
        {1, {1.0, 0.25}},
        {2, {100.0, 200.0}},
    };
    settings.tableResources = {{"Tables/NbrPartials", {0.0, 1.0, 0.0, 1.0, 0.0}}};

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic connected-nbrPartials synthetic spectrum from sounds document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "synthetic spectrum from sounds should reject dynamic connected nbrPartials");
    require(result.mono.empty(), "failed dynamic nbrPartials synthetic spectrum from sounds render should not return left audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", "nbrPartials", {}),
        "render should identify dynamic synthetic spectrum from sounds nbrPartials input");
}

