void testLiveSpectralAnalysisRejectsMalformedPreparedPartialShape()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 64;
    settings.audioInputChannels.push_back(
        {1, liveSpectralSine(64, 8.0, 1.0)});
    const auto compile = talas::runtime::compileProject(
        makeLiveSpectralAnalysisTrackSelectorDocument(),
        makeRegistry(),
        settings);
    require(compile.ok(), "live spectral shape fixture should compile");

    auto malformedPlan = compile.graph->plan();
    const auto partialBuffer = std::ranges::find_if(
        malformedPlan.buffers,
        [](const talas::runtime::BufferSpec& buffer) {
            return buffer.nodeId == "spectrum"
                && buffer.portId == "spectrumOut";
        });
    require(partialBuffer != malformedPlan.buffers.end(),
            "live spectral fixture should expose a partial output buffer");
    partialBuffer->partialFrameCapacity = 0;
    const talas::runtime::PreparedRuntimeGraph malformedGraph{
        std::move(malformedPlan), settings};
    const auto result = talas::runtime::renderOffline(malformedGraph, 64);

    require(!result.ok(),
            "malformed prepared PartialSpectrumV1 shape should fail before processing");
    require(result.mono.empty() && result.right.empty(),
            "malformed partial shape should fail closed without audio");
    require(hasDiagnosticMessageContaining(
                result,
                DiagnosticCode::GraphValidationFailed,
                {},
                {},
                "PartialSpectrumV1 runtime buffer is missing its exact prepared shape"),
            "malformed partial shape should report the exact preparation authority");
}

