void testSpectrumInRamSerializesSelectedPartialPairsAcrossBlocks()
{
    talas::project::ProjectDocument document;
    document.graph.nodes = {
        node("out", "talas.audioOutput"),
        node("source", "talas.spectrumInRam",
            spectrumInRamParameters({{"firstPartial", "2"}})),
    };
    document.graph.connections = {
        connection("source", "amplitudeOut", "out", "audioIn"),
        connection("source", "frequencyOut", "out", "rightIn"),
    };
    talas::runtime::RenderSettings settings{1000.0, 3};
    settings.tableResources = {{"Analysis/RAM", {
        1.0, 1.0, 0.0,
        0.5, 2.0, 0.0,
        0.25, 3.0, 0.0,
    }}};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "serialized SpectrumInRAM graph should compile");
    const auto rendered = talas::runtime::renderOffline(
        *compiled.graph, 7);
    require(rendered.ok(),
        "serialized SpectrumInRAM should render across internal blocks");
    require(rendered.mono == std::vector<double>{
            0.25, 0.125, 0.25, 0.125, 0.25, 0.125, 0.25}
            && rendered.right == std::vector<double>{
                200, 300, 200, 300, 200, 300, 200},
        "SpectrumInRAM should emit one selected amplitude/frequency pair per sample");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(3);
    const auto second = session.render(4);
    require(first.ok() && second.ok()
            && first.mono == std::vector<double>{0.25, 0.125, 0.25}
            && second.mono == std::vector<double>{
                0.125, 0.25, 0.125, 0.25},
        "separate offline calls should preserve the serial partial phase");
    session.reset();
    const auto restarted = session.render(3);
    require(restarted.ok() && restarted.mono == first.mono
            && restarted.right == first.right,
        "offline reset should restart at the first selected partial");
}

