void testC58SpectrumInRamReadsControlsOncePerOfflineWindow()
{
    const std::array cases{
        std::pair{"frequency", std::vector<double>{100.0, 100.0, 200.0, 200.0}},
        std::pair{"level", std::vector<double>{0.5, 0.5, 1.0, 1.0}},
        std::pair{"timeIndex", std::vector<double>{-1.0, -1.0, 1.0, 1.0}},
        std::pair{"nbrPartials", std::vector<double>{2.0, 2.0, 1.0, 1.0}},
        std::pair{"firstPartial", std::vector<double>{1.0, 1.0, 2.0, 2.0}},
    };
    for (const auto& [port, values] : cases)
    {
        // One partial, so the second can be the first selected.
        auto document = makeSpectrumInRamTrackSelectorDocument(
            spectrumInRamParameters({
                {"analysisFrames", "2"},
                {"nbrPartials", std::string_view{port} == "firstPartial" ? "1" : "2"},
            }));
        document.graph.nodes.push_back(node(
            "control", "talas.triggeredTableRead",
            triggeredTableReadParameters({
                resourceParameter("wavetable", "Tables/C58Control"),
            })));
        document.graph.connections.push_back(connection(
            "control", "value", "source", port));

        auto settings = talas::runtime::RenderSettings{1000.0, 2};
        settings.tableResources = {
            {"Analysis/RAM", {
                1.0, 1.0, 0.1,
                0.5, 2.0, 0.2,
                0.25, 3.0, 0.3,
                0.125, 4.0, 0.4,
            }},
            {"Tables/C58Control", values},
        };
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(
            compiled.ok(),
            "C58 offline transaction-control fixture should compile");
        // Each callback-sized window reads the controls at its start, so
        // one render of both windows plays as two renders of one each.
        const auto result = talas::runtime::renderOffline(*compiled.graph, 4);
        talas::runtime::OfflineRenderSession partitioned(*compiled.graph);
        const auto firstWindow = partitioned.render(2);
        const auto secondWindow = partitioned.render(2);
        require(
            result.ok() && firstWindow.ok() && secondWindow.ok()
                && result.mono.size() == 4
                && std::equal(firstWindow.mono.begin(), firstWindow.mono.end(), result.mono.begin())
                && std::equal(secondWindow.mono.begin(), secondWindow.mono.end(), result.mono.begin() + 2)
                && std::equal(firstWindow.right.begin(), firstWindow.right.end(), result.right.begin())
                && std::equal(secondWindow.right.begin(), secondWindow.right.end(), result.right.begin() + 2),
            std::string("C58 offline SpectrumInRAM should read ")
                + port
                + " once per callback-sized window of one public render");
    }

    auto document = makeSpectrumInRamTrackSelectorDocument(
        spectrumInRamParameters({{"analysisFrames", "2"}}));
    document.graph.nodes.push_back(node(
        "control", "talas.triggeredTableRead",
        triggeredTableReadParameters({
            resourceParameter("wavetable", "Tables/C58Control"),
        })));
    document.graph.connections.push_back(connection(
        "control", "value", "source", "timeIndex"));
    auto settings = talas::runtime::RenderSettings{1000.0, 2};
    settings.tableResources = {
        {"Analysis/RAM", {
            1.0, 1.0, 0.1,
            0.5, 2.0, 0.2,
            0.25, 3.0, 0.3,
            0.125, 4.0, 0.4,
        }},
        {"Tables/C58Control", {-1.0, -1.0, -1.0, -1.0}},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "C58 offline constant transaction-control fixture should compile");
    const auto result = talas::runtime::renderOffline(*compiled.graph, 4);
    require(
        result.ok(),
        "C58 offline SpectrumInRAM should preserve constant-control parity across internal blocks");
    require(
        result.mono.size() == 4,
        "C58 offline public transaction should return every requested frame");
    for (const auto sample : result.mono)
    {
        requireNear(
            sample, 0.5, 0.0,
            "C58 offline public transaction should reuse the captured normalized coordinate");
    }
}

