void testC60SpectrumOnDiskDefaultsToOriginalPitchAndRemainingPartials()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 3;
    settings.tableResources = {{"Analysis/Disk", {
        0.2, 1.0, 0.1,
        0.4, 2.0, 0.2,
        0.6, 3.0, 0.3,
        0.8, 1.5, 0.15,
        1.0, 2.5, 0.25,
        1.2, 3.5, 0.35,
    }}};
    const auto document = makeSpectrumOnDiskTrackSelectorDocument(
        {
            resourceParameter("fileName", "Analysis/Disk"),
            {"analysisFrames", "2"},
            {"analysisFrequency", "125 hz"},
            {"rateScale", "1"},
        },
        spectrumTrackSelectorParameters({{"track", "3"}}));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "C60 default-metadata SpectrumOnDisk fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(5);
    const auto second = session.render(5);
    require(
        first.ok() && second.ok(),
        "C60 default-metadata SpectrumOnDisk scan should publish both transactions");
    // One analysis frame per 3-frame window: the first render's
    // second window already reaches the final frame.
    require(
        first.mono == std::vector<double>{0.6, 0.6, 0.6, 1.2, 1.2},
        "C60 default count should retain the final partial of each frame");
    require(
        first.right == std::vector<double>{375.0, 375.0, 375.0, 437.5, 437.5},
        "C60 default pitch should scale each frame by analysisFrequency");
    requireConstantSamples(
        second.mono, 1.2,
        "C60 default scan should stay on the final frame amplitude");
    requireConstantSamples(
        second.right, 437.5,
        "C60 default scan should preserve original pitch on the final frame");

    session.reset();
    const auto reset = session.render(5);
    require(
        reset.ok() && reset.mono == first.mono
            && reset.right == first.right,
        "C60 reset should restore default metadata and scan state exactly");
}

