void testSpectrumOnDiskSessionScansAndInterpolatesLogicalFrames()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};

    const auto document = makeSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"frequency", "100 hz"},
            {"level", "1"},
            {"rateScale", "0.5"},
            {"analysisFrames", "3"},
            {"firstPartial", "1"},
            {"nbrPartials", "1"},
        }));
    const auto compile = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compile.ok(),
            "C56 logical-frame Spectrum On Disk fixture should compile");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(1);
    const auto half = session.render(1);
    const auto second = session.render(1);
    const auto oneAndHalf = session.render(1);
    const auto clamped = session.render(1);

    require(first.ok() && half.ok() && second.ok()
                && oneAndHalf.ok() && clamped.ok(),
            "C56 logical-frame scan should publish every transaction");
    requireNear(first.mono[0], 0.1, 1.0e-12,
                "C56 scan should begin at frame zero amplitude");
    requireNear(first.right[0], 100.0, 1.0e-12,
                "C56 scan should begin at frame zero frequency");
    requireNear(half.mono[0], 0.3, 1.0e-12,
                "C56 half-rate cursor should interpolate amplitude");
    requireNear(half.right[0], 150.0, 1.0e-12,
                "C56 half-rate cursor should interpolate frequency");
    requireNear(second.mono[0], 0.5, 1.0e-12,
                "C56 half-rate cursor should reach frame one");
    requireNear(oneAndHalf.mono[0], 0.7, 1.0e-12,
                "C56 half-rate cursor should interpolate the final pair");
    requireNear(clamped.mono[0], 0.9, 1.0e-12,
                "C56 scan should clamp at the final frame");
}

void testSpectrumOnDiskEmptyTransactionUsesConnectedControlSnapshots()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    settings.eventValues = {
        {"C56Rate", 1.0, talas::expr::ValueDomain::Scalar},
        {"C56Trigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto document = makeSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"frequency", "100 hz"},
            {"level", "1"},
            {"rateScale", "0"},
            {"trigger", "-1"},
            {"analysisFrames", "3"},
            {"nbrPartials", "1"},
            {"firstPartial", "1"},
        }));
    document.graph.nodes.push_back(node(
        "rateControl", "talas.constant", {{"value", "!C56Rate"}}));
    document.graph.nodes.push_back(node(
        "triggerControl", "talas.constant", {{"value", "!C56Trigger"}}));
    document.graph.connections.push_back(connection(
        "rateControl", "value", "source", "rateScale"));
    document.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
            "C56 offline empty-transaction fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto empty = session.render(0);
    const auto afterEmpty = session.render(1);
    require(
        empty.ok() && empty.mono.empty() && empty.right.empty()
            && afterEmpty.ok()
            && afterEmpty.mono[0] == 0.5
            && afterEmpty.right[0] == 200.0,
        "C56 offline empty transaction must use connected rate/trigger precedence and advance once: emptyOk="
            + std::to_string(empty.ok()) + ", afterOk="
            + std::to_string(afterEmpty.ok()) + ", monoSize="
            + std::to_string(afterEmpty.mono.size()) + ", mono="
            + (afterEmpty.mono.empty() ? std::string{"empty"}
                                       : std::to_string(afterEmpty.mono[0]))
            + ", right="
            + (afterEmpty.right.empty() ? std::string{"empty"}
                                        : std::to_string(afterEmpty.right[0]))
            + ", diagnostic="
            + (empty.diagnostics.empty() ? std::string{"none"}
                                         : empty.diagnostics.front().nodeId
                                               + "."
                                               + empty.diagnostics.front().portId
                                               + ": "
                                               + empty.diagnostics.front().message));

    session.reset();
    const auto reset = session.render(1);
    require(
        reset.ok() && reset.mono[0] == 0.1
            && reset.right[0] == 100.0,
        "C56 offline reset after an empty transaction must restore pristine scan state");
}

void testSpectrumOnDiskOfflineTriggerLifecycleAndRetryRollback()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    settings.eventValues = {
        {"C56Trigger", 0.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1, "C56Trigger", 1.0, talas::expr::ValueDomain::Scalar},
        {3, "C56Trigger", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "C56Trigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    auto document = makeSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"frequency", "100 hz"}, {"level", "1"},
            {"rateScale", "1"}, {"trigger", "0"},
            {"analysisFrames", "3"}, {"nbrPartials", "1"},
            {"firstPartial", "1"},
        }));
    document.graph.nodes.push_back(node(
        "triggerControl", "talas.constant",
        {{"value", "!C56Trigger"}}));
    document.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C56 offline trigger lifecycle should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    std::array<double, 5> actual{};
    for (std::size_t transaction = 0; transaction < actual.size(); ++transaction)
    {
        const auto block = session.render(1);
        require(block.ok(), "C56 offline trigger lifecycle transaction should render");
        actual[transaction] = block.mono[0];
    }
    require(
        actual == std::array<double, 5>{0.1, 0.1, 0.5, 0.9, 0.1},
        "C56 offline trigger must restart on rising edges, sustain, close, and rearm exactly");
    session.reset();
    const auto reset = session.render(1);
    require(
        reset.ok() && reset.mono[0] == 0.1,
        "C56 offline reset must restore trigger and cursor history");

    auto failingSettings = settings;
    failingSettings.maxBlockFrames = 5;
    failingSettings.tableResources = {{"Analysis/Disk", {
        2.0, 1.0, 0.1,
        4.0, 2.0, 0.2,
        6.0, 3.0, 0.3,
    }}};
    failingSettings.eventValueChanges = {{
        2, "C56Downstream",
        std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar,
    }};
    failingSettings.eventValues = {{
        "C56Downstream", 1.0, talas::expr::ValueDomain::Scalar,
    }};
    auto failingDocument = makeSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"frequency", "100 hz"}, {"level", "1"},
            {"rateScale", "1"}, {"trigger", "0"},
            {"analysisFrames", "3"}, {"nbrPartials", "1"},
            {"firstPartial", "1"},
        }));
    failingDocument.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "1"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.nodes.push_back(node(
        "downstreamControl", "talas.constant",
        {{"value", "!C56Downstream"}}));
    std::erase_if(
        failingDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "selector"
                && edge.fromPort == "leftOut"
                && edge.toNode == "out";
        });
    failingDocument.graph.connections.push_back(connection(
        "selector", "leftOut", "downstream", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "downstreamControl", "value", "downstream", "left"));
    failingDocument.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));
    const auto failingCompiled = talas::runtime::compileProject(
        failingDocument, makeRegistry(), failingSettings);
    require(failingCompiled.ok(), "C56 offline downstream rollback should compile");
    talas::runtime::OfflineRenderSession failing{*failingCompiled.graph};
    const auto rejected = failing.render(5);
    const auto retry = failing.render(1);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && retry.mono[0] == 2.0,
        "C56 offline downstream failure must publish nothing and preserve the retry cursor");
}

void testSpectrumOnDiskNestedScopesOwnIndependentOfflineState()
{
    talas::project::ProjectSoundDefinition definition;
    definition.definitionId = "c56Cell";
    definition.displayName = "C56 Cell";
    definition.graph.nodes = {
        node("source", "talas.spectrumOnDisk", spectrumOnDiskParameters({
            {"frequency", "100 hz"}, {"level", "1"},
            {"rateScale", "1"}, {"trigger", "0"},
            {"analysisFrames", "3"}, {"nbrPartials", "1"},
            {"firstPartial", "1"},
        })),
        node("selector", "talas.spectrumTrackSelector",
             spectrumTrackSelectorParameters({{"track", "1"}})),
    };
    definition.graph.connections = {connection(
        "source", "spectrumOut", "selector", "spectrumIn")};
    definition.outputs = {
        {"leftOut", talas::core::PortType::Audio, "selector", "leftOut"},
        {"rightOut", talas::core::PortType::Audio, "selector", "rightOut"},
    };
    talas::project::ProjectNode first;
    first.instanceId = "firstCell";
    first.soundDefinitionId = definition.definitionId;
    talas::project::ProjectNode second;
    second.instanceId = "secondCell";
    second.soundDefinitionId = definition.definitionId;

    talas::project::ProjectDocument document;
    document.soundDefinitions.push_back(std::move(definition));
    document.graph.nodes = {
        std::move(first), std::move(second), node("out", "talas.audioOutput")};
    document.graph.connections = {
        connection("firstCell", "leftOut", "out", "audioIn"),
        connection("secondCell", "leftOut", "out", "rightIn"),
    };
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.5, 2.0, 0.2,
        0.9, 3.0, 0.3,
    }}};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "nested C56 scope fixture should compile: "
            + (compiled.diagnostics.empty()
                   ? std::string{"no diagnostic"}
                   : compiled.diagnostics.front().nodeId + "."
                         + compiled.diagnostics.front().portId + "."
                         + compiled.diagnostics.front().parameterId + ": "
                         + compiled.diagnostics.front().message));
    std::vector<talas::runtime::RuntimeScopeId> scopes;
    for (const auto& step : compiled.graph->plan().steps)
    {
        if (step.typeId == "talas.spectrumOnDisk")
            scopes.push_back(step.scopeId);
    }
    require(
        scopes.size() == 2 && scopes[0] != scopes[1]
            && scopes[0] != talas::runtime::globalRuntimeScope
            && scopes[1] != talas::runtime::globalRuntimeScope,
        "nested C56 instances must compile to distinct non-global runtime scopes");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto firstBlock = session.render(1);
    const auto secondBlock = session.render(1);
    require(
        firstBlock.ok() && secondBlock.ok()
            && firstBlock.mono[0] == 0.1 && firstBlock.right[0] == 0.1
            && secondBlock.mono[0] == 0.5 && secondBlock.right[0] == 0.5,
        "nested C56 scopes must advance identical independent scan state");
}

void testSpectrumOnDiskRejectsInvalidC56FrameLayouts()
{
    auto result = renderSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"analysisFrames", "2"},
            {"firstPartial", "1"},
            {"nbrPartials", "1"},
        }),
        {{"Analysis/Disk", {
            0.1, 1.0, 0.1,
            0.2, 2.0, 0.2,
            0.3, 3.0, 0.3,
        }}});
    require(!result.ok(),
            "C56 should reject a table that does not divide by analysisFrames");
    require(result.mono.empty(),
            "invalid C56 frame division should publish no audio");
    require(hasDiagnostic(
                result, DiagnosticCode::GraphValidationFailed,
                "source", {}, "fileName"),
            "invalid C56 frame division should identify fileName");

    result = renderSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"analysisFrames", "2"},
            {"firstPartial", "2"},
            {"nbrPartials", "1"},
        }),
        {{"Analysis/Disk", {
            0.1, 1.0, 0.1,
            0.2, 2.0, 0.2,
        }}});
    require(!result.ok(),
            "C56 should reject a selected range beyond fixed frame width");
    require(result.mono.empty(),
            "out-of-frame C56 range should publish no audio");

    std::vector<double> oversizedFrame(4097U * 3U, 0.0);
    for (std::size_t partial = 0; partial < 4097U; ++partial)
        oversizedFrame[partial * 3U + 1U] = 1.0;
    result = renderSpectrumOnDiskTrackSelectorDocument(
        spectrumOnDiskParameters({
            {"analysisFrames", "1"},
            {"firstPartial", "1"},
            {"nbrPartials", "1"},
        }),
        {{"Analysis/Disk", std::move(oversizedFrame)}});
    require(!result.ok(),
            "C56 should reject a frame wider than 4096 partials");
    require(result.mono.empty(),
            "oversized C56 frame should publish no audio");
}

void testSpectrumOnDiskRejectsNearZeroTriggerChangesAtomically()
{
    const auto parameters = spectrumOnDiskParameters({
        {"frequency", "100 hz"},
        {"level", "1"},
        {"rateScale", "1"},
        {"trigger", "0"},
        {"analysisFrames", "2"},
        {"nbrPartials", "1"},
        {"firstPartial", "1"},
    });

    auto segmentedDocument =
        makeSpectrumOnDiskTrackSelectorDocument(parameters);
    segmentedDocument.graph.nodes.push_back(node(
        "triggerControl", "talas.constant", {{"value", "!C56Trigger"}}));
    segmentedDocument.graph.connections.push_back(connection(
        "triggerControl", "value", "source", "trigger"));

    auto segmentedSettings = talas::runtime::RenderSettings{};
    segmentedSettings.sampleRate = 1000.0;
    segmentedSettings.maxBlockFrames = 5;
    segmentedSettings.tableResources = {{"Analysis/Disk", {
        0.1, 1.0, 0.1,
        0.9, 2.0, 0.2,
    }}};
    segmentedSettings.eventValues = {
        {"C56Trigger", 0.0, talas::expr::ValueDomain::Scalar},
    };
    segmentedSettings.eventValueChanges = {
        {2, "C56Trigger", 5.0e-13, talas::expr::ValueDomain::Scalar},
    };
    const auto segmentedCompiled = talas::runtime::compileProject(
        segmentedDocument, makeRegistry(), segmentedSettings);
    require(
        segmentedCompiled.ok(),
        "near-zero segmented C56 trigger fixture should compile");
    talas::runtime::OfflineRenderSession segmentedSession{
        *segmentedCompiled.graph};
    // The trigger changes inside the window and waits for the next one.
    const auto segmented = segmentedSession.render(5);
    require(
        segmented.ok() && segmented.mono.size() == 5
            && segmented.mono.front() == 0.1
            && segmented.right.front() == 100.0,
        "a near-zero trigger inside a window should wait for the next one");
}

void testC60SpectrumOnDiskTakesLateOfflineControlChangesPerWindow()
{
    struct ControlCase
    {
        std::string_view port;
        double initialValue;
        double changedValue;
    };
    constexpr std::array cases{
        ControlCase{"frequency", 100.0, 125.0},
        ControlCase{"level", 1.0, 0.5},
        ControlCase{"rateScale", 1.0, 0.5},
        ControlCase{"trigger", 0.0, 1.0},
        ControlCase{"nbrPartials", 2.0, 1.0},
        ControlCase{"firstPartial", 1.0, 2.0},
    };

    for (const auto& controlCase : cases)
    {
        auto document = makeSpectrumOnDiskTrackSelectorDocument(
            spectrumOnDiskParameters({
                {"frequency", "100 hz"},
                {"level", "1"},
                {"rateScale", "1"},
                {"trigger", "0"},
                {"analysisFrames", "2"},
                {"nbrPartials", "2"},
                {"firstPartial", "1"},
            }));
        document.graph.nodes.push_back(node(
            "control", "talas.constant", {{"value", "!C60Control"}}));
        document.graph.connections.push_back(connection(
            "control", "value", "source",
            std::string{controlCase.port}));

        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 1000.0;
        settings.maxBlockFrames = 2;
        settings.tableResources = {{"Analysis/Disk", {
            0.2, 1.0, 0.1,
            0.4, 2.0, 0.2,
            0.6, 3.0, 0.3,
            0.8, 1.5, 0.15,
            1.0, 2.5, 0.25,
            1.2, 3.5, 0.35,
        }}};
        settings.eventValues = {{
            "C60Control", controlCase.initialValue,
            talas::expr::ValueDomain::Scalar,
        }};
        settings.eventValueChanges = {{
            2, "C60Control", controlCase.changedValue,
            talas::expr::ValueDomain::Scalar,
        }};
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(
            compiled.ok(),
            std::string{"C60 late-control "}
                + std::string{controlCase.port}
                + " offline fixture should compile");
        // The change lands on a window boundary: the first window keeps
        // the initial control, and the render goes on with the new one.
        auto unchangedSettings = settings;
        unchangedSettings.eventValueChanges.clear();
        const auto unchanged = talas::runtime::compileProject(
            document, makeRegistry(), unchangedSettings);
        talas::runtime::OfflineRenderSession session{*compiled.graph};
        const auto rendered = session.render(5);
        const auto reference = talas::runtime::renderOffline(*unchanged.graph, 5);
        require(
            rendered.ok() && reference.ok()
                && rendered.mono.size() == 5
                && std::equal(rendered.mono.begin(), rendered.mono.begin() + 2, reference.mono.begin())
                && std::equal(rendered.right.begin(), rendered.right.begin() + 2, reference.right.begin()),
            std::string{"C60 late-control "}
                + std::string{controlCase.port}
                + " change should take effect from its window on");
    }
}

