void requireSpectrumFileSourceRejectsNonFiniteConnectedLevel(
    talas::project::ProjectDocument document,
    std::vector<talas::runtime::TableResource> tableResources)
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    document.graph.nodes.push_back(node("left", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("right", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("level", "talas.add"));
    document.graph.connections.push_back(connection("left", "value", "level", "left"));
    document.graph.connections.push_back(connection("right", "value", "level", "right"));
    document.graph.connections.push_back(connection("level", "value", "source", "level"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = std::move(tableResources);

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "non-finite connected-level spectrum file source document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "spectrum file source should reject non-finite connected level");
    require(result.mono.empty(), "failed connected-level spectrum file source render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "source", "level", {}), "render should identify connected spectrum file source level input");
}

