void testSpectrumTrackSelectorSingleFlagDuplicatesSelectedEnvelope()
{
    auto result = renderDocument(
        makeSyntheticSpectrumTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters(),
            spectrumTrackSelectorParameters({booleanParameter("amp", false)})),
        4.0,
        5);

    require(result.ok(), "amp-disabled spectrum selector render should not emit diagnostics");
    requireConstantSamples(result.mono, 200.0, "freq-only selected spectrum left frequency");
    requireConstantSamples(result.right, 200.0, "freq-only selected spectrum right frequency");

    result = renderDocument(
        makeSyntheticSpectrumTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters(),
            spectrumTrackSelectorParameters({booleanParameter("freq", false)})),
        4.0,
        5);

    require(result.ok(), "freq-disabled spectrum selector render should not emit diagnostics");
    requireConstantSamples(result.mono, 0.125, "amp-only selected spectrum left amplitude");
    requireConstantSamples(result.right, 0.125, "amp-only selected spectrum right amplitude");
}

void testSyntheticSpectrumFromSoundsRejectsShortBlockAndNegativeFrequency()
{
    auto result = renderSyntheticSpectrumFromSoundsDocument(
        {
            {1, {1.0, 0.25}},
            {2, {100.0, 200.0}},
        },
        syntheticSpectrumFromSoundsParameters(),
        1);

    require(!result.ok(), "synthetic spectrum from sounds should reject blocks shorter than nbrPartials");
    require(result.mono.empty(), "failed short from-sounds spectrum render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, "amplitudes"), "render should identify short from-sounds amplitude frame");

    result = renderSyntheticSpectrumFromSoundsDocument({
        {1, {1.0, 0.25}},
        {2, {100.0, -200.0}},
    });

    require(!result.ok(), "synthetic spectrum from sounds should reject negative frequencies");
    require(result.mono.empty(), "failed negative from-sounds spectrum render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, "frequenciesAndBandwidths"), "render should identify negative from-sounds frequency frame");

    result = renderSyntheticSpectrumFromSoundsDocument(
        {
            {1, {1.0}},
            {2, {100.0}},
        },
        syntheticSpectrumFromSoundsParameters({{"nbrPartials", "1"}, booleanParameter("includesBandwidths", true)}),
        1);

    require(!result.ok(), "synthetic spectrum from sounds should reject short alternating bandwidth blocks");
    require(result.mono.empty(), "failed short bandwidth from-sounds spectrum render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, "frequenciesAndBandwidths"), "render should identify short bandwidth frame");

    result = renderSyntheticSpectrumFromSoundsDocument(
        {
            {1, {1.0}},
            {2, {100.0, -10.0}},
        },
        syntheticSpectrumFromSoundsParameters({{"nbrPartials", "1"}, booleanParameter("includesBandwidths", true)}));

    require(!result.ok(), "synthetic spectrum from sounds should reject negative bandwidths");
    require(result.mono.empty(), "failed negative bandwidth from-sounds spectrum render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, "frequenciesAndBandwidths"), "render should identify negative bandwidth frame");

    result = renderSyntheticSpectrumFromSoundsDocument(
        {
            {1, {1.0}},
            {2, {0.0}},
        },
        syntheticSpectrumFromSoundsParameters({{"nbrPartials", "1"}, booleanParameter("logScale", true)}),
        1);

    require(!result.ok(), "synthetic spectrum from sounds should reject zero logScale frequency");
    require(result.mono.empty(), "failed zero logScale from-sounds spectrum render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, "frequenciesAndBandwidths"), "render should identify zero logScale frequency frame");
}

