void testSpectrumVoicedUnvoicedEmitsOnePublicTransitionFrame()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = {{"Analysis/C57", {
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.6, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
        1.0, 1.0, 0.1, 0.5, 2.0, 0.2,
    }}};
    const auto document = makeSpectrumOnDiskVoicedUnvoicedDocument(
        spectrumOnDiskParameters({
            {"frequency", "100 hz"},
            {"level", "1"},
            {"rateScale", "1"},
            resourceParameter("fileName", "Analysis/C57"),
            {"analysisFrames", "5"},
            {"nbrPartials", "2"},
            {"firstPartial", "1"},
        }));
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C57 transition-frame fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const std::array expected{1.0, 0.5, 0.0, 0.5, 1.0};
    for (std::size_t transaction = 0;
         transaction < expected.size(); ++transaction)
    {
        const auto result = session.render(1);
        require(result.ok(),
                "C57 transition-frame transaction should render");
        requireNear(
            result.mono[0], expected[transaction], 1.0e-12,
            "C57 left transition transaction "
                + std::to_string(transaction));
        requireNear(
            result.right[0], expected[transaction], 1.0e-12,
            "C57 right transition transaction "
                + std::to_string(transaction));
    }

    session.reset();
    const auto reset = session.render(1);
    require(
        reset.ok() && reset.mono[0] == 1.0 && reset.right[0] == 1.0,
        "C57 offline reset should clear transition history");

    talas::runtime::OfflineRenderSession emptySession{*compiled.graph};
    const auto beforeEmpty = emptySession.render(1);
    const auto empty = emptySession.render(0);
    const auto afterEmpty = emptySession.render(1);
    require(
        beforeEmpty.ok() && beforeEmpty.mono[0] == 1.0
            && empty.ok() && empty.mono.empty() && empty.right.empty()
            && afterEmpty.ok() && afterEmpty.mono[0] == 0.0
            && afterEmpty.right[0] == 0.0,
        "C57 offline zero-frame public transaction should consume exactly one transition frame");

    auto failingSettings = settings;
    failingSettings.maxBlockFrames = 5;
    failingSettings.eventValues = {{
        "C57Gain", 1.0, talas::expr::ValueDomain::Scalar,
    }};
    failingSettings.eventValueChanges = {{
        3, "C57Gain", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar,
    }};
    auto failingDocument = document;
    failingDocument.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "1"}, {"right", "1"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.nodes.push_back(node(
        "gain", "talas.constant", {{"value", "!C57Gain"}}));
    failingDocument.graph.nodes.push_back(node(
        "overflow", "talas.level", {
            {"left", "3"}, {"right", "3"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        failingDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "voiced" && edge.toNode == "out";
        });
    failingDocument.graph.connections.push_back(connection(
        "voiced", "leftOut", "downstream", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "gain", "value", "downstream", "left"));
    failingDocument.graph.connections.push_back(connection(
        "downstream", "leftOut", "overflow", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "overflow", "leftOut", "out", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "overflow", "rightOut", "out", "rightIn"));
    const auto failingCompiled = talas::runtime::compileProject(
        failingDocument, makeRegistry(), failingSettings);
    require(failingCompiled.ok(), "C57 offline rollback fixture should compile");
    talas::runtime::OfflineRenderSession failing{*failingCompiled.graph};
    const auto initial = failing.render(1);
    const auto rejected = failing.render(5);
    const auto retry = failing.render(1);
    require(
        initial.ok() && initial.mono[0] == 3.0
            && !rejected.ok() && rejected.mono.empty()
            && retry.ok() && retry.mono[0] == 1.5
            && retry.right[0] == 1.5,
        "C57 offline late downstream failure should retry the uncommitted transition frame");
}

