void testSpectrumModifierUsesTrackNumberProbabilityProfileOffline()
{
    auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "3"},
            {"envelope", "1"},
            textParameter("amplitudes", "0.25 0.25 0.25"),
            textParameter("frequencies", "100 200 300"),
            textParameter("bandwidths", "10 20 30"),
        }),
        spectrumModifierParameters({
            {"loTrack", "1"},
            {"hiTrack", "3"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"ampScale", "2"},
            {"ampOffset", "0"},
            {"probability", "TrackNumber / 8"},
            {"seed", "-1"},
        }),
        spectrumTrackSelectorParameters({
            {"track", "3"},
            booleanParameter("amp", true),
            booleanParameter("freq", true),
        }));

    const auto result = renderDocument(document, 4.0, 5);

    require(
        result.ok(),
        "offline C54 TrackNumber probability profile should render");
    requireConstantSamples(
        result.mono,
        0.5,
        "offline C54 track three should use probability 3/8 instead of the track-one scalar compatibility value");
    requireConstantSamples(
        result.right,
        300.0,
        "offline C54 track profile should preserve selected frequency");

    connectConstantControl(
        document,
        "probabilityControl",
        "0",
        "modifier",
        "probability");
    const auto connectedOverride = renderDocument(
        document, 4.0, 5);
    require(
        connectedOverride.ok(),
        "offline C54 connected probability override should render");
    requireConstantSamples(
        connectedOverride.mono,
        0.0,
        "offline C54 connected probability should override the TrackNumber profile");
    requireConstantSamples(
        connectedOverride.right,
        300.0,
        "offline C54 connected probability rejection should preserve frequency");
}

void testSpectrumModifierUsesVariablesV2RemainderProbabilityProfileOffline()
{
    const auto renderTrack = [](
                                 std::string probability,
                                 std::string track) {
        auto document = makeSpectrumModifierTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters({
                {"nbrPartials", "4"},
                {"envelope", "1"},
                textParameter("amplitudes", "0.25 0.25 0.25 0.25"),
                textParameter("frequencies", "100 200 300 400"),
                textParameter("bandwidths", "10 20 30 40"),
            }),
            spectrumModifierParameters({
                {"loTrack", "1"},
                {"hiTrack", "4"},
                {"freqScale", "1"},
                {"freqOffset", "0"},
                {"ampScale", "2"},
                {"ampOffset", "0"},
                {"probability", std::move(probability)},
                {"seed", "-1"},
            }),
            spectrumTrackSelectorParameters({
                {"track", std::move(track)},
                booleanParameter("amp", true),
                booleanParameter("freq", true),
            }));
        return renderDocument(document, 4.0, 5);
    };

    for (std::size_t track = 1; track <= 4; ++track)
    {
        const auto result = renderTrack(
            "(TrackNumber - 1) rem: 2",
            std::to_string(track));
        require(
            result.ok(),
            "offline C55 remainder probability profile should render");
        requireConstantSamples(
            result.mono,
            track % 2 == 0 ? 0.5 : 0.0,
            "offline C55 remainder profile should reject odd and transform even one-based tracks exactly");
        requireConstantSamples(
            result.right,
            static_cast<double>(track * 100),
            "offline C55 remainder profile should preserve each selected track frequency");
    }

    auto definitionDocument = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "4"},
            {"envelope", "1"},
            textParameter("amplitudes", "0.25 0.25 0.25 0.25"),
            textParameter("frequencies", "100 200 300 400"),
            textParameter("bandwidths", "10 20 30 40"),
        }),
        spectrumModifierParameters({
            {"loTrack", "1"},
            {"hiTrack", "4"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"ampScale", "2"},
            {"ampOffset", "0"},
            {"probability", "alternatingTrack(TrackNumber)"},
            {"seed", "-1"},
        }),
        spectrumTrackSelectorParameters({
            {"track", "2"},
            booleanParameter("amp", true),
            booleanParameter("freq", true),
        }));
    definitionDocument.expressionDefinitions.definitions.push_back({
        "alternatingTrack",
        {{"track", talas::expr::ValueDomain::Scalar}},
        talas::expr::ValueDomain::Scalar,
        "(track - 1) rem: 2",
    });
    const auto definitionExpanded = renderDocument(
        definitionDocument, 4.0, 5);
    require(
        definitionExpanded.ok(),
        "offline C55 definition-expanded remainder profile should render");
    requireConstantSamples(
        definitionExpanded.mono,
        0.5,
        "offline C55 definition-expanded remainder profile should match direct even-track behavior");

    auto connectedOverride = definitionDocument;
    connectConstantControl(
        connectedOverride,
        "probabilityControl",
        "0",
        "modifier",
        "probability");
    const auto overridden = renderDocument(
        connectedOverride, 4.0, 5);
    require(
        overridden.ok(),
        "offline C55 connected probability override should render");
    requireConstantSamples(
        overridden.mono,
        0.0,
        "offline C55 connected probability should override the immutable remainder profile");
}

void testSpectrumModifierConnectedSelectorsOverrideBooleanFallbacks()
{
    const auto renderWithSelector = [](
                                        std::string_view selectorId,
                                        std::string_view selectorValue,
                                        std::vector<talas::project::ProjectParameterExpression> overrides) {
        auto document = makeSpectrumModifierTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters(),
            spectrumModifierParameters(std::move(overrides)));
        connectConstantControl(
            document,
            std::string(selectorId) + "Control",
            std::string(selectorValue),
            "modifier",
            std::string(selectorId));
        return renderDocument(document, 4.0, 5);
    };

    const auto positiveSelect = renderWithSelector(
        "select", "1", {booleanParameter("select", false)});
    require(positiveSelect.ok(), "positive connected select should render");
    requireConstantSamples(
        positiveSelect.mono, 0.5,
        "positive connected select should override false fallback amplitude");
    requireConstantSamples(
        positiveSelect.right, 110.0,
        "positive connected select should override false fallback frequency");

    for (const auto disabledValue : {std::string_view{"0"}, std::string_view{"-1"}})
    {
        const auto disabledSelect = renderWithSelector(
            "select", disabledValue, {booleanParameter("select", true)});
        require(disabledSelect.ok(), "non-positive connected select should render");
        requireConstantSamples(
            disabledSelect.mono, 0.0,
            "non-positive connected select should override true fallback amplitude");
        requireConstantSamples(
            disabledSelect.right, 200.0,
            "non-positive connected select should override true fallback frequency");
    }

    const auto positiveHearAll = renderWithSelector(
        "hearAll",
        "1",
        {
            {"loTrack", "1"},
            {"hiTrack", "1"},
            booleanParameter("hearAll", false),
        });
    require(positiveHearAll.ok(), "positive connected hearAll should render");
    requireConstantSamples(
        positiveHearAll.mono, 0.125,
        "positive connected hearAll should preserve unselected amplitude");
    requireConstantSamples(
        positiveHearAll.right, 200.0,
        "positive connected hearAll should preserve unselected frequency");

    for (const auto disabledValue : {std::string_view{"0"}, std::string_view{"-1"}})
    {
        const auto disabledHearAll = renderWithSelector(
            "hearAll",
            disabledValue,
            {
                {"loTrack", "1"},
                {"hiTrack", "1"},
                booleanParameter("hearAll", true),
            });
        require(disabledHearAll.ok(), "non-positive connected hearAll should render");
        requireConstantSamples(
            disabledHearAll.mono, 0.0,
            "non-positive connected hearAll should mute unselected amplitude");
        requireConstantSamples(
            disabledHearAll.right, 200.0,
            "non-positive connected hearAll should preserve unselected frequency");
    }

    auto dualDocument = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({
            booleanParameter("select", false),
            {"loTrack", "1"},
            {"hiTrack", "1"},
            booleanParameter("hearAll", false),
        }));
    connectConstantControl(
        dualDocument, "selectControl", "1", "modifier", "select");
    connectConstantControl(
        dualDocument, "hearAllControl", "1", "modifier", "hearAll");
    const auto dual = renderDocument(dualDocument, 4.0, 5);
    require(dual.ok(), "dual connected Spectrum Modifier selectors should render");
    requireConstantSamples(
        dual.mono, 0.125,
        "dual connected selectors should preserve unselected amplitude");
    requireConstantSamples(
        dual.right, 200.0,
        "dual connected selectors should preserve unselected frequency");
}

