void testSpectrumModifierRejectsDynamicConnectedSeedAtomically()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    const auto renderDynamicSeed = [](
                                       std::vector<double> values,
                                       std::size_t maxBlockFrames = 5) {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = maxBlockFrames;
        settings.tableResources = {{"Tables/Seed", std::move(values)}};

        auto document = makeSpectrumModifierTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters(),
            spectrumModifierParameters({
                {"probability", "0.5"},
                {"seed", "0.5"},
            }));
        document.graph.nodes.push_back(node(
            "seedControl",
            "talas.triggeredTableRead",
            triggeredTableReadParameters({
                resourceParameter("wavetable", "Tables/Seed")})));
        document.graph.connections.push_back(connection(
            "seedControl", "value", "modifier", "seed"));

        const auto compile = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(compile.ok(), "dynamic Spectrum Modifier seed should compile");
        return talas::runtime::renderOffline(*compile.graph, 5);
    };

    const auto toleranceDrift = renderDynamicSeed(
        {0.0, 0.0, 2.0e-12, 0.0, 0.0});
    require(!toleranceDrift.ok(), "seed drift beyond tolerance should fail");
    require(
        toleranceDrift.mono.empty() && toleranceDrift.right.empty(),
        "failed seed drift should publish no audio");
    require(
        hasDiagnostic(
            toleranceDrift,
            DiagnosticCode::GraphValidationFailed,
            "modifier",
            "seed"),
        "seed drift diagnostic should identify the connected seed port");

    // Each 2-frame window takes the seed it starts with, as each realtime
    // callback does.
    const auto windowSeeds = renderDynamicSeed(
        {0.0, 0.0, 0.5, 0.5, 0.5},
        2);
    require(
        windowSeeds.ok() && windowSeeds.mono.size() == 5,
        "each window of one render should take the seed it starts with");

    for (const auto& invalidSeed : {
             std::vector<double>(5, -1.000000000001),
             std::vector<double>(5, 1.000000000001),
         })
    {
        const auto outOfRange = renderDynamicSeed(invalidSeed);
        require(!outOfRange.ok(), "out-of-range connected seed should fail");
        require(
            outOfRange.mono.empty() && outOfRange.right.empty(),
            "out-of-range connected seed should publish no audio");
        require(
            hasDiagnostic(
                outOfRange,
                DiagnosticCode::GraphValidationFailed,
                "modifier",
                "seed"),
            "out-of-range seed diagnostic should identify seed");
    }

    auto nonFiniteDocument = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({{"probability", "0.5"}}));
    nonFiniteDocument.graph.nodes.push_back(node(
        "seedLeft", "talas.constant", {{"value", "1e308"}}));
    nonFiniteDocument.graph.nodes.push_back(node(
        "seedRight", "talas.constant", {{"value", "1e308"}}));
    nonFiniteDocument.graph.nodes.push_back(node(
        "nonFiniteSeed", "talas.add"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "seedLeft", "value", "nonFiniteSeed", "left"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "seedRight", "value", "nonFiniteSeed", "right"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "nonFiniteSeed", "value", "modifier", "seed"));
    const auto nonFinite = renderDocument(nonFiniteDocument, 4.0, 5);
    require(!nonFinite.ok(), "non-finite connected seed should fail");
    require(
        nonFinite.mono.empty() && nonFinite.right.empty(),
        "non-finite connected seed should publish no audio");
    require(
        hasDiagnostic(
            nonFinite,
            DiagnosticCode::GraphValidationFailed,
            "modifier",
            "seed"),
        "non-finite seed diagnostic should identify seed");

    const auto withinTolerance = renderDynamicSeed(
        {0.0, 0.5e-12, 0.0, 0.0, 0.0});
    require(
        withinTolerance.ok(),
        "seed drift inside tolerance should render");
    requireConstantSamples(
        withinTolerance.mono,
        0.5,
        "within-tolerance seed drift should use frame-zero amplitude exactly");
    requireConstantSamples(
        withinTolerance.right,
        110.0,
        "within-tolerance seed drift should use frame-zero frequency exactly");
}

void testSpectrumModifierLateSeedFailureRollsBackOfflineSessionState()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "spectrum",
        "talas.syntheticSpectrumFromArray",
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "1"},
            textParameter("amplitudes", "1"),
            textParameter("frequencies", "4"),
            textParameter("bandwidths", "0"),
        })));
    document.graph.nodes.push_back(node(
        "seedControl", "talas.constant", {{"value", "!C51Seed"}}));
    document.graph.nodes.push_back(node(
        "modifier",
        "talas.spectrumModifier",
        spectrumModifierParameters({{"probability", "0.5"}})));
    document.graph.nodes.push_back(node(
        "bank",
        "talas.oscillatorBank",
        oscillatorBankParameters({
            {"nbrOscillators", "1"},
            {"bankSize", "1"},
        })));
    document.graph.connections.push_back(connection(
        "spectrum", "spectrumOut", "modifier", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "seedControl", "value", "modifier", "seed"));
    document.graph.connections.push_back(connection(
        "modifier", "spectrumOut", "bank", "spectrum"));
    document.graph.connections.push_back(connection(
        "bank", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 32.0;
    settings.maxBlockFrames = 5;
    settings.eventValues = {
        {"C51Seed", 0.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C51Seed", 0.5, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "late seed rollback fixture should compile");

    talas::runtime::OfflineRenderSession rejectedSession{*compiled.graph};
    const auto rejected = rejectedSession.render(5);
    require(
        !rejected.ok(),
        "late seed drift should reject the complete offline transaction");
    require(
        rejected.mono.empty() && rejected.right.empty(),
        "late seed drift should publish no audio");

    const auto retried = rejectedSession.render(2);
    talas::runtime::OfflineRenderSession freshSession{*compiled.graph};
    const auto fresh = freshSession.render(2);
    require(
        retried.ok() && fresh.ok(),
        "corrected seed retry and fresh reference should both render");
    require(
        retried.mono.size() == fresh.mono.size(),
        "corrected seed retry should preserve the fresh frame count");
    for (std::size_t frame = 0; frame < fresh.mono.size(); ++frame)
    {
        requireNear(
            retried.mono[frame],
            fresh.mono[frame],
            1.0e-12,
            "late seed rejection should roll back offline session state at frame "
                + std::to_string(frame));
    }
}

void testSpectrumModifierLateSeedFailurePublishesNoInspectionFrames()
{
    auto document = makeLiveSpectralAnalysisTrackSelectorDocument();
    document.graph.nodes.push_back(node(
        "modifier",
        "talas.spectrumModifier",
        spectrumModifierParameters({
            {"probability", "0.5"},
            {"seed", "0.5"},
        })));
    document.graph.nodes.push_back(node(
        "seedControl", "talas.constant", {{"value", "!C51InspectSeed"}}));
    const auto bridgeToSelector = std::ranges::find_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "bridge"
                && edge.fromPort == "spectrumOut"
                && edge.toNode == "selector"
                && edge.toPort == "spectrumIn";
        });
    require(
        bridgeToSelector != document.graph.connections.end(),
        "C51 inspection fixture should expose its legacy Spectrum edge");
    *bridgeToSelector = connection(
        "bridge", "spectrumOut", "modifier", "spectrumIn");
    document.graph.connections.push_back(connection(
        "modifier", "spectrumOut", "selector", "spectrumIn"));
    document.graph.connections.push_back(connection(
        "seedControl", "value", "modifier", "seed"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 64.0;
    settings.maxBlockFrames = 64;
    settings.audioInputChannels.push_back(
        {1, liveSpectralSine(128, 8.0, 0.75)});
    settings.eventValues = {{
        "C51InspectSeed", 0.0,
        talas::expr::ValueDomain::Scalar}};
    // Inside the second 64-frame window, where the seed must hold.
    settings.eventValueChanges = {{
        96,
        "C51InspectSeed",
        0.5,
        talas::expr::ValueDomain::Scalar}};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C51 inspection rollback fixture should compile");

    talas::runtime::OfflineRenderSession rejectedSession{*compiled.graph};
    const auto rejected = rejectedSession.inspectPartialSpectrum(
        "spectrum", "spectrumOut", 128);
    require(
        !rejected.ok() && rejected.frames.empty(),
        "late seed failure should publish no partial inspection frames");

    const auto retried = rejectedSession.inspectPartialSpectrum(
        "spectrum", "spectrumOut", 64);
    talas::runtime::OfflineRenderSession freshSession{*compiled.graph};
    const auto fresh = freshSession.inspectPartialSpectrum(
        "spectrum", "spectrumOut", 64);
    require(
        retried.ok() && fresh.ok()
            && retried.frames.size() == fresh.frames.size()
            && !retried.frames.empty()
            && retried.frames.front().partials.size()
                == fresh.frames.front().partials.size()
            && !retried.frames.front().partials.empty(),
        "corrected seed inspection retry should match a fresh session shape");
    requireNear(
        retried.frames.front().partials.front().amplitude,
        fresh.frames.front().partials.front().amplitude,
        0.0,
        "late seed inspection failure should roll back partial amplitude");
    requireNear(
        retried.frames.front().partials.front().frequencyHz,
        fresh.frames.front().partials.front().frequencyHz,
        0.0,
        "late seed inspection failure should roll back partial frequency");
}

void testSpectrumModifierAcceptsSeedChangesAtRenderBoundaries()
{
    auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({
            {"probability", "0.5"},
            {"seed", "-1.0"},
        }));
    document.graph.nodes.push_back(node(
        "seedControl", "talas.constant", {{"value", "!C51Seed"}}));
    document.graph.connections.push_back(connection(
        "seedControl", "value", "modifier", "seed"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.eventValues = {
        {"C51Seed", 0.5, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C51Seed", 0.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "render-boundary seed fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(3);
    const auto second = session.render(3);
    const auto third = session.render(1);
    require(
        first.ok() && second.ok() && third.ok(),
        "seed changes at public render boundaries should succeed");
    for (std::size_t frame = 0; frame < 3; ++frame)
    {
        requireNear(
            first.mono[frame], 0.0, 1.0e-12,
            "first seed transaction should use the unselected seed");
        requireNear(
            first.right[frame], 200.0, 1.0e-12,
            "first seed transaction should preserve source frequency");
        requireNear(
            second.mono[frame], 0.5, 1.0e-12,
            "second seed transaction should use the selected seed");
        requireNear(
            second.right[frame], 110.0, 1.0e-12,
            "second seed transaction should transform frequency");
    }
    requireNear(
        third.mono[0], 0.0, 1.0e-12,
        "later seed transactions should preserve the accepted seed while advancing the C53 frame stream");
    requireNear(
        third.right[0], 200.0, 1.0e-12,
        "later seed transactions should publish the next C53 probability decision");
}

void testSpectrumModifierSeedReplayRejectsRetroactiveOfflineAssignments()
{
    auto variableDocument = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({{"probability", "0.5"}}));
    variableDocument.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    variableDocument.variableLibrary.variables.push_back({
        "seed",
        "Seed",
        talas::expr::ValueDomain::Scalar,
        0.0,
    });
    variableDocument.graph.nodes.push_back(node(
        "seedControl", "talas.constant", {{"value", "@seed"}}));
    variableDocument.graph.connections.push_back(connection(
        "seedControl", "value", "modifier", "seed"));
    const auto variableCompiled = talas::runtime::compileProject(
        variableDocument, makeRegistry(), {4.0, 3});
    require(
        variableCompiled.ok()
            && variableCompiled.graph->preparedVariables().cells.size() == 1,
        "retroactive variable seed fixture should compile");

    talas::runtime::OfflineRenderSession variableSession{
        *variableCompiled.graph};
    require(
        variableSession.render(3).ok(),
        "retroactive variable seed fixture should accept its initial transaction");
    const std::array variableAssignments{
        talas::runtime::OfflineVariableAssignment{
            0,
            1,
            1,
            variableCompiled.graph->preparedVariables().cells.front().identity,
            0.5,
            talas::expr::ValueDomain::Scalar,
        },
    };
    require(
        variableSession.scheduleVariableAssignments(variableAssignments),
        "retroactive variable seed assignment should reach render-cursor validation");
    const auto zeroVariable = variableSession.render(0);
    require(
        zeroVariable.ok() && zeroVariable.mono.empty()
            && zeroVariable.right.empty(),
        "zero-frame seed transactions must not consume stale variable assignments");
    const auto rejectedVariable = variableSession.render(1);
    require(
        !rejectedVariable.ok() && rejectedVariable.mono.empty()
            && rejectedVariable.right.empty(),
        "seed replay must reject a project-variable assignment behind the accepted cursor");

    auto soundDocument = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({{"probability", "0.5"}}));
    connectConstantControl(
        soundDocument, "seedControl", "0", "modifier", "seed");
    soundDocument.soundDefinitions = {
        {.definitionId = "toneA", .displayName = "Tone A"},
        {.definitionId = "toneB", .displayName = "Tone B"},
    };
    soundDocument.soundVariableLibrary.variables.push_back({
        "sound",
        "Sound",
        {},
        talas::project::ProjectSoundVariableKind::Sound,
        {"toneA", "toneB"},
    });
    const auto soundCompiled = talas::runtime::compileProject(
        soundDocument, makeRegistry(), {4.0, 3});
    require(
        soundCompiled.ok()
            && soundCompiled.graph->preparedSoundVariables().cells.size() == 1,
        "retroactive Sound-variable seed fixture should compile");

    talas::runtime::OfflineRenderSession soundSession{*soundCompiled.graph};
    require(
        soundSession.render(3).ok(),
        "retroactive Sound-variable seed fixture should accept its initial transaction");
    const std::array soundAssignments{
        talas::runtime::OfflineSoundVariableAssignment{
            0,
            1,
            1,
            soundCompiled.graph->preparedSoundVariables().cells.front().identity,
            "toneB",
        },
    };
    require(
        soundSession.scheduleSoundVariableAssignments(soundAssignments),
        "retroactive Sound-variable seed assignment should reach render-cursor validation");
    const auto zeroSound = soundSession.render(0);
    const auto retainedAfterZero = soundSession.soundVariableValues();
    require(
        zeroSound.ok() && zeroSound.mono.empty() && zeroSound.right.empty()
            && retainedAfterZero.size() == 1
            && retainedAfterZero.front().selectedDefinitionId == "toneA",
        "zero-frame seed transactions must not consume stale Sound-variable assignments");
    const auto rejectedSound = soundSession.render(1);
    const auto retainedSound = soundSession.soundVariableValues();
    require(
        !rejectedSound.ok() && rejectedSound.mono.empty()
            && rejectedSound.right.empty(),
        "seed replay must reject a Sound-variable assignment behind the accepted cursor");
    require(
        retainedSound.size() == 1
            && retainedSound.front().selectedDefinitionId == "toneA",
        "rejected retroactive Sound-variable seed assignment must not alter publication state");
}

void testSpectrumModifierRejectsDynamicConnectedSelectorsAtomically()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    const auto renderDynamicSelector = [](
                                           std::string selectorId,
                                           std::vector<double> values,
                                           std::size_t maxBlockFrames = 5) {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = maxBlockFrames;
        settings.tableResources = {{"Tables/Selector", std::move(values)}};

        auto document = makeSpectrumModifierTrackSelectorDocument();
        document.graph.nodes.push_back(node(
            "selectorControl",
            "talas.triggeredTableRead",
            triggeredTableReadParameters({
                resourceParameter("wavetable", "Tables/Selector")})));
        document.graph.connections.push_back(connection(
            "selectorControl", "value", "modifier", std::move(selectorId)));

        const auto compile = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(compile.ok(), "dynamic Spectrum Modifier selector should compile");
        return talas::runtime::renderOffline(*compile.graph, 5);
    };

    const auto toleranceDrift = renderDynamicSelector(
        "select", {1.0, 1.0, 1.0 + 2.0e-12, 1.0, 1.0});
    require(!toleranceDrift.ok(), "selector drift beyond tolerance should fail");
    require(
        toleranceDrift.mono.empty() && toleranceDrift.right.empty(),
        "failed selector drift should publish no audio");
    require(
        hasDiagnostic(
            toleranceDrift,
            DiagnosticCode::GraphValidationFailed,
            "modifier",
            "select"),
        "selector drift diagnostic should identify select");

    const auto truthCrossing = renderDynamicSelector(
        "hearAll", {0.0, 0.5e-12, 0.0, 0.0, 0.0});
    require(!truthCrossing.ok(), "selector truth crossing inside tolerance should fail");
    require(
        truthCrossing.mono.empty() && truthCrossing.right.empty(),
        "failed selector truth crossing should publish no audio");
    require(
        hasDiagnostic(
            truthCrossing,
            DiagnosticCode::GraphValidationFailed,
            "modifier",
            "hearAll"),
        "selector truth-crossing diagnostic should identify hearAll");

    // Each 2-frame window takes the selector it starts with, as each
    // realtime callback does.
    const auto windowSelectors = renderDynamicSelector(
        "select",
        {1.0, 1.0, 1.0 + 2.0e-12, 1.0 + 2.0e-12, 1.0 + 2.0e-12},
        2);
    require(
        windowSelectors.ok() && windowSelectors.mono.size() == 5,
        "each window of one render should take the selector it starts with");

    const auto withinTolerance = renderDynamicSelector(
        "select", {1.0, 1.0 + 0.5e-12, 1.0, 1.0, 1.0});
    require(
        withinTolerance.ok(),
        "truth-stable selector drift inside tolerance should render");
    requireConstantSamples(
        withinTolerance.mono, 0.5,
        "truth-stable selector drift inside tolerance amplitude");
    requireConstantSamples(
        withinTolerance.right, 110.0,
        "truth-stable selector drift inside tolerance frequency");

    auto nonFiniteDocument = makeSpectrumModifierTrackSelectorDocument();
    nonFiniteDocument.graph.nodes.push_back(node(
        "selectorLeft", "talas.constant", {{"value", "1e308"}}));
    nonFiniteDocument.graph.nodes.push_back(node(
        "selectorRight", "talas.constant", {{"value", "1e308"}}));
    nonFiniteDocument.graph.nodes.push_back(node(
        "nonFiniteSelector", "talas.add"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "selectorLeft", "value", "nonFiniteSelector", "left"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "selectorRight", "value", "nonFiniteSelector", "right"));
    nonFiniteDocument.graph.connections.push_back(connection(
        "nonFiniteSelector", "value", "modifier", "select"));
    const auto nonFinite = renderDocument(nonFiniteDocument, 4.0, 5);
    require(!nonFinite.ok(), "non-finite connected selector should fail");
    require(
        nonFinite.mono.empty() && nonFinite.right.empty(),
        "failed non-finite selector should publish no audio");
    require(
        hasDiagnostic(
            nonFinite,
            DiagnosticCode::GraphValidationFailed,
            "modifier",
            "select"),
        "non-finite selector diagnostic should identify select");
}

