void testSpectrumModifierAcceptsSelectorChangesAtRenderBoundaries()
{
    auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumModifierParameters({booleanParameter("select", true)}));
    document.graph.nodes.push_back(node(
        "selectControl", "talas.constant", {{"value", "!C50Select"}}));
    document.graph.connections.push_back(connection(
        "selectControl", "value", "modifier", "select"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.eventValues = {
        {"C50Select", -1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C50Select", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "render-boundary selector fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto first = session.render(3);
    const auto second = session.render(3);
    const auto third = session.render(1);
    require(
        first.ok() && second.ok() && third.ok(),
        "selector changes at public render boundaries should succeed");
    require(
        first.mono.size() == 3 && first.right.size() == 3
            && second.mono.size() == 3 && second.right.size() == 3
            && third.mono.size() == 1 && third.right.size() == 1,
        "selector boundary transactions should return requested frames");
    for (std::size_t frame = 0; frame < 3; ++frame)
    {
        requireNear(
            first.mono[frame], 0.0, 1.0e-12,
            "first selector transaction should use disabled select");
        requireNear(
            first.right[frame], 200.0, 1.0e-12,
            "first selector transaction should preserve source frequency");
        requireNear(
            second.mono[frame], 0.5, 1.0e-12,
            "second selector transaction should use enabled select");
        requireNear(
            second.right[frame], 110.0, 1.0e-12,
            "second selector transaction should transform frequency");
    }
    requireNear(
        third.mono[0], 0.5, 1.0e-12,
        "later selector transactions should preserve the accepted boundary value");
    requireNear(
        third.right[0], 110.0, 1.0e-12,
        "later selector transactions should preserve the transformed frequency");
}

void testSpectrumModifierReplayRejectsRetroactiveOfflineAssignments()
{
    auto variableDocument = makeSpectrumModifierTrackSelectorDocument();
    variableDocument.expressionLanguage =
        talas::expr::ExpressionLanguageVersion::VariablesV1;
    variableDocument.variableLibrary.variables.push_back({
        "selector",
        "Selector",
        talas::expr::ValueDomain::Scalar,
        0.0,
    });
    variableDocument.graph.nodes.push_back(node(
        "selectControl", "talas.constant", {{"value", "@selector"}}));
    variableDocument.graph.connections.push_back(connection(
        "selectControl", "value", "modifier", "select"));
    const auto variableCompiled = talas::runtime::compileProject(
        variableDocument, makeRegistry(), {4.0, 3});
    require(
        variableCompiled.ok()
            && variableCompiled.graph->preparedVariables().cells.size() == 1,
        "retroactive variable selector fixture should compile");

    talas::runtime::OfflineRenderSession variableSession{
        *variableCompiled.graph};
    require(
        variableSession.render(3).ok(),
        "retroactive variable selector fixture should accept its initial transaction");
    const std::array variableAssignments{
        talas::runtime::OfflineVariableAssignment{
            0,
            1,
            1,
            variableCompiled.graph->preparedVariables().cells.front().identity,
            1.0,
            talas::expr::ValueDomain::Scalar,
        },
    };
    require(
        variableSession.scheduleVariableAssignments(variableAssignments),
        "retroactive variable assignment should reach render-cursor validation");
    const auto zeroVariable = variableSession.render(0);
    require(
        zeroVariable.ok() && zeroVariable.mono.empty()
            && zeroVariable.right.empty(),
        "zero-frame selector transactions must not consume stale variable assignments");
    const auto rejectedVariable = variableSession.render(1);
    require(
        !rejectedVariable.ok() && rejectedVariable.mono.empty()
            && rejectedVariable.right.empty(),
        "selector replay must reject a project-variable assignment behind the accepted cursor");

    auto soundDocument = makeSpectrumModifierTrackSelectorDocument();
    soundDocument.graph.nodes.push_back(node(
        "selectControl", "talas.constant", {{"value", "1"}}));
    soundDocument.graph.connections.push_back(connection(
        "selectControl", "value", "modifier", "select"));
    soundDocument.soundDefinitions = {
        {.definitionId = "toneA", .displayName = "Tone A"},
        {.definitionId = "toneB", .displayName = "Tone B"},
    };
    soundDocument.soundVariableLibrary.variables.push_back({
        "sound",
        "Sound",
        {},
        talas::project::ProjectSoundVariableKind::Sound,
        {"toneA", "toneB"},
    });
    const auto soundCompiled = talas::runtime::compileProject(
        soundDocument, makeRegistry(), {4.0, 3});
    require(
        soundCompiled.ok()
            && soundCompiled.graph->preparedSoundVariables().cells.size() == 1,
        "retroactive Sound-variable selector fixture should compile");

    talas::runtime::OfflineRenderSession soundSession{*soundCompiled.graph};
    require(
        soundSession.render(3).ok(),
        "retroactive Sound-variable fixture should accept its initial transaction");
    const std::array soundAssignments{
        talas::runtime::OfflineSoundVariableAssignment{
            0,
            1,
            1,
            soundCompiled.graph->preparedSoundVariables().cells.front().identity,
            "toneB",
        },
    };
    require(
        soundSession.scheduleSoundVariableAssignments(soundAssignments),
        "retroactive Sound-variable assignment should reach render-cursor validation");
    const auto zeroSound = soundSession.render(0);
    const auto retainedAfterZero = soundSession.soundVariableValues();
    require(
        zeroSound.ok() && zeroSound.mono.empty() && zeroSound.right.empty()
            && retainedAfterZero.size() == 1
            && retainedAfterZero.front().selectedDefinitionId == "toneA",
        "zero-frame selector transactions must not consume stale Sound-variable assignments");
    const auto rejectedSound = soundSession.render(1);
    const auto retainedSound = soundSession.soundVariableValues();
    require(
        !rejectedSound.ok() && rejectedSound.mono.empty()
            && rejectedSound.right.empty(),
        "selector replay must reject a Sound-variable assignment behind the accepted cursor");
    require(
        retainedSound.size() == 1
            && retainedSound.front().selectedDefinitionId == "toneA",
        "rejected retroactive Sound-variable assignment must not alter publication state");
}

void testSpectrumModifierRejectsForgedOfflineSelectorAuthority()
{
    auto document = makeSpectrumModifierTrackSelectorDocument();
    connectConstantControl(
        document, "selectControl", "1", "modifier", "select");
    connectConstantControl(
        document, "seedControl", "0", "modifier", "seed");
    connectConstantControl(
        document, "hearAllControl", "0", "modifier", "hearAll");
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), {4.0, 5});
    require(compiled.ok(), "forged offline selector fixture should compile");

    const auto findModifier = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.spectrumModifier"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto requireRejected = [&](talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        const auto result = talas::runtime::renderOffline(
            handBuiltGraph(
                std::move(plan), compiled.graph->renderSettings()),
            5);
        require(
            !result.ok() && result.mono.empty() && result.right.empty(),
            std::string(context)
                + " should reject forged Spectrum Modifier authority");
        require(
            hasDiagnostic(
                result,
                DiagnosticCode::GraphValidationFailed,
                "modifier"),
            std::string(context)
                + " should identify forged Spectrum Modifier authority");
    };

    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(modifier != plan.steps.end(), "duplicate-selector fixture should expose modifier");
        const auto selector = std::ranges::find(
            modifier->inputs,
            std::string_view{"select"},
            &talas::runtime::InputBinding::inputPortId);
        require(selector != modifier->inputs.end(), "duplicate-selector fixture should expose select");
        modifier->inputs.push_back(*selector);
        requireRejected(std::move(plan), "duplicate select binding");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(modifier != plan.steps.end(), "duplicate-seed fixture should expose modifier");
        const auto seed = std::ranges::find(
            modifier->inputs,
            std::string_view{"seed"},
            &talas::runtime::InputBinding::inputPortId);
        require(seed != modifier->inputs.end(), "duplicate-seed fixture should expose seed");
        modifier->inputs.push_back(*seed);
        requireRejected(std::move(plan), "duplicate seed binding");
    }
    for (const auto invalidSeed : {
             2.0,
             std::numeric_limits<double>::quiet_NaN()})
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(
            modifier != plan.steps.end(),
            "invalid connected-seed fallback fixture should expose modifier");
        const auto seed = std::ranges::find(
            modifier->parameters,
            std::string_view{"seed"},
            &talas::runtime::ParameterValue::id);
        require(
            seed != modifier->parameters.end(),
            "invalid connected-seed fallback fixture should expose seed parameter");
        seed->value = invalidSeed;
        requireRejected(
            std::move(plan),
            "invalid connected-seed static fallback");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(modifier != plan.steps.end(), "duplicate-spectrum fixture should expose modifier");
        modifier->inputs.push_back(modifier->inputs.front());
        requireRejected(std::move(plan), "duplicate spectrum binding");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(modifier != plan.steps.end(), "unrelated-input fixture should expose modifier");
        auto unrelated = modifier->inputs.back();
        unrelated.inputPortId = "forgedSelector";
        modifier->inputs.push_back(std::move(unrelated));
        requireRejected(std::move(plan), "unrelated selector binding");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(
            modifier != plan.steps.end() && modifier->inputs.size() == 4,
            "out-of-order fixture should expose four modifier inputs");
        std::swap(modifier->inputs[1], modifier->inputs[2]);
        requireRejected(std::move(plan), "out-of-order selector bindings");
    }
}

void testSpectrumModifierRejectsForgedTrackNumberProbabilityProfileOffline()
{
    const auto compiled = talas::runtime::compileProject(
        makeSpectrumModifierTrackSelectorDocument(
            syntheticSpectrumFromArrayParameters(),
            spectrumModifierParameters({
                {"probability", "TrackNumber / 8"},
            })),
        makeRegistry(),
        {4.0, 5});
    require(
        compiled.ok(),
        "C54 forged offline probability-profile fixture should compile");

    const auto findModifier = [](talas::runtime::RuntimePlan& plan) {
        return std::ranges::find(
            plan.steps,
            std::string_view{"talas.spectrumModifier"},
            &talas::runtime::CompileStep::typeId);
    };
    const auto requireRejected = [&] (
                                     talas::runtime::RuntimePlan plan,
                                     std::string_view context) {
        const auto result = talas::runtime::renderOffline(
            handBuiltGraph(
                std::move(plan),
                compiled.graph->renderSettings()),
            5);
        require(
            !result.ok() && result.mono.empty()
                && result.right.empty(),
            std::string{context}
                + " should reject forged C54 probability-profile authority");
    };

    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(
            modifier != plan.steps.end()
                && modifier->spectrumModifierProbabilityProfile.size()
                    == 4096,
            "C54 short-profile fixture should expose the exact compiled profile");
        modifier->spectrumModifierProbabilityProfile.pop_back();
        requireRejected(std::move(plan), "short probability profile");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(
            modifier != plan.steps.end(),
            "C54 mismatched-profile fixture should expose Spectrum Modifier");
        modifier->spectrumModifierProbabilityProfile.back() = 0.5;
        requireRejected(
            std::move(plan),
            "numerically valid but expression-mismatched probability profile");
    }
    {
        auto plan = compiled.graph->plan();
        const auto modifier = findModifier(plan);
        require(
            modifier != plan.steps.end(),
            "C54 wrong-owner fixture should expose Spectrum Modifier");
        const auto profile =
            modifier->spectrumModifierProbabilityProfile;
        modifier->spectrumModifierProbabilityProfile.clear();
        const auto wrongOwner = std::ranges::find_if(
            plan.steps,
            [](const talas::runtime::CompileStep& step) {
                return step.typeId != "talas.spectrumModifier";
            });
        require(
            wrongOwner != plan.steps.end(),
            "C54 wrong-owner fixture should expose a non-modifier step");
        wrongOwner->spectrumModifierProbabilityProfile = profile;
        requireRejected(
            std::move(plan),
            "probability profile on the wrong node type");
    }
}

