void testSpectrumModifierRetainsLiveHysteresisMembershipAcrossOfflineCalls()
{
    auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "0.5"},
            textParameter("amplitudes", "1"),
            textParameter("frequencies", "100"),
            textParameter("bandwidths", "0"),
        }),
        spectrumModifierParameters({
            {"loFreq", "0 hz"},
            {"hiFreq", "200 hz"},
            {"freqHysteresis", "10 hz"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"ampScale", "1"},
            {"ampOffset", "0"},
        }),
        spectrumTrackSelectorParameters({{"track", "1"}}));
    document.graph.nodes.push_back(node(
        "loFreqControl", "talas.constant", {{"value", "!C52LoFreq"}}));
    document.graph.connections.push_back(connection(
        "loFreqControl", "value", "modifier", "loFreq"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.eventValues = {
        {"C52LoFreq", 100.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1, "C52LoFreq", 120.0, talas::expr::ValueDomain::Scalar},
        {2, "C52LoFreq", 105.0, talas::expr::ValueDomain::Scalar},
        {3, "C52LoFreq", 90.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "offline live-hysteresis fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto firstObservation = session.render(1);
    const auto expandedExit = session.render(1);
    const auto contractedDeadband = session.render(1);
    const auto contractedEntry = session.render(1);
    require(
        firstObservation.ok() && expandedExit.ok()
            && contractedDeadband.ok() && contractedEntry.ok(),
        "offline live-hysteresis public calls should render");
    requireNear(
        firstObservation.mono.front(), 0.5, 1.0e-12,
        "first offline observation should retain C27 expanded-range compatibility");
    requireNear(
        expandedExit.mono.front(), 0.0, 1.0e-12,
        "active offline membership should leave beyond the expanded range");
    requireNear(
        contractedDeadband.mono.front(), 0.0, 1.0e-12,
        "inactive offline membership should remain out inside the hysteresis deadband");
    requireNear(
        contractedEntry.mono.front(), 0.5, 1.0e-12,
        "inactive offline membership should re-enter at the inclusive contracted boundary");

    session.reset();
    const auto afterReset = session.render(1);
    require(
        afterReset.ok() && afterReset.mono.size() == 1,
        "reset offline live-hysteresis fixture should render from frame zero");
    requireNear(
        afterReset.mono.front(), 0.5, 1.0e-12,
        "offline reset should clear membership and restore first-observation behavior");
}

void testSpectrumModifierAdvancesProbabilityOncePerOfflinePublicFrame()
{
    const auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "0.5"},
            textParameter("amplitudes", "1"),
            textParameter("frequencies", "100"),
            textParameter("bandwidths", "0"),
        }),
        spectrumModifierParameters({
            {"loTrack", "1"},
            {"hiTrack", "1"},
            {"loFreq", "0 hz"},
            {"hiFreq", "1000 hz"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"loAmp", "0"},
            {"hiAmp", "1"},
            {"ampScale", "2"},
            {"ampOffset", "0"},
            {"probability", "TrackNumber * 0.7"},
            {"seed", "-1"},
        }),
        spectrumTrackSelectorParameters({{"track", "1"}}));
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "offline C54 track-profile probability stream fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto zero = session.render(0);
    const auto ordinalZero = session.render(1);
    const auto ordinalOne = session.render(1);
    require(
        zero.ok() && zero.mono.empty()
            && ordinalZero.ok() && ordinalZero.mono.size() == 1
            && ordinalOne.ok() && ordinalOne.mono.size() == 1,
        "offline C54 probability frames should render around a zero-frame no-op");
    requireNear(
        ordinalZero.mono.front(), 1.0, 0.0,
        "offline C54 ordinal zero should preserve the C53 selected decision through the track profile");
    requireNear(
        ordinalOne.mono.front(), 0.0, 0.0,
        "offline C54 ordinal one should publish the next track-profile probability decision");

    session.reset();
    const auto afterReset = session.render(1);
    require(
        afterReset.ok() && afterReset.mono.size() == 1,
        "reset offline C54 probability stream fixture should render");
    requireNear(
        afterReset.mono.front(), ordinalZero.mono.front(), 0.0,
        "offline reset should restore probability ordinal zero exactly");
}

void testSpectrumModifierAdvancesProbabilityAfterOfflineBypassFrames()
{
    const auto verify = [](
                            double initialProbability,
                            double initialLoTrack,
                            double expectedFirstAmplitude,
                            std::string_view context) {
        auto document = makeSyntheticSpectrumFromSoundsTrackSelectorDocument(
            syntheticSpectrumFromSoundsParameters({{"nbrPartials", "1"}}),
            spectrumTrackSelectorParameters({{"track", "1"}}));
        const auto selector = std::ranges::find(
            document.graph.nodes,
            std::string{"selector"},
            &talas::project::ProjectNode::instanceId);
        require(
            selector != document.graph.nodes.end(),
            std::string{context} + " should expose its selector");
        document.graph.nodes.insert(
            selector,
            node(
                "modifier",
                "talas.spectrumModifier",
                spectrumModifierParameters({
                    {"loTrack", "1"},
                    {"hiTrack", "2"},
                    {"freqScale", "1"},
                    {"freqOffset", "0"},
                    {"ampScale", "2"},
                    {"ampOffset", "0"},
                    {"probability", "0.7"},
                    {"seed", "-1"},
                })));
        const auto spectrumToSelector = std::ranges::find_if(
            document.graph.connections,
            [](const talas::core::Connection& edge) {
                return edge.fromNode == "spectrum"
                    && edge.fromPort == "spectrumOut"
                    && edge.toNode == "selector"
                    && edge.toPort == "spectrumIn";
            });
        require(
            spectrumToSelector != document.graph.connections.end(),
            std::string{context} + " should expose its Spectrum edge");
        *spectrumToSelector = connection(
            "spectrum", "spectrumOut", "modifier", "spectrumIn");
        document.graph.connections.push_back(connection(
            "modifier", "spectrumOut", "selector", "spectrumIn"));
        document.graph.nodes.push_back(node(
            "probabilityControl", "talas.constant",
            {{"value", "!C53Probability"}}));
        document.graph.nodes.push_back(node(
            "loTrackControl", "talas.constant",
            {{"value", "!C53LoTrack"}}));
        document.graph.connections.push_back(connection(
            "probabilityControl", "value", "modifier", "probability"));
        document.graph.connections.push_back(connection(
            "loTrackControl", "value", "modifier", "loTrack"));

        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = 1;
        settings.audioInputChannels = {
            {1, {0.5, 0.5}},
            {2, {100.0, 100.0}},
        };
        settings.eventValues = {
            {"C53Probability", initialProbability,
             talas::expr::ValueDomain::Scalar},
            {"C53LoTrack", initialLoTrack,
             talas::expr::ValueDomain::Scalar},
        };
        settings.eventValueChanges = {
            {1, "C53Probability", 0.7,
             talas::expr::ValueDomain::Scalar},
            {1, "C53LoTrack", 1.0,
             talas::expr::ValueDomain::Scalar},
        };
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(
            compiled.ok(),
            std::string{context} + " offline fixture should compile");

        talas::runtime::OfflineRenderSession session{*compiled.graph};
        const auto bypass = session.render(1);
        const auto fractional = session.render(1);
        require(
            bypass.ok() && bypass.mono.size() == 1
                && fractional.ok() && fractional.mono.size() == 1,
            std::string{context}
                + " offline public frames should render");
        requireNear(
            bypass.mono.front(), expectedFirstAmplitude, 0.0,
            std::string{context} + " first-frame output");
        requireNear(
            fractional.mono.front(), 0.0, 0.0,
            std::string{context}
                + " should consume ordinal zero before the distinguishing fractional frame");
    };

    verify(0.0, 1.0, 0.0, "C53 probability-zero bypass");
    verify(1.0, 1.0, 1.0, "C53 probability-one bypass");
    verify(0.7, 2.0, 0.0, "C53 criteria-false bypass");

    auto emptyDocument = makeLiveSpectralAnalysisTrackSelectorDocument(
        liveSpectralAnalysisParameters({{"initFreq", "8 hz"}}));
    const auto emptySelector = std::ranges::find(
        emptyDocument.graph.nodes,
        std::string{"selector"},
        &talas::project::ProjectNode::instanceId);
    require(
        emptySelector != emptyDocument.graph.nodes.end(),
        "C53 empty-Spectrum fixture should expose its selector");
    emptyDocument.graph.nodes.insert(
        emptySelector,
        node(
            "modifier",
            "talas.spectrumModifier",
            spectrumModifierParameters({
                {"loTrack", "1"},
                {"hiTrack", "1"},
                {"freqScale", "1"},
                {"freqOffset", "0"},
                {"ampScale", "2"},
                {"ampOffset", "0"},
                {"probability", "0.7"},
                {"seed", "-1"},
            })));
    const auto bridgeToSelector = std::ranges::find_if(
        emptyDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "bridge"
                && edge.fromPort == "spectrumOut"
                && edge.toNode == "selector"
                && edge.toPort == "spectrumIn";
        });
    require(
        bridgeToSelector != emptyDocument.graph.connections.end(),
        "C53 empty-Spectrum fixture should expose its bridge edge");
    *bridgeToSelector = connection(
        "bridge", "spectrumOut", "modifier", "spectrumIn");
    emptyDocument.graph.connections.push_back(connection(
        "modifier", "spectrumOut", "selector", "spectrumIn"));

    auto emptySettings = talas::runtime::RenderSettings{};
    emptySettings.sampleRate = 64.0;
    emptySettings.maxBlockFrames = 64;
    emptySettings.audioInputChannels = {{
        1, liveSpectralSine(64, 8.0, 0.75),
    }};
    const auto emptyCompiled = talas::runtime::compileProject(
        emptyDocument, makeRegistry(), emptySettings);
    require(
        emptyCompiled.ok(),
        "C53 empty-Spectrum offline fixture should compile");
    talas::runtime::OfflineRenderSession emptySession{*emptyCompiled.graph};
    const auto emptyFrame = emptySession.render(63);
    const auto laterFractionalFrame = emptySession.render(1);
    require(
        emptyFrame.ok() && emptyFrame.mono.size() == 63
            && laterFractionalFrame.ok()
            && laterFractionalFrame.mono.size() == 1
            && std::ranges::all_of(
                emptyFrame.mono,
                [](double value) { return value == 0.0; }),
        "C53 empty legacy Spectrum frame should publish successfully before the first analyzed partial frame");
    requireNear(
        laterFractionalFrame.mono.front(), 0.0, 0.0,
        "C53 empty offline Spectrum frame should consume ordinal zero before the first nonempty fractional frame");
}

void testSpectrumModifierRetainsMissingOfflineOrdinalMembership()
{
    auto document = makeSyntheticSpectrumFromSoundsTrackSelectorDocument(
        syntheticSpectrumFromSoundsParameters({{"nbrPartials", "2"}}),
        spectrumTrackSelectorParameters({{"track", "2"}}));
    document.graph.nodes.push_back(node(
        "modifier",
        "talas.spectrumModifier",
        spectrumModifierParameters({
            {"loTrack", "1"},
            {"hiTrack", "2"},
            {"loFreq", "100 hz"},
            {"hiFreq", "200 hz"},
            {"freqHysteresis", "10 hz"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"ampScale", "1"},
            {"ampOffset", "0"},
        })));
    const auto sourceToSelector = std::ranges::find_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "spectrum"
                && edge.fromPort == "spectrumOut"
                && edge.toNode == "selector"
                && edge.toPort == "spectrumIn";
        });
    require(
        sourceToSelector != document.graph.connections.end(),
        "missing-ordinal fixture should expose its source edge");
    *sourceToSelector = connection(
        "spectrum", "spectrumOut", "modifier", "spectrumIn");
    document.graph.connections.push_back(connection(
        "modifier", "spectrumOut", "selector", "spectrumIn"));
    document.graph.nodes.push_back(node(
        "countControl",
        "talas.triggeredTableRead",
        triggeredTableReadParameters({
            resourceParameter("wavetable", "Tables/C52Count"),
        })));
    document.graph.connections.push_back(connection(
        "countControl", "value", "spectrum", "nbrPartials"));
    document.graph.connections.push_back(connection(
        "countControl", "value", "selector", "track"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8.0;
    settings.maxBlockFrames = 2;
    settings.audioInputChannels = {
        {1, {0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5, 0.5}},
        {2, {100.0, 100.0, 100.0, 80.0, 100.0, 0.0, 100.0, 95.0}},
    };
    settings.tableResources = {{
        "Tables/C52Count",
        {2.0, 2.0, 2.0, 2.0, 1.0, 1.0, 2.0, 2.0},
    }};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "missing-ordinal offline live-hysteresis fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto zero = session.render(0);
    require(
        zero.ok() && zero.mono.empty() && zero.right.empty(),
        "zero-frame offline live-hysteresis call should be a no-op");
    const auto active = session.render(2);
    const auto exited = session.render(2);
    const auto missing = session.render(2);
    const auto reappeared = session.render(2);
    require(
        active.ok() && exited.ok() && missing.ok() && reappeared.ok(),
        "offline ordinal disappearance sequence should render");
    require(
        active.mono.size() == 2 && exited.mono.size() == 2
            && missing.mono.size() == 2 && reappeared.mono.size() == 2,
        "offline ordinal disappearance calls should return requested frames");
    for (std::size_t frame = 0; frame < 2; ++frame)
    {
        requireNear(
            active.mono[frame], 0.5, 1.0e-12,
            "second ordinal should initialize active through the expanded range");
        requireNear(
            exited.mono[frame], 0.0, 1.0e-12,
            "second ordinal should exit beyond its expanded range");
        requireNear(
            missing.mono[frame], 0.5, 1.0e-12,
            "first ordinal should remain independently active while the second is absent");
        requireNear(
            reappeared.mono[frame], 0.0, 1.0e-12,
            "reappearing second ordinal should retain inactive membership in the deadband");
    }
}

void testSpectrumModifierLateDownstreamFailureRollsBackOfflineState()
{
    auto document = makeSpectrumModifierTrackSelectorDocument(
        syntheticSpectrumFromArrayParameters({
            {"nbrPartials", "1"},
            {"envelope", "0.5"},
            textParameter("amplitudes", "1"),
            textParameter("frequencies", "100"),
            textParameter("bandwidths", "0"),
        }),
        spectrumModifierParameters({
            {"loFreq", "100 hz"},
            {"hiFreq", "200 hz"},
            {"freqHysteresis", "10 hz"},
            {"freqScale", "1"},
            {"freqOffset", "0"},
            {"ampScale", "2"},
            {"ampOffset", "0"},
            {"probability", "TrackNumber * 0.8"},
            {"seed", "-1"},
        }),
        spectrumTrackSelectorParameters({{"track", "1"}}));
    document.graph.nodes.push_back(node(
        "loFreqControl", "talas.constant", {{"value", "!C52RollbackLoFreq"}}));
    document.graph.connections.push_back(connection(
        "loFreqControl", "value", "modifier", "loFreq"));
    document.graph.nodes.push_back(node(
        "trackControl",
        "talas.triggeredTableRead",
        triggeredTableReadParameters({
            resourceParameter("wavetable", "Tables/C52Track"),
        })));
    document.graph.connections.push_back(connection(
        "trackControl", "value", "selector", "track"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.eventValues = {
        {"C52RollbackLoFreq", 100.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1, "C52RollbackLoFreq", 120.0, talas::expr::ValueDomain::Scalar},
    };
    settings.tableResources = {{
        "Tables/C52Track", {1.0, 1.0, 1.0, 2.0},
    }};
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "late-downstream offline membership fixture should compile");

    talas::runtime::OfflineRenderSession rejectedSession{*compiled.graph};
    const auto acceptedPrefix = rejectedSession.render(1);
    require(
        acceptedPrefix.ok() && acceptedPrefix.mono.size() == 1,
        "late-downstream fixture should accept its active prefix");
    requireNear(
        acceptedPrefix.mono.front(), 1.0, 1.0e-12,
        "late-downstream fixture should initialize active membership at C53 ordinal zero");

    const auto rejected = rejectedSession.render(3);
    require(
        !rejected.ok() && rejected.mono.empty() && rejected.right.empty(),
        "late downstream selector failure should reject the complete state transaction");

    const auto retried = rejectedSession.render(2);
    talas::runtime::OfflineRenderSession freshSession{*compiled.graph};
    const auto freshPrefix = freshSession.render(1);
    const auto fresh = freshSession.render(2);
    require(
        retried.ok() && freshPrefix.ok() && fresh.ok()
            && retried.mono.size() == fresh.mono.size(),
        "corrected retry and fresh stateful reference should render");
    for (std::size_t frame = 0; frame < fresh.mono.size(); ++frame)
    {
        requireNear(
            retried.mono[frame], fresh.mono[frame], 0.0,
            "late downstream rejection should roll back offline membership and probability ordinal at frame "
                + std::to_string(frame));
        requireNear(
            retried.right[frame], fresh.right[frame], 0.0,
            "late downstream rejection should roll back the downstream cursor at frame "
                + std::to_string(frame));
    }
}

