void testHandBuiltSpectrumFundamentalRejectsMalformedSpectrum()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "fundamental",
            "talas.spectrumFundamental",
            {binding("spectrumIn", "source", "spectrumOut", 0)},
            {},
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "fundamental", "leftOut", 1), binding("rightIn", "fundamental", "rightOut", 2)},
            {},
        },
    };
    plan.buffers = {
        {"source", "spectrumOut", talas::core::PortType::Spectrum, 5},
        {"fundamental", "leftOut", talas::core::PortType::Audio, 5},
        {"fundamental", "rightOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;
    plan.rightOutputBufferIndex = 2;
    plan.outputBufferIndices = {1, 2};

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 1000.0;
    settings.maxBlockFrames = 5;
    auto result = talas::runtime::renderOffline(handBuiltGraph(plan, settings), 5);

    require(!result.ok(), "spectrum fundamental should reject malformed spectrum buffer");
    require(result.mono.empty(), "failed malformed spectrum fundamental render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "fundamental", "spectrumIn"), "render should identify malformed fundamental spectrum input");

    // An empty spectrum, a Hold's before its analysis's first frame, gives
    // no fundamental rather than a refusal (ADR-0016); the documented
    // SpectrumFundamental test plays one.
}

