talas::runtime::OfflineRenderResult renderSpectralShapeDocument(
    std::vector<talas::runtime::TableResource> tableResources,
    std::vector<talas::project::ProjectParameterExpression> shapeParameters = spectralShapeParameters(),
    std::vector<talas::project::ProjectParameterExpression> selectorParameters = spectrumTrackSelectorParameters())
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = std::move(tableResources);

    const auto document = makeSpectralShapeTrackSelectorDocument(std::move(shapeParameters), std::move(selectorParameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "spectral shape document should compile before offline render");
    return talas::runtime::renderOffline(*compile.graph, 5);
}

