talas::runtime::OfflineRenderResult renderInvalidSyntheticSpectrumDocument(
    std::vector<talas::project::ProjectParameterExpression> spectrumParameters,
    std::vector<talas::project::ProjectParameterExpression> selectorParameters = spectrumTrackSelectorParameters())
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;

    const auto document = makeSyntheticSpectrumTrackSelectorDocument(std::move(spectrumParameters), std::move(selectorParameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid synthetic spectrum document should compile before render validation");
    return talas::runtime::renderOffline(*compile.graph, 5);
}

void requireSyntheticSpectrumRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> spectrumParameters,
    std::string_view parameterId)
{
    const auto result = renderInvalidSyntheticSpectrumDocument(std::move(spectrumParameters));
    require(!result.ok(), "invalid synthetic spectrum render should fail");
    require(result.mono.empty(), "failed synthetic spectrum render should not return left audio");
    require(result.right.empty(), "failed synthetic spectrum render should not return right audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "spectrum", {}, parameterId), "render should identify synthetic spectrum parameter");
}

