void testHandBuiltSpectrumTrackSelectorRejectsInvalidSpectrumAndTrackAtRender()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "selector",
            "talas.spectrumTrackSelector",
            {binding("spectrumIn", "source", "spectrumOut", 0)},
            {{"track", talas::expr::ValueDomain::Scalar, 2.0}, booleanRuntimeParameter("amp", true), booleanRuntimeParameter("freq", true)},
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "selector", "leftOut", 1), binding("rightIn", "selector", "rightOut", 2)},
            {},
        },
    };
    plan.buffers = {
        {"source", "spectrumOut", talas::core::PortType::Spectrum, 5},
        {"selector", "leftOut", talas::core::PortType::Audio, 5},
        {"selector", "rightOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;
    plan.rightOutputBufferIndex = 2;
    plan.outputBufferIndices = {1, 2};

    auto result = talas::runtime::renderOffline(handBuiltGraph(plan), 5);

    require(!result.ok(), "selector should reject malformed spectrum buffer");
    require(result.mono.empty(), "failed malformed selector render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "selector", "spectrumIn"), "render should identify malformed spectrum input");

    result = renderInvalidSyntheticSpectrumDocument(
        syntheticSpectrumFromArrayParameters(),
        spectrumTrackSelectorParameters({{"track", "3"}}));

    require(!result.ok(), "selector should reject out-of-range track");
    require(result.mono.empty(), "failed out-of-range selector render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "selector", {}, "track"), "render should identify out-of-range selector track");
}

