void testAnalysisFilterEmphasizesTunedHarmonic()
{
    const auto tuned = renderAnalysisFilterDocument("100 hz", "2", "200 hz", 8000.0, 4096);
    const auto distant = renderAnalysisFilterDocument("100 hz", "2", "600 hz", 8000.0, 4096);

    const auto tunedRms = rmsAfterSettling(tuned.mono, 1024);
    const auto distantRms = rmsAfterSettling(distant.mono, 1024);
    require(tunedRms > distantRms * 3.0, "analysis filter should emphasize tuned harmonic more than distant input");
}

void testAnalysisFilterProducesQuadratureRightOutput()
{
    const auto result = renderAnalysisFilterDocument("100 hz", "2", "200 hz", 8000.0, 4096);

    const auto leftRms = rmsAfterSettling(result.mono, 1024);
    const auto rightRms = rmsAfterSettling(result.right, 1024);
    require(leftRms > 0.1, "analysis filter left output should contain tuned energy");
    require(rightRms > 0.1, "analysis filter right output should contain tuned quadrature energy");
    require(std::abs(result.mono[1200] - result.right[1200]) > 1.0e-6, "analysis filter right output should not duplicate left output exactly");
}

void testAnalysisFilterConnectedFundamentalMatchesStaticReference()
{
    auto connectedDocument = makeAnalysisFilterDocument(
        {{"fundamental", "150 hz"}, {"harmonic", "2"}},
        {{"frequency", "200 hz"}, {"amplitude", "1.0"}});
    connectedDocument.graph.nodes.push_back(node("fundamental", "talas.constant", {{"value", "100"}}));
    connectedDocument.graph.connections.push_back(connection("fundamental", "value", "analysis", "fundamental"));

    const auto connected = renderDocument(connectedDocument, 8000.0, 512);
    const auto reference = renderDocument(
        makeAnalysisFilterDocument(
            {{"fundamental", "100 hz"}, {"harmonic", "2"}},
            {{"frequency", "200 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        512);

    require(connected.ok(), "connected-fundamental analysis filter render should not emit diagnostics");
    require(reference.ok(), "reference analysis filter render should not emit diagnostics");
    require(connected.mono.size() == reference.mono.size(), "connected-fundamental analysis filter should return reference left frame count");
    require(connected.right.size() == reference.right.size(), "connected-fundamental analysis filter should return reference right frame count");
    for (std::size_t index = 0; index < connected.mono.size(); ++index)
    {
        requireNear(connected.mono[index], reference.mono[index], 1.0e-12, "connected-fundamental analysis filter left sample " + std::to_string(index));
        requireNear(connected.right[index], reference.right[index], 1.0e-12, "connected-fundamental analysis filter right sample " + std::to_string(index));
    }
}

