void testAnalysisFilterSessionKeepsFilterStateAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 256;
    const auto document = makeAnalysisFilterDocument(
        {{"fundamental", "100 hz"}, {"harmonic", "2"}},
        {{"frequency", "200 hz"}, {"amplitude", "1.0"}});
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "analysis filter document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(256);
    const auto second = session.render(256);
    const auto oneShot = renderDocument(document, 8000.0, 512);

    require(first.ok(), "first analysis filter session render should not emit diagnostics");
    require(second.ok(), "second analysis filter session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot analysis filter render should not emit diagnostics");
    require(first.mono.size() == 256, "first analysis filter session render should return left frames");
    require(second.mono.size() == 256, "second analysis filter session render should return left frames");
    require(first.right.size() == 256, "first analysis filter session render should return right frames");
    require(second.right.size() == 256, "second analysis filter session render should return right frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "analysis filter session first left frame 0");
    requireNear(first.right[0], oneShot.right[0], 1.0e-12, "analysis filter session first right frame 0");
    requireNear(first.mono[128], oneShot.mono[128], 1.0e-12, "analysis filter session first left frame 128");
    requireNear(first.right[128], oneShot.right[128], 1.0e-12, "analysis filter session first right frame 128");
    requireNear(second.mono[0], oneShot.mono[256], 1.0e-12, "analysis filter session second left frame 0");
    requireNear(second.right[0], oneShot.right[256], 1.0e-12, "analysis filter session second right frame 0");
    requireNear(second.mono[128], oneShot.mono[384], 1.0e-12, "analysis filter session second left frame 128");
    requireNear(second.right[128], oneShot.right[384], 1.0e-12, "analysis filter session second right frame 128");
}

void testAnalysisFilterScheduledControlsArePartitionResetAndFailureAtomic()
{
    const auto document = makeAnalysisFilterDocument(
        {{"fundamental", "!C164Fundamental"},
         {"harmonic", "!C164Harmonic"}},
        {{"frequency", "1 hz"}, {"amplitude", "0.75"}});
    auto settings = talas::runtime::RenderSettings{8.0, 8};
    settings.eventValues = {
        {"C164Fundamental", 0.5, talas::expr::ValueDomain::Hertz},
        {"C164Harmonic", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C164Fundamental", 0.25, talas::expr::ValueDomain::Hertz},
        {2, "C164Harmonic", 1.5, talas::expr::ValueDomain::Scalar},
        {4, "C164Fundamental", 0.5, talas::expr::ValueDomain::Hertz},
        {4, "C164Harmonic", 1.5, talas::expr::ValueDomain::Scalar},
        {6, "C164Fundamental", 0.25, talas::expr::ValueDomain::Hertz},
        {6, "C164Harmonic", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C164 offline paired-control schedule fixture should compile");
    talas::runtime::OfflineRenderSession oneShot{*compiled.graph};
    talas::runtime::OfflineRenderSession partitioned{*compiled.graph};
    const auto expected = oneShot.render(8);
    const auto empty = partitioned.render(0);
    const auto first = partitioned.render(3);
    const auto second = partitioned.render(2);
    const auto third = partitioned.render(3);
    require(expected.ok() && empty.ok() && empty.mono.empty()
            && empty.right.empty() && first.ok() && second.ok()
            && third.ok(),
        "C164 offline stereo schedule should render across a zero frame and irregular partitions");
    auto actualLeft = first.mono;
    auto actualRight = first.right;
    actualLeft.insert(
        actualLeft.end(), second.mono.begin(), second.mono.end());
    actualLeft.insert(
        actualLeft.end(), third.mono.begin(), third.mono.end());
    actualRight.insert(
        actualRight.end(), second.right.begin(), second.right.end());
    actualRight.insert(
        actualRight.end(), third.right.begin(), third.right.end());
    require(actualLeft == expected.mono
            && actualRight == expected.right,
        "C164 same-frame fundamental/harmonic schedule should be bit-identical across offline partitions");
    partitioned.reset();
    const auto replay = partitioned.render(8);
    require(replay.ok() && replay.mono == expected.mono
            && replay.right == expected.right,
        "C164 offline reset should replay both quadrature channels and paired schedules exactly");

    auto failingDocument = document;
    std::erase_if(
        failingDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "analysis"
                && edge.toNode == "out";
        });
    failingDocument.graph.nodes.push_back(node(
        "downstreamLeft", "talas.level", {
            {"left", "!C164Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.nodes.push_back(node(
        "downstreamRight", "talas.level", {
            {"left", "!C164Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.nodes.push_back(node(
        "outputScaleLeft", "talas.level", {
            {"left", "100"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.nodes.push_back(node(
        "outputScaleRight", "talas.level", {
            {"left", "100"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    failingDocument.graph.connections.push_back(connection(
        "analysis", "leftOut", "downstreamLeft", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "analysis", "rightOut", "downstreamRight", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "downstreamLeft", "leftOut", "outputScaleLeft", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "downstreamRight", "leftOut", "outputScaleRight", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "outputScaleLeft", "leftOut", "out", "audioIn"));
    failingDocument.graph.connections.push_back(connection(
        "outputScaleRight", "leftOut", "out", "rightIn"));
    settings.eventValues.push_back({
        "C164Downstream", 1.0, talas::expr::ValueDomain::Scalar});
    settings.eventValueChanges.push_back({
        6, "C164Downstream", std::numeric_limits<double>::max(),
        talas::expr::ValueDomain::Scalar});
    std::ranges::sort(
        settings.eventValueChanges, {},
        &talas::runtime::EventValueChange::frame);
    const auto failingCompiled = talas::runtime::compileProject(
        failingDocument, makeRegistry(), settings);
    require(failingCompiled.ok(),
        "C164 offline late-failure fixture should compile"
            + (failingCompiled.diagnostics.empty()
                ? std::string{}
                : ": " + failingCompiled.diagnostics.front().message));
    talas::runtime::OfflineRenderSession candidate{*failingCompiled.graph};
    require(candidate.render(3).ok(),
        "C164 offline rollback fixture should establish quadrature filter state");
    const auto rejected = candidate.render(4);
    const auto retry = candidate.render(3);
    const auto repeatedFailure = candidate.render(1);

    std::erase_if(settings.eventValueChanges, [](const auto& change) {
        return change.name == "C164Downstream";
    });
    const auto referenceCompiled = talas::runtime::compileProject(
        failingDocument, makeRegistry(), settings);
    require(referenceCompiled.ok(),
        "C164 offline rollback reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(3).ok(),
        "C164 offline rollback reference should establish matching state");
    const auto referenceRetry = reference.render(3);
    require(!rejected.ok() && rejected.mono.empty()
            && rejected.right.empty(),
        "C164 late downstream failure should publish neither quadrature channel");
    require(retry.ok() && referenceRetry.ok()
            && retry.mono == referenceRetry.mono
            && retry.right == referenceRetry.right,
        "C164 offline failure should restore both allpass histories and the paired-control cursor before retry");
    require(!repeatedFailure.ok() && repeatedFailure.mono.empty()
            && repeatedFailure.right.empty(),
        "C164 offline rollback should restore the failing event for deterministic rejection");
}

void testHandBuiltAnalysisFilterRejectsNyquistCenterAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8000.0;
    settings.maxBlockFrames = 5;

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "osc",
            "talas.oscillator",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 1000.0},
                {"amplitude", talas::expr::ValueDomain::Scalar, 1.0},
            },
        },
        {
            "analysis",
            "talas.analysisFilter",
            {binding("audioIn", "osc", "audioOut", 0)},
            {
                {"fundamental", talas::expr::ValueDomain::Hertz, 1000.0},
                {"harmonic", talas::expr::ValueDomain::Scalar, 4.0},
            },
        },
        {
            "out",
            "talas.audioOutput",
            {
                binding("audioIn", "analysis", "leftOut", 1),
                binding("rightIn", "analysis", "rightOut", 2),
            },
            {},
        },
    };
    plan.buffers = {
        {"osc", "audioOut", talas::core::PortType::Audio, 5},
        {"analysis", "leftOut", talas::core::PortType::Audio, 5},
        {"analysis", "rightOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 1;
    plan.rightOutputBufferIndex = 2;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 5);

    require(!result.ok(), "analysis filter with Nyquist center should fail render");
    require(result.mono.empty(), "failed analysis filter render should not return left audio");
    require(result.right.empty(), "failed analysis filter render should not return right audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "analysis", {}, "harmonic"), "render should identify analysis filter harmonic");
}

