void testSimplePitchShifterConnectedPitchBoundsUpdatePerFrame()
{
    auto document = makeSimplePitchShifterDocument(
        {{"interval", "0"}, {"minInputPitch", "20 hz"}, {"maxInputPitch", "2000 hz"}},
        {{"frequency", "1 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("minPitch", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/MinPitch")})));
    document.graph.nodes.push_back(node("maxPitch", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/MaxPitch")})));
    document.graph.connections.push_back(connection("minPitch", "value", "pitch", "minInputPitch"));
    document.graph.connections.push_back(connection("maxPitch", "value", "pitch", "maxInputPitch"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/MinPitch", {20.0, 100.0, 200.0, 50.0, 20.0}});
    settings.tableResources.push_back({"Tables/MaxPitch", {2000.0, 1000.0, 400.0, 500.0, 100.0}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-pitch-bounds simple pitch shifter document should compile before render");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-pitch-bounds simple pitch shifter render should not emit diagnostics");
    require(result.mono.size() == 5, "dynamic-pitch-bounds simple pitch shifter should return requested frames");
    const std::vector<double> expected{0.0, 1.0, 0.0, -1.0, 0.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic-pitch-bounds simple pitch shifter frame " + std::to_string(frame));
}

