// A known pitch a Sound feeds is read each frame: one that stays the
// Input's pitch leaves it unshifted however it moves.
void testMonotonizerFollowsSampleRateKnownPitchChanges()
{
    auto document = makeMonotonizerDocument(
        {{"frequency", "440 hz"}, {"minInputPitch", "440 hz"}, {"maxInputPitch", "440 hz"}},
        {{"frequency", "1 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("frequency", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Pitch")})));
    document.graph.nodes.push_back(node("minPitch", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Pitch")})));
    document.graph.nodes.push_back(node("maxPitch", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Pitch")})));
    document.graph.connections.push_back(connection("frequency", "value", "mono", "frequency"));
    document.graph.connections.push_back(connection("minPitch", "value", "mono", "minInputPitch"));
    document.graph.connections.push_back(connection("maxPitch", "value", "mono", "maxInputPitch"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    auto steady = settings;
    settings.tableResources.push_back({"Tables/Pitch", {440.0, 220.0, 330.0, 440.0, 550.0}});
    steady.tableResources.push_back({"Tables/Pitch", {440.0, 440.0, 440.0, 440.0, 440.0}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    const auto steadyCompile = talas::runtime::compileProject(document, makeRegistry(), steady);
    require(compile.ok() && steadyCompile.ok(), "dynamic-neutral monotonizer document should compile before render");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);
    const auto expected = talas::runtime::renderOffline(*steadyCompile.graph, 5);

    require(result.ok() && expected.ok(),
            "sample-rate Monotonizer pitch changes should be read each frame");
    require(result.mono == expected.mono,
            "a known pitch that stays the Input's should leave it unshifted however it moves");
}

