void testMonotonizerRetargetsKnownPitch()
{
    const auto result = renderDocument(
        makeMonotonizerDocument(
            {
                {"frequency", "200 hz"},
                {"minInputPitch", "100 hz"},
                {"maxInputPitch", "100 hz"},
            },
            {{"frequency", "100 hz"}, {"amplitude", "1.0"}}),
        8000.0,
        8192);
    require(result.ok(), "known-pitch Monotonizer retarget should render");
    const auto target = toneCorrelationMagnitude(
        result.mono, 8000.0, 200.0, 4096);
    const auto source = toneCorrelationMagnitude(
        result.mono, 8000.0, 100.0, 4096);
    require(target > source * 4.0,
            "Monotonizer should favor the requested known-pitch target");
}

