void testTimeFrequencyScaleSeparatesPlaybackRateFromPitch()
{
    constexpr double pi = 3.1415926535897932384626433832795;
    constexpr std::size_t sourceFrames = 32768;
    constexpr std::array<std::pair<double, double>, 5> profiles{{
        {0.5, 1.0},
        {1.0, 0.75},
        {1.0, 1.0},
        {1.0, 1.5},
        {2.0, 1.0},
    }};
    for (const auto sampleRate : {44100.0, 48000.0})
    {
        const auto sourceFrequency = sampleRate / 100.0;
        std::vector<double> source(sourceFrames);
        for (std::size_t frame = 0; frame < source.size(); ++frame)
        {
            source[frame] = std::sin(
                2.0 * pi * sourceFrequency * static_cast<double>(frame)
                / sampleRate);
        }
        for (const auto [rate, frequencyScale] : profiles)
        {
            const auto active = rate != frequencyScale;
            const auto durationFrames = static_cast<std::size_t>(
                std::ceil(static_cast<double>(sourceFrames) / rate));
            const auto windowSize = talas::dsp::timeFrequencyScaleAnalysisFrameSize(sampleRate, 20.0);
            const auto latency = active ? talas::dsp::timeFrequencyScaleLatencyFrames(windowSize) : std::size_t{0};
            const auto supportMargin = active
                ? static_cast<std::size_t>(std::ceil(windowSize * 0.5 * (1.0 + 1.0 / rate)))
                : std::size_t{256};
            const auto renderFrames = durationFrames + latency + supportMargin + 1024;
            const auto result = renderTimeFrequencyScaleDocument(
                timeFrequencyScaleParameters({
                    {"frequencyScale", std::to_string(frequencyScale)},
                    {"rate", std::to_string(rate)},
                    {"maxFreqScale", "2.0"},
                    // Rate 2 compresses time as before format 92.
                    choiceParameter("rateAboveOne", "legacyCompresses"),
                }),
                source,
                renderFrames,
                sampleRate);
            require(result.ok(),
                    "independent TimeFrequencyScale profile should render");

            const auto firstSettled = latency + supportMargin;
            const auto lastSettled = durationFrames + latency - supportMargin;
            require(firstSettled < lastSettled
                        && lastSettled <= result.mono.size(),
                    "TimeFrequencyScale settled evidence window should be valid");
            std::vector<double> settled(
                result.mono.begin() + static_cast<std::ptrdiff_t>(firstSettled),
                result.mono.begin() + static_cast<std::ptrdiff_t>(lastSettled));
            const auto target = toneCorrelationMagnitude(
                settled, sampleRate, sourceFrequency * frequencyScale, 0);
            if (active)
            {
                const auto uncorrected = toneCorrelationMagnitude(
                    settled, sampleRate, sourceFrequency * rate, 0);
                require(target > 0.5 && target > uncorrected * 4.0,
                        "TimeFrequencyScale should favor requested pitch over raw resampling pitch");
            }
            else
            {
                require(target > 0.95,
                        "same-ratio TimeFrequencyScale should keep exact raw pitch");
            }

            const auto lastAudible = std::find_if(
                result.mono.rbegin(), result.mono.rend(),
                [](double sample) { return std::abs(sample) > 1.0e-8; });
            require(lastAudible != result.mono.rend(),
                    "TimeFrequencyScale profile should contain audible output");
            const auto lastAudibleFrame = result.mono.size() - 1
                - static_cast<std::size_t>(
                    std::distance(result.mono.rbegin(), lastAudible));
            require(lastAudibleFrame + 512 >= durationFrames
                        && lastAudibleFrame
                            <= durationFrames + latency + supportMargin,
                    "TimeFrequencyScale output duration should follow source duration divided by rate plus bounded tail");
        }
    }
}

