void testTimeFrequencyScaleSessionKeepsReadCursor()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.tableResources.push_back({"Samples/TFS", {10.0, 20.0, 30.0, 40.0, 50.0}});
    const auto parameters = timeFrequencyScaleParameters({{"rate", "1.0"}});
    const auto document = makeTimeFrequencyScaleDocument(parameters);
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "time frequency scale document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(4);
    const auto oneShot = renderTimeFrequencyScaleDocument(parameters, {10.0, 20.0, 30.0, 40.0, 50.0}, 6);

    require(first.ok(), "first time frequency scale session render should not emit diagnostics");
    require(second.ok(), "second time frequency scale session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot time frequency scale render should not emit diagnostics");
    require(first.mono.size() == 2, "first time frequency scale session render should return requested frames");
    require(second.mono.size() == 4, "second time frequency scale session render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "time frequency scale session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "time frequency scale session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "time frequency scale session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "time frequency scale session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "time frequency scale session second frame 2");
    requireNear(second.mono[3], oneShot.mono[5], 1.0e-12, "time frequency scale session second frame 3");
}

talas::runtime::OfflineRenderResult renderInvalidTimeFrequencyScaleDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::TableResource> tableResources)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = std::move(tableResources);

    const auto document = makeTimeFrequencyScaleDocument(std::move(parameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid time frequency scale document should compile before render validation");
    return talas::runtime::renderOffline(*compile.graph, 5);
}

void requireTimeFrequencyScaleRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::TableResource> tableResources,
    std::string_view)
{
    const auto result = renderInvalidTimeFrequencyScaleDocument(std::move(parameters), std::move(tableResources));
    require(!result.ok(), "unsupported time frequency scale configuration should fail render");
    require(result.mono.empty(), "failed time frequency scale render should not return audio");
    require(!result.diagnostics.empty(),
            "render should report the rejected TimeFrequencyScale preparation");
}

void testTimeFrequencyScaleRejectsUnsupportedConfigurationsAtRender()
{
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters({{"detectors", "11"}}),
        {{"Samples/TFS", {1.0, 2.0, 3.0}}},
        "detectors");
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters({booleanParameter("fromDisk", true)}),
        {{"Samples/TFS", {1.0, 2.0, 3.0}}},
        "fromDisk");
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters({booleanParameter("fromMemoryWriter", true)}),
        {{"Samples/TFS", {1.0, 2.0, 3.0}}},
        "fromMemoryWriter");
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters({resourceParameter("sample", "Samples/Missing")}),
        {{"Samples/TFS", {1.0, 2.0, 3.0}}},
        "sample");
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters(),
        {{"Samples/TFS", {}}},
        "sample");
    requireTimeFrequencyScaleRenderFailure(
        timeFrequencyScaleParameters(),
        {{"Samples/TFS", {1.0, std::numeric_limits<double>::infinity()}}},
        "sample");
}

void testHandBuiltTimeFrequencyScaleRejectsInvalidRateAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Samples/TFS", {10.0, 20.0, 30.0}});

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "tfs",
            "talas.timeFrequencyScale",
            {},
            {
                {"frequencyScale", talas::expr::ValueDomain::Scalar, 1.0},
                {"rate", talas::expr::ValueDomain::Scalar, -0.1},
                {"gate", talas::expr::ValueDomain::Scalar, 1.0},
                {"minInputFreq", talas::expr::ValueDomain::Hertz, 20.0},
                {"maxInputFreq", talas::expr::ValueDomain::Hertz, 2000.0},
                {"maxFreqScale", talas::expr::ValueDomain::Scalar, 1.0},
                {"detectors", talas::expr::ValueDomain::Scalar, 10.0},
                booleanRuntimeParameter("fromDisk", false),
                resourceRuntimeParameter("sample", "Samples/TFS"),
                booleanRuntimeParameter("fromMemoryWriter", false),
            },
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "tfs", "audioOut", 0)},
            {},
        },
    };
    plan.buffers = {{"tfs", "audioOut", talas::core::PortType::Audio, 5}};
    plan.outputBufferIndex = 0;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 5);

    require(!result.ok(), "stale invalid rate time frequency scale render should fail");
    require(result.mono.empty(), "failed stale time frequency scale render should not return audio");
    require(!result.diagnostics.empty(),
            "render should identify stale TimeFrequencyScale preparation");
}

