void testAudioInputDuplicatesSingleSelectedChannelToRightOut()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.audioInputChannels.push_back({1, {1.0, 2.0, 3.0}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection("input", "audioOut", "out", "audioIn"));
    document.graph.connections.push_back(connection("input", "rightOut", "out", "rightIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "stereo audio input document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);

    require(result.ok(), "stereo audio input render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.mono.size() == 4, "stereo audio input left should return requested frames");
    require(result.right.size() == 4, "stereo audio input right should return requested frames");
    const std::vector<double> expected = {1.0, 2.0, 3.0, 0.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
    {
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "stereo audio input left frame " + std::to_string(frame));
        requireNear(result.right[frame], expected[frame], 1.0e-12, "stereo audio input right frame " + std::to_string(frame));
    }
}

