{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.audioInputChannels.push_back({1, {1.0, 2.0, 3.0, 4.0}});
    const auto document = makeAudioInputDocument();
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "audio input document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(3);
    const auto oneShot = renderAudioInputDocument(audioInputParameters(), {{1, {1.0, 2.0, 3.0, 4.0}}}, 5);

    require(first.ok(), "first audio input session render should not emit diagnostics");
    require(second.ok(), "second audio input session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot audio input render should not emit diagnostics");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "audio input session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "audio input session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "audio input session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "audio input session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "audio input session second frame 2");
}

