void requireAudioInputRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::AudioInputChannel> channels,
    std::string_view parameterId)
{
    const auto result = renderAudioInputDocument(std::move(parameters), std::move(channels), 4);

    require(!result.ok(), "unsupported audio input configuration should fail render");
    require(result.mono.empty(), "failed audio input render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "input", {}, parameterId), "render should identify audio input channel parameter");
}

void testAudioInputRejectsUnsupportedConfigurationsAtRender()
{
    requireAudioInputRenderFailure(
        audioInputParameters({booleanParameter("channel1", false), booleanParameter("channel3", true)}),
        {{1, {1.0, 2.0, 3.0}}},
        "channel3");
    requireAudioInputRenderFailure(
        audioInputParameters(),
        {{1, {1.0, std::numeric_limits<double>::infinity(), 3.0}}},
        "channel1");
}

