// AttackTime and ReleaseTime shape a sample
// source; the live input passes unshaped.
void testGenericSourceLiveInputIgnoresTheSampleEnvelope()
{
    const auto result = renderGenericSourceDocument(
        genericSourceParameters({
            {"attackTime", "0.5 s"},
            {"releaseTime", "0.5 s"},
        }),
        {{1, {10.0, 20.0, 30.0, 40.0}}, {2, {-10.0, -20.0, -30.0, -40.0}}},
        5);

    require(result.ok(), "generic source live input with envelope times should not emit diagnostics");
    require(result.mono.size() == 5, "generic source live left output should return requested frames");
    require(result.right.size() == 5, "generic source live right output should return requested frames");
    const std::vector<double> expected{10.0, 20.0, 30.0, 40.0, 0.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
    {
        requireNear(result.mono[frame], expected[frame], 1.0e-12,
            "generic source live left frame " + std::to_string(frame) + " should pass unshaped");
        requireNear(result.right[frame], -expected[frame], 1.0e-12,
            "generic source live right frame " + std::to_string(frame) + " should pass unshaped");
    }
}

