void testGenericSourceSampleModeConnectedTriggerReplaysOnRisingEdges()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Samples/Source", {10.0, 20.0, 30.0, 40.0}});
    settings.tableResources.push_back({"Tables/Trigger", {0.0, 1.0, 1.0, 0.0, 1.0}});

    auto document = makeGenericSourceDocument(genericSourceParameters({
        textParameter("source", "sample"),
        resourceParameter("sample", "Samples/Source"),
        {"trigger", "0.0"},
    }));
    document.graph.nodes.push_back(node("trigger", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Trigger")})));
    document.graph.connections.push_back(connection("trigger", "value", "source", "trigger"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-trigger generic source sample document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "connected-trigger generic source sample render should not emit diagnostics");
    require(result.mono.size() == 5, "connected-trigger generic source left output should return requested frames");
    require(result.right.size() == 5, "connected-trigger generic source right output should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "connected-trigger generic source left frame 0 should be silent before trigger");
    requireNear(result.mono[1], 10.0, 1.0e-12, "connected-trigger generic source left frame 1 should start playback");
    requireNear(result.mono[2], 20.0, 1.0e-12, "connected-trigger generic source left frame 2 should continue playback");
    requireNear(result.mono[3], 30.0, 1.0e-12, "connected-trigger generic source left frame 3 should continue after closed trigger");
    requireNear(result.mono[4], 10.0, 1.0e-12, "connected-trigger generic source left frame 4 should restart playback");
    requireNear(result.right[0], 0.0, 1.0e-12, "connected-trigger generic source right frame 0 should be silent before trigger");
    requireNear(result.right[1], 10.0, 1.0e-12, "connected-trigger generic source right frame 1 should start playback");
    requireNear(result.right[2], 20.0, 1.0e-12, "connected-trigger generic source right frame 2 should continue playback");
    requireNear(result.right[3], 30.0, 1.0e-12, "connected-trigger generic source right frame 3 should continue after closed trigger");
    requireNear(result.right[4], 10.0, 1.0e-12, "connected-trigger generic source right frame 4 should restart playback");
}

