void connectNonFiniteControl(talas::project::ProjectDocument& document, std::string portId, std::string targetNodeId)
{
    const auto leftId = portId + "Left";
    const auto rightId = portId + "Right";
    const auto sumId = portId + "Sum";
    document.graph.nodes.push_back(node(leftId, "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node(rightId, "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node(sumId, "talas.add"));
    document.graph.connections.push_back(connection(leftId, "value", sumId, "left"));
    document.graph.connections.push_back(connection(rightId, "value", sumId, "right"));
    document.graph.connections.push_back(connection(sumId, "value", std::move(targetNodeId), std::move(portId)));
}

