void requireBlankMidiInStereoPassthrough(std::string typeId, std::vector<talas::project::ProjectParameterExpression> parameters)
{
    const auto expectsPreparedSilence = typeId == "talas.midiVoice";
    const auto result = renderDocument(makeMidiInDocument(std::move(typeId), std::move(parameters)), 4.0, 5);

    require(result.ok(), "blank MIDI-In render should not emit diagnostics");
    require(result.mono.size() == 5, "blank MIDI-In left output should return requested frames");
    require(result.right.size() == 5, "blank MIDI-In right output should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "blank MIDI-In left frame 0");
    requireNear(result.mono[1], expectsPreparedSilence ? 0.0 : 0.5, 1.0e-12, "blank MIDI-In left frame 1");
    requireNear(result.mono[2], 0.0, 1.0e-12, "blank MIDI-In left frame 2");
    requireNear(result.mono[3], expectsPreparedSilence ? 0.0 : -0.5, 1.0e-12, "blank MIDI-In left frame 3");
    requireNear(result.mono[4], 0.0, 1.0e-12, "blank MIDI-In left frame 4");
    requireNear(result.right[0], 0.0, 1.0e-12, "blank MIDI-In right frame 0");
    requireNear(result.right[1], expectsPreparedSilence ? 0.0 : 0.25, 1.0e-12, "blank MIDI-In right frame 1");
    requireNear(result.right[2], 0.0, 1.0e-12, "blank MIDI-In right frame 2");
    requireNear(result.right[3], expectsPreparedSilence ? 0.0 : -0.25, 1.0e-12, "blank MIDI-In right frame 3");
    requireNear(result.right[4], 0.0, 1.0e-12, "blank MIDI-In right frame 4");
}

void testBlankMidiMapperScalesInputToStereoOutputs()
{
    requireBlankMidiInStereoPassthrough("talas.midiMapper", midiMapperParameters());
}

void testMappedMidiMapperRendersClosedWithoutScheduledMidi()
{
    const auto result = renderDocument(
        makeMidiInDocument(
            "talas.midiMapper",
            midiMapperParameters({textParameter("map", "gate")})),
        4.0,
        5);
    require(result.ok(),
        "mapped MIDI Mapper without a scheduled stream should render closed");
    require(result.mono.size() == 5 && result.right.size() == 5,
        "closed mapper should preserve the requested stereo extent");
    require(std::ranges::all_of(result.mono, [](double sample) {
            return std::abs(sample) <= 1.0e-12;
        }) && std::ranges::all_of(result.right, [](double sample) {
            return std::abs(sample) <= 1.0e-12;
        }),
        "mapped MIDI Mapper should emit silence before its first accepted note");
}

