void requireMidiInConnectedGainsUpdatePerFrame(
    std::string typeId,
    std::vector<talas::project::ProjectParameterExpression> parameters)
{
    const auto expectsPreparedSilence = typeId == "talas.midiVoice";
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/LeftGain", {0.0, 0.5, 1.0, -0.5, 1.0}});
    settings.tableResources.push_back({"Tables/RightGain", {1.0, -1.0, 0.25, 0.5, 0.0}});

    auto document = makeMidiInDocument(std::move(typeId), std::move(parameters));
    document.graph.nodes.push_back(node("left", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/LeftGain")})));
    document.graph.nodes.push_back(node("right", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/RightGain")})));
    document.graph.connections.push_back(connection("left", "value", "midi", "left"));
    document.graph.connections.push_back(connection("right", "value", "midi", "right"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-gain MIDI-In document should compile before render");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-gain MIDI-In render should not emit diagnostics");
    require(result.mono.size() == 5, "dynamic-gain MIDI-In left output should return requested frames");
    require(result.right.size() == 5, "dynamic-gain MIDI-In right output should return requested frames");
    const std::vector<double> expectedLeft = expectsPreparedSilence
        ? std::vector<double>(5, 0.0)
        : std::vector<double>{0.0, 0.5, 0.0, 0.5, 0.0};
    const std::vector<double> expectedRight = expectsPreparedSilence
        ? std::vector<double>(5, 0.0)
        : std::vector<double>{0.0, -1.0, 0.0, -0.5, 0.0};
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(result.mono[frame], expectedLeft[frame], 1.0e-12, "dynamic-gain MIDI-In left frame " + std::to_string(frame));
        requireNear(result.right[frame], expectedRight[frame], 1.0e-12, "dynamic-gain MIDI-In right frame " + std::to_string(frame));
    }
}

