void testMidiOutputControllerConnectedInputsCaptureChangeStream()
{
    auto document = makeNoAudioTerminalDocument(
        "talas.midiOutputController",
        midiOutputControllerParameters({
            {"channel", "1"},
            {"controllerNumber", "10"},
            textParameter("value", ""),
        }));
    document.graph.nodes.push_back(node("channel", "talas.linearRamp", {{"duration", "1 s"}, {"start", "1"}, {"end", "5"}}));
    document.graph.nodes.push_back(node("controller", "talas.linearRamp", {{"duration", "1 s"}, {"start", "10"}, {"end", "14"}}));
    document.graph.nodes.push_back(node("value", "talas.linearRamp", {{"duration", "1 s"}, {"start", "0"}, {"end", "96"}}));
    document.graph.connections.push_back(connection("channel", "value", "terminal", "channel"));
    document.graph.connections.push_back(connection("controller", "value", "terminal", "controllerNumber"));
    document.graph.connections.push_back(connection("value", "value", "terminal", "value"));

    const auto result = renderDocument(document, 4.0, 6);

    require(result.ok(), "connected MIDIOutputController render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.midiEvents.size() == 5, "connected MIDIOutputController should emit one event per changed controller tuple");
    require(result.midiEvents[0].frame == 0, "connected control-change event 0 frame");
    require(result.midiEvents[0].bytes == std::vector<std::uint8_t>({0xb0, 10, 0}), "connected control-change event 0 bytes");
    require(result.midiEvents[1].frame == 1, "connected control-change event 1 frame");
    require(result.midiEvents[1].bytes == std::vector<std::uint8_t>({0xb1, 11, 24}), "connected control-change event 1 bytes");
    require(result.midiEvents[2].frame == 2, "connected control-change event 2 frame");
    require(result.midiEvents[2].bytes == std::vector<std::uint8_t>({0xb2, 12, 48}), "connected control-change event 2 bytes");
    require(result.midiEvents[3].frame == 3, "connected control-change event 3 frame");
    require(result.midiEvents[3].bytes == std::vector<std::uint8_t>({0xb3, 13, 72}), "connected control-change event 3 bytes");
    require(result.midiEvents[4].frame == 4, "connected control-change event 4 frame");
    require(result.midiEvents[4].bytes == std::vector<std::uint8_t>({0xb4, 14, 96}), "connected control-change event 4 bytes");
}

void testMidiOutputControllerConnectedInputsKeepRenderRelativeFramesAcrossBlocks()
{
    auto document = makeNoAudioTerminalDocument(
        "talas.midiOutputController",
        midiOutputControllerParameters({
            {"channel", "1"},
            {"controllerNumber", "10"},
            textParameter("value", ""),
        }));
    document.graph.nodes.push_back(node("value", "talas.linearRamp", {{"duration", "1 s"}, {"start", "0"}, {"end", "96"}}));
    document.graph.connections.push_back(connection("value", "value", "terminal", "value"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "multi-block MIDIOutputController document should compile before render");

    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "multi-block MIDIOutputController render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.midiEvents.size() == 5, "multi-block MIDIOutputController should emit every changed value");
    for (std::size_t frame = 0; frame < result.midiEvents.size(); ++frame)
        require(result.midiEvents[frame].frame == frame, "multi-block MIDIOutputController event frame " + std::to_string(frame));
    require(result.midiEvents[0].bytes == std::vector<std::uint8_t>({0xb0, 10, 0}), "multi-block MIDIOutputController initial bytes");
    require(result.midiEvents[4].bytes == std::vector<std::uint8_t>({0xb0, 10, 96}), "multi-block MIDIOutputController final bytes");
}

