void testMidiOutputEventSessionDoesNotRepeatHeldGateNoteOn()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;

    const auto compile = talas::runtime::compileProject(
        makeNoAudioTerminalDocument(
            "talas.midiOutputEvent",
            midiOutputEventParameters({
                {"frequency", "440 hz"},
                {"amplitude", "1"},
                {"channel", "2"},
                {"gate", "1"},
            })),
        makeRegistry(),
        settings);
    require(compile.ok(), "MIDIOutputEvent held gate document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(5);
    const auto second = session.render(5);

    require(first.ok(), "first held-gate MIDI render should not emit diagnostics");
    require(second.ok(), "second held-gate MIDI render should not emit diagnostics");
    require(first.midiEvents.size() == 1, "first held-gate render should emit initial note-on");
    require(second.midiEvents.empty(), "second held-gate render should not repeat note-on without a new gate edge");
}

void testMidiOutputEventConnectedGateCapturesNoteOnAndOffEdges()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node(
        "terminal",
        "talas.midiOutputEvent",
        midiOutputEventParameters({
            {"frequency", "440 hz"},
            {"amplitude", "1"},
            {"channel", "2"},
            {"gate", "0"},
        })));
    document.graph.nodes.push_back(node(
        "gate",
        "talas.triggeredTableRead",
        triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Gate")})));
    document.graph.connections.push_back(connection("gate", "value", "terminal", "gate"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/Gate", {0.0, 1.0, 1.0, 0.0, 0.0}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "MIDIOutputEvent connected-gate document should compile before render");

    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "MIDIOutputEvent connected-gate render should not emit diagnostics");
    require(result.midiEvents.size() == 2, "connected-gate render should emit note-on and note-off");
    require(result.midiEvents[0].frame == 1, "connected-gate note-on should use gate rising-edge frame");
    require(result.midiEvents[0].bytes == std::vector<std::uint8_t>({0x91, 69, 127}), "connected-gate note-on bytes should match channel, note, and velocity");
    require(result.midiEvents[1].frame == 3, "connected-gate note-off should use gate falling-edge frame");
    require(result.midiEvents[1].bytes == std::vector<std::uint8_t>({0x81, 69, 0}), "connected-gate note-off bytes should match channel and note");
}

