void testSoundToGlobalControllerCapturesDynamicFallbackChanges()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8.0;
    settings.maxBlockFrames = 3;
    settings.eventValues = {
        {"GlobalValue", 0.25, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "GlobalValue", 0.75, talas::expr::ValueDomain::Scalar},
        {4, "GlobalValue", 0.75 + 0.5e-12,
         talas::expr::ValueDomain::Scalar},
        {5, "GlobalValue", -0.5, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        makeNoAudioTerminalDocument(
            "talas.soundToGlobalController",
            soundToGlobalControllerParameters({
                textParameter("generatedEvent", "!Generated"),
                textParameter("value", "{!GlobalValue}"),
            })),
        makeRegistry(),
        settings);
    require(
        compiled.ok(),
        "C48 dynamic Global Controller fallback should compile");

    const auto result = talas::runtime::renderOffline(*compiled.graph, 7);
    require(
        result.ok() && result.globalControllerEvents.size() == 3,
        "C48 dynamic Global Controller fallback should emit initial and materially changed values (ok="
            + std::to_string(result.ok()) + ", events="
            + std::to_string(result.globalControllerEvents.size())
            + ")\n" + diagnosticDetails(result));
    require(
        result.globalControllerEvents[0].frame == 0
            && result.globalControllerEvents[0].name == "!Generated"
            && result.globalControllerEvents[0].value == 0.25,
        "C48 dynamic fallback initial event");
    require(
        result.globalControllerEvents[1].frame == 2
            && result.globalControllerEvents[1].value == 0.75,
        "C48 dynamic fallback scheduled event");
    require(
        result.globalControllerEvents[2].frame == 5
            && result.globalControllerEvents[2].value == -0.5,
        "C48 dynamic fallback deduplicated event");
}

void testSoundToGlobalControllerRejectsForgedOfflineFallbackAuthority()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 8.0;
    settings.eventValues = {
        {"GlobalValue", 0.25, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        makeNoAudioTerminalDocument(
            "talas.soundToGlobalController",
            soundToGlobalControllerParameters({
                textParameter("generatedEvent", "!Generated"),
                textParameter("value", "{!GlobalValue}"),
            })),
        makeRegistry(),
        settings);
    require(
        compiled.ok(),
        "C48 forged offline fallback fixture should compile");

    auto forgedPlan = compiled.graph->plan();
    const auto terminal = std::ranges::find(
        forgedPlan.steps,
        "terminal",
        &talas::runtime::CompileStep::nodeId);
    require(
        terminal != forgedPlan.steps.end(),
        "C48 forged offline fallback fixture terminal");
    const auto value = std::ranges::find(
        terminal->parameters,
        "value",
        &talas::runtime::ParameterValue::id);
    require(
        value != terminal->parameters.end(),
        "C48 forged offline fallback fixture value");
    value->value = 0.5;

    auto result = talas::runtime::renderOffline(
        handBuiltGraph(
            std::move(forgedPlan),
            compiled.graph->renderSettings()),
        1);
    require(
        !result.ok() && result.globalControllerEvents.empty(),
        "C48 offline fallback should reject a forged cached value");
    require(
        hasDiagnostic(
            result,
            DiagnosticCode::GraphValidationFailed,
            "terminal",
            {},
            "value"),
        "C48 forged cached fallback should identify value authority");

    auto missingReferenceSettings = compiled.graph->renderSettings();
    missingReferenceSettings.eventValues.clear();
    result = talas::runtime::renderOffline(
        handBuiltGraph(
            compiled.graph->plan(),
            std::move(missingReferenceSettings)),
        1);
    require(
        !result.ok() && result.globalControllerEvents.empty(),
        "C48 offline fallback should reject a missing authoritative Event Value");
    require(
        hasDiagnostic(
            result,
            DiagnosticCode::GraphValidationFailed,
            "terminal",
            {},
            "value"),
        "C48 missing fallback reference should identify value authority");
}

