void testHandBuiltMidiOutputEventRejectsNonFiniteRuntimeParameters()
{
    auto parameters = std::vector<talas::runtime::ParameterValue>{
        {"frequency", talas::expr::ValueDomain::Hertz, 440.0},
        {"amplitude", talas::expr::ValueDomain::Scalar, 0.5},
        {"channel", talas::expr::ValueDomain::Scalar, 1.0},
        {"gate", talas::expr::ValueDomain::Scalar, 0.0},
    };

    auto invalid = parameters;
    invalid[0].value = std::numeric_limits<double>::infinity();
    requireHandBuiltMidiOutputEventFailure(std::move(invalid), "frequency");

    invalid = parameters;
    invalid[1].value = std::numeric_limits<double>::infinity();
    requireHandBuiltMidiOutputEventFailure(std::move(invalid), "amplitude");

    invalid = parameters;
    invalid[3].value = std::numeric_limits<double>::infinity();
    requireHandBuiltMidiOutputEventFailure(std::move(invalid), "gate");
}

