    requireNear(first.right[0], oneShot.right[0], 1.0e-12, "generic source sample session right first frame 0");
    requireNear(first.right[1], oneShot.right[1], 1.0e-12, "generic source sample session right first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "generic source sample session left second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "generic source sample session left second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "generic source sample session left second frame 2");
