void requireGenericSourceRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::AudioInputChannel> channels,
    std::vector<talas::runtime::TableResource> tableResources,
    std::string_view parameterId)
{
    const auto result = renderGenericSourceDocument(std::move(parameters), std::move(channels), std::move(tableResources), 4);

    require(!result.ok(), "unsupported generic source configuration should fail render");
    require(result.mono.empty(), "failed generic source render should not return left audio");
    require(result.right.empty(), "failed generic source render should not return right audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "source", {}, parameterId), "render should identify generic source parameter");
}

void requireGenericSourceRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::AudioInputChannel> channels,
    std::string_view parameterId)
{
    requireGenericSourceRenderFailure(std::move(parameters), std::move(channels), {}, parameterId);
}

void testGenericSourceRejectsUnsupportedConfigurationsAtRender()
{
    requireGenericSourceRenderFailure(
        genericSourceParameters({textParameter("source", "network stream")}),
        {{1, {1.0, 2.0}}, {2, {3.0, 4.0}}},
        "source");
    requireGenericSourceRenderFailure(
        genericSourceParameters({booleanParameter("autoloop", true)}),
        {{1, {1.0, 2.0}}, {2, {3.0, 4.0}}},
        "autoloop");
    requireGenericSourceRenderFailure(
        genericSourceParameters({textParameter("source", "sample"), resourceParameter("sample", "")}),
        {},
        "sample");
    requireGenericSourceRenderFailure(
        genericSourceParameters({textParameter("source", "sample"), resourceParameter("sample", "Samples/Missing")}),
        {},
        "sample");
    requireGenericSourceRenderFailure(
        genericSourceParameters({textParameter("source", "sample"), resourceParameter("sample", "Samples/Source")}),
        {},
        {{"Samples/Source", {}}},
        "sample");
    requireGenericSourceRenderFailure(
        genericSourceParameters({textParameter("source", "sample"), resourceParameter("sample", "Samples/Source")}),
        {},
        {{"Samples/Source", {1.0, std::numeric_limits<double>::infinity()}}},
        "sample");
    requireGenericSourceRenderFailure(
        genericSourceParameters({
            textParameter("source", "sample"),
            resourceParameter("sample", "Samples/Source"),
            {"frequency", "-1 hz"},
        }),
        {},
        {{"Samples/Source", {1.0, 2.0}}},
        "frequency");
    requireGenericSourceRenderFailure(
        genericSourceParameters({booleanParameter("leftChannel", false)}),
        {{1, {1.0, 2.0}}},
        "rightChannel");
    requireGenericSourceRenderFailure(
        genericSourceParameters(),
        {{1, {1.0, std::numeric_limits<double>::infinity()}}, {2, {3.0, 4.0}}},
        "leftChannel");
}

void testHandBuiltMidiInRejectsUnsupportedRuntimeFields()
{
    auto makePlan = [](std::vector<talas::runtime::ParameterValue> parameters) {
        talas::runtime::RuntimePlan plan;
        plan.steps = {
            {
                "osc",
                "talas.oscillator",
                {},
                {{"frequency", talas::expr::ValueDomain::Hertz, 1.0}, {"amplitude", talas::expr::ValueDomain::Scalar, 1.0}},
            },
            {
                "midi",
                "talas.midiVoice",
                {binding("audioIn", "osc", "audioOut", 0)},
                std::move(parameters),
            },
            {
                "out",
                "talas.audioOutput",
                {binding("audioIn", "midi", "leftOut", 1), binding("rightIn", "midi", "rightOut", 2)},
                {},
            },
        };
        plan.buffers = {
            {"osc", "audioOut", talas::core::PortType::Audio, 5},
            {"midi", "leftOut", talas::core::PortType::Audio, 5},
            {"midi", "rightOut", talas::core::PortType::Audio, 5},
        };
        plan.outputBufferIndex = 1;
        plan.rightOutputBufferIndex = 2;
        plan.outputBufferIndices = {1, 2};
        return plan;
    };

    auto baseParameters = std::vector<talas::runtime::ParameterValue>{
        {"left", talas::expr::ValueDomain::Scalar, 0.5},
        {"right", talas::expr::ValueDomain::Scalar, 0.25},
        {"channel", talas::expr::ValueDomain::Scalar, 1.0},
        textRuntimeParameter("source", ""),
        resourceRuntimeParameter("midiFile", ""),
        {"polyphony", talas::expr::ValueDomain::Scalar, 1.0},
        {"lowPitch", talas::expr::ValueDomain::NoteNumber, 0.0},
        {"highPitch", talas::expr::ValueDomain::NoteNumber, 127.0},
        textRuntimeParameter("script", "noteOn"),
        booleanRuntimeParameter("shared", false),
    };

    auto result = talas::runtime::renderOffline(handBuiltGraph(makePlan(baseParameters)), 5);

    require(!result.ok(), "MIDI-In should reject non-empty runtime script");
    require(result.mono.empty(), "failed MIDI-In script render should not return left audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "midi", {}, "script"), "render should identify MIDI-In script");

    baseParameters[8] = textRuntimeParameter("script", "");
    baseParameters[9] = booleanRuntimeParameter("shared", true);
    result = talas::runtime::renderOffline(handBuiltGraph(makePlan(baseParameters)), 5);

    // A shared MIDI-In takes its notes along with other Sounds.
    require(result.ok(), "a shared MIDI-In should render");
    require(result.mono.size() == 5, "a shared MIDI-In should render every frame");
}

