    require(result.ok(), "separate-envelope quad oscillator render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.mono.size() == 5, "separate-envelope quad oscillator left should return requested frames");
    require(result.right.size() == 5, "separate-envelope quad oscillator right should return requested frames");
