void testQuadOscillatorConnectedFrequencyAccumulatesPhaseAcrossBlocks()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    settings.audioInputChannels.push_back({1, std::vector<double>(5, 1.0)});

    auto document = makeQuadOscillatorDocument({{"frequency", "1 hz"}});
    document.graph.nodes.push_back(node("frequency", "talas.linearRamp", {{"duration", "1 s"}, {"start", "0.5"}, {"end", "1.5"}}));
    document.graph.connections.push_back(connection("frequency", "value", "quad", "frequency"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "ramp-frequency quad oscillator document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "ramp-frequency quad oscillator render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.mono.size() == 5, "ramp-frequency quad oscillator render should return requested frames");
    const auto rootTwo = std::sqrt(2.0);
    const std::vector<double> expected = {
        1.0,
        rootTwo,
        rootTwo * std::sin(std::numbers::pi / 8.0),
        -rootTwo * std::cos(std::numbers::pi / 8.0),
        0.0};
    for (std::size_t frame = 0; frame < result.mono.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "ramp-frequency quad oscillator frame " + std::to_string(frame));
}

