void testCompileTimeStringCollectionSelectsSecondSampleResource()
{
    const auto registry = makeRegistry();
    talas::project::ProjectEditor editor{
        makeSampleDocument(), registry};
    const auto selectedText =
        std::string{"(#('Samples/First' 'Samples/Second') at: 2)"};
    require(editor.setParameter("sample",
                resourceParameter("sample", selectedText)).ok(),
        "Project Editor must author a bounded String collection selection");
    require(!editor.setParameter("sample",
                resourceParameter("sample", "#('Samples/First' 'Samples/Second') at: 3")).ok(),
        "out-of-range String selection must reject at authoring");
    require(!editor.setParameter("sample",
                resourceParameter("sample", "#(1 2) at: 2")).ok(),
        "numeric values must not be coerced into resource Strings");
    const auto saved = talas::project::serializeProjectDocument(
        editor.document());
    const auto reopened = talas::project::parseProjectDocument(saved);
    require(reopened.ok()
            && talas::project::serializeProjectDocument(
                   reopened.document) == saved,
        "String collection must retain its authored type and selector through persistence");
    const auto references = talas::audio::reachableProjectAssetReferences(
        reopened.document, registry);
    require(references.ok() && references.references.size() == 1
            && references.references[0].assetId == "Samples/Second",
        "asset loading must request only the selected second resource");

    talas::runtime::RenderSettings settings{4.0, 4};
    settings.tableResources = {
        {"Samples/First", {9.0, 9.0, 9.0}},
        {"Samples/Second", {1.0, 2.0, 3.0}},
    };
    const auto compiled = talas::runtime::compileProject(
        reopened.document, registry, settings);
    require(compiled.ok(),
        "the selected String resource must compile: "
            + (compiled.diagnostics.empty()
                    ? std::string{}
                    : compiled.diagnostics.front().message));
    const auto sampleStep = std::ranges::find(
        compiled.graph->plan().steps,
        std::string_view{"sample"},
        &talas::runtime::CompileStep::nodeId);
    require(sampleStep != compiled.graph->plan().steps.end(),
        "selected Sample step must exist");
    const auto sampleParameter = std::ranges::find(
        sampleStep->parameters,
        std::string_view{"sample"},
        &talas::runtime::ParameterValue::id);
    require(sampleParameter != sampleStep->parameters.end()
            && sampleParameter->resource
                == std::optional<std::string>{"Samples/Second"},
        "compiled Resource must retain the second String, not a scalar or first String");
    const auto rendered = talas::runtime::renderOffline(
        *compiled.graph, 4);
    require(rendered.ok() && rendered.mono.size() == 4,
        "selected Sample must render");
    for (std::size_t index = 0; index < 4; ++index)
    {
        requireNear(rendered.mono[index],
            index < 3 ? static_cast<double>(index + 1) : 0.0,
            1.0e-12,
            "the second String must select the intended sample data");
    }
}

