void testSampleRejectsNegativeConnectedAttackTime()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.tableResources.push_back({"Samples/Hit", {10.0, 20.0, 30.0, 40.0}});

    auto document = makeSampleDocument();
    document.graph.nodes.push_back(node("attackTime", "talas.constant", {{"value", "-0.25"}}));
    document.graph.connections.push_back(connection("attackTime", "value", "sample", "attackTime"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "negative connected-attack sample document should compile before render");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);

    require(!result.ok(), "sample should reject negative connected attackTime");
    require(result.mono.empty(), "failed connected-attack sample render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "sample", "attackTime", {}), "render should identify connected sample attackTime input");
}

