    settings.tableResources.push_back({"Samples/DiskFile", {10.0, 20.0, 30.0, 40.0, 50.0}});
    settings.tableResources.push_back({"Tables/RateScale", {1.0, 2.0, 1.0, 1.0}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("rate", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/RateScale")})));
    document.graph.nodes.push_back(node("disk", "talas.diskPlayer", diskPlayerParameters({{"filePosition", "0 s"}, {"duration", "1 s"}, {"rateScale", "1.0"}})));
    document.graph.connections.push_back(connection("rate", "value", "disk", "rateScale"));
    document.graph.connections.push_back(connection("disk", "audioOut", "out", "audioIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-rateScale disk player document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "connected-rateScale disk player render should not emit diagnostics");
    require(result.mono.size() == 5, "connected-rateScale disk player render should return requested frames");
    requireNear(result.mono[0], 10.0, 1.0e-12, "connected-rateScale disk player frame 0");
    requireNear(result.mono[1], 20.0, 1.0e-12, "connected-rateScale disk player frame 1 should use rateScale 2 for next cursor advance");
    requireNear(result.mono[2], 40.0, 1.0e-12, "connected-rateScale disk player frame 2 should skip over frame 30");
    requireNear(result.mono[3], 50.0, 1.0e-12, "connected-rateScale disk player frame 3 should continue at rateScale 1");
    requireNear(result.mono[4], 0.0, 1.0e-12, "connected-rateScale disk player frame 4 should stop after duration");
