void testDiskPlayerRejectsNonFiniteConnectedRateScale()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Samples/DiskFile", {10.0, 20.0, 30.0, 40.0}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("left", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("right", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("rate", "talas.add"));
    document.graph.nodes.push_back(node("disk", "talas.diskPlayer", diskPlayerParameters({{"filePosition", "0 s"}, {"duration", "1 s"}})));
    document.graph.connections.push_back(connection("left", "value", "rate", "left"));
    document.graph.connections.push_back(connection("right", "value", "rate", "right"));
    document.graph.connections.push_back(connection("rate", "value", "disk", "rateScale"));
    document.graph.connections.push_back(connection("disk", "audioOut", "out", "audioIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "non-finite connected-rateScale disk player document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(!result.ok(), "disk player should reject non-finite connected rateScale");
    require(result.mono.empty(), "failed disk player connected rateScale render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "disk", "rateScale"), "render should identify connected rateScale input");
}

