void testDiskPlayerSessionKeepsReadCursor()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.tableResources.push_back({"Samples/DiskFile", {10.0, 20.0, 30.0, 40.0, 50.0}});
    const auto parameters = diskPlayerParameters({{"duration", "1 s"}});
    const auto document = makeDiskPlayerDocument(parameters);
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "disk player document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(3);
    const auto oneShot = renderDiskPlayerDocument(parameters, {10.0, 20.0, 30.0, 40.0, 50.0}, 5);

    require(first.ok(), "first disk player session render should not emit diagnostics");
    require(second.ok(), "second disk player session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot disk player render should not emit diagnostics");
    require(first.mono.size() == 2, "first disk player session render should return requested frames");
    require(second.mono.size() == 3, "second disk player session render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "disk player session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "disk player session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "disk player session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "disk player session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "disk player session second frame 2");
}

talas::runtime::OfflineRenderResult renderInvalidDiskPlayerDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::TableResource> tableResources)
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources = std::move(tableResources);

    const auto document = makeDiskPlayerDocument(std::move(parameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "invalid disk player document should compile before render validation");
    return talas::runtime::renderOffline(*compile.graph, 5);
}

void requireDiskPlayerRenderFailure(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::vector<talas::runtime::TableResource> tableResources,
    std::string_view parameterId)
{
    const auto result = renderInvalidDiskPlayerDocument(std::move(parameters), std::move(tableResources));
    require(!result.ok(), "unsupported disk player configuration should fail render");
    require(result.mono.empty(), "failed disk player render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "disk", {}, parameterId), "render should identify disk player parameter");
}

void testDiskPlayerRejectsMissingOrInvalidResources()
{
    requireDiskPlayerRenderFailure(diskPlayerParameters(), {}, "fileName");
    requireDiskPlayerRenderFailure(diskPlayerParameters(), {{"Samples/DiskFile", {}}}, "fileName");
    requireDiskPlayerRenderFailure(
        diskPlayerParameters(),
        {{"Samples/DiskFile", {1.0, std::numeric_limits<double>::infinity()}}},
        "fileName");
    requireDiskPlayerRenderFailure(
        diskPlayerParameters({{"filePosition", "1 s"}}),
        {{"Samples/DiskFile", {10.0, 20.0, 30.0}}},
        "filePosition");
}

void testHandBuiltDiskPlayerRejectsInvalidDurationAtRender()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Samples/DiskFile", {10.0, 20.0, 30.0}});

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "disk",
            "talas.diskPlayer",
            {},
            {
                resourceRuntimeParameter("fileName", "Samples/DiskFile"),
                {"filePosition", talas::expr::ValueDomain::Seconds, 0.0},
                {"duration", talas::expr::ValueDomain::Seconds, 0.0},
                {"rateScale", talas::expr::ValueDomain::Scalar, 1.0},
                {"trigger", talas::expr::ValueDomain::Scalar, 1.0},
            },
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "disk", "audioOut", 0)},
            {},
        },
    };
    plan.buffers = {{"disk", "audioOut", talas::core::PortType::Audio, 5}};
    plan.outputBufferIndex = 0;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 5);

    require(!result.ok(), "stale invalid duration disk player render should fail");
    require(result.mono.empty(), "failed stale disk player render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "disk", {}, "duration"), "render should identify stale disk player duration parameter");
}

