void testDiskRecorderConnectedTriggerCapturesSelectedFrames()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/Trigger", {0.0, 1.0, 0.0, 1.0, 0.0}});

    auto document = makeDiskRecorderDocument(
        diskRecorderParameters({{"trigger", "0.0"}}),
        {{"frequency", "0.25 hz"}, {"amplitude", "1.0"}});
    document.graph.nodes.push_back(node("trigger", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Trigger")})));
    document.graph.connections.push_back(connection("trigger", "value", "recorder", "trigger"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-trigger disk recorder document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);
    const auto sinPiOver8 = std::sin(std::acos(-1.0) / 8.0);
    const auto sinPiOver4 = std::sin(std::acos(-1.0) / 4.0);
    const auto sin3PiOver8 = std::sin(3.0 * std::acos(-1.0) / 8.0);

    require(result.ok(), "connected-trigger disk recorder should not emit diagnostics");
    require(result.mono.size() == 5, "connected-trigger disk recorder should return requested frames");
    requireNear(result.mono[0], 0.0, 1.0e-12, "connected-trigger disk recorder frame 0");
    requireNear(result.mono[1], sinPiOver8, 1.0e-12, "connected-trigger disk recorder frame 1 should capture");
    requireNear(result.mono[2], sinPiOver4, 1.0e-12, "connected-trigger disk recorder frame 2 should continue capture after trigger closes");
    requireNear(result.mono[3], sin3PiOver8, 1.0e-12, "connected-trigger disk recorder frame 3 should capture");
    requireNear(result.mono[4], 1.0, 1.0e-12, "connected-trigger disk recorder frame 4 should continue capture after retrigger edge");
}

