void testHandBuiltDiskRecorderRejectsInvalidMetadataAtRender()
{
    auto result = renderHandBuiltDiskRecorderDocument({
        resourceRuntimeParameter("fileName", "Recordings/Capture"),
        textRuntimeParameter("format", "AIFF"),
        textRuntimeParameter("wordSize", "24"),
        choiceRuntimeParameter("channels", "mono"),
        {"trigger", talas::expr::ValueDomain::Scalar, std::numeric_limits<double>::infinity()},
        {"captureDuration", talas::expr::ValueDomain::Seconds, 0.0},
        booleanRuntimeParameter("gated", false),
    });

    require(!result.ok(), "non-finite trigger disk recorder render should fail");
    require(result.mono.empty(), "failed disk recorder render should not return audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed)
            && diagnosticDetails(result).find("Disk Recorder capture")
                != std::string::npos,
        "render should reject non-canonical Disk Recorder capture authority");

    result = renderHandBuiltDiskRecorderDocument({
        resourceRuntimeParameter("fileName", "Recordings/Capture"),
        textRuntimeParameter("format", "AIFF"),
        textRuntimeParameter("wordSize", "24"),
        choiceRuntimeParameter("channels", "mono"),
        {"trigger", talas::expr::ValueDomain::Scalar, 1.0},
        {"captureDuration", talas::expr::ValueDomain::Seconds, -1.0},
        booleanRuntimeParameter("gated", false),
    });

    require(!result.ok(), "negative captureDuration disk recorder render should fail");
    require(result.mono.empty(), "failed duration disk recorder render should not return audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed)
            && diagnosticDetails(result).find("Disk Recorder capture")
                != std::string::npos,
        "render should reject invalid Disk Recorder duration authority");
}

