void testSampleCloudRejectsNegativeConnectedDensity()
{
    const auto requireRejectedDensity = [](double value,
                                            double sampleRate,
                                            const std::string& context) {
        auto document = makeSampleCloudDocument(
            sampleCloudParameters({{"density", "1.0"}}));
        document.graph.nodes.push_back(node("density", "talas.triggeredTableRead",
            triggeredTableReadParameters({resourceParameter(
                "wavetable", "Tables/InvalidDensity")})));
        document.graph.connections.push_back(connection(
            "density", "value", "cloud", "density"));
        auto resources = sampleCloudTableResources();
        resources.push_back({"Tables/InvalidDensity", {value}});

        const auto result = renderSampleCloudDocument(
            std::move(document), 1, sampleRate, std::move(resources));

        require(!result.ok(), context + " should reject");
        require(result.mono.empty(),
            context + " should not return partial audio");
        require(hasDiagnostic(result,
                    DiagnosticCode::GraphValidationFailed,
                    "cloud"),
            context + " should publish a SampleCloud density diagnostic");
    };

    requireRejectedDensity(
        -1.0, 1.0, "negative connected SampleCloud density");
    requireRejectedDensity(
        std::numeric_limits<double>::denorm_min(), 4.0,
        "positive connected SampleCloud density whose increment underflows");
    requireRejectedDensity(
        0x1p63, 1.0,
        "connected SampleCloud density at the exclusive int64 crossing limit");
}

