void testSampleCloudSessionKeepsGrainScheduleAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    settings.tableResources = sampleCloudTableResources();
    const auto parameters = sampleCloudParameters({{"amplitude", "1.0"}, {"density", "2.0"}});
    const auto document = makeSampleCloudDocument(parameters);
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "sample cloud document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(4);
    const auto oneShot = renderSampleCloudDocument(parameters, 6);

    require(first.ok(), "first sample cloud session render should not emit diagnostics");
    require(second.ok(), "second sample cloud session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot sample cloud render should not emit diagnostics");
    require(first.mono.size() == 2, "first sample cloud session render should return requested frames");
    require(second.mono.size() == 4, "second sample cloud session render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "sample cloud session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "sample cloud session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "sample cloud session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "sample cloud session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "sample cloud session second frame 2");
    requireNear(second.mono[3], oneShot.mono[5], 1.0e-12, "sample cloud session second frame 3");
}

void testSampleCloudRejectsInexactAbsoluteFrameWithoutStatePublication()
{
    if constexpr (std::numeric_limits<std::size_t>::digits <= 53)
        return;

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = sampleCloudTableResources();
    const auto compiled = talas::runtime::compileProject(
        makeSampleCloudDocument(sampleCloudParameters()),
        makeRegistry(),
        settings);
    require(compiled.ok(),
        "C110 inexact absolute-frame fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    constexpr auto inexactFrame = (std::uint64_t{1} << 53) + 1;
    require(
        talas::runtime::OfflineRenderSessionTestAccess::setCloudRenderedFrames(
            session,
            "cloud",
            static_cast<std::size_t>(inexactFrame)),
        "C110 fixture should set the SampleCloud node cursor");
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::cloudState(
            session, "cloud");
    const auto rejected =
        talas::runtime::OfflineRenderSessionTestAccess::renderUnchecked(
            session, 1);
    const auto after =
        talas::runtime::OfflineRenderSessionTestAccess::cloudState(
            session, "cloud");

    require(!rejected.ok()
            && rejected.mono.empty()
            && rejected.right.empty()
            && rejected.channels.empty(),
        "C110 offline SampleCloud should reject an absolute frame that cannot be represented exactly as double");
    require(after == before,
        "C110 offline inexact absolute-frame rejection should publish no cursor, scheduler, or retention state");
}

