    document.graph.nodes.push_back(node("panJitter", "talas.constant", {{"value", "0.5"}}));
    document.graph.connections.push_back(connection("panJitter", "value", "cloud", "panJitter"));

    const auto connected = renderSampleCloudDocument(std::move(document), 4);
    const auto staticallyJittered = renderSampleCloudDocument(makeStereoSampleCloudDocument(sampleCloudParameters({{"panJitter", "0.5"}, {"seed", "0.25"}})), 4);
