talas::runtime::OfflineRenderResult renderGrainCloudDocument(
    std::vector<talas::project::ProjectParameterExpression> parameters,
    std::size_t frameCount,
    double sampleRate = 4.0,
    std::vector<talas::runtime::TableResource> resources = grainCloudTableResources())
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = sampleRate;
    settings.maxBlockFrames = frameCount;
    settings.tableResources = std::move(resources);

    const auto document = makeGrainCloudDocument(std::move(parameters));
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "grain cloud document should compile before render");
    return talas::runtime::renderOffline(*compile.graph, frameCount);
}

void testSharedGranularDensityArithmeticRejectionIsStateAtomic()
{
    const auto requireAtomicRejection = [](double density,
                                           double sampleRate,
                                           const std::string& context) {
        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = sampleRate;
        settings.maxBlockFrames = 1;
        settings.tableResources = grainCloudTableResources();
        auto compiled = talas::runtime::compileProject(
            makeGrainCloudDocument(
                grainCloudParameters({{"density", "1.0"}})),
            makeRegistry(), std::move(settings));
        require(compiled.ok(),
            context + " fixture should compile before derived arithmetic");

        auto& plan = const_cast<talas::runtime::RuntimePlan&>(
            compiled.graph->plan());
        const auto cloud = std::ranges::find(
            plan.steps,
            std::string_view{"cloud"},
            &talas::runtime::CompileStep::nodeId);
        require(cloud != plan.steps.end(),
            context + " fixture should expose the GrainCloud step");
        const auto densityParameter = std::ranges::find(
            cloud->parameters,
            std::string_view{"density"},
            &talas::runtime::ParameterValue::id);
        require(densityParameter != cloud->parameters.end(),
            context + " fixture should expose the density parameter");
        densityParameter->value = density;

        talas::runtime::OfflineRenderSession session{*compiled.graph};
        const auto sessionBefore =
            talas::runtime::OfflineRenderSessionTestAccess::state(session);
        const auto before =
            talas::runtime::OfflineRenderSessionTestAccess::cloudState(
                session, "cloud");
        const auto rejected = session.render(1);
        const auto sessionAfter =
            talas::runtime::OfflineRenderSessionTestAccess::state(session);
        const auto after =
            talas::runtime::OfflineRenderSessionTestAccess::cloudState(
                session, "cloud");
        require(!rejected.ok() && rejected.mono.empty(),
            context + " should reject without audio publication");
        require(sessionAfter == sessionBefore,
            context + " should not publish session or transaction state");
        require(after == before,
            context + " should not publish immediate-grain, index, phase, or retention state"
                + " (before phase=" + std::to_string(before.densityPhase)
                + ", index=" + std::to_string(before.nextGrainIndex)
                + ", retained=" + std::to_string(before.retainedGrainLimit)
                + ", starts=" + std::to_string(before.grainStartCount)
                + "; after phase=" + std::to_string(after.densityPhase)
                + ", index=" + std::to_string(after.nextGrainIndex)
                + ", retained=" + std::to_string(after.retainedGrainLimit)
                + ", starts=" + std::to_string(after.grainStartCount)
                + ")");
    };

    requireAtomicRejection(
        std::numeric_limits<double>::denorm_min(),
        4.0,
        "shared granular density increment underflow");
    requireAtomicRejection(
        0x1p63,
        1.0,
        "shared granular density crossing overflow");
}

void requireMirroredGrainCloudSamples(const talas::runtime::OfflineRenderResult& result, const std::vector<double>& expected)
{
    require(result.ok(), "grain cloud render should not emit diagnostics");
    require(result.mono.size() == expected.size(), "grain cloud left mirror should return requested frames");
    require(result.right.size() == expected.size(), "grain cloud right mirror should return requested frames");
    require(result.channels.size() == 2, "grain cloud should expose two rendered channels");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
    {
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "grain cloud left frame " + std::to_string(frame));
        requireNear(result.right[frame], expected[frame], 1.0e-12, "grain cloud right frame " + std::to_string(frame));
        requireNear(result.channels[0][frame], expected[frame], 1.0e-12, "grain cloud channel 1 frame " + std::to_string(frame));
        requireNear(result.channels[1][frame], expected[frame], 1.0e-12, "grain cloud channel 2 frame " + std::to_string(frame));
    }
}

void requireStereoGrainCloudSamples(const talas::runtime::OfflineRenderResult& result, const std::vector<double>& expectedLeft, const std::vector<double>& expectedRight)
{
    require(result.ok(), "stereo grain cloud render should not emit diagnostics");
    require(result.mono.size() == expectedLeft.size(), "stereo grain cloud left should return requested frames");
    require(result.right.size() == expectedRight.size(), "stereo grain cloud right should return requested frames");
    require(result.channels.size() == 2, "stereo grain cloud should expose two rendered channels");
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(result.mono[frame], expectedLeft[frame], 1.0e-12, "stereo grain cloud left frame " + std::to_string(frame));
        requireNear(result.right[frame], expectedRight[frame], 1.0e-12, "stereo grain cloud right frame " + std::to_string(frame));
        requireNear(result.channels[0][frame], expectedLeft[frame], 1.0e-12, "stereo grain cloud channel 1 frame " + std::to_string(frame));
        requireNear(result.channels[1][frame], expectedRight[frame], 1.0e-12, "stereo grain cloud channel 2 frame " + std::to_string(frame));
    }
}

bool vectorsNearlyEqual(const std::vector<double>& lhs, const std::vector<double>& rhs, double tolerance)
{
    if (lhs.size() != rhs.size())
        return false;
    for (std::size_t index = 0; index < lhs.size(); ++index)
    {
        if (std::abs(lhs[index] - rhs[index]) > tolerance)
            return false;
    }
    return true;
}

bool renderOutputsNearlyEqual(const talas::runtime::OfflineRenderResult& lhs, const talas::runtime::OfflineRenderResult& rhs, double tolerance)
{
    return vectorsNearlyEqual(lhs.mono, rhs.mono, tolerance)
        && vectorsNearlyEqual(lhs.right, rhs.right, tolerance);
}

bool renderOutputsDiffer(const talas::runtime::OfflineRenderResult& lhs, const talas::runtime::OfflineRenderResult& rhs, double tolerance)
{
    return !renderOutputsNearlyEqual(lhs, rhs, tolerance);
}

