    const auto dynamic = renderSampleCloudDocument(std::move(document), 4, 4.0, std::move(dynamicResources));
    const auto baseline = renderSampleCloudDocument(sampleCloudParameters({{"amplitude", "1.0"}, {"grainDurJitter", "0.0"}, {"seed", "0.25"}}), 4, 4.0, comparisonResources);
    const auto staticallyJittered = renderSampleCloudDocument(sampleCloudParameters({{"amplitude", "1.0"}, {"grainDurJitter", "0.5"}, {"seed", "0.25"}}), 4, 4.0, comparisonResources);

    require(dynamic.ok(), "dynamic-grainDurJitter sample cloud render should not emit diagnostics");
    require(baseline.ok(), "baseline sample cloud grainDurJitter comparison should render");
    require(staticallyJittered.ok(), "static sample cloud grainDurJitter comparison should render");
    require(dynamic.mono.size() == 4, "dynamic-grainDurJitter sample cloud should return requested frames");
    for (std::size_t frame = 0; frame < 2; ++frame)
        requireNear(dynamic.mono[frame], baseline.mono[frame], 1.0e-12, "dynamic-grainDurJitter baseline frame " + std::to_string(frame));
