void requireIdleGrainCloudConnectedControlFailure(std::string portId, std::string value)
{
    auto document = makeGrainCloudDocument(grainCloudParameters({{"amplitude", "1.0"}, {"density", "0.0"}}));
    connectConstantControl(document, portId, std::move(value), "cloud", portId);

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 4;
    settings.tableResources = grainCloudTableResources();

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "idle grain cloud connected " + portId + " document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 4);

    require(!result.ok(), "idle grain cloud should reject invalid connected " + portId);
    require(result.mono.empty(), "failed idle grain cloud connected " + portId + " render should not return left audio");
    require(result.right.empty(), "failed idle grain cloud connected " + portId + " render should not return right audio");
    require(result.channels.empty(), "failed idle grain cloud connected " + portId + " render should not return channel audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "cloud", portId, {}), "render should identify idle grain cloud " + portId + " input");
}

