void testGrainCloudIdlePathStillChecksDurationArithmeticAndExactCursor()
{
    auto document = makeGrainCloudDocument(grainCloudParameters({
        {"amplitude", "0"}, {"density", "0"},
        {"grainDur", "1 s"}, {"cyclesPerGrain", "0"},
    }));
    connectConstantControl(document, "grainDur", "1e308", "cloud", "grainDur");

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 2.0;
    settings.maxBlockFrames = 1;
    settings.tableResources = grainCloudTableResources();
    const auto compiled = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compiled.ok(), "C113 idle checked-duration fixture should compile");

    talas::runtime::OfflineRenderSession durationSession{*compiled.graph};
    const auto durationBefore =
        talas::runtime::OfflineRenderSessionTestAccess::cloudState(durationSession, "cloud");
    const auto durationRejected = durationSession.render(1);
    require(!durationRejected.ok()
            && talas::runtime::OfflineRenderSessionTestAccess::cloudState(
                    durationSession, "cloud") == durationBefore,
        "C113 idle GrainCloud should reject duration-frame overflow without state publication");

    const auto cycleCompiled = talas::runtime::compileProject(
        makeGrainCloudDocument(grainCloudParameters({
            {"amplitude", "0"}, {"density", "0"},
            {"grainDur", "0 s"}, {"cyclesPerGrain", "1e308"},
            {"frequency", "1 hz"},
        })),
        makeRegistry(), settings);
    require(cycleCompiled.ok(),
        "C113 idle cycle-derived duration fixture should compile");
    talas::runtime::OfflineRenderSession cycleSession{*cycleCompiled.graph};
    const auto cycleBefore =
        talas::runtime::OfflineRenderSessionTestAccess::cloudState(
            cycleSession, "cloud");
    const auto cycleRejected = cycleSession.render(1);
    require(!cycleRejected.ok()
            && talas::runtime::OfflineRenderSessionTestAccess::cloudState(
                    cycleSession, "cloud") == cycleBefore,
        "C113 idle GrainCloud should reject cycle-derived duration overflow without state publication");

    const auto exactGraph = talas::runtime::compileProject(
        makeGrainCloudDocument(grainCloudParameters({
            {"amplitude", "0"}, {"density", "0"},
        })),
        makeRegistry(), settings);
    require(exactGraph.ok(), "C113 idle exact-cursor fixture should compile");
    talas::runtime::OfflineRenderSession exactSession{*exactGraph.graph};
    constexpr auto inexactFrame = (std::size_t{1} << 53) + 1;
    require(talas::runtime::OfflineRenderSessionTestAccess::setCloudRenderedFrames(
                exactSession, "cloud", inexactFrame),
        "C113 idle exact-cursor fixture should set GrainCloud state");
    const auto exactBefore =
        talas::runtime::OfflineRenderSessionTestAccess::cloudState(exactSession, "cloud");
    const auto exactRejected =
        talas::runtime::OfflineRenderSessionTestAccess::renderUnchecked(
            exactSession, 1);
    require(!exactRejected.ok(),
        "C113 idle GrainCloud should reject an inexact absolute cursor");
    require(talas::runtime::OfflineRenderSessionTestAccess::cloudState(
                exactSession, "cloud") == exactBefore,
        "C113 idle GrainCloud should reject an inexact absolute cursor without state publication");
}

