void testGrainCloudFreqJitterIsSeededAndAffectsFrequency()
{
    const std::vector<talas::runtime::TableResource> resources = {
        {"Tables/GrainWave", {0.0, 1.0, 0.0}},
        {"Tables/GrainEnv", {1.0}},
    };
    const auto baseline = renderGrainCloudDocument(grainCloudParameters(), 4, 4.0, resources);
    const auto jitteredA = renderGrainCloudDocument(grainCloudParameters({{"freqJitter", "1.0"}, {"seed", "0.25"}}), 4, 4.0, resources);
    const auto jitteredB = renderGrainCloudDocument(grainCloudParameters({{"freqJitter", "1.0"}, {"seed", "0.25"}}), 4, 4.0, resources);
    const auto differentSeed = renderGrainCloudDocument(grainCloudParameters({{"freqJitter", "1.0"}, {"seed", "0.75"}}), 4, 4.0, resources);

    require(baseline.ok(), "baseline grain cloud freq jitter comparison should render");
    require(jitteredA.ok(), "freq jitter grain cloud should render");
    require(jitteredB.ok(), "second same-seed freq jitter grain cloud should render");
    require(differentSeed.ok(), "different-seed freq jitter grain cloud should render");
    require(renderOutputsNearlyEqual(jitteredA, jitteredB, 1.0e-12), "same seed should reproduce freq jitter output");
    require(renderOutputsDiffer(jitteredA, baseline, 1.0e-9), "freq jitter should change output");
    require(renderOutputsDiffer(jitteredA, differentSeed, 1.0e-9), "different seed should change freq jitter output");
}

