void testGrainCloudDurationJitterIsSeededAndAffectsEnvelopeTiming()
{
    const std::vector<talas::runtime::TableResource> resources = {
        {"Tables/GrainWave", {1.0}},
        {"Tables/GrainEnv", {0.0, 1.0}},
    };
    const auto baseline = renderGrainCloudDocument(grainCloudParameters(), 4, 4.0, resources);
    const auto jitteredA = renderGrainCloudDocument(grainCloudParameters({{"grainDurJitter", "0.5"}, {"seed", "0.25"}}), 4, 4.0, resources);
    const auto jitteredB = renderGrainCloudDocument(grainCloudParameters({{"grainDurJitter", "0.5"}, {"seed", "0.25"}}), 4, 4.0, resources);

    require(baseline.ok(), "baseline grain duration jitter comparison should render");
    require(jitteredA.ok(), "grain duration jitter cloud should render");
    require(jitteredB.ok(), "second same-seed duration jitter cloud should render");
    require(renderOutputsNearlyEqual(jitteredA, jitteredB, 1.0e-12), "same seed should reproduce duration jitter output");
    require(renderOutputsDiffer(jitteredA, baseline, 1.0e-9), "grainDurJitter should change envelope timing");
}

