void testGrainCloudSessionKeepsScheduleAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    settings.tableResources = grainCloudTableResources();
    const auto parameters = grainCloudParameters({{"amplitude", "1.0"}, {"density", "2.0"}});
    const auto document = makeGrainCloudDocument(parameters);
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "grain cloud document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(4);
    const auto oneShot = renderGrainCloudDocument(parameters, 6);

    require(first.ok(), "first grain cloud session render should not emit diagnostics");
    require(second.ok(), "second grain cloud session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot grain cloud render should not emit diagnostics");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "grain cloud session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "grain cloud session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "grain cloud session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "grain cloud session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "grain cloud session second frame 2");
    requireNear(second.mono[3], oneShot.mono[5], 1.0e-12, "grain cloud session second frame 3");
}

