std::vector<talas::runtime::TableResource> cloudBankTableResources()
{
    return {
        {"Tables/CloudWave", {1.0}},
        {"Tables/CloudEnv", {1.0}},
    };
}

talas::runtime::OfflineRenderResult renderCloudBankDocument(
    talas::project::ProjectDocument document,
    std::size_t frameCount,
    std::vector<talas::runtime::TableResource> resources = cloudBankTableResources())
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = frameCount;
    settings.tableResources = std::move(resources);

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "cloud bank document should compile before render");
    return talas::runtime::renderOffline(*compile.graph, frameCount);
}

void requireMirroredCloudBankSamples(const talas::runtime::OfflineRenderResult& result, const std::vector<double>& expected)
{
    require(result.ok(), "cloud bank render should not emit diagnostics");
    require(result.mono.size() == expected.size(), "cloud bank left mirror should return requested frames");
    require(result.right.size() == expected.size(), "cloud bank right mirror should return requested frames");
    require(result.channels.size() == 2, "cloud bank should expose two rendered channels");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
    {
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "cloud bank left frame " + std::to_string(frame));
        requireNear(result.right[frame], expected[frame], 1.0e-12, "cloud bank right frame " + std::to_string(frame));
        requireNear(result.channels[0][frame], expected[frame], 1.0e-12, "cloud bank channel 1 frame " + std::to_string(frame));
        requireNear(result.channels[1][frame], expected[frame], 1.0e-12, "cloud bank channel 2 frame " + std::to_string(frame));
    }
}

void requireStereoCloudBankSamples(const talas::runtime::OfflineRenderResult& result, const std::vector<double>& expectedLeft, const std::vector<double>& expectedRight)
{
    require(result.ok(), "stereo cloud bank render should not emit diagnostics");
    require(result.mono.size() == expectedLeft.size(), "stereo cloud bank left should return requested frames");
    require(result.right.size() == expectedRight.size(), "stereo cloud bank right should return requested frames");
    require(result.channels.size() == 2, "stereo cloud bank should expose two rendered channels");
    for (std::size_t frame = 0; frame < expectedLeft.size(); ++frame)
    {
        requireNear(result.mono[frame], expectedLeft[frame], 1.0e-12, "stereo cloud bank left frame " + std::to_string(frame));
        requireNear(result.right[frame], expectedRight[frame], 1.0e-12, "stereo cloud bank right frame " + std::to_string(frame));
        requireNear(result.channels[0][frame], expectedLeft[frame], 1.0e-12, "stereo cloud bank channel 1 frame " + std::to_string(frame));
        requireNear(result.channels[1][frame], expectedRight[frame], 1.0e-12, "stereo cloud bank channel 2 frame " + std::to_string(frame));
    }
}

