void testCloudBankOfflineRetainsCountsAbovePreparedLimit()
{
    constexpr std::size_t trackCount = 65;
    std::string amplitudes;
    std::string frequencies;
    std::string bandwidths;
    for (std::size_t track = 0; track < trackCount; ++track)
    {
        if (track != 0)
        {
            amplitudes += ' ';
            frequencies += ' ';
            bandwidths += ' ';
        }
        amplitudes += "1";
        frequencies += "1";
        bandwidths += "0";
    }
    const auto result = renderCloudBankDocument(
        makeCloudBankDocument(
            cloudBankParameters({
                {"nbrTracks", "65"},
                {"grainsPerTrack", "1"},
                {"bankSize", "65"},
            }),
            cloudBankSpectrumParameters({
                {"nbrPartials", "65"},
                textParameter("amplitudes", amplitudes),
                textParameter("frequencies", frequencies),
                textParameter("bandwidths", bandwidths),
            })),
        1);

    requireMirroredCloudBankSamples(result, {65.0});
}

void testCloudBankOfflineDownstreamFailureRollsBackCompleteTransaction()
{
    auto document = makeCloudBankDocument();
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C111Downstream"},
            {"right", "!C111Downstream"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "cloud" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "cloud", "leftOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "rightOut", "out", "rightIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.tableResources = {
        {"Tables/CloudWave", {1.0}},
        {"Tables/CloudEnv", {1.0}},
    };
    settings.eventValues = {
        {"C111Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3,
            "C111Downstream",
            std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C111 offline CloudBank rollback fixture should compile");

    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    talas::runtime::OfflineRenderSession pristine{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(candidate);
    const auto rejected = candidate.render(5);
    const auto after =
        talas::runtime::OfflineRenderSessionTestAccess::state(candidate);
    require(!rejected.ok() && rejected.mono.empty()
            && rejected.right.empty() && rejected.channels.empty()
            && after == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(candidate, "cloud") == 0,
        "C111 late offline downstream failure should publish no CloudBank audio, cursor, Event Value, scheduler, or transaction state");

    const auto retry = candidate.render(2);
    const auto expected = pristine.render(2);
    require(retry.ok() && expected.ok()
            && retry.mono == expected.mono
            && retry.right == expected.right
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(candidate, "cloud") == 2,
        "C111 repaired offline retry should match an equally progressed pristine CloudBank session");
}

void testCloudBankOfflineZeroFramePreservesCompleteSessionState()
{
    auto document = makeCloudBankDocument();
    document.graph.nodes.push_back(node(
        "forced", "talas.forcedProcessorAssignment", {{"processor", "7"}}));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "cloud" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "cloud", "leftOut", "forced", "audioIn"));
    document.graph.connections.push_back(connection(
        "forced", "audioOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "cloud", "rightOut", "out", "rightIn"));
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.tableResources = cloudBankTableResources();
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C111 offline CloudBank zero-frame fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeCursor =
        talas::runtime::OfflineRenderSessionTestAccess::
            cloudBankRenderedFrames(session, "cloud");
    const auto empty = session.render(0);
    const auto after =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    require(empty.ok() && empty.mono.empty() && empty.right.empty()
            && after == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(session, "cloud")
                == beforeCursor,
        "C111 zero-frame offline CloudBank render should preserve cursor, scheduler, transaction history, and transport state exactly");
}

