void testCloudBankElementOfflineFailureRollsBackCompleteTransaction()
{
    for (const auto downstream : {false, true})
    {
        auto document = makeCloudBankElementDocument(
            cloudBankElementParameters(),
            downstream
                ? cloudBankSpectrumParameters()
                : cloudBankSpectrumParameters({
                    textParameter("frequencies", "2 2")}),
            {{"value", "1"}},
            {{"value", "0.5"}},
            downstream
                ? std::vector<talas::project::ProjectParameterExpression>{
                    {"value", "0"}}
                : std::vector<talas::project::ProjectParameterExpression>{
                    {"value", "!C112FrequencyMod"}},
            {{"value", "0"}});
        if (downstream)
        {
            document.graph.nodes.push_back(node(
                "downstream", "talas.level", {
                    {"left", "!C112Downstream"},
                    {"right", "!C112Downstream"},
                    booleanParameter("noGain", false),
                }));
            std::erase_if(document.graph.connections, [](const auto& edge) {
                return edge.fromNode == "cloud" && edge.toNode == "out";
            });
            document.graph.connections.push_back(connection(
                "cloud", "leftOut", "downstream", "audioIn"));
            document.graph.connections.push_back(connection(
                "downstream", "leftOut", "out", "audioIn"));
            document.graph.connections.push_back(connection(
                "downstream", "rightOut", "out", "rightIn"));
        }

        auto settings = talas::runtime::RenderSettings{4.0, 5};
        settings.tableResources = cloudBankTableResources();
        settings.eventValues = downstream
            ? std::vector<talas::runtime::EventValueBinding>{
                {"C112Downstream", 1.0, talas::expr::ValueDomain::Scalar}}
            : std::vector<talas::runtime::EventValueBinding>{
                {"C112FrequencyMod", 0.0, talas::expr::ValueDomain::Scalar}};
        settings.eventValueChanges = downstream
            ? std::vector<talas::runtime::EventValueChange>{
                {3,
                    "C112Downstream",
                    std::numeric_limits<double>::max(),
                    talas::expr::ValueDomain::Scalar}}
            : std::vector<talas::runtime::EventValueChange>{
                {3,
                    "C112FrequencyMod",
                    std::numeric_limits<double>::max(),
                    talas::expr::ValueDomain::Scalar}};
        const auto compiled = talas::runtime::compileProject(
            document, makeRegistry(), settings);
        require(compiled.ok(),
            "C112 offline CloudBankElement rollback fixture should compile");

        talas::runtime::OfflineRenderSession candidate{*compiled.graph};
        talas::runtime::OfflineRenderSession pristine{*compiled.graph};
        const auto before =
            talas::runtime::OfflineRenderSessionTestAccess::state(candidate);
        const auto rejected = candidate.render(5);
        const auto after =
            talas::runtime::OfflineRenderSessionTestAccess::state(candidate);
        require(!rejected.ok() && rejected.mono.empty()
                && rejected.right.empty() && rejected.channels.empty(),
            downstream
                ? "C112 late downstream failure should publish no offline Element audio"
                : "C112 own failure should publish no offline Element audio");
        require(after == before,
            downstream
                ? "C112 late downstream failure should restore offline Element session, Event Value, scheduler, and transaction state"
                : "C112 own failure should restore offline Element session, Event Value, scheduler, and transaction state");
        require(talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(candidate, "cloud") == 0,
            downstream
                ? "C112 late downstream failure should restore the offline Element cursor"
                : "C112 own failure should restore the offline Element cursor");

        const auto retry = candidate.render(2);
        const auto expected = pristine.render(2);
        require(retry.ok() && expected.ok()
                && retry.mono == expected.mono
                && retry.right == expected.right
                && talas::runtime::OfflineRenderSessionTestAccess::
                        cloudBankRenderedFrames(candidate, "cloud") == 2,
            "C112 repaired offline Element retry should match an equally progressed pristine session");
    }
}

void testCloudBankElementOfflineZeroFramePreservesCompleteSessionState()
{
    auto document = makeCloudBankElementDocument();
    document.graph.nodes.push_back(node(
        "forced", "talas.forcedProcessorAssignment", {{"processor", "7"}}));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "cloud" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "cloud", "leftOut", "forced", "audioIn"));
    document.graph.connections.push_back(connection(
        "forced", "audioOut", "out", "audioIn"));
    document.graph.connections.push_back(connection(
        "cloud", "rightOut", "out", "rightIn"));
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.tableResources = cloudBankTableResources();
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C112 offline CloudBankElement zero-frame fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeCursor =
        talas::runtime::OfflineRenderSessionTestAccess::
            cloudBankRenderedFrames(session, "cloud");
    const auto empty = session.render(0);
    const auto after =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    require(empty.ok() && empty.mono.empty() && empty.right.empty()
            && after == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(session, "cloud")
                == beforeCursor,
        "C112 zero-frame offline Element render should preserve cascade, cursor, scheduler, transaction history, and transport state exactly");
}

void testCloudBankElementOfflineZeroFrameSkipsRuntimeInvalidSelectedRange()
{
    auto settings = talas::runtime::RenderSettings{4.0, 4};
    settings.tableResources = cloudBankTableResources();
    const auto compiled = talas::runtime::compileProject(
        makeCloudBankElementDocument(
            cloudBankElementParameters({{"first", "2"}, {"count", "2"}})),
        makeRegistry(),
        settings);
    require(compiled.ok(),
        "C112 runtime-invalid selected-range zero-frame fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    const auto beforeCursor =
        talas::runtime::OfflineRenderSessionTestAccess::
            cloudBankRenderedFrames(session, "cloud");
    const auto empty = session.render(0);
    const auto after =
        talas::runtime::OfflineRenderSessionTestAccess::state(session);
    require(empty.ok() && empty.mono.empty() && empty.right.empty()
            && empty.channels.size() == 2
            && empty.channels[0].empty() && empty.channels[1].empty()
            && after == before
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(session, "cloud")
                == beforeCursor,
        "C112 zero-frame offline Element render should validate only the prepared output contract and skip runtime range execution");

    const auto rejected = session.render(1);
    require(!rejected.ok() && rejected.mono.empty()
            && rejected.right.empty() && rejected.channels.empty(),
        "C112 zero-frame range fixture should remain runtime-invalid for a non-empty render");
}

void testCloudBankElementOfflineRejectsInexactHighFrameWithoutStatePublication()
{
    auto settings = talas::runtime::RenderSettings{4.0, 1};
    settings.tableResources = cloudBankTableResources();
    const auto compiled = talas::runtime::compileProject(
        makeCloudBankElementDocument(), makeRegistry(), settings);
    require(compiled.ok(),
        "C112 offline Element high-frame fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};
    constexpr auto inexactFrame = (std::uint64_t{1} << 53) + 1;
    require(talas::runtime::OfflineRenderSessionTestAccess::
                setCloudBankRenderedFrames(session, "cloud", inexactFrame),
        "C112 offline fixture should set the exact Element cursor");
    const auto before =
        talas::runtime::OfflineRenderSessionTestAccess::
            cloudBankRenderedFrames(session, "cloud");
    const auto rejected =
        talas::runtime::OfflineRenderSessionTestAccess::renderUnchecked(
            session, 1);
    require(!rejected.ok() && rejected.mono.empty()
            && rejected.right.empty() && rejected.channels.empty()
            && talas::runtime::OfflineRenderSessionTestAccess::
                    cloudBankRenderedFrames(session, "cloud") == before,
        "C112 offline Element should reject an inexact absolute frame without publishing output or state");
}

void requireCloudBankRenderFailure(
    talas::project::ProjectDocument document,
    std::string_view nodeId,
    std::string_view parameterId,
    std::vector<talas::runtime::TableResource> resources = cloudBankTableResources())
{
    const auto result = renderCloudBankDocument(std::move(document), 4, std::move(resources));

    require(!result.ok(), "invalid cloud bank configuration should fail render");
    require(result.mono.empty(), "failed cloud bank render should not return left audio");
    require(result.right.empty(), "failed cloud bank render should not return right audio");
    require(result.channels.empty(), "failed cloud bank render should not return channel audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, nodeId, {}, parameterId), "render should identify cloud bank parameter");
}

