    require(compile.ok(), "multifile disk player document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(4);
    const auto oneShot = renderMultifileDiskPlayerDocument(parameters, {1.0, 2.0, 3.0}, {10.0, 20.0, 30.0, 40.0, 50.0}, 6);

    require(first.ok(), "first multifile disk player session render should not emit diagnostics");
