void testSamplesFromDiskSingleStepConnectedControlsReadAndReset()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 6;
    settings.tableResources.push_back({"Samples/DiskStep", {10.0, 20.0, 30.0, 40.0}});
    settings.tableResources.push_back({"Tables/Trigger", {1.0, 1.0, 0.0, 1.0, 1.0, 1.0}});
    settings.tableResources.push_back({"Tables/Gate", {1.0, 1.0, 1.0, 0.0, 1.0, 1.0}});

    auto document = makeSamplesFromDiskSingleStepDocument(samplesFromDiskSingleStepParameters({{"trigger", "0.0"}, {"gate", "0.0"}}));
    document.graph.nodes.push_back(node("trigger", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Trigger")})));
    document.graph.nodes.push_back(node("gate", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Gate")})));
    document.graph.connections.push_back(connection("trigger", "value", "disk", "trigger"));
    document.graph.connections.push_back(connection("gate", "value", "disk", "gate"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "connected-control samples from disk document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 6);

    require(result.ok(), "connected-control samples from disk render should not emit diagnostics");
    require(result.mono.size() == 6, "connected-control samples from disk render should return requested frames");
    requireNear(result.mono[0], 20.0, 1.0e-12, "connected-control samples from disk frame 0");
    requireNear(result.mono[1], 30.0, 1.0e-12, "connected-control samples from disk frame 1");
    requireNear(result.mono[2], 30.0, 1.0e-12, "connected-control samples from disk frame 2 should hold the last sample on closed trigger");
    requireNear(result.mono[3], 40.0, 1.0e-12, "connected-control samples from disk frame 3 should continue while gate is closed");
    requireNear(result.mono[4], 20.0, 1.0e-12, "connected-control samples from disk frame 4 should restart on gate positive edge");
    requireNear(result.mono[5], 30.0, 1.0e-12, "connected-control samples from disk frame 5 should continue after reset");
}

