void testSamplesFromDiskSingleStepSessionKeepsReadCursor()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    settings.tableResources.push_back({"Samples/DiskStep", {10.0, 20.0, 30.0, 40.0, 50.0}});
    const auto parameters = samplesFromDiskSingleStepParameters();
    const auto document = makeSamplesFromDiskSingleStepDocument(parameters);
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "samples from disk document should compile before session render");

    talas::runtime::OfflineRenderSession session{*compile.graph};
    const auto first = session.render(2);
    const auto second = session.render(3);
    const auto oneShot = renderSamplesFromDiskSingleStepDocument(parameters, {10.0, 20.0, 30.0, 40.0, 50.0}, 5);

    require(first.ok(), "first samples from disk session render should not emit diagnostics");
    require(second.ok(), "second samples from disk session render should not emit diagnostics");
    require(oneShot.ok(), "one-shot samples from disk render should not emit diagnostics");
    require(first.mono.size() == 2, "first samples from disk session render should return requested frames");
    require(second.mono.size() == 3, "second samples from disk session render should return requested frames");
    requireNear(first.mono[0], oneShot.mono[0], 1.0e-12, "samples from disk session first frame 0");
    requireNear(first.mono[1], oneShot.mono[1], 1.0e-12, "samples from disk session first frame 1");
    requireNear(second.mono[0], oneShot.mono[2], 1.0e-12, "samples from disk session second frame 0");
    requireNear(second.mono[1], oneShot.mono[3], 1.0e-12, "samples from disk session second frame 1");
    requireNear(second.mono[2], oneShot.mono[4], 1.0e-12, "samples from disk session second frame 2");
}

