    document.graph.nodes.push_back(node("right", "talas.constant", {{"value", "1e308"}}));
    document.graph.nodes.push_back(node("scale", "talas.add"));
    document.graph.connections.push_back(connection("left", "value", "scale", "left"));
    document.graph.connections.push_back(connection("right", "value", "scale", "right"));
    document.graph.connections.push_back(connection("scale", "value", "multi", "scale"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "non-finite connected-scale multisample document should compile");
