    require(compile.ok(), "connected-gate looped key mapped multisample document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 6);

    require(result.ok(), "connected-gate looped key mapped multisample render should not emit diagnostics");
    require(result.mono.size() == 6, "connected-gate looped key mapped multisample render should return requested frames");
    requireNear(result.mono[0], 1.0, 1.0e-12, "connected-gate looped key mapped multisample frame 0");
    requireNear(result.mono[1], -0.5, 1.0e-12, "connected-gate looped key mapped multisample frame 1");
    requireNear(result.mono[2], 0.25, 1.0e-12, "connected-gate looped key mapped multisample frame 2");
    requireNear(result.mono[3], 0.5, 1.0e-12, "connected-gate looped key mapped multisample frame 3 should leave loop mode after gate closes");
    requireNear(result.mono[4], 0.0, 1.0e-12, "connected-gate looped key mapped multisample frame 4 should stop after release reaches the end");
