void testAveragingLowPassFilterWindowSizeConversionIsBounded()
{
    using talas::runtime::checked_averaging_low_pass_filter::Error;
    using talas::runtime::checked_averaging_low_pass_filter::Window;
    const auto exclusiveLimit = std::ldexp(
        1.0, std::numeric_limits<std::size_t>::digits);
    const auto immediatelyBelow = std::nextafter(exclusiveLimit, 0.0);
    const auto immediatelyAbove = std::nextafter(
        exclusiveLimit, std::numeric_limits<double>::infinity());

    auto window = Window{};
    require(
        talas::runtime::checked_averaging_low_pass_filter::deriveWindow(
            exclusiveLimit, 1.0, 0, window)
            == Error::WindowNonFiniteOrUnrepresentable,
        "averaging low pass should reject the exclusive size_t window boundary before conversion");
    require(
        talas::runtime::checked_averaging_low_pass_filter::deriveWindow(
            immediatelyAbove, 1.0, 0, window)
            == Error::WindowNonFiniteOrUnrepresentable,
        "averaging low pass should reject the first window above the size_t conversion boundary");

    const auto belowWholeValue = std::floor(immediatelyBelow);
    const auto belowWhole = static_cast<std::size_t>(belowWholeValue);
    const auto belowFraction = immediatelyBelow - belowWholeValue;
    const auto belowRequiredWouldOverflow =
        belowFraction
                > talas::runtime::checked_averaging_low_pass_filter::
                    fractionalSampleThreshold
        && belowWhole == std::numeric_limits<std::size_t>::max();
    const auto belowStatus =
        talas::runtime::checked_averaging_low_pass_filter::deriveWindow(
            immediatelyBelow, 1.0, 0, window);
    require(
        belowStatus
            == (belowRequiredWouldOverflow
                ? Error::WindowNonFiniteOrUnrepresentable
                : Error::None),
        "averaging low pass should classify the first representable window below the conversion boundary without undefined conversion");
    if (!belowRequiredWouldOverflow)
    {
        require(
            window.wholeSamples == belowWhole,
            "averaging low pass should preserve the adjacent in-range whole window exactly");
    }
}

