void testAveragingLowPassFilterConnectedCutoffUpdatesWindowPerFrame()
{
    auto document =
        makeAveragingLowPassFilterDocument({{"cutoff", "1 hz"}, resourceParameter("wavetable", "Private"), {"scale", "1.0"}});
    document.graph.nodes.push_back(node("cutoff", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Cutoff")})));
    document.graph.connections.push_back(connection("cutoff", "value", "avg", "cutoff"));

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.tableResources.push_back({"Tables/Cutoff", {1.0, 1.0, 2.0, 2.0, 2.0}});

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-cutoff averaging low pass document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-cutoff averaging low pass render should not emit diagnostics");
    const std::vector<double> expected = {0.0, 0.25, 0.5, -0.5, -0.5};
    require(result.mono.size() == expected.size(), "dynamic-cutoff averaging low pass should return requested frames");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic-cutoff averaging low pass frame " + std::to_string(frame));
}

