void testScaleAndOffsetConnectedControlsUpdatePerFrame()
{
    auto document = makeVcaDocument(
        {
            node("source", "talas.constant", {{"value", "1"}}),
            node("scaleControl", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Scale")})),
            node("offsetControl", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Offset")})),
            node("scale", "talas.scaleAndOffset", {{"scale", "0.25"}, {"offset", "0.25"}}),
        },
        {
            connection("source", "value", "scale", "value"),
            connection("scaleControl", "value", "scale", "scale"),
            connection("offsetControl", "value", "scale", "offset"),
            connection("scale", "value", "vca", "gain"),
        },
        {},
        {{"frequency", "0.25 hz"}, {"amplitude", "1.0"}});

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 6;
    settings.tableResources = {
        {"Tables/Scale", {1.0, 1.5, 0.5, 2.0, 1.25, 0.75}},
        {"Tables/Offset", {0.0, -0.5, 0.25, -1.0, 0.5, 0.125}},
    };

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic scale and offset document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 6);
    const auto pi = std::acos(-1.0);
    const std::vector<double> expected = {
        0.0,
        std::sin(pi / 8.0),
        std::sin(pi / 4.0) * 0.75,
        std::sin(3.0 * pi / 8.0),
        1.75,
        std::sin(3.0 * pi / 8.0) * 0.875,
    };

    require(result.ok(), "dynamic scale and offset render should not emit diagnostics");
    require(result.mono.size() == expected.size(), "dynamic scale and offset render should return requested frames");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic scale and offset frame " + std::to_string(frame));
}

