void testScaleAndOffsetPreservesFiniteFmaRounding()
{
    constexpr auto input = -1.000000007450580596923828125;
    constexpr auto scale = -0.999999992549419403076171875;
    constexpr auto offset = -1.0;
    const auto expected = std::fma(input, scale, offset);
    require(
        std::bit_cast<std::uint64_t>(expected)
            == std::uint64_t{0xbc90000000000000},
        "C83 FMA oracle should retain negative 2^-54");

    auto document = makeVcaDocument(
        {
            node(
                "source",
                "talas.constant",
                {{"value", "-1.000000007450580596923828125"}}),
            node(
                "scale",
                "talas.scaleAndOffset",
                {
                    {"scale", "-0.999999992549419403076171875"},
                    {"offset", "-1"},
                }),
        },
        {
            connection("source", "value", "scale", "value"),
            connection("scale", "value", "vca", "gain"),
        });

    const auto result = renderDocument(document, 4.0, 2);
    require(result.ok() && result.mono.size() == 2,
        "C83 offline FMA fixture should render");
    require(
        std::bit_cast<std::uint64_t>(result.mono[1])
            == std::bit_cast<std::uint64_t>(expected),
        "offline ScaleAndOffset should publish the frozen FMA result");
}

