// A connected OldMin that reaches OldMax saturates a fixed-point step from
// it (owner, 2026-10-12), so the range stays finite: 0.25 against an OldMin
// and OldMax of 1 maps to -2 - 0.75 / 2^-23 * 4.
void testSetRangeSaturatesDegenerateConnectedOldMin()
{
    auto document = makeVcaDocument(
        {
            node("source", "talas.constant", {{"value", "0.25"}}),
            node("range", "talas.setRange", {{"oldMin", "0"}, {"oldMax", "1"}, {"newMin", "-2"}, {"newMax", "2"}}),
            node("oldMin", "talas.constant", {{"value", "1"}}),
        },
        {
            connection("source", "value", "range", "value"),
            connection("oldMin", "value", "range", "oldMin"),
            connection("range", "value", "vca", "gain"),
        });

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "degenerate connected-oldMin setRange document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok() && result.mono.size() == 5,
        "setRange should saturate a connected oldMin equal to oldMax");
    constexpr double gain = -2.0 - 0.75 * 8388608.0 * 4.0;
    require(std::abs(result.mono[1] - gain) <= 1.0e-6 && std::abs(result.mono[3] + gain) <= 1.0e-6,
        "a saturated setRange should map against oldMax a fixed-point step from oldMin");
}

