void testThresholdPreservesExactMagnitudeAndBoundaryInequalities()
{
    auto document = makeVcaDocument(
        {
            node("source", "talas.constant", {{"value", "!C66BoundaryValue"}}),
            node("threshold", "talas.threshold", {{"threshold", "0.5"}, {"hysteresis", "0.2"}}),
        },
        {
            connection("source", "value", "threshold", "value"),
            connection("threshold", "value", "vca", "gain"),
        },
        {},
        {{"frequency", "0.25 hz"}, {"amplitude", "1"}});
    auto settings = talas::runtime::RenderSettings{4.0, 3};
    settings.eventValues = {{
        "C66BoundaryValue", -0.7,
        talas::expr::ValueDomain::Scalar,
    }};
    settings.eventValueChanges = {
        {1, "C66BoundaryValue", 0.3, talas::expr::ValueDomain::Scalar},
        {2, "C66BoundaryValue", 0.299, talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C66 exact Threshold boundary fixture should compile");
    const auto rendered = talas::runtime::renderOffline(*compiled.graph, 3);
    require(rendered.ok(), "C66 exact Threshold boundary fixture should render");
    requireNear(rendered.mono[0], 0.0, 1.0e-12,
        "C66 negative magnitude should activate at upper equality");
    requireNear(rendered.mono[1], std::sin(std::acos(-1.0) / 8.0), 1.0e-12,
        "C66 active Threshold should remain active at lower equality");
    requireNear(rendered.mono[2], 0.0, 1.0e-12,
        "C66 active Threshold should deactivate strictly below the lower boundary");
}

