void testAmplitudeFollowerFailureRollsBackOfflineStateBeforeRetry()
{
    auto document = makeAmplitudeFollowerVcaDocument();
    document.graph.nodes.push_back(node(
        "scaleControl", "talas.constant", {{"value", "!C88Scale"}}));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C88Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "outputScale", "talas.level", {
            {"left", "3"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "scaleControl", "value", "follower", "scale"));
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "outputScale", "audioIn"));
    document.graph.connections.push_back(connection(
        "outputScale", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C88Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"C88Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C88Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C88 offline Amplitude Follower rollback fixture should compile");
    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    require(candidate.render(2).ok(),
        "C88 offline Amplitude Follower should establish committed state");
    const auto rejected = candidate.render(2);
    const auto retry = candidate.render(1);

    auto referenceSettings = settings;
    referenceSettings.eventValueChanges.clear();
    const auto referenceCompiled = talas::runtime::compileProject(
        document, makeRegistry(), referenceSettings);
    require(referenceCompiled.ok(),
        "C88 offline Amplitude Follower reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(2).ok(),
        "C88 offline Amplitude Follower reference should establish state");
    const auto referenceRetry = reference.render(1);

    require(!rejected.ok() && rejected.mono.empty(),
        "C88 later offline failure should reject the whole public transaction");
    require(retry.ok() && referenceRetry.ok(),
        "C88 offline rollback retry and reference should render");
    require(retry.mono == referenceRetry.mono,
        "C88 failed offline transaction should restore Amplitude Follower before an exact retry");
}

