void testRmsSquaredFailureRollsBackOfflineStateBeforeRetry()
{
    auto document = makeRmsSquaredVcaDocument();
    document.graph.nodes.push_back(node(
        "scaleControl", "talas.constant", {{"value", "!C87Scale"}}));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C87Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "outputScale", "talas.level", {
            {"left", "3"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "scaleControl", "value", "detector", "scale"));
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "outputScale", "audioIn"));
    document.graph.connections.push_back(connection(
        "outputScale", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C87Scale", 1.0, talas::expr::ValueDomain::Scalar},
        {"C87Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C87Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C87 offline RMS Squared rollback fixture should compile");
    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    require(candidate.render(2).ok(),
        "C87 offline RMS Squared should establish committed state");
    const auto rejected = candidate.render(2);
    const auto retry = candidate.render(1);

    auto referenceSettings = settings;
    referenceSettings.eventValueChanges.clear();
    const auto referenceCompiled = talas::runtime::compileProject(
        document, makeRegistry(), referenceSettings);
    require(referenceCompiled.ok(),
        "C87 offline RMS Squared reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(2).ok(),
        "C87 offline RMS Squared reference should establish state");
    const auto referenceRetry = reference.render(1);

    require(!rejected.ok() && rejected.mono.empty(),
        "C87 later offline failure should reject the whole public transaction");
    require(retry.ok() && referenceRetry.ok(),
        "C87 offline rollback retry and reference should render");
    require(retry.mono == referenceRetry.mono,
        "C87 failed offline transaction should restore RMS Squared before an exact retry");
}

void testFrequencyTrackerEstimatesMonophonicSine()
{
    const auto result = renderFrequencyTrackerDocument(
        frequencyTrackerParameters(),
        {{"frequency", "4 hz"}, {"amplitude", "1.0"}},
        256);

    require(result.ok(), "frequency tracker sine render should not emit diagnostics");
    require(result.mono.size() == 256, "frequency tracker sine render should return requested frames");
    // The first estimate needs two periods of the 1 hz minimum: 128 frames.
    for (std::size_t frame = 0; frame < 127; ++frame)
        require(result.mono[frame] == 0.0, "frequency tracker should not estimate before its history fills");
    for (std::size_t frame = 127; frame < result.mono.size(); ++frame)
        requireNear(result.mono[frame], 1.0, 0.05, "frequency tracker sine frame " + std::to_string(frame));
}

