void testSqrtMagnitudePreservesTinyFiniteMagnitudes()
{
    constexpr auto tinyAmplitude = 1.0e-200;

    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "left",
            "talas.oscillator",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                {"amplitude", talas::expr::ValueDomain::Scalar, tinyAmplitude},
            },
        },
        {
            "right",
            "talas.oscillator",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                {"amplitude", talas::expr::ValueDomain::Scalar, tinyAmplitude},
            },
        },
        {
            "magnitude",
            "talas.sqrtMagnitude",
            {
                binding("audioIn", "left", "audioOut", 0),
                binding("rightIn", "right", "audioOut", 1),
            },
            {},
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "magnitude", "audioOut", 2)},
            {},
        },
    };
    plan.buffers = {
        {"left", "audioOut", talas::core::PortType::Audio, 2},
        {"right", "audioOut", talas::core::PortType::Audio, 2},
        {"magnitude", "audioOut", talas::core::PortType::Audio, 2},
    };
    plan.outputBufferIndex = 2;

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan), settings), 2);

    require(result.ok(), "sqrt magnitude tiny finite render should not emit diagnostics");
    require(result.mono.size() == 2, "sqrt magnitude tiny finite render should return two frames");
    requireNear(result.mono[0], 0.0, 1.0e-210, "sqrt magnitude tiny finite frame 0");
    requireNear(result.mono[1], std::sqrt(2.0) * tinyAmplitude, 1.0e-210, "sqrt magnitude tiny finite frame 1");
}

