void testInterpolateConnectedAmountUpdatesPerFrame()
{
    auto document = makeVcaDocument(
        {
            node("left", "talas.constant", {{"value", "-1"}}),
            node("right", "talas.constant", {{"value", "3"}}),
            node("amount", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Amount")})),
            node("interp", "talas.interpolate", {{"amount", "0.25"}}),
        },
        {
            connection("left", "value", "interp", "left"),
            connection("right", "value", "interp", "right"),
            connection("amount", "value", "interp", "amount"),
            connection("interp", "value", "vca", "gain"),
        },
        {},
        {{"frequency", "0.25 hz"}, {"amplitude", "1.0"}});

    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 6;
    settings.tableResources = {{"Tables/Amount", {0.0, 0.25, 0.5, 0.75, 1.0, 0.125}}};

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic interpolate amount document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 6);
    const auto pi = std::acos(-1.0);
    const std::vector<double> expected = {
        0.0,
        0.0,
        std::sin(pi / 4.0),
        std::sin(3.0 * pi / 8.0) * 2.0,
        3.0,
        std::sin(3.0 * pi / 8.0) * -0.5,
    };

    require(result.ok(), "dynamic interpolate amount render should not emit diagnostics");
    require(result.mono.size() == expected.size(), "dynamic interpolate amount render should return requested frames");
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic interpolate amount frame " + std::to_string(frame));
}

