void testLfoConnectedFrequencyAccumulatesPhaseAcrossBlocks()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;

    auto document = makeVcaDocument(
        {
            node("frequency", "talas.linearRamp", {{"duration", "1 s"}, {"start", "0.5"}, {"end", "1.5"}}),
            node("lfo", "talas.lfo", {{"frequency", "1 hz"}, {"minimum", "-1"}, {"maximum", "1"}}),
        },
        {
            connection("frequency", "value", "lfo", "frequency"),
            connection("lfo", "value", "vca", "gain"),
        });

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "ramp-frequency LFO document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "ramp-frequency LFO render should not emit diagnostics\n" + diagnosticDetails(result));
    require(result.mono.size() == 5, "ramp-frequency LFO render should return requested frames");

    const auto lfoExpected = expectedSinePhaseAccumulatedSamples({0.5, 0.75, 1.0, 1.25, 1.5}, 4.0, 1.0);
    const std::vector<double> carrier = {0.0, 1.0, 0.0, -1.0, 0.0};
    for (std::size_t frame = 0; frame < result.mono.size(); ++frame)
        requireNear(result.mono[frame], carrier[frame] * lfoExpected[frame], 1.0e-12, "ramp-frequency LFO frame " + std::to_string(frame));
}

