void testRunningMaxFailureRollsBackOfflineStateBeforeRetry()
{
    auto document = makeVcaDocument(
        {
            node("source", "talas.constant", {{"value", "!C85RunningValue"}}),
            node("running", "talas.runningMax"),
            node("downstream", "talas.level", {
                {"left", "!C85Downstream"}, {"right", "0"},
                booleanParameter("noGain", false),
            }),
            node("overflow", "talas.level", {
                {"left", "3"}, {"right", "0"},
                booleanParameter("noGain", false),
            }),
        },
        {
            connection("source", "value", "running", "value"),
            connection("running", "value", "vca", "gain"),
            connection("vca", "audioOut", "downstream", "audioIn"),
            connection("downstream", "leftOut", "overflow", "audioIn"),
            connection("overflow", "leftOut", "out", "audioIn"),
        },
        {},
        {{"frequency", "0.5 hz"}, {"amplitude", "1"}});
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C85RunningValue", 0.75, talas::expr::ValueDomain::Scalar},
        {"C85Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C85RunningValue", 0.9, talas::expr::ValueDomain::Scalar},
        {3, "C85Downstream", std::numeric_limits<double>::max(), talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C85 offline Running Max rollback fixture should compile");
    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    require(
        candidate.render(2).ok(),
        "C85 offline Running Max should establish committed state");
    const auto rejected = candidate.render(2);
    const auto retry = candidate.render(1);

    auto referenceSettings = settings;
    referenceSettings.eventValueChanges.resize(1);
    const auto referenceCompiled = talas::runtime::compileProject(
        document, makeRegistry(), referenceSettings);
    require(referenceCompiled.ok(), "C85 offline Running Max reference should compile");
    talas::runtime::OfflineRenderSession reference{*referenceCompiled.graph};
    require(reference.render(2).ok(), "C85 offline reference should establish state");
    const auto referenceRetry = reference.render(1);

    require(!rejected.ok() && rejected.mono.empty(),
        "C85 later offline failure should reject the whole public transaction");
    require(retry.ok() && referenceRetry.ok(),
        "C85 offline rollback retry and reference should render");
    require(retry.mono == referenceRetry.mono,
        "C85 failed offline transaction should restore Running Max before an exact retry");
    require(retry.mono == std::vector<double>({2.7}),
        "C85 offline retry should repeat the scheduled maximum transition exactly");
}

