void testTalasRampSessionKeepsLifecycleAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 2;
    settings.audioInputChannels.push_back({1, std::vector<double>(8, 1.0)});
    const auto document = makeTalasRampDocument(
        {{"trigger", "1"}, {"duration", "1 s"}, choiceParameter("variant", "ramp")});
    const auto compiled = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compiled.ok(), "cross-call Ramp fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};

    const auto first = session.render(3);
    const auto second = session.render(4);

    require(first.ok(), "first cross-call Ramp render should succeed");
    require(second.ok(), "second cross-call Ramp render should succeed");
    const std::vector<double> expectedFirst = {0.0, 0.25, 0.5};
    const std::vector<double> expectedSecond = {0.75, 1.0, 1.0, 1.0};
    for (std::size_t frame = 0; frame < expectedFirst.size(); ++frame)
        requireNear(first.mono[frame], expectedFirst[frame], 1.0e-12, "first cross-call Ramp frame");
    for (std::size_t frame = 0; frame < expectedSecond.size(); ++frame)
        requireNear(second.mono[frame], expectedSecond[frame], 1.0e-12, "second cross-call Ramp frame");
}

void testTalasRampRejectsInvalidStaticControls()
{
    for (const auto& parameters : {
             std::vector<talas::project::ProjectParameterExpression>{{"trigger", "1"}, {"duration", "0 s"}, choiceParameter("variant", "ramp")},
             std::vector<talas::project::ProjectParameterExpression>{{"trigger", "1 / 0"}, {"duration", "1 s"}, choiceParameter("variant", "ramp")},
         })
    {
        const auto compiled = talas::runtime::compileProject(makeTalasRampDocument(parameters), makeRegistry(), {});
        require(!compiled.ok(), "Ramp should reject invalid static controls");
        require(hasDiagnostic(compiled, DiagnosticCode::ParameterEvaluationError, "ramp"), "compile should identify invalid static Ramp control");
    }

    const auto result = renderTalasRamp(
        {{"trigger", "1"}, {"duration", "2305843009213693952 s"}, choiceParameter("variant", "ramp")},
        2);
    require(!result.ok(), "Ramp should reject duration that reaches 2^63 frames");
    require(result.mono.empty(), "unrenderable Ramp duration should not return audio");
}

void testTalasRampRejectsInvalidConnectedControls()
{
    const ScopedRejectedAddResultInjectionForTesting
        injectRejectedAddResult;
    for (const auto duration : {0.0, 2305843009213693952.0})
    {
        const auto result = renderTalasRamp(
            {{"trigger", "1"}, {"duration", "1 s"}, choiceParameter("variant", "ramp")},
            2,
            {{"RampDuration", duration, talas::expr::ValueDomain::Scalar}},
            {},
            false,
            true);
        require(!result.ok(), "Ramp should reject invalid connected duration");
        require(result.mono.empty(), "invalid connected Ramp duration should not return audio");
        require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "ramp", "duration"), "render should identify connected Ramp duration");
    }

    for (const auto& portId : {std::string{"trigger"}, std::string{"duration"}})
    {
        auto document = makeTalasRampDocument(
            {{"trigger", "1"}, {"duration", "1 s"}, choiceParameter("variant", "ramp")});
        document.graph.nodes.push_back(node("left", "talas.constant", {{"value", "1e308"}}));
        document.graph.nodes.push_back(node("right", "talas.constant", {{"value", "1e308"}}));
        document.graph.nodes.push_back(node("nonFinite", "talas.add"));
        document.graph.connections.push_back(connection("left", "value", "nonFinite", "left"));
        document.graph.connections.push_back(connection("right", "value", "nonFinite", "right"));
        document.graph.connections.push_back(connection("nonFinite", "value", "ramp", portId));

        auto settings = talas::runtime::RenderSettings{};
        settings.sampleRate = 4.0;
        settings.maxBlockFrames = 2;
        settings.audioInputChannels.push_back({1, std::vector<double>(2, 1.0)});
        const auto compiled = talas::runtime::compileProject(document, makeRegistry(), settings);
        require(compiled.ok(), "non-finite connected Ramp fixture should compile");
        const auto result = talas::runtime::renderOffline(*compiled.graph, 2);
        require(!result.ok(), "Ramp should reject non-finite connected control");
        require(result.mono.empty(), "non-finite connected Ramp control should not return audio");
        require(
            hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "ramp", portId),
            "render should identify non-finite connected Ramp control\n" + diagnosticDetails(result));
    }
}

