    require(compile.ok(), "LFO document should compile before session render");
    talas::runtime::OfflineRenderSession session{*compile.graph};

    const auto first = session.render(2);
    const auto second = session.render(3);

    require(first.ok(), "first LFO session render should succeed");
    require(second.ok(), "second LFO session render should succeed");
