void testThresholdFailureRollsBackOfflineLatchAndResetClearsIt()
{
    auto document = makeVcaDocument(
        {
            node("source", "talas.constant", {{"value", "!C66ThresholdValue"}}),
            node("threshold", "talas.threshold", {{"threshold", "0.5"}, {"hysteresis", "0.2"}}),
            node("downstream", "talas.level", {
                {"left", "!C66Downstream"}, {"right", "0"},
                booleanParameter("noGain", false),
            }),
            node("overflow", "talas.level", {
                {"left", "3"}, {"right", "0"},
                booleanParameter("noGain", false),
            }),
        },
        {
            connection("source", "value", "threshold", "value"),
            connection("threshold", "value", "vca", "gain"),
            connection("vca", "audioOut", "downstream", "audioIn"),
            connection("downstream", "leftOut", "overflow", "audioIn"),
            connection("overflow", "leftOut", "out", "audioIn"),
        },
        {},
        {{"frequency", "0.5 hz"}, {"amplitude", "1"}});
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C66ThresholdValue", 0.5, talas::expr::ValueDomain::Scalar},
        {"C66Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C66ThresholdValue", 0.8, talas::expr::ValueDomain::Scalar},
        {3, "C66Downstream", std::numeric_limits<double>::max(), talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C66 offline Threshold rollback fixture should compile");

    talas::runtime::OfflineRenderSession session{*compiled.graph};
    const auto rejected = session.render(5);
    const auto retry = session.render(2);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && retry.mono == std::vector<double>({0.0, 0.0}),
        "C66 failed offline transaction should restore the entry Threshold latch");

    const auto activated = session.render(1);
    require(
        activated.ok(),
        "C66 offline Threshold should accept the scheduled activation before reset");
    session.reset();
    const auto reset = session.render(2);
    require(
        reset.ok() && reset.mono == std::vector<double>({0.0, 0.0}),
        "C66 offline reset should restore an inactive Threshold latch");
}

