void testSampleAndHoldOfflineFailureRollsBackClockHeldStateAndSchedule()
{
    auto document = makeSampleAndHoldVcaDocument();
    const auto carrier = std::ranges::find(
        document.graph.nodes, std::string_view{"osc"},
        &talas::project::ProjectNode::instanceId);
    const auto source = std::ranges::find(
        document.graph.nodes, std::string_view{"ramp"},
        &talas::project::ProjectNode::instanceId);
    require(carrier != document.graph.nodes.end()
            && source != document.graph.nodes.end(),
        "C98 offline rollback fixture should expose its carrier and source");
    carrier->typeId = "talas.audioInput";
    carrier->parameters.clear();
    source->typeId = "talas.constant";
    source->parameters = {{"value", "!C98Source"}};
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C98Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(document.graph.connections, [](const auto& edge) {
        return edge.fromNode == "vca" && edge.toNode == "out";
    });
    document.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C98Source", 1.0, talas::expr::ValueDomain::Scalar},
        {"C98Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C98Source", 3.0,
            talas::expr::ValueDomain::Scalar},
        {3, "C98Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    settings.audioInputChannels.push_back(
        {1, std::vector<double>(5, 1.0)});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C98 offline Sample And Hold rollback fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};

    const auto rejected = session.render(5);
    const auto retryPrefix = session.render(2);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retryPrefix.ok()
            && retryPrefix.mono == std::vector<double>({1.0, 1.0}),
        "C98 downstream failure should restore offline Sample And Hold clock, held state, and schedule before retry");
    const auto repeatedFailure = session.render(2);
    require(
        !repeatedFailure.ok() && repeatedFailure.mono.empty(),
        "C98 restored schedule should encounter the same absolute-frame downstream failure again");

    session.reset();
    const auto resetPrefix = session.render(2);
    require(
        resetPrefix.ok() && resetPrefix.mono == retryPrefix.mono,
        "C98 offline reset should replay the exact fresh Sample And Hold prefix");
}

