void testPhaseShiftBy90OfflineFailureRollsBackAllpassStateAndSchedule()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C100Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "phase", "talas.phaseShiftBy90", {{"frequency", "1 hz"}, choiceParameter("overflow", "unclipped")}));
    document.graph.nodes.push_back(node(
        "input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "phase", "audioIn"));
    document.graph.connections.push_back(connection(
        "phase", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C100Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {3, "C100Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    settings.audioInputChannels.push_back(
        {1, {2.0, 2.0, 2.0, 2.0, 2.0}});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C100 offline Phase Shift By 90 rollback fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};

    const auto rejected = session.render(5);
    const auto retryPrefix = session.render(2);
    require(
        !rejected.ok() && rejected.mono.empty(),
        "C100 downstream failure should publish no offline audio");
    require(
        retryPrefix.ok() && retryPrefix.mono.size() == 2,
        "C100 rejected offline transaction should permit a two-frame retry");
    const auto r = std::sqrt(2.0) - 1.0;
    require(
        std::abs(retryPrefix.mono[0] - 2.0 * r) <= 1.0e-12
            && std::abs(retryPrefix.mono[1] + 2.0 * r) <= 1.0e-12,
        "C100 downstream failure should restore offline allpass state and schedule before retry");
    const auto repeatedFailure = session.render(2);
    require(
        !repeatedFailure.ok() && repeatedFailure.mono.empty(),
        "C100 restored schedule should encounter the same absolute-frame downstream failure again");

    session.reset();
    const auto resetPrefix = session.render(2);
    require(
        resetPrefix.ok() && resetPrefix.mono == retryPrefix.mono,
        "C100 offline reset should replay the exact fresh allpass prefix");
}

