void testSingleSideBandRmOfflineIntermediateFailureUsesNodeGenericDiagnostic()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "ssb", "talas.singleSideBandRm", {
            {"frequency", "1.9 hz"},
            {"freqScale", "1e200 * 1e200"},
        }));
    document.graph.nodes.push_back(node(
        "scale", "talas.constant", {{"value", "2"}}));
    document.graph.nodes.push_back(node(
        "input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "ssb", "audioIn"));
    document.graph.connections.push_back(connection(
        "scale", "value", "ssb", "freqScale"));
    document.graph.connections.push_back(connection(
        "ssb", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 2};
    settings.audioInputChannels.push_back({1, {
        std::numeric_limits<double>::max(),
        std::numeric_limits<double>::max(),
    }});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C101 intermediate-diagnostic fixture should compile with connected scale authority");
    const auto result = talas::runtime::renderOffline(*compiled.graph, 2);
    const auto diagnostic = std::ranges::find_if(
        result.diagnostics,
        [](const talas::runtime::Diagnostic& candidate) {
            return candidate.nodeId == "ssb"
                && candidate.message.find(
                    "SingleSideBandRM transition must stay finite")
                    != std::string::npos;
        });
    require(!result.ok() && result.mono.empty()
            && diagnostic != result.diagnostics.end()
            && diagnostic->portId.empty()
            && diagnostic->parameterId.empty(),
        "C101 shared-transition overflow should use a truthful node-generic diagnostic instead of blaming valid connected freqScale authority");
}

