void testMonotonizerOfflineFailureRollsBackPhaseVocoderInputAndSchedule()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "mono", "talas.monotonizer", {
            {"frequency", "150 hz"},
            {"minInputPitch", "100 hz"},
            {"maxInputPitch", "100 hz"},
        }));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C105Downstream"},
            {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.nodes.push_back(node(
        "input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "mono", "audioIn"));
    document.graph.connections.push_back(connection(
        "mono", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    constexpr std::size_t frameCount = 1280;
    auto settings = talas::runtime::RenderSettings{48000.0, frameCount};
    settings.eventValues = {
        {"C105Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {1100, "C105Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    std::vector<double> input(frameCount);
    for (std::size_t frame = 0; frame < input.size(); ++frame)
    {
        input[frame] = 1.0e20 * std::sin(
            2.0 * std::numbers::pi * 100.0
            * static_cast<double>(frame) / settings.sampleRate);
    }
    settings.audioInputChannels.push_back({1, std::move(input)});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C105 offline Monotonizer rollback fixture should compile");
    talas::runtime::OfflineRenderSession session{*compiled.graph};

    const auto rejected = session.render(frameCount);
    const auto retryPrefix = session.render(512);
    require(!rejected.ok() && rejected.mono.empty(),
        "C105 downstream failure should publish no offline Monotonizer audio");
    require(retryPrefix.ok() && retryPrefix.mono.size() == 512,
        "C105 rejected offline transaction should permit a Monotonizer retry");

    talas::runtime::OfflineRenderSession reference{*compiled.graph};
    const auto expectedPrefix = reference.render(512);
    require(expectedPrefix.ok() && retryPrefix.mono == expectedPrefix.mono,
        "C105 downstream failure should restore complete Monotonizer phase-vocoder state, input cursor, and schedule");
    const auto repeatedFailure = session.render(768);
    require(!repeatedFailure.ok() && repeatedFailure.mono.empty(),
        "C105 restored schedule should encounter the same downstream failure again");

    session.reset();
    const auto resetPrefix = session.render(512);
    require(resetPrefix.ok() && resetPrefix.mono == retryPrefix.mono,
        "C105 offline reset should replay the exact fresh Monotonizer prefix");
}

void testReverbSectionDynamicDelayIsPartitionIndependent()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "reverb", "talas.reverbSection", {
            choiceParameter("type", "comb"),
            {"scale", "1"},
            {"decayTime", "1 s"},
            {"delay", "1 / 0"},
            {"delayScale", "1"},
            resourceParameter("wavetable", "Private"),
            booleanParameter("prezero", true),
            choiceParameter("interpolation", "linear"),
            // The delay jumps to each new value, as before format 69.
            booleanParameter("smoothDelayChanges", false),
        }));
    document.graph.nodes.push_back(node(
        "delayControl", "talas.constant", {{"value", "!C104Delay"}}));
    document.graph.nodes.push_back(node(
        "input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "reverb", "audioIn"));
    document.graph.connections.push_back(connection(
        "delayControl", "value", "reverb", "delay"));
    document.graph.connections.push_back(connection(
        "reverb", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 3};
    settings.maxRealtimeHistoryFrames = 2;
    settings.eventValues = {
        {"C104Delay", 0.25, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {2, "C104Delay", 0.5, talas::expr::ValueDomain::Scalar},
    };
    settings.audioInputChannels.push_back(
        {1, std::vector<double>{1.0, 2.0, 0.0}});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C104 dynamic-delay partition fixture should compile");

    talas::runtime::OfflineRenderSession contiguous{*compiled.graph};
    const auto expected = contiguous.render(3);
    talas::runtime::OfflineRenderSession partitioned{*compiled.graph};
    std::vector<double> actual;
    for (int partition = 0; partition < 3; ++partition)
    {
        const auto block = partitioned.render(1);
        require(block.ok() && block.mono.size() == 1,
            "C104 one-frame dynamic-delay partition should render");
        actual.push_back(block.mono.front());
    }
    require(expected.ok()
            && expected.mono == std::vector<double>({0.0, 1.0, 1.0})
            && actual == expected.mono,
        "C104 connected delay must retain nonzero older history across capacity growth and partitions");

    auto zeroHistorySettings = settings;
    zeroHistorySettings.maxRealtimeHistoryFrames = 0;
    zeroHistorySettings.eventValues.front().value = 0.0;
    zeroHistorySettings.eventValueChanges.clear();
    const auto zeroHistoryCompiled = talas::runtime::compileProject(
        document, makeRegistry(), zeroHistorySettings);
    require(zeroHistoryCompiled.ok(),
        "C104 zero-history dynamic-delay boundary should compile before runtime admission");
    const auto zeroHistory = talas::runtime::renderOffline(
        *zeroHistoryCompiled.graph, 1);
    require(!zeroHistory.ok() && zeroHistory.mono.empty(),
        "C104 offline dynamic delay must reject zero retained-history authority like prepared admission");
}

void testReverbSectionDerivedOverflowUsesTruthfulDiagnosticIdentity()
{
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node(
        "reverb", "talas.reverbSection", {
            choiceParameter("type", "comb"),
            {"scale", "2"},
            {"decayTime", "1 s"},
            {"delay", "0 s"},
            {"delayScale", "1"},
            resourceParameter("wavetable", "Private"),
            booleanParameter("prezero", true),
            choiceParameter("interpolation", "linear"),
            booleanParameter("smoothDelayChanges", true),
        }));
    document.graph.nodes.push_back(node(
        "input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection(
        "input", "audioOut", "reverb", "audioIn"));
    document.graph.connections.push_back(connection(
        "reverb", "audioOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 1};
    settings.audioInputChannels.push_back(
        {1, {std::numeric_limits<double>::max()}});
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(),
        "C104 derived-overflow diagnostic fixture should compile");
    const auto result = talas::runtime::renderOffline(*compiled.graph, 1);
    const auto diagnostic = std::ranges::find_if(
        result.diagnostics,
        [](const talas::runtime::Diagnostic& candidate) {
            return candidate.nodeId == "reverb"
                && candidate.message.find("scaled input")
                    != std::string::npos;
        });
    require(!result.ok() && result.mono.empty()
            && diagnostic != result.diagnostics.end()
            && diagnostic->portId.empty()
            && diagnostic->parameterId.empty(),
        "C104 finite input-scale overflow should use a truthful derived-arithmetic diagnostic");

    talas::project::ProjectDocument geometryDocument;
    geometryDocument.graph.nodes.push_back(node("out", "talas.audioOutput"));
    geometryDocument.graph.nodes.push_back(node(
        "reverb", "talas.reverbSection", {
            choiceParameter("type", "comb"),
            {"scale", "1"},
            {"decayTime", "1 s"},
            {"delay", "1e308 s"},
            {"delayScale", "1 / 0"},
            resourceParameter("wavetable", "Private"),
            booleanParameter("prezero", true),
            choiceParameter("interpolation", "linear"),
            booleanParameter("smoothDelayChanges", true),
        }));
    geometryDocument.graph.nodes.push_back(node(
        "osc", "talas.oscillator", {
            {"frequency", "1 hz"}, {"amplitude", "1"},
        }));
    geometryDocument.graph.connections.push_back(connection(
        "osc", "audioOut", "reverb", "audioIn"));
    geometryDocument.graph.connections.push_back(connection(
        "reverb", "audioOut", "out", "audioIn"));
    connectConstantControl(
        geometryDocument, "delayScale", "1", "reverb", "delayScale");
    const auto geometryResult = renderDocument(geometryDocument, 4.0, 1);
    const auto geometryDiagnostic = std::ranges::find_if(
        geometryResult.diagnostics,
        [](const talas::runtime::Diagnostic& candidate) {
            return candidate.nodeId == "reverb"
                && candidate.portId == "delayScale"
                && candidate.parameterId.empty()
                && candidate.message.find("frame conversion")
                    != std::string::npos;
        });
    require(!geometryResult.ok() && geometryResult.mono.empty()
            && geometryDiagnostic != geometryResult.diagnostics.end(),
        "C104 delayScale-only geometry overflow should identify its connected authority and arithmetic stage:\n"
            + diagnosticDetails(geometryResult));
}

void testTriggeredSampleAndHoldSessionKeepsHeldValueAcrossCalls()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 3;
    const auto document = makeTriggeredSampleAndHoldVcaDocument();
    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "triggered sample and hold document should compile before session render");
    talas::runtime::OfflineRenderSession session{*compile.graph};

    const auto first = session.render(3);
    const auto second = session.render(3);

    require(first.ok(), "first triggered sample and hold session render should succeed");
    require(second.ok(), "second triggered sample and hold session render should succeed");
    requireNear(first.mono[0], 0.0, 1.0e-12, "triggered sample and hold session first frame 0");
    requireNear(first.mono[1], 1.0, 1.0e-12, "triggered sample and hold session first frame 1");
    requireNear(first.mono[2], 0.0, 1.0e-12, "triggered sample and hold session first frame 2");
    requireNear(second.mono[0], -1.0, 1.0e-12, "triggered sample and hold session second frame 0");
    requireNear(second.mono[1], 0.0, 1.0e-12, "triggered sample and hold session second frame 1");
    requireNear(second.mono[2], 1.0, 1.0e-12, "triggered sample and hold session second frame 2");
}

void testTriggeredSampleAndHoldDirectEdgesFailureRollbackAndReset()
{
    auto directSettings = talas::runtime::RenderSettings{4.0, 6};
    directSettings.eventValues = {
        {"SampleTrigger", 0.0, talas::expr::ValueDomain::Scalar},
    };
    directSettings.eventValueChanges = {
        {1, "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {3, "SampleTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {4, "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
    };
    const auto direct = talas::runtime::compileProject(
        makeTriggeredSampleAndHoldVcaDocument({{"trigger", "!SampleTrigger"}}),
        makeRegistry(), directSettings);
    require(direct.ok(),
        "C70 direct Event Value edge fixture should compile");
    const auto directResult = talas::runtime::renderOffline(*direct.graph, 6);
    const std::vector<double> directExpected{
        0.0, 2.0, 0.0, -2.0, 0.0, 5.0};
    require(directResult.ok()
            && directResult.mono.size() == directExpected.size(),
        "C70 offline direct trigger should render the complete edge sequence");
    for (std::size_t frame = 0; frame < directExpected.size(); ++frame)
        requireNear(
            directResult.mono[frame], directExpected[frame], 1.0e-12,
            "C70 offline direct trigger should re-arm low and recapture on the next rising edge frame "
                + std::to_string(frame));

    auto failureDocument = makeTriggeredSampleAndHoldVcaDocument(
        {{"trigger", "!SampleTrigger"}});
    failureDocument.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C70Downstream"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    std::erase_if(
        failureDocument.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca" && edge.toNode == "out";
        });
    failureDocument.graph.connections.push_back(connection(
        "vca", "audioOut", "downstream", "audioIn"));
    failureDocument.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto failureSettings = talas::runtime::RenderSettings{4.0, 6};
    failureSettings.eventValues = {
        {"SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {"C70Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    failureSettings.eventValueChanges = {
        {2, "SampleTrigger", 0.0, talas::expr::ValueDomain::Scalar},
        {3, "SampleTrigger", 1.0, talas::expr::ValueDomain::Scalar},
        {5, "C70Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        failureDocument, makeRegistry(), failureSettings);
    require(compiled.ok(), "C70 offline rollback fixture should compile");

    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    talas::runtime::OfflineRenderSession reference{*compiled.graph};
    const auto candidateFirst = candidate.render(2);
    const auto referenceFirst = reference.render(2);
    require(
        candidateFirst.ok() && referenceFirst.ok()
            && candidateFirst.mono == referenceFirst.mono,
        "C70 rollback fixture should establish matching captured state");
    const auto rejected = candidate.render(4);
    const auto retry = candidate.render(3);
    const auto referenceNext = reference.render(3);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && referenceNext.ok(),
        "C70 failed offline transaction should reject without output and permit retry");
    const std::vector<double> retryExpected{0.0, -4.0, 0.0};
    require(retry.mono.size() == retryExpected.size(),
        "C70 offline retry should render the expected frame count");
    for (std::size_t frame = 0; frame < retryExpected.size(); ++frame)
        requireNear(
            retry.mono[frame], retryExpected[frame], 1.0e-12,
            "C70 offline retry edge sequence frame "
                + std::to_string(frame));
    require(
        retry.mono == referenceNext.mono,
        "C70 failed offline transaction should restore held value, initialization, polarity, and scheduled controls");

    candidate.reset();
    talas::runtime::OfflineRenderSession resetReference{*compiled.graph};
    const auto reset = candidate.render(2);
    const auto resetPristine = resetReference.render(2);
    require(
        reset.ok() && resetPristine.ok()
            && reset.mono == resetPristine.mono,
        "C70 offline reset should restore pristine Triggered Sample And Hold state");
}

