// Reverse plays the Input backwards in windows of the offset here, as in
// projects before format 51.
talas::project::ProjectDocument makeTimeOffsetDocument(std::vector<talas::project::ProjectParameterExpression> offsetParameters)
{
    if (std::ranges::none_of(offsetParameters, [](const auto& parameter) {
            return parameter.parameterId == "reverseMeans";
        }))
        offsetParameters.push_back(choiceParameter("reverseMeans", "legacyReverseWindows"));
    // And the offset delays the Input, as in projects before format 64.
    if (std::ranges::none_of(offsetParameters, [](const auto& parameter) {
            return parameter.parameterId == "offsetMeans";
        }))
        offsetParameters.push_back(choiceParameter("offsetMeans", "legacyDelay"));
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("offset", "talas.timeOffset", std::move(offsetParameters)));
    document.graph.nodes.push_back(node("osc", "talas.oscillator", {{"frequency", "1 hz"}, {"amplitude", "1.0"}}));
    document.graph.connections.push_back(connection("osc", "audioOut", "offset", "audioIn"));
    document.graph.connections.push_back(connection("offset", "audioOut", "out", "audioIn"));
    return document;
}

talas::project::ProjectDocument makeTimeControlDocument(std::vector<talas::project::ProjectParameterExpression> timeParameters)
{
    // These fixtures exercise the replay that projects before format 45 keep.
    if (std::ranges::none_of(timeParameters, [](const auto& parameter) { return parameter.parameterId == "rateChanges"; }))
        timeParameters.push_back(choiceParameter("rateChanges", "legacyPlaybackSpeed"));
    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("time", "talas.timeControl", std::move(timeParameters)));
    document.graph.nodes.push_back(node("input", "talas.audioInput", audioInputParameters()));
    document.graph.connections.push_back(connection("input", "audioOut", "time", "audioIn"));
    document.graph.connections.push_back(connection("time", "audioOut", "out", "audioIn"));
    return document;
}

