void testWaitUntilFailureRollsBackOfflineHistoryAndResetRestoresPristine()
{
    auto document = makeTimeGateDocument(
        "talas.waitUntil",
        {{"resume", "0.0"}, booleanParameter("resumeOnZero", false)});
    document.graph.nodes.push_back(node(
        "resumeSource", "talas.linearRamp",
        {{"duration", "1 s"}, {"start", "0"}, {"end", "1"}}));
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C77Downstream * 2"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.connections.push_back(connection(
        "resumeSource", "value", "gate", "resume"));
    std::erase_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "gate" && edge.toNode == "out";
        });
    document.graph.connections.push_back(connection(
        "gate", "audioOut", "downstream", "audioIn"));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{4.0, 5};
    settings.eventValues = {
        {"C77Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {4, "C77Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(compiled.ok(), "C77 offline WaitUntil rollback fixture should compile");

    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    talas::runtime::OfflineRenderSession reference{*compiled.graph};
    const auto rejected = candidate.render(5);
    const auto retry = candidate.render(2);
    const auto pristine = reference.render(2);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && pristine.ok()
            && retry.mono == pristine.mono,
        "C77 failed offline transaction should restore WaitUntil history, resumed state, predecessors, and scheduled controls");

    const auto advanced = candidate.render(1);
    require(advanced.ok(), "C77 reset fixture should advance WaitUntil before reset");
    candidate.reset();
    talas::runtime::OfflineRenderSession resetReference{*compiled.graph};
    const auto reset = candidate.render(2);
    const auto resetPristine = resetReference.render(2);
    require(
        reset.ok() && resetPristine.ok()
            && reset.mono == resetPristine.mono,
        "C77 offline reset should restore pristine WaitUntil history and resumed state");
}

