void testWarpedTimeIndexFailureRollsBackOfflineStateAndResetRestoresPristine()
{
    auto document = makeWarpedTimeIndexVcaDocument(
        warpedTimeIndexParameters());
    const auto terminal = std::ranges::find_if(
        document.graph.connections,
        [](const talas::core::Connection& edge) {
            return edge.fromNode == "vca"
                && edge.fromPort == "audioOut"
                && edge.toNode == "out";
        });
    require(
        terminal != document.graph.connections.end(),
        "C78 offline rollback fixture should expose the VCA terminal edge");
    terminal->toNode = "downstream";
    terminal->toPort = "audioIn";
    document.graph.nodes.push_back(node(
        "downstream", "talas.level", {
            {"left", "!C78Downstream * 2"}, {"right", "0"},
            booleanParameter("noGain", false),
        }));
    document.graph.connections.push_back(connection(
        "downstream", "leftOut", "out", "audioIn"));

    auto settings = talas::runtime::RenderSettings{2.0, 5};
    settings.audioInputChannels.push_back(
        {1, std::vector<double>(8, 1.0)});
    settings.eventValues = {
        {"C78Downstream", 1.0, talas::expr::ValueDomain::Scalar},
    };
    settings.eventValueChanges = {
        {4, "C78Downstream", std::numeric_limits<double>::max(),
            talas::expr::ValueDomain::Scalar},
    };
    const auto compiled = talas::runtime::compileProject(
        document, makeRegistry(), settings);
    require(
        compiled.ok(),
        "C78 offline WarpedTimeIndex rollback fixture should compile");

    talas::runtime::OfflineRenderSession candidate{*compiled.graph};
    talas::runtime::OfflineRenderSession reference{*compiled.graph};
    const auto rejected = candidate.render(5);
    const auto retry = candidate.render(3);
    const auto pristine = reference.render(3);
    require(
        !rejected.ok() && rejected.mono.empty()
            && retry.ok() && pristine.ok()
            && retry.mono == pristine.mono,
        "C78 failed offline transaction should restore WarpedTimeIndex playback, active, trigger-edge, predecessor, and scheduled state");

    const auto advanced = candidate.render(1);
    require(
        advanced.ok(),
        "C78 offline reset fixture should advance WarpedTimeIndex");
    candidate.reset();
    talas::runtime::OfflineRenderSession resetReference{*compiled.graph};
    const auto reset = candidate.render(3);
    const auto resetPristine = resetReference.render(3);
    require(
        reset.ok() && resetPristine.ok()
            && reset.mono == resetPristine.mono,
        "C78 offline reset should restore pristine WarpedTimeIndex state");
}

