void testDelayFrameConversionAndTransitionAreBoundedAndAtomic()
{
    namespace delay = talas::runtime::checked_delay_with_feedback;
    using delay::Error;
    const auto exclusiveLimit = std::ldexp(
        1.0, std::numeric_limits<std::size_t>::digits);
    const auto immediatelyBelow = std::nextafter(exclusiveLimit, 0.0);
    const auto immediatelyAbove = std::nextafter(
        exclusiveLimit, std::numeric_limits<double>::infinity());
    const delay::Config unitRate{1.0, delay::Type::Comb, delay::Interpolation::None};
    auto delayFrames = 0.0;
    auto frames = std::size_t{0};
    require(
        delay::delayGeometry(unitRate, exclusiveLimit, 1.0, delayFrames, frames)
            == Error::DelayFramesNonFiniteOrUnrepresentable
        && delay::delayGeometry(unitRate, immediatelyAbove, 1.0, delayFrames, frames)
            == Error::DelayFramesNonFiniteOrUnrepresentable,
        "C140 delay should reject the exact and first-above exclusive size_t conversion boundary");
    require(
        delay::delayGeometry(unitRate, immediatelyBelow, 1.0, delayFrames, frames)
            == Error::None
        && frames == static_cast<std::size_t>(immediatelyBelow),
        "C140 delay should preserve the adjacent representable frame count below the conversion boundary");
    std::array<double, 3> shortHistory{};
    auto shortWriteIndex = std::size_t{0};
    auto shortOutput = 0.0;
    require(
        delay::advance(shortHistory, shortWriteIndex,
            {4.0, delay::Type::Comb, delay::Interpolation::None},
            {0.0, 1.0, 1.0, 1.0, 0.0, 1.0}, shortOutput)
            == Error::HistoryCapacityExceeded,
        "C140 connected delay should reject a selected frame count beyond fixed history");

    std::array history{std::numeric_limits<double>::max()};
    auto writeIndex = std::size_t{0};
    auto output = 140.0;
    const auto original = history;
    require(
        delay::advance(
            history,
            writeIndex,
            unitRate,
            {std::numeric_limits<double>::max(), 1.0, 1.0, 1.0, 0.5, 1.0},
            output)
            == Error::FeedbackSumNonFinite
        && history == original && writeIndex == 0 && output == 140.0,
        "C140 rejected feedback arithmetic should not mutate line, cursor, or output");
}

