void testTimeOffsetConnectedOffsetUpdatesPerFrame()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.audioInputChannels.push_back({1, {10.0, 20.0, 30.0, 40.0, 50.0}});
    settings.tableResources.push_back({"Tables/Offset", {0.0, 0.25, 0.25, 0.0, 0.25}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput"));
    // A SilentTime fed by a Sound that delays the Input's samples, as
    // projects before format 87 play it (ADR-0023).
    document.graph.nodes.push_back(node("timeOffset", "talas.timeOffset",
        {{"offset", "0 s"}, choiceParameter("offsetMeans", "legacyFixedStartsLate")}));
    document.graph.nodes.push_back(node("offset", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Offset")})));
    document.graph.connections.push_back(connection("input", "audioOut", "timeOffset", "audioIn"));
    document.graph.connections.push_back(connection("offset", "value", "timeOffset", "offset"));
    document.graph.connections.push_back(connection("timeOffset", "audioOut", "out", "audioIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-offset time offset document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-offset time offset should render");
    require(result.mono.size() == 5, "dynamic-offset time offset should return five samples");
    const std::vector<double> expected{10.0, 10.0, 20.0, 40.0, 40.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic-offset time offset frame " + std::to_string(frame));
}

