void testSetDurationConnectedTimingUpdatesPerFrame()
{
    auto settings = talas::runtime::RenderSettings{};
    settings.sampleRate = 4.0;
    settings.maxBlockFrames = 5;
    settings.audioInputChannels.push_back({1, {10.0, 20.0, 30.0, 40.0, 50.0}});
    settings.tableResources.push_back({"Tables/StartTime", {0.0, 0.0, 0.5, 0.5, 0.0}});
    settings.tableResources.push_back({"Tables/Duration", {0.25, 0.5, 0.5, 0.5, 1.25}});

    talas::project::ProjectDocument document;
    document.graph.nodes.push_back(node("out", "talas.audioOutput"));
    document.graph.nodes.push_back(node("input", "talas.audioInput"));
    // A StartTime fed by a Sound that delays the Input's samples, as
    // projects before format 87 play it (ADR-0023).
    document.graph.nodes.push_back(node("duration", "talas.setDuration",
        {{"duration", "1 s"}, {"startTime", "0 s"}, choiceParameter("startTimeMeans", "legacyFixedStartsLate")}));
    document.graph.nodes.push_back(node("startTime", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/StartTime")})));
    document.graph.nodes.push_back(node("durationValue", "talas.triggeredTableRead", triggeredTableReadParameters({resourceParameter("wavetable", "Tables/Duration")})));
    document.graph.connections.push_back(connection("input", "audioOut", "duration", "audioIn"));
    document.graph.connections.push_back(connection("startTime", "value", "duration", "startTime"));
    document.graph.connections.push_back(connection("durationValue", "value", "duration", "duration"));
    document.graph.connections.push_back(connection("duration", "audioOut", "out", "audioIn"));

    const auto compile = talas::runtime::compileProject(document, makeRegistry(), settings);
    require(compile.ok(), "dynamic-timing set duration document should compile");
    const auto result = talas::runtime::renderOffline(*compile.graph, 5);

    require(result.ok(), "dynamic-timing set duration should render");
    require(result.mono.size() == 5, "dynamic-timing set duration should return five samples");
    const std::vector<double> expected{10.0, 20.0, 10.0, 20.0, 50.0};
    for (std::size_t frame = 0; frame < expected.size(); ++frame)
        requireNear(result.mono[frame], expected[frame], 1.0e-12, "dynamic-timing set duration frame " + std::to_string(frame));
}

