void testVcaGainBindingValidatesSourceBufferSpec()
{
    talas::runtime::RuntimePlan plan;
    plan.steps = {
        {
            "osc",
            "talas.oscillator",
            {},
            {
                {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                {"amplitude", talas::expr::ValueDomain::Scalar, 1.0},
            },
        },
        {
            "actualGain",
            "talas.constant",
            {},
            {parameter("value", 0.5)},
        },
        {
            "staleGain",
            "talas.audioOutput",
            {},
            {},
        },
        {
            "vca",
            "talas.vca",
            {
                binding("audioIn", "osc", "audioOut", 0),
                binding("gain", "staleGain", "value", 1),
            },
            {parameter("gain", 0.25)},
        },
        {
            "out",
            "talas.audioOutput",
            {binding("audioIn", "vca", "audioOut", 2)},
            {},
        },
    };
    plan.buffers = {
        {"osc", "audioOut", talas::core::PortType::Audio, 5},
        {"actualGain", "value", talas::core::PortType::Control, 5},
        {"vca", "audioOut", talas::core::PortType::Audio, 5},
    };
    plan.outputBufferIndex = 2;

    const auto result = talas::runtime::renderOffline(handBuiltGraph(std::move(plan)), 5);

    require(!result.ok(), "stale VCA gain binding should fail render");
    require(result.mono.empty(), "failed render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "vca", "gain"), "render should identify stale VCA gain binding");
}

