void testHandBuiltSampleAndHoldRejectsInvalidTimingAtRender()
{
    auto makePlan = [](double holdTime, double offsetTime) {
        talas::runtime::RuntimePlan plan;
        plan.steps = {
            {
                "source",
                "talas.constant",
                {},
                {parameter("value", 1.0)},
            },
            {
                "hold",
                "talas.sampleAndHold",
                {binding("value", "source", "value", 0)},
                {
                    {"holdTime", talas::expr::ValueDomain::Seconds, holdTime},
                    {"offsetTime", talas::expr::ValueDomain::Seconds, offsetTime},
                },
            },
            {
                "osc",
                "talas.oscillator",
                {},
                {
                    {"frequency", talas::expr::ValueDomain::Hertz, 1.0},
                    {"amplitude", talas::expr::ValueDomain::Scalar, 1.0},
                },
            },
            {
                "vca",
                "talas.vca",
                {
                    binding("audioIn", "osc", "audioOut", 2),
                    binding("gain", "hold", "value", 1),
                },
                {parameter("gain", 1.0)},
            },
            {
                "out",
                "talas.audioOutput",
                {binding("audioIn", "vca", "audioOut", 3)},
                {},
            },
        };
        plan.buffers = {
            {"source", "value", talas::core::PortType::Control, 5},
            {"hold", "value", talas::core::PortType::Control, 5},
            {"osc", "audioOut", talas::core::PortType::Audio, 5},
            {"vca", "audioOut", talas::core::PortType::Audio, 5},
        };
        plan.outputBufferIndex = 3;
        return plan;
    };

    auto result = talas::runtime::renderOffline(handBuiltGraph(makePlan(0.0, 0.0)), 5);
    require(!result.ok(), "hand-built sample and hold with invalid hold time should fail render");
    require(result.mono.empty(), "failed render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "hold", {}, "holdTime"), "render should identify invalid hold time");

    result = talas::runtime::renderOffline(handBuiltGraph(makePlan(0.5, -0.25)), 5);
    require(!result.ok(), "hand-built sample and hold with invalid offset time should fail render");
    require(result.mono.empty(), "failed render should not return audio");
    require(hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "hold", {}, "offsetTime"), "render should identify invalid offset time");
}

