void requireHandBuiltPanRenderParameterError(
    std::vector<talas::runtime::ParameterValue> panParameters,
    std::string_view parameterId,
    const std::string& message)
{
    const auto result = talas::runtime::renderOffline(
        handBuiltGraph(makeHandBuiltPanToOutputPlan(std::move(panParameters))),
        5);

    require(!result.ok(), message);
    require(result.mono.empty(), "failed render should not return left audio");
    require(result.right.empty(), "failed render should not return right audio");
    require(
        hasDiagnostic(result, DiagnosticCode::GraphValidationFailed, "pan", {}, parameterId),
        message + " should identify " + std::string(parameterId));
}

void testHandBuiltPanRejectsInvalidParametersAtRender()
{
    requireHandBuiltPanRenderParameterError(
        {parameter("pan", -0.1), parameter("scale", 1.0), choiceRuntimeParameter("type", "power")},
        "pan",
        "hand-built pan with negative pan should fail render");
    requireHandBuiltPanRenderParameterError(
        {parameter("pan", 1.1), parameter("scale", 1.0), choiceRuntimeParameter("type", "power")},
        "pan",
        "hand-built pan above one should fail render");
    requireHandBuiltPanRenderParameterError(
        {parameter("pan", 0.5), parameter("scale", -1.0), choiceRuntimeParameter("type", "power")},
        "scale",
        "hand-built pan with negative scale should fail render");
    requireHandBuiltPanRenderParameterError(
        {parameter("pan", 0.5), parameter("scale", 1.0), choiceRuntimeParameter("type", "wrong")},
        "type",
        "hand-built pan with unknown type should fail render");
    requireHandBuiltPanRenderParameterError(
        {parameter("pan", 0.5), parameter("scale", 1.0), parameter("type", 0.0)},
        "type",
        "hand-built pan with numeric type should fail render");
}

